window.BOOK={"key":"qudouri","app":"mutoon","lsk":"mutoon_qudouri_v1","title":"مختصر القدوري","sub":"في فقه الإمام أبي حنيفة · أبو الحسين القدوري (ت ٤٢٨هـ) · ١١٨ بابًا","unitWord":"فقرة","chapters":[{"id":"q1","title":"كتاب الطهارة","group":"كتاب الطهارة","units":[{"id":"q1_1","label":"كتاب الطهارة · الفقرة ١","segs":[["matn","قال الله تعالى: {يا أيها الذين آمنوا إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق وامسحوا برؤوسكم وأرجلكم إلى الكعبين}"]]},{"id":"q1_2","label":"كتاب الطهارة · الفقرة ٢","segs":[["matn","ففرض الطهارة: غسل الأعضاء الثلاثة ومسح الرأس والمرفقان والكعبان يدخلان في الغسل والمفروض في مسح الرأس مقدار الناصية لما روى المغيرة بن شعبة [أن النبي صلى الله عليه وسلم أتى سباطة قوم فبال وتوضأ ومسح على ناصيته وخفيه]"]]},{"id":"q1_3","label":"كتاب الطهارة · الفقرة ٣","segs":[["matn","وسنن الطهارة: وغسل اليدين قبل إدخالها إذا استيقظ المتوضئ من نومه وتسمية الله تعالى في ابتداء الوضوء"]]},{"id":"q1_4","label":"كتاب الطهارة · الفقرة ٤","segs":[["matn","والسواك والمضمضة والأستنشاق ومسح الأذنين وتخليل اللحية والأصابع وتكرار الغسل إلى الثلاث"]]},{"id":"q1_5","label":"كتاب الطهارة · الفقرة ٥","segs":[["matn","ويستحب للمتوضئ أن ينوي الطهارة ويستوعب رأسه بالمسح ويرتب الوضوء فيبدأ بما بدأ الله تعالى بذكره وبالميامن"]]},{"id":"q1_6","label":"كتاب الطهارة · الفقرة ٦","segs":[["matn","والمعاني الناقضة للوضوء: كل ما خرج من السبيلين والدم والقيح والصديد إذا خرج من البدن فتجاوز إلى موضع يلحقه حكم التطهير والقيء إذا كان ملء الفم والنوم مضطجعا أو متكئا أو مستندا إلى شيء لو أزيل عنه لسقط والغلبة على العقل بالإغماء"]]},{"id":"q1_7","label":"كتاب الطهارة · الفقرة ٧","segs":[["matn","والجنون والقهقهة في كل صلاة ذات ركوع وسجود"]]},{"id":"q1_8","label":"كتاب الطهارة · الفقرة ٨","segs":[["matn","وفرض الغسل: المضمضة والاستنشاق وغسل سائر البدن"]]},{"id":"q1_9","label":"كتاب الطهارة · الفقرة ٩","segs":[["matn","وسنة الغسل: أن يبدأ المغتسل يديه وفرجه ويزيل النجاسة إن كانت على بدنه ثم يتوضأ وضوءه للصلاة إلا رجليه ثم يفيض الماء على رأسه وسائر جسده ثلاثا ثم يتنحى عن ذلك المكان فيغتسل رجليه"]]},{"id":"q1_10","label":"كتاب الطهارة · الفقرة ١٠","segs":[["matn","وليس على المرأة أن تنقض ضفائرها في الغسل إذا بلغ الماء أصول الشعر"]]},{"id":"q1_11","label":"كتاب الطهارة · الفقرة ١١","segs":[["matn","والمعاني الموجبة للغسل: إنزال المني على وجه الدفق والشهوة من الرجل والمرأة والتقاء الختانين من غير إنزال والحيض والنفاس"]]},{"id":"q1_12","label":"كتاب الطهارة · الفقرة ١٢","segs":[["matn","وسن رسول الله صلى الله عليه وسلم الغسل للجمعة والعيدين والإحرام"]]},{"id":"q1_13","label":"كتاب الطهارة · الفقرة ١٣","segs":[["matn","وليس في المذي والودي غسل وفيهما الوضوء"]]},{"id":"q1_14","label":"كتاب الطهارة · الفقرة ١٤","segs":[["matn","والطهارة من الأحداث جائزة بماء السماء والأودية والعيون والآبار وماء البحار ولا تجوز بما اعتصر من الشجر والثمر ولا بماء غلب عليه غيره وأخرجه عن طبع الماء"]]},{"id":"q1_15","label":"كتاب الطهارة · الفقرة ١٥","segs":[["matn","كالأشربة والخل وماء الورد وماء الباقلاء والمرق وماء الزردج"]]},{"id":"q1_16","label":"كتاب الطهارة · الفقرة ١٦","segs":[["matn","وتجوز الطهارة بماء خالطة شيء طاهر فغير أحد أوصافه كماء المد والماء الذي يختلط به الأشنان والصابون والزعفران"]]},{"id":"q1_17","label":"كتاب الطهارة · الفقرة ١٧","segs":[["matn","وكل ماء وقعت فيه نجاسة لم يجز اوضوء به قليلا أو كثيرا [لأن النبي عليه الصلاة والسلام أمر بحفظ الماء من النجاسة فقال لا يبولن"]]},{"id":"q1_18","label":"كتاب الطهارة · الفقرة ١٨","segs":[["matn","أحدكم في الماء الدائم ولا يغتسلن فيه من الجنابة] و [قال عليه الصلاة والسلام: إذا استيقظ أحدكم من منامه فلا يغمسن يده في الإناء حتى يغسلها ثلاثا فإنه لا يدري أين باتت يده]"]]},{"id":"q1_19","label":"كتاب الطهارة · الفقرة ١٩","segs":[["matn","وأما الماء الجاري إذا وقعت فيه نجاسة جاز الوضوء منه إذا لم ير لها أثر لا تستقر مع جريان الماء والغدير العظيم الذي لا يتحرك أحد طرفيه بتحريك الطرف الآخر"]]},{"id":"q1_20","label":"كتاب الطهارة · الفقرة ٢٠","segs":[["matn","إذا وقعت نجاسة في أحد جانبيه جاز الوضوء من الجانب الآخر لأن الظاهر أن النجاسة لا تصل إليه"]]},{"id":"q1_21","label":"كتاب الطهارة · الفقرة ٢١","segs":[["matn","وموت ما ليس له نفس سائلة في الماء لا ينجسه كالبق والذباب والزنابير والعقارب وموت ما يعيش في الماء فيه لا يفسده كالسمك والضفدع والسرطان"]]},{"id":"q1_22","label":"كتاب الطهارة · الفقرة ٢٢","segs":[["matn","والماء المستعمل لا يجوز استعماله في طهارة الأحداث"]]},{"id":"q1_23","label":"كتاب الطهارة · الفقرة ٢٣","segs":[["matn","والمستعمل: كل ماء أزيل به حدث أو استعمل في البدن على وجه القربة"]]},{"id":"q1_24","label":"كتاب الطهارة · الفقرة ٢٤","segs":[["matn","وكل إهاب دبغ فقد ظهر وجازت الصلاة فيه والوضوء منه إلا جلد الخنزير والآدمي"]]},{"id":"q1_25","label":"كتاب الطهارة · الفقرة ٢٥","segs":[["matn","وشعر الميتة وعظمها وعصبها وحافرها وقرنها طاهر"]]},{"id":"q1_26","label":"كتاب الطهارة · الفقرة ٢٦","segs":[["matn","وإذا وقعت في البئر نجاسة نزحت وكان نزح ما فيها من الماء طهارة لها"]]},{"id":"q1_27","label":"كتاب الطهارة · الفقرة ٢٧","segs":[["matn","فإن ماتت فيها فأرة أو عصفورة أو صعوة أو سوادنية أو سام أبرص نزح منها ما بين عشرين دلوا إلى ثلاثين دلوا"]]},{"id":"q1_28","label":"كتاب الطهارة · الفقرة ٢٨","segs":[["matn","بحسب كبر الحيوان وصغره"]]},{"id":"q1_29","label":"كتاب الطهارة · الفقرة ٢٩","segs":[["matn","وإن ماتت فيها حمامة أو دجاجة أو سنور نزح منها ما بين أربعين دلوا إلى ستين"]]},{"id":"q1_30","label":"كتاب الطهارة · الفقرة ٣٠","segs":[["matn","وإن مات فيها كلب أو شاة أو آدمي نزح جميع ما فيها من الماء"]]},{"id":"q1_31","label":"كتاب الطهارة · الفقرة ٣١","segs":[["matn","وإن انتفخ الحيوان فيها أو تفسخ نزح جميع ما فيها من الماء صغر الحيوان أو كبر"]]},{"id":"q1_32","label":"كتاب الطهارة · الفقرة ٣٢","segs":[["matn","وعدد الدلاء يعتبر بالدلو الوسط المستعمل للآبار في البلدان فإن نزح منها بدلو عظيم قدر ما يسع عشرين دلوا من الدلو الوسط احتسب به"]]},{"id":"q1_33","label":"كتاب الطهارة · الفقرة ٣٣","segs":[["matn","وإن كانت البئر معينا لا تنزح ما فيها من الماء أخرجوا مقدار ما كان فيها من الماء وقد روي عن محمد بن الحسن رحمه الله عليه أنه قال: ينزح منها مائتا دلو إلى ثلاثمائة دلو"]]},{"id":"q1_34","label":"كتاب الطهارة · الفقرة ٣٤","segs":[["matn","وإذا وجد في البئر أو غيرها ولا يدرون متى وقعت ولم تنتفخ ولم تتفسخ أعادوا صلاة يوم وليلة إذا كانوا توضئوا منها وغسلوا كل شيء أصابه ماءها"]]},{"id":"q1_35","label":"كتاب الطهارة · الفقرة ٣٥","segs":[["matn","وإن كانت انتفخت أو تفسخت أعادوا صلاة ثلاثة أيام ولياليها في قول أبي حنيفة رحمه الله وقال أبو يوسف ومحمد رحمهما الله: ليس عليهم إعادة شيء حتى يتحققوا متى وقعت"]]},{"id":"q1_36","label":"كتاب الطهارة · الفقرة ٣٦","segs":[["matn","وسؤر الآدمي وما يؤكل لحمه طاهر وسؤر الكلب والخنزير وسباع البهائم نجس وسؤر الهرة والدجاجة المخلاة وسباع الطير وما يسكن في البيوت مثل الحية والفأرة مكروه"]]},{"id":"q1_37","label":"كتاب الطهارة · الفقرة ٣٧","segs":[["matn","وسؤر الحمار والبغل مشكوك فيهما فإن لم يجد غيرهما توضأ بهما وتيمم بأيهما بدأ جاز"]]}]},{"id":"q2","title":"باب التيمم","group":"كتاب الطهارة","units":[{"id":"q2_1","label":"باب التيمم · الفقرة ١","segs":[["matn","ومن لم يجد الماء وهو مسافر أو خارج المصر بينه وبين المصر نحو الميل أو أكثر"]]},{"id":"q2_2","label":"باب التيمم · الفقرة ٢","segs":[["matn","أو كان يجد الماء إلا أنه مريض فخاف إن استعمل الماء اشتد مرضه أو خاف الجنب إن غسل بالماء أن يقتله البرد أو يمرضه فإنه يتيمم بالصعيد"]]},{"id":"q2_3","label":"باب التيمم · الفقرة ٣","segs":[["matn","والتيمم ضربتان: يمسح بإحداهما وجهه وبالأخرى يديه إلى المرفقين والتيمم من الجنابة والحدث سواء"]]},{"id":"q2_4","label":"باب التيمم · الفقرة ٤","segs":[["matn","ويجوز التيمم عند أبي حنيفة ومحمد بكل ما كان من جنس الأرض كالتراب والرمل والحجر والجص والنورة والكحل والزرنيخ"]]},{"id":"q2_5","label":"باب التيمم · الفقرة ٥","segs":[["matn","وقال أبو يوسف رحمه الله: لا يجوز إلا بالتراب والرمل خاصة"]]},{"id":"q2_6","label":"باب التيمم · الفقرة ٦","segs":[["matn","والنية فرض في التيمم مستحبة في الوضوء"]]},{"id":"q2_7","label":"باب التيمم · الفقرة ٧","segs":[["matn","وينقض التيمم كل شيء ينقض الوضوء وينقضه أيضا رؤية الماء إذا قدر على"]]},{"id":"q2_8","label":"باب التيمم · الفقرة ٨","segs":[["matn","استعماله ولا يجوز التيمم إلا بصعيد طاهر"]]},{"id":"q2_9","label":"باب التيمم · الفقرة ٩","segs":[["matn","ويستحب لمن لا يجد الماء وهو يرجو أن يجده في آخر الوقت أن يؤخر الصلاة إلى آخر الوقت فإن وجد الماء توضأ به وصلى وإلا تيمم"]]},{"id":"q2_10","label":"باب التيمم · الفقرة ١٠","segs":[["matn","ويصلي بتيممه ما شاء من الفرائض والنوافل"]]},{"id":"q2_11","label":"باب التيمم · الفقرة ١١","segs":[["matn","ويجوز التيمم للصحيح في المصر إذا حضرت جنازة والولي غيره فخاف إن اشتغل بالطهارة أن تفوته الصلاة فإنه يتيمم ويصلي وكذلك من حضر العيد فخاف إن اشتغل بالطهارة أن تفوته صلاة العيدين فإنه يتيمم ويصلي وإن خاف من شهد الجمعة إن اشتغل بالطهارة أن تفوته صلاة الجمعة لم يتيمم ولكنه يتوضأ فإن أدرك الجمعة صلاها وإلا صلى الظهر أربعا وكذلك إذا ضاق الوقت فخشي إن توضأ قات الوقت لم يتيمم ولكنه يتوضأ ويصلي فائتة"]]},{"id":"q2_12","label":"باب التيمم · الفقرة ١٢","segs":[["matn","والمسافر إذا نسي الماء في رحله فتيمم وصلى ثم ذكر الماء في الوقت لم يعد الصلاة عند أبي حنيفة ومحمد رحمهما الله"]]},{"id":"q2_13","label":"باب التيمم · الفقرة ١٣","segs":[["matn","وقال أبو يوسف: يعيدها"]]},{"id":"q2_14","label":"باب التيمم · الفقرة ١٤","segs":[["matn","وليس على المتيمم إذا لم يغلب على ظنه أن بقربه ماء أن يطلب الماء فإن غلب على ظنه أن هناك ماء لم يجز له أن يتيمم حتى يطلبه وإن كان مع رفيقه ماء طلبه منه قبل أن يتيمم فإن منعه منه تيمم وصلى"]]}]},{"id":"q3","title":"باب المسح على الخفين","group":"كتاب الطهارة","units":[{"id":"q3_1","label":"باب المسح على الخفين · الفقرة ١","segs":[["matn","المسح على الخفين جائز بالسنة من كل حدث موجب للوضوء إذا لبس الخفين على طهارة كاملة ثم أحدث"]]},{"id":"q3_2","label":"باب المسح على الخفين · الفقرة ٢","segs":[["matn","فإن كان مقيما مسح يوما وليلة وإن كان مسافرا مسح ثلاثة أيام ولياليها وابتداؤها عقيب الحدث"]]},{"id":"q3_3","label":"باب المسح على الخفين · الفقرة ٣","segs":[["matn","والمسح على الخفين على ظاهرهما خطوطا بالأصابع يبدأ من رؤوس أصابع الرجل إلى الساق"]]},{"id":"q3_4","label":"باب المسح على الخفين · الفقرة ٤","segs":[["matn","وفرض ذلك مقدار ثلاث أصابع من أصغر أصابع اليد"]]},{"id":"q3_5","label":"باب المسح على الخفين · الفقرة ٥","segs":[["matn","ولا يجوز المسح على خف فيه خرق كبير يبين منه مقدار ثلاث أصابع من أصابع الرجل وإن كان أقل من ذلك جاز"]]},{"id":"q3_6","label":"باب المسح على الخفين · الفقرة ٦","segs":[["matn","ولا يجوز المسح على الخفين لمن وجب عليه الغسل"]]},{"id":"q3_7","label":"باب المسح على الخفين · الفقرة ٧","segs":[["matn","ونقض المسح ما ينقض الوضوء وينقضه أيضا نزع الخف ومضي المدة فإذا مضت المدة نزع خفيه وغسل رجليه وصلى وليس عيه إعادة بقيه الوضوء"]]},{"id":"q3_8","label":"باب المسح على الخفين · الفقرة ٨","segs":[["matn","ومن ابتدأ المسح وهو مقيم فسافر قبل تمام يوم وليلة مسح ثلاثة أيام ولياليها ومن ابتدأ المسح وهو مسافر ثم أقام فإن كان مسح يوما وليلة أو أكثر لزمه نزع خفيه وغسل رجليه وإن كان مسح أقل من يوم وليلة تمم مسح يوم وليلة"]]},{"id":"q3_9","label":"باب المسح على الخفين · الفقرة ٩","segs":[["matn","ومن لبس الجرموق فوق الخف مسح عليه"]]},{"id":"q3_10","label":"باب المسح على الخفين · الفقرة ١٠","segs":[["matn","ولا يجوز المسح على الجوربين عند أبي حنيفة رحمه الله"]]},{"id":"q3_11","label":"باب المسح على الخفين · الفقرة ١١","segs":[["matn","إلا أن يكونا منعلين أو مجلدين وقال أبو يوسف ومحمد رحمهما الله: يجوز المسح على الجوربين إذا كانا ثخينين لا يشفان الماء"]]},{"id":"q3_12","label":"باب المسح على الخفين · الفقرة ١٢","segs":[["matn","ولا يجوز المسح على العمامة والقلنسوة والبرقع والقفازين"]]},{"id":"q3_13","label":"باب المسح على الخفين · الفقرة ١٣","segs":[["matn","ويجوز المسح على الجبائر وإن شدها على غير وضوء فإن سقطت عن غير برء لم يبطل المسح وإن سقطت عن برء بطل المسح"]]}]},{"id":"q4","title":"باب الحيض","group":"كتاب الطهارة","units":[{"id":"q4_1","label":"باب الحيض · الفقرة ١","segs":[["matn","أقل الحيض ثلاثة أيام ولياليها"]]},{"id":"q4_2","label":"باب الحيض · الفقرة ٢","segs":[["matn","وما نقض عن ذلك فليس بحيض وهو استحاضة"]]},{"id":"q4_3","label":"باب الحيض · الفقرة ٣","segs":[["matn","وأكثر الحيض عشرة أيام ولياليها وما زاد على ذلك فهو استحاضة"]]},{"id":"q4_4","label":"باب الحيض · الفقرة ٤","segs":[["matn","وما تراه المرأة من الحمرة والصفرة والكدرة في أيام الحيض فهو حيض حتى ترى البياض الخالص"]]},{"id":"q4_5","label":"باب الحيض · الفقرة ٥","segs":[["matn","والحيض يسقط عن الحائض الصلاة ويحرم عليها الصوم وتقضي الصوم ولا تضي الصلاة ولا تدخل المسجد ولا تطوف بالبيت ولا يأتيها زوجها"]]},{"id":"q4_6","label":"باب الحيض · الفقرة ٦","segs":[["matn","ولا يجوز لحائض ولا جنب قراءة القرآن"]]},{"id":"q4_7","label":"باب الحيض · الفقرة ٧","segs":[["matn","ولا يجوز لمحدث مس المصحف إلا أن يأخذه بغلافه"]]},{"id":"q4_8","label":"باب الحيض · الفقرة ٨","segs":[["matn","وإذا انقطع دم الحيض لأقل من عشرة أيام لم يجز وطؤها حتى تغتسل أو يمضي عليها وقت صلاة كامل فإن انقطع دمها لعشرة أيام جاز وطؤها قبل الغسل"]]},{"id":"q4_9","label":"باب الحيض · الفقرة ٩","segs":[["matn","والطهر إذا تخلل بين الدمين في مدة الحيض فهو كالدم الجاري"]]},{"id":"q4_10","label":"باب الحيض · الفقرة ١٠","segs":[["matn","وأقل الطهر خمسة عشر يوما ولا غاية لأكثره"]]},{"id":"q4_11","label":"باب الحيض · الفقرة ١١","segs":[["matn","ودم الإستحاضة هو ما تراه المرأة أقل من ثلاثة أيام أو أكثر من عشرة أيام فحكمه حكم الرعاف الدائم: لا يمنع الصوم ولا الصلاة ولا الوطء"]]},{"id":"q4_12","label":"باب الحيض · الفقرة ١٢","segs":[["matn","وإذا زاد الدم على عشرة أيام وللمرأة عادة"]]},{"id":"q4_13","label":"باب الحيض · الفقرة ١٣","segs":[["matn","معروفة ردت إلى أيام عادتها وما زاد على ذلك فهو استحاضة وإن ابتدأت مع البلوغ مستحاضة فيحضها عشرة أيام من كل شهر والباقي استحاضة"]]},{"id":"q4_14","label":"باب الحيض · الفقرة ١٤","segs":[["matn","والمستحاضة ومن به سلس البول والرعاف الدائم والجرح الذي لا يزقلأ يتوضئون لوقت كل صلاة فيصلون بذلك الوضوء في الوقت ما شاءوا من الفرائض والنوافل فإذا خرج الوقت بطل وضوءهم وكان عليهم استئناف الوضوء لصلاة أخرى"]]},{"id":"q4_15","label":"باب الحيض · الفقرة ١٥","segs":[["matn","والنفاس: هو الدم الخارج عقيب الولادة والدم الذي تراه الحامل وما تره المرأة في حال ولادتها قبل خروج الولد استحاضة"]]},{"id":"q4_16","label":"باب الحيض · الفقرة ١٦","segs":[["matn","وأقل النفاس لا حد له وأكثره أربعون يوما وما زاد على ذلك فهو استحاضة وإذا تجاوز الدم الأربعين وقد كانت هذه المرأة ولدت قبل ذلك ولها عادة في النفاس ردت إلى أيام عادتها وإن لم لها عادة فابتدأ نفاسها أربعون يوما ومن ولدت ولدين في بطن واحد"]]},{"id":"q4_17","label":"باب الحيض · الفقرة ١٧","segs":[["matn","فنفاسها ما خرج من الدم عقيب الولد الأول عند أبي حنيفة وأبي يوسف وقال محمد وزفر: نفاسها ما خرج من الدم عقيب الولد الثاني"]]}]},{"id":"q5","title":"باب الأنجاس","group":"كتاب الطهارة","units":[{"id":"q5_1","label":"باب الأنجاس · الفقرة ١","segs":[["matn","تطهير النجاسة واجب من بدن المصلي وثوبه"]]},{"id":"q5_2","label":"باب الأنجاس · الفقرة ٢","segs":[["matn","والمكان الذي يصلي عليه"]]},{"id":"q5_3","label":"باب الأنجاس · الفقرة ٣","segs":[["matn","ويجوز تطهير النجاسة بالماء وبكل مائع طاهر يمكن إزالتها به كالخل وماء الورد"]]},{"id":"q5_4","label":"باب الأنجاس · الفقرة ٤","segs":[["matn","وإذا أصابت الخف نجاسة ولها جرم فجفت فدلكه بالأرض جاز"]]},{"id":"q5_5","label":"باب الأنجاس · الفقرة ٥","segs":[["matn","والمني نجس يجب غسل رطبه فإذا جف على الثوب أجزأ فيه الفرك"]]},{"id":"q5_6","label":"باب الأنجاس · الفقرة ٦","segs":[["matn","والنجاسة إذا أصابت المرآة أو السيف اكتفي بمسحهما"]]},{"id":"q5_7","label":"باب الأنجاس · الفقرة ٧","segs":[["matn","وإذا أصابت الأرض نجاسة فجفت بالشمس وذهب أثرها جازت الصلاة بمكانها ولا يجوز التيمم منها"]]},{"id":"q5_8","label":"باب الأنجاس · الفقرة ٨","segs":[["matn","ومن أصابه من النجاسة المغلظة كالدم والبول والغائط والخمر مقدار الدرهم فما دونه جازت الصلاة معه فإن زاد لم تجز وإن أصابته نجاسة مخففة كبول ما يؤكل لحمه"]]},{"id":"q5_9","label":"باب الأنجاس · الفقرة ٩","segs":[["matn","جازت الصلاة معه ما لم يبلغ ربع الثوب"]]},{"id":"q5_10","label":"باب الأنجاس · الفقرة ١٠","segs":[["matn","وتطهير النجاسة التي يجب غسلها على وجهين: فما كان له منها مرئية زوال عينها إلا أن يبقى من أثرها ما يشق إزالته وما ليس له عني مرئية فطهارتها أن يغسل حتى يغلب على ظن الغاسل أنه قد طهر"]]},{"id":"q5_11","label":"باب الأنجاس · الفقرة ١١","segs":[["matn","والاستنجاء سنة يجزي فيها الحجر وما يقوم مقامه يمسحه حتى ينقه وليس فيه عدد مسنون وغسله بالماء أفضل فإن تجاوزت النجاسة مخرجها لم يجز فيه إلا الماء ولا يستنجي بعظم ولا بروث ولا بطعام ولا بيمينه إلا بعذر"]]}]},{"id":"q6","title":"كتاب الصلاة","group":"كتاب الصلاة","units":[{"id":"q6_1","label":"كتاب الصلاة · الفقرة ١","segs":[["matn","أول وقت الصبح إذا طلع الفجر الثاني وهو البياض المعترض في الأفق وآخر وقتها ما لت تتطلع الشمس وأول وقت الظهر إذا زالت الشمس وآخر وقتها عند أبي حنيفة إذا صار ظل كل شيء مثليه سوي فيء الزوال"]]},{"id":"q6_2","label":"كتاب الصلاة · الفقرة ٢","segs":[["matn","وقال أبو يوسف ومحمد: إذا صار ظل كل شيء مثله"]]},{"id":"q6_3","label":"كتاب الصلاة · الفقرة ٣","segs":[["matn","وأول وقت العصر إذا خرج وقت الظهر على القولين وآخر وقتها ما لم تغرب الشمس"]]},{"id":"q6_4","label":"كتاب الصلاة · الفقرة ٤","segs":[["matn","وأول وقت المغرب إذا فربت الشمس وآخر وقتها ما لم يغب الشفق وهو البياض الذي ف الأفق بعد الحمرة"]]},{"id":"q6_5","label":"كتاب الصلاة · الفقرة ٥","segs":[["matn","عند أبي حنيفة وقال أبو يوسف ومحمد: هو الحمرة وأول وقت العشاء إذا غاب الشفق وآخر وقتها ما لم يطلع الفجر وأول وقت الوتر بعد العشاء وآخر وقتها ما لم يطلع الفجر"]]},{"id":"q6_6","label":"كتاب الصلاة · الفقرة ٦","segs":[["matn","ويستحب الإسفار بالفجر والإبراد بالظهر في الصيف وتقديمها في الشتاء وتأخير العصر ما لم تتغير الشمس وتعجيل"]]},{"id":"q6_7","label":"كتاب الصلاة · الفقرة ٧","segs":[["matn","المغرب وتأخير العشاء إلى ما قبل ثلث الليل ويستحب في الوتر لمن يألف صلاة الليل أن يؤخر الوتر إلى آخر الليل فإن لم يثق بالانتباه أوتر قبل النوم"]]}]},{"id":"q7","title":"باب الأذان","group":"كتاب الصلاة","units":[{"id":"q7_1","label":"باب الأذان · الفقرة ١","segs":[["matn","الأذان سنة للصلوات الخمس والجمعة"]]},{"id":"q7_2","label":"باب الأذان · الفقرة ٢","segs":[["matn","دون ما سواها وصفة الأذان: أن يقول: الله أكبر الله أكبر - إلى آخره ولا ترجيع فيه ويزيد في أذان الفجر بعد الفلاح: الصلاة خير من النوم مرتين"]]},{"id":"q7_3","label":"باب الأذان · الفقرة ٣","segs":[["matn","والإقامة مثل الأذان إلا أنه يزيد فيها بعد الفلاح: قد قامت الصلاة مرتين"]]},{"id":"q7_4","label":"باب الأذان · الفقرة ٤","segs":[["matn","ويترسل في الأذان ويحدر في الإقامة ويستقبل بهما القبلة فإذا بلغ إلى الصلاة والفلاح حول وجهه يمينا وشمالا"]]},{"id":"q7_5","label":"باب الأذان · الفقرة ٥","segs":[["matn","ويؤذن للفائتة ويقيم فإن فاتته صلوات أذن للأولى وأقام وكان مخيرا في الباقية: إن شاء أذن وأقام وإن شاء اقتصر على الإقامة"]]},{"id":"q7_6","label":"باب الأذان · الفقرة ٦","segs":[["matn","وينبغي أن يؤذن ويقيم على طهر فإن أذن على غير وضوء جاز ويكره أن يقيم على غير وضوء أو يؤذن وهو جنب ولا يؤذن لصلاة قبل دخول وقتها"]]}]},{"id":"q8","title":"باب شروط الصلاة التي تتقدمها","group":"كتاب الصلاة","units":[{"id":"q8_1","label":"باب شروط الصلاة التي تتقدمها · الفقرة ١","segs":[["matn","يجب على المصلي أن يقدم الطهارة من الأحداث والأنجاس على ما قدمناه ويستر عورته والعورة من الرجل: ما تحت السرة إلى الركبة والركبة من العورة"]]},{"id":"q8_2","label":"باب شروط الصلاة التي تتقدمها · الفقرة ٢","segs":[["matn","وبدن المرأة الحرة كله عورة إلا وجهها وكفيها وقدميها وما كان عورة من الرجل فهو عروة من الأمة وبطنها وظهرها عورة وما سوى ذلك من بدنها فليس بعورة"]]},{"id":"q8_3","label":"باب شروط الصلاة التي تتقدمها · الفقرة ٣","segs":[["matn","ومن لم يجد ما يزل به النجاسة صلى معها ولم يعد الصلاة"]]},{"id":"q8_4","label":"باب شروط الصلاة التي تتقدمها · الفقرة ٤","segs":[["matn","ومن لم يجد ثوبا صلى عريانا قاعدا يومئ بالركوع والسجود فإن صلى قائما أجزاه والأول أفضل وينوي الصلاة التي يدخل فيها بنية لا يفصل بينها وبين"]]},{"id":"q8_5","label":"باب شروط الصلاة التي تتقدمها · الفقرة ٥","segs":[["matn","التحريمة بعمل ويستقبل القبلة إلا أن يكون خائفا فيصلي إلى أي جهة قدر فإن اشتبهت عليه القبلة وليس بحضرته من يسأله عنها اجتهد وصلى"]]},{"id":"q8_6","label":"باب شروط الصلاة التي تتقدمها · الفقرة ٦","segs":[["matn","فإن علم أنه أخطأ بإخبار بعد ما صلى فلا إعادة عليه وإن علم ذلك وهو في الصلاة استدار إلى القبلة وبنى عليها"]]}]},{"id":"q9","title":"باب صفة الصلاة","group":"كتاب الصلاة","units":[{"id":"q9_1","label":"باب صفة الصلاة · الفقرة ١","segs":[["matn","فرائض الصلاة ستة: التحريمة والقيام والقرءة والركوع والسجود والقعدة الأخيرة مقدار التشهد"]]},{"id":"q9_2","label":"باب صفة الصلاة · الفقرة ٢","segs":[["matn","وما زاد على ذلك فهو سنة فإذا دخل الرجل في الصلاة كبر ورفع يديه مع التكبير حتى يحاذى بإبهاميه شحمتي أذنيه فإن قال بدلا من التكبير: الله أجل أو أعظم"]]},{"id":"q9_3","label":"باب صفة الصلاة · الفقرة ٣","segs":[["matn","أو الرحمن أكبر أجزأه عند أبي حنيفة ومحمد وقال أبو يوسف: لا يجزئه إلا بلفظ التكبير ويعتمد بيده اليمنى على اليسرى ويضعهما تحت سرته ثم يقول: سبحانك اللهم وبحمدك وتبارك اسمك وتعلى جدك ولا إله غيرك ويستعيذ بالله من الشيطان الرجيم ويقرأ بسم الله الرحمن الرحيم ويسر بهما ثم يقرأ فاتحة الكتاب وسورة معها أو ثلاث آيات من أي سورة شاء وإذا قال الإمام {ولا الضالين} قال: آمين ويقولها ويخفونها ثم يكبر ويركع"]]},{"id":"q9_4","label":"باب صفة الصلاة · الفقرة ٤","segs":[["matn","ويعتمد بيديه على ركبتيه ويفرج أصابعه ويبسط ظهره ولا يرفع رأسه ولا ينكسه ويقول في ركوعه: سبحان ربي العظيم ثلاثا وذلك أذناه ثم يرفع رأسه ويقول: وسجد واعتمد بيديه على الأرض ووضع وجهه بين كفيه وسجد على أنفه وجبهته فإن اقتصر على أحدهما جاز عند أبي حنيفة"]]},{"id":"q9_5","label":"باب صفة الصلاة · الفقرة ٥","segs":[["matn","وقال أبو يوسف ومحمد: لا يجوز الاقتصار على الأنف إلا من عذر وإن سجد على كور عمامته أو فاضل ثوبه جاز ويبدي ضبعيه ويجافي بطنه عن فخذيه ويوجه أصابع رجليه نحو القبله ويقول في سجوده: سبحان ربي الأعلى ثلاثا وذلك أدناه ثم يرفع رأسه"]]},{"id":"q9_6","label":"باب صفة الصلاة · الفقرة ٦","segs":[["matn","ويكبر فإذا اطمأن جالسا كبر وسجد فإذا اطمأن ساجدا كبر واستوى قائما على صدور قدميه ولا يقعد ولا يعتمد بيديه على الأرض"]]},{"id":"q9_7","label":"باب صفة الصلاة · الفقرة ٧","segs":[["matn","ويفعل في الركعة الثانية مثل ما فعل في الأولى إلا أنه لا يستفتح ولا يتعوذ ولا يرفع يديه إلا في التكبير الأولى"]]},{"id":"q9_8","label":"باب صفة الصلاة · الفقرة ٨","segs":[["matn","فإذا رفع رأسه من السجدة الثانية في الركعة الثانية افترش رجله اليسرى فجلس عليها ونصب اليمنى نصبا ووجه أصابعه نحو القبله ووضع يديه على فخذيه وبسط أصابعة وتشهد"]]},{"id":"q9_9","label":"باب صفة الصلاة · الفقرة ٩","segs":[["matn","والتشهد أن يقول: التحيات لله والصلوات والطيبات السلام عليك أيها النبي ورحمة الله وبركاته السلام علينا وعلى عباد الله الصالحين أشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله ولا يزيد على هذا في القعدة الأولى"]]},{"id":"q9_10","label":"باب صفة الصلاة · الفقرة ١٠","segs":[["matn","ويقرأ في الركعتين الأخريين الكتاب خاصة فإذا جلس في آخر الصلاة جلس كما في الأولى وتشهد وصلى على النبي صلى الله عليه وسلم ودعا بما شاء بما يشبه ألفاظ القرآن والأدعيه المأثورة ولا يدعو بما يشبه كلام الناس ثم يسلم عن يمينه فيقول: السلام عليكم ورحمة الله وعن يساره مثل ذلك"]]},{"id":"q9_11","label":"باب صفة الصلاة · الفقرة ١١","segs":[["matn","ويجهز بالقرءة في الفجر والركعتين"]]},{"id":"q9_12","label":"باب صفة الصلاة · الفقرة ١٢","segs":[["matn","الأوليين من المغرب والعشاء إن كان إماما ويخفي القراءة فيما بعد الأوليين وإن كان منفردا فهو مخير: إن شاء جهر وأسمع نفسه وإن شاء خافت ويخفي الإمام القرءة في الظهر والعصر"]]},{"id":"q9_13","label":"باب صفة الصلاة · الفقرة ١٣","segs":[["matn","والوتر: ثلاث ركعات لا يفصل بينها بسلام"]]},{"id":"q9_14","label":"باب صفة الصلاة · الفقرة ١٤","segs":[["matn","ويقنت في الثالثه قبل الركوع في جميع السنة ويقرأ في كل ركعة من الوتر بفاتحة الكتاب وسورة معها فإذا أراد أن يقنت كبر ورفع يديه ثم قنت"]]},{"id":"q9_15","label":"باب صفة الصلاة · الفقرة ١٥","segs":[["matn","ولا يقنت في صلاة غيرها"]]},{"id":"q9_16","label":"باب صفة الصلاة · الفقرة ١٦","segs":[["matn","وليس في شيء من الصلوات قراءة سورة بعينها لا يجزئ غيرها ويكره أن يتخذ سورة بعينها لصلاة لا يقرأ فيها غيرها"]]},{"id":"q9_17","label":"باب صفة الصلاة · الفقرة ١٧","segs":[["matn","وأدنى ما يجزئ من القراءة في الصلاة ما يتناوله اسم القرآن عند أبي حنيفة"]]},{"id":"q9_18","label":"باب صفة الصلاة · الفقرة ١٨","segs":[["matn","وقال يوسف ومحمد: لا يجزئ أقل من ثلاث آيات قصار أو آية طويلة"]]},{"id":"q9_19","label":"باب صفة الصلاة · الفقرة ١٩","segs":[["matn","ولا يقرأ المؤتم خلف الإمام"]]},{"id":"q9_20","label":"باب صفة الصلاة · الفقرة ٢٠","segs":[["matn","ومن أراد الدخول في صلاة غيره يحتاج إلى نيتين: نية الصلاة ونية المتابعة"]]},{"id":"q9_21","label":"باب صفة الصلاة · الفقرة ٢١","segs":[["matn","والجماعة: سنة مؤكدة وأولى الناس بالإمامة أعلمهم"]]},{"id":"q9_22","label":"باب صفة الصلاة · الفقرة ٢٢","segs":[["matn","بالسنة فإن تساووا فأقرهم فإن تساووا فأورعهم فإن تساووا فأسنهم"]]},{"id":"q9_23","label":"باب صفة الصلاة · الفقرة ٢٣","segs":[["matn","ويكره تقديم العبد والأعرابي والفاسق والأعمى وولد الزنا فإن تقدموا جاز"]]},{"id":"q9_24","label":"باب صفة الصلاة · الفقرة ٢٤","segs":[["matn","وينبغي للإمام أن لا يطول بهم الصلاة"]]},{"id":"q9_25","label":"باب صفة الصلاة · الفقرة ٢٥","segs":[["matn","ويكره للنساء أن يصلين وحدهن جماعة فإن فعلن وقفت الإمام وسطهن"]]},{"id":"q9_26","label":"باب صفة الصلاة · الفقرة ٢٦","segs":[["matn","ومن صلى مع واحد أقامه عن يمينه"]]},{"id":"q9_27","label":"باب صفة الصلاة · الفقرة ٢٧","segs":[["matn","فإن كان اثنين تقدم عليهما"]]},{"id":"q9_28","label":"باب صفة الصلاة · الفقرة ٢٨","segs":[["matn","ولا يجوز للرجال أن يقتدوا بامرأة أو صبي"]]},{"id":"q9_29","label":"باب صفة الصلاة · الفقرة ٢٩","segs":[["matn","ويصف الرجال ثم الصبيان ثم النساء"]]},{"id":"q9_30","label":"باب صفة الصلاة · الفقرة ٣٠","segs":[["matn","فإن قامت امرأة إلى جنب رجل وهما مشتركان في صلاة واحدة فسدت صلاته"]]},{"id":"q9_31","label":"باب صفة الصلاة · الفقرة ٣١","segs":[["matn","ويكره للنساء حضور الجماعة ولا بأس بأن تخرج العجوز في الفجر والمغرب والعشاء عند أبي حنيفة وقال أبو يوسف ومحمد يجوز خروج العجوز في كل"]]},{"id":"q9_32","label":"باب صفة الصلاة · الفقرة ٣٢","segs":[["matn","صلاة ولا يصلي الطاهر خلف من به سلس البول ولا الطاهرات خلف المستحاضة ولا القارئ خلف الأمي ولا المكتسي خلف العريان ويجوز أن يؤم المتيمم المتوضئين والماسح على الخفين الغاسلين ويصلي القائم خلف القاعد ولا يصلي الذي يركع ويسجد خلف الموميء ولا يصلي المفترض خلف المتنقل ولا من يصلي فرضا خلف من يصلي فرضا آخر ويصلي المتنقل خلف المفترض"]]},{"id":"q9_33","label":"باب صفة الصلاة · الفقرة ٣٣","segs":[["matn","ومن اقتدى بإمام ثم علم أنه على غير وضوء"]]},{"id":"q9_34","label":"باب صفة الصلاة · الفقرة ٣٤","segs":[["matn","إعاد الصلاة ويكره للمصلي أن يعبث بثوبه أو بجسدهن ولا يقلب الحصى إلا أن لا يمكنه السجود فيسويه مرة واحدة ولا يفرقع أصابعه ولا يتخصر ولا يسدل ثوبه ولا يعقص شعره ولا يكف ثوبه"]]},{"id":"q9_35","label":"باب صفة الصلاة · الفقرة ٣٥","segs":[["matn","ولا يلتفت ولا يقعي ولا يرد السلام بلسانه ولا بيده ولا يتربع إلا من عذر ولا يأكل ولا يشرب"]]},{"id":"q9_36","label":"باب صفة الصلاة · الفقرة ٣٦","segs":[["matn","فإن سبقه الحدث انصرف فإن كان إماما استخلف وتوضأ وبنى على صلاته والاستئناف أفضل"]]},{"id":"q9_37","label":"باب صفة الصلاة · الفقرة ٣٧","segs":[["matn","وإن نام فاحتلم أو جن أو أغمي عليه أو قهقه استأنف الوضوء والصلاة"]]},{"id":"q9_38","label":"باب صفة الصلاة · الفقرة ٣٨","segs":[["matn","وإن تكلم في صلاته عامدا أو ساهيا بطلت صلاته"]]},{"id":"q9_39","label":"باب صفة الصلاة · الفقرة ٣٩","segs":[["matn","وإن سبقه الحدث بعد التشهد توضأ وسلم وإن تعمد الحدث في هذه الحالة أو تكلم أو عمل عملا ينافي الصلاة تمت صلاته"]]},{"id":"q9_40","label":"باب صفة الصلاة · الفقرة ٤٠","segs":[["matn","وإن رأى المتيمم الماء في صلاته بطلب صلاته"]]},{"id":"q9_41","label":"باب صفة الصلاة · الفقرة ٤١","segs":[["matn","وإن رآه بعدما قعد قدر التشهد أو كان ماسحا على الخفين فانقضت مدة مسحه أو خلع حفيه بعمل رفيق أو كان أميا فتعلم سورة أو عريانا فوجد ثوبا أو موميا فقدر على الركوع والسجود أو تذكر أن عليه صلاة قبل هذه الصلاة أو وقت العصر في الجمعة أو كان ماسحا على الجبيرة فسقطت عن برء أو كان صاحب عذر فانقطع عذره"]]},{"id":"q9_42","label":"باب صفة الصلاة · الفقرة ٤٢","segs":[["matn","بطلت صلاته في قول أبي حنيفة وقال أبو يوسف ومحمد: تمت صلاته"]]}]},{"id":"q10","title":"باب قضاء الفوائت","group":"كتاب الصلاة","units":[{"id":"q10_1","label":"باب قضاء الفوائت · الفقرة ١","segs":[["matn","ومن فاتته الصلاة قضاها إذا ذكرها وقدمها لزوما على صلاة الوقت إلا أن يخاف فوات صلاة الوقت فيقدم صلاة الوقت ثم يقضيها فإن فاتته صلوات رتبها في القضاء كما وجبت في الأصل إلا أن تزيد الفوائت على ست صلوات فيسقط الترتيب فيها"]]}]},{"id":"q11","title":"باب الأوقات التي تكره فيها الصلاة","group":"كتاب الصلاة","units":[{"id":"q11_1","label":"باب الأوقات التي تكره فيها الصلاة · الفقرة ١","segs":[["matn","لا تجوز الصلاة عند طلوع الشمس ولا عند قيامها في الظهيرة ولا عند غروبها ولا يصلي على جنازة ولا يسجد للتلاوة إلا عصر يومه عند غروب الشمس"]]},{"id":"q11_2","label":"باب الأوقات التي تكره فيها الصلاة · الفقرة ٢","segs":[["matn","ويكره أن يتنفل بعد صلاة الفجر حتى تطلع الشمس وبعد صلاة العصر حتى تغرب الشمس ولا بأس بأن يصلي في هذين الوقتين الفوائت ويسجد للتلاوة ويصلي على الجنازة"]]},{"id":"q11_3","label":"باب الأوقات التي تكره فيها الصلاة · الفقرة ٣","segs":[["matn","ولا يصلي ركعتي الطواف"]]},{"id":"q11_4","label":"باب الأوقات التي تكره فيها الصلاة · الفقرة ٤","segs":[["matn","ويكره أن يتنقل بعد طلوع الفجر بأكثر من ركعتي الفجر ولا يتنقل قبل المغرب"]]}]},{"id":"q12","title":"باب النوافل","group":"كتاب الصلاة","units":[{"id":"q12_1","label":"باب النوافل · الفقرة ١","segs":[["matn","السنة في الصلاة أن يصلي ركعتين بعد طلوع الفجر وأربعا قبل الظهر وركعتين بعدها وأربعا قبل العصر وإن شاء ركعتين وركعتين بعد المغرب وأربعا قبل العشاء وأربعا بعدها وإن شاء ركعتين"]]},{"id":"q12_2","label":"باب النوافل · الفقرة ٢","segs":[["matn","ونوافل النهار إن شاء صلى ركعتين بتسليمة واحدة وإن شاء أربعا وتكره الزيادة على ذلك"]]},{"id":"q12_3","label":"باب النوافل · الفقرة ٣","segs":[["matn","فأما نافلة الليل فقال أبو حنيفة إن صلى ثمان ركعات بتسليمة واحدة جاز وتكره الزيادة على ذلك وقال أبو يوسف ومحمد: لا يزيد بالليل على ركعتين بتسليمة واحدة"]]},{"id":"q12_4","label":"باب النوافل · الفقرة ٤","segs":[["matn","والقراءة في الفرض واجبة في الركعتين الأوليين وهو مخير في الأخريين إن شاء قرأ وإن شاء سبح وإن شاء سكت"]]},{"id":"q12_5","label":"باب النوافل · الفقرة ٥","segs":[["matn","والقراءة واجبة في جميع ركعات النفل وفي جميل الوتر ومن دخل في صلاة النفل ثم أفسدها قضاها"]]},{"id":"q12_6","label":"باب النوافل · الفقرة ٦","segs":[["matn","فإن صلى أربع ركعات وقعد في الأوليين ثم أفسد الأخريين قضى ركعتين"]]},{"id":"q12_7","label":"باب النوافل · الفقرة ٧","segs":[["matn","ويصلي النافلة قاعدا مع القدرة على القيام وإن افتتحها قائما ثم قعد جاز عند أبي حنيفة"]]},{"id":"q12_8","label":"باب النوافل · الفقرة ٨","segs":[["matn","وقال أبو يوسف ومحمد: لا يجوز إلا من عذر"]]},{"id":"q12_9","label":"باب النوافل · الفقرة ٩","segs":[["matn","ومن كان خارج المصر يجوز أن ينتقل على دابته إلى أي جهة توجهت يومئ إيماء"]]}]},{"id":"q13","title":"باب السجود السهو","group":"كتاب الصلاة","units":[{"id":"q13_1","label":"باب السجود السهو · الفقرة ١","segs":[["matn","سجود السهو واجب في الزيادة والنقصان بعد السلام ثم يسجد سجدتين ثم يشهد ويسلم"]]},{"id":"q13_2","label":"باب السجود السهو · الفقرة ٢","segs":[["matn","والسهو يلزم إذا راد في صلاته فعلا من جنسها ليس منها أو ترك فعلا مسنونا أو ترك قراءة فاتحة الكتاب أو القنوت أو التشهد أو تكبيرات العيدين أو جهز الإمام فيما يخافت أو خافت فيما يجهر"]]},{"id":"q13_3","label":"باب السجود السهو · الفقرة ٣","segs":[["matn","وسهو الإمام يوجب على المؤتم السجودن فإن لم يسجد الإمام لم يسجد المؤتم وإن سها المؤتم لم يلزم الإمام ولا المؤتم السجود"]]},{"id":"q13_4","label":"باب السجود السهو · الفقرة ٤","segs":[["matn","ومن سها عن القعدة الأولى ثم تذكر وهو إلى حال القعود أقرب عاد فجلس وتشهد وإن كان إلى حال القيام أقرب لم يعد"]]},{"id":"q13_5","label":"باب السجود السهو · الفقرة ٥","segs":[["matn","ويسجد للسهو ومن سها عن القعدة الأخيرة فقام إلى الخامسة رجع إلى القعدة ما لم يسجد وألغى الخامسة ويسجد للسهو وإن قيد الخامسة بسجدة بطل فرضه وتحولت صلاته نفلا وكان عليه أن يضم إليها ركعة سادسة"]]},{"id":"q13_6","label":"باب السجود السهو · الفقرة ٦","segs":[["matn","وإن قعد في الرابعة قدر التشهد ثم قام ولم يسلم يظنها القعدة الأولى عاد إلى القعود ما لم يسجد في الخامسة ويسلم وإن قيد الخامسة بسجدة ضم"]]},{"id":"q13_7","label":"باب السجود السهو · الفقرة ٧","segs":[["matn","إليها ركعة أخرى ويسجد للسهو وقد تمت صلاته والركعتان له نافله"]]},{"id":"q13_8","label":"باب السجود السهو · الفقرة ٨","segs":[["matn","ومن شك في صلاته فلم يدر أثلاثا صلى أم أربعا وكان ذلك أول ما عرض له استأنف الصلاة فإن كان الشك يعرض له كثيرا بنى على غالب ظنه إن كان له ظن فإن لم يكن له ظن بنى على اليقين"]]}]},{"id":"q14","title":"باب صلاة المريض","group":"كتاب الصلاة","units":[{"id":"q14_1","label":"باب صلاة المريض · الفقرة ١","segs":[["matn","إذا تعذر على المريض القيام صلى قاعدا يركع ويسجد فإن لم يستطع الركوع والسجود أومأ إيماء برأسه وجعل السجود أخفض من الركوع"]]},{"id":"q14_2","label":"باب صلاة المريض · الفقرة ٢","segs":[["matn","ولا يرفع إلى وجهه شيئا يسجد عليه"]]},{"id":"q14_3","label":"باب صلاة المريض · الفقرة ٣","segs":[["matn","فإن لم يستطع القعود استلقى على ظهره وجعل رجله إلى القبلة وأومأ بالركوع والسجود وإن استلقى على جنبه ووجهه إلى القبلة وأومأ جاز فإن لم يستطع الإيماء برأسه أخر الصلاة ولا يومئ بعينه ولا بقلبه ولا بحاجبيه فإن قدر على القيام ولم يقدر على الركوع والسجود لم يلزمه القيام"]]},{"id":"q14_4","label":"باب صلاة المريض · الفقرة ٤","segs":[["matn","وجاز أن يصلي قاعدا يومئ إيماء فإن صلى الصحيح بعض صلاته قائما ثم حدث به مرض"]]},{"id":"q14_5","label":"باب صلاة المريض · الفقرة ٥","segs":[["matn","أتمها قاعدا يركع ويسجد أو يومئ إن لم يستطع الركوع والسجود أو مستلقيا إن لم يستطع القعود فإن صلى بإيماء ثم قدر على الركوع والسجود استأنف الصلاة"]]},{"id":"q14_6","label":"باب صلاة المريض · الفقرة ٦","segs":[["matn","ومن أغمي عليه خمس صلوات فما دونها قضاها إذا صح فإن فاتته بالإغماء أكثر من ذلك لم يقض"]]}]},{"id":"q15","title":"باب سجود التلاوة","group":"كتاب الصلاة","units":[{"id":"q15_1","label":"باب سجود التلاوة · الفقرة ١","segs":[["matn","سجود التلاوة في القرآن أربعة عشر: في"]]},{"id":"q15_2","label":"باب سجود التلاوة · الفقرة ٢","segs":[["matn","آخر الأعراف وفي الرعد والنحل وبني إسرائيل ومريم والأولى من الحج والفرقان والنمل و {الم * تنزيل} وص {حم} السجدة و {إذا السماء انشقت} و {اقرأ باسم ربك}"]]},{"id":"q15_3","label":"باب سجود التلاوة · الفقرة ٣","segs":[["matn","والسجود واجب في هذه المواضع كلها على التالي والسامع سواء قصد سماع القرآن أولم يقصد وإذا تلا الإمام آية السجدة سجدها وسجد المأموم معه وإن تلا المأموم لم يسجد الإمام ولا المأموم"]]},{"id":"q15_4","label":"باب سجود التلاوة · الفقرة ٤","segs":[["matn","وإن سمعوا وهم في الصلاة آية سجدة من رجل ليس معهم في الصلاة لم يسجدوها في الصلاة وسجدوها بعد الصلاة فإن سجدوها في الصلاة لم تجزهم"]]},{"id":"q15_5","label":"باب سجود التلاوة · الفقرة ٥","segs":[["matn","ولم فسد صلاتهم ومن تلا آية سجدة فلم يسجدها حتى دخل في الصلاة فتلاها وسجد لها أجزأته السجدة عن التلاوتين وإن تلاها في غير الصلاة فسجد لها ثم دخل في الصلاة فتلاها سجد لها ولت تجزه السجدة الأولى ومن كرر تلاوة سجدة واحدة في مجلس واحد أجزأته سجدة واحدة"]]},{"id":"q15_6","label":"باب سجود التلاوة · الفقرة ٦","segs":[["matn","ومن أراد السجود كبر ولم يرفع يديه وسجد ثم كبر ورفع رأسه ولا تشهد عليه ولا سلام"]]}]},{"id":"q16","title":"باب صلاة المسافر","group":"كتاب الصلاة","units":[{"id":"q16_1","label":"باب صلاة المسافر · الفقرة ١","segs":[["matn","السفر الذي تتغير به الأحكام: أن يقصد الإنسان موضا بينه وبين ذلك الموضع مسيرة ثلاثة أيام ولياليها بسير الإبل ومشي الأقدام ولا يعتبر ذلك بالسير في الماء"]]},{"id":"q16_2","label":"باب صلاة المسافر · الفقرة ٢","segs":[["matn","وفرض المسافر عندنا: في كل صلاة رباعية ركعتان لا تجوز له الزيادة عليهما فإن صلى أربعا وقد قعد في الثانية مقدار التشهد أجزأته ركعتان عن فرضه وكانت الأخريان له نافلة وإن لم يقعد مقدار التشهد في الركعتين الأوليين بطلت صلاته"]]},{"id":"q16_3","label":"باب صلاة المسافر · الفقرة ٣","segs":[["matn","ومن خرج مسافرا صلى وكعتين إذا فارق بيوت المصر ولا يزال على حكم السفر حتى ينوي الإقامة في بلد خمسة عشر يوما فصاعدا فيلزمه الإتمام وإن نوى الإقامة أقل من ذلك لم يتم"]]},{"id":"q16_4","label":"باب صلاة المسافر · الفقرة ٤","segs":[["matn","ومن دخل بلدا ولم ينو أن يقيم فيه خمسة عشر يوما وإنما يقول غدا أخرج أو بعد غد أخرج حتى بقي على ذلك سنين صلى ركعتين"]]},{"id":"q16_5","label":"باب صلاة المسافر · الفقرة ٥","segs":[["matn","وإذا دخل العسكر أرض الحرب فنووا الإقامة بها خمسة عشر يوما لم يتموا الصلاة"]]},{"id":"q16_6","label":"باب صلاة المسافر · الفقرة ٦","segs":[["matn","وإذا دخل المسافر في صلاة المقيم مع بقاء الوقت أتم الصلاة"]]},{"id":"q16_7","label":"باب صلاة المسافر · الفقرة ٧","segs":[["matn","وإن دخل معه في فائتة لم تجز صلاته خلفه"]]},{"id":"q16_8","label":"باب صلاة المسافر · الفقرة ٨","segs":[["matn","وإذا صلى المسافر بالمقيمين ركعتين سلم ثم أتم المقيمون صلاتهم ويستحب له إذا سلم أن يقول: أتموا صلاتكم فإنا قوم سفر وإذا دخل المسافر مصرة أتم الصلاة وإن لم ينو الإقامة فيه"]]},{"id":"q16_9","label":"باب صلاة المسافر · الفقرة ٩","segs":[["matn","ومن كان له وطن فانتقل عنه واستوطن غيره ثم سافر فدخل وطنه الأول لم يتم الصلاة وإذا نوى المسافر أن يقيم بمكة ومنى خمسة عشر يوما لم يتم الصلاة"]]},{"id":"q16_10","label":"باب صلاة المسافر · الفقرة ١٠","segs":[["matn","ومن فاتته صلاة في السفر قضاها في الحضر ركعتين"]]},{"id":"q16_11","label":"باب صلاة المسافر · الفقرة ١١","segs":[["matn","ومن فاتته صلاة في الحضر قضاها في السفر أربعا"]]},{"id":"q16_12","label":"باب صلاة المسافر · الفقرة ١٢","segs":[["matn","والعاصي والمطيع في السفر في الرخصة سواء"]]}]},{"id":"q17","title":"باب صلاة الجمعة","group":"كتاب الصلاة","units":[{"id":"q17_1","label":"باب صلاة الجمعة · الفقرة ١","segs":[["matn","لا تصح الجمعة إلا بمصر جامع أو في مصلى المصر"]]},{"id":"q17_2","label":"باب صلاة الجمعة · الفقرة ٢","segs":[["matn","ولا تجوز في القرى ولا تجوز إقامتها إلا بالسطان أو من أمره السلطان"]]},{"id":"q17_3","label":"باب صلاة الجمعة · الفقرة ٣","segs":[["matn","ومن شرائطها: الوقت فتصح في الوقت ولا تصح بعده"]]},{"id":"q17_4","label":"باب صلاة الجمعة · الفقرة ٤","segs":[["matn","ومن شرائطها الخطبة قبل الصلاة يخطب الإمام خطبتين يفصل بينهما بقعدة ويخطب قائما على طهارة فإن اقتصر على ذكر الله تعالى جاز عند أبي حنيفة"]]},{"id":"q17_5","label":"باب صلاة الجمعة · الفقرة ٥","segs":[["matn","وقال أبو يوسف ومحمد: لا بد من ذكر طويل يسمى خطبة وإن خطب قاعدا أو على غير طهارة جاز ويكره ومن شرائطها: الجماعة وأقلهم عند أبي حنيفة"]]},{"id":"q17_6","label":"باب صلاة الجمعة · الفقرة ٦","segs":[["matn","ثلاثة سوى الإمام وقال أبو يوسف ومحمد: اثنان سوى الإمام ويجهر الإمام بالقراءة في الركعتين وليس فيهما قراءة سورة بعينها"]]},{"id":"q17_7","label":"باب صلاة الجمعة · الفقرة ٧","segs":[["matn","ولا تجب الجمعة على مسافر ولا امرأة ولا مريض ولا عبد ولا أعمى فإن حضروا وصلوا مع الناس أجزاهم عن فرض الوقت"]]},{"id":"q17_8","label":"باب صلاة الجمعة · الفقرة ٨","segs":[["matn","ويجوز للمسافر والعبد والمريض ونحوهم أن يؤم في الجمعة"]]},{"id":"q17_9","label":"باب صلاة الجمعة · الفقرة ٩","segs":[["matn","ومن صلى الظهر في منزله يوم الجمعة قبل صلاة الإمام ولا عذر له كره له ذلك وجازت صلاته فإن بدا له أن يحضر الجمعة فتوجه إليها بطلب صلاة الظهر"]]},{"id":"q17_10","label":"باب صلاة الجمعة · الفقرة ١٠","segs":[["matn","عند أبي حنيفة بالسعي وقال أبو يوسف ومحمد: لا تبطل حتى يدخل مع الإمام"]]},{"id":"q17_11","label":"باب صلاة الجمعة · الفقرة ١١","segs":[["matn","ويكره أن يصلي المعذورون الظهر بجماعة يوم الجمعة وكذلك أهل السجن"]]},{"id":"q17_12","label":"باب صلاة الجمعة · الفقرة ١٢","segs":[["matn","ومن أدرك الإمام يوم الجمعة صلى معه ما أدرك وبنى عليها الجمعة وإن أدركه في التشهد أو في سجود السهو بنى عليها الجمعة عند أبي حنيفة وأبي يوسف وقال محمد: إن أدرك معه أكثر الركعة الثانية بنى عليها الجمعة وإن أدرك أقلها بنى عليها الظهر"]]},{"id":"q17_13","label":"باب صلاة الجمعة · الفقرة ١٣","segs":[["matn","وإذا خرج الإمام على المنبر يوم الجمعة ترك الناس الصلاة والكلام حتى يفرغ من خطبته وإذا أذن المؤذنون يوم الجمعة الأذان الأول ترك الناس البيع والشراء وتوجهوا إلى صلاة الجمعة"]]},{"id":"q17_14","label":"باب صلاة الجمعة · الفقرة ١٤","segs":[["matn","فإذا صعد الإمام المنبر جلس وأذن المؤذنون بين يدي المنبر فإذا فرغ من خطبته أقاموا الصلاة وصلوا"]]}]},{"id":"q18","title":"باب صلاة العيدين","group":"كتاب الصلاة","units":[{"id":"q18_1","label":"باب صلاة العيدين · الفقرة ١","segs":[["matn","ويستحب في يوم الفطر: أن يطعم الإنسان قبل الخروج إلى المصلى ويغتسل ويتطيب ويتوجه إلى المصلى ولا يكبر في طريق المصلى عند أبي حنيفة وعندها يكبر"]]},{"id":"q18_2","label":"باب صلاة العيدين · الفقرة ٢","segs":[["matn","ولا يتنقل في المصلى قبل صلاة العيد فإذا حلت الصلاة من ارتفاع الشمس دخل وقتها إلى الزوال فإذا زالت الشمس خرج وقتها"]]},{"id":"q18_3","label":"باب صلاة العيدين · الفقرة ٣","segs":[["matn","ويصلي الإمام بالناس ركعتين: يكبر في الأولى تكبيرة الأفتتاح وثلاثا بعدها ثم يقرأ فاتحة الكتاب وسورة معها ثم يكبر تكبيرة يركع بها ثم يبتدئ في الركعة الثانية بالقراءة كبر ثلاث تكبيرات وكبر تكبيرة رابعة يركع بها ويرفع يديه في تكبيرات العيدين ثم يخطب بعد الصلاة خطبتين يعلم الناس فيها صدقة الفطر وأحكامها"]]},{"id":"q18_4","label":"باب صلاة العيدين · الفقرة ٤","segs":[["matn","ومن فاتته صلاة العيد مع الإمام لم يقضها"]]},{"id":"q18_5","label":"باب صلاة العيدين · الفقرة ٥","segs":[["matn","فإن غم الهلال على الناس فشهدوا عند الإمام برؤية الهلال بعد الزوال صلى العيد من الغد فإن حدث عذر منع الناس من الصلاة في اليوم الثاني لم يصلها بعده"]]},{"id":"q18_6","label":"باب صلاة العيدين · الفقرة ٦","segs":[["matn","ويستحب في يوم الأضحى: أن يغتسل ويتطيب ويؤخر الأكل حتى يفرغ من الصلاة ويتوجه إلى المصلى وهو يكبر"]]},{"id":"q18_7","label":"باب صلاة العيدين · الفقرة ٧","segs":[["matn","ويصلي الأضحى ركعتين كصلاة الفطر ويخطب بعدها خطبيتن يعلم الناس فيهما الأضحية وتكبيرات التشريق فإن حدث عذر منع الناس من الصلاة في يوم الأضحى صلاها من الغد وبعد الغد ولا يصليها بعد ذلك"]]},{"id":"q18_8","label":"باب صلاة العيدين · الفقرة ٨","segs":[["matn","وتكبير التشريق أوله عقيب صلاة الفجر من يوم"]]},{"id":"q18_9","label":"باب صلاة العيدين · الفقرة ٩","segs":[["matn","عرفة وآخره عقيب صلاة العصر من النحر عند أبي حنيفة وقال أبو يوسف ومحمد: إلى صلاة العصر"]]},{"id":"q18_10","label":"باب صلاة العيدين · الفقرة ١٠","segs":[["matn","من آخر أيام التشريق"]]},{"id":"q18_11","label":"باب صلاة العيدين · الفقرة ١١","segs":[["matn","والتكبير عقيب الصلوات المفروضات وهو أن يقول: الله أكبر الله أكبر لا إله إلا الله والله أكبر الله أكبر ولله الحمد"]]}]},{"id":"q19","title":"باب صلاة الكسوف","group":"كتاب الصلاة","units":[{"id":"q19_1","label":"باب صلاة الكسوف · الفقرة ١","segs":[["matn","إذا انكسفت الشمس صلى الإمام بالناس ركعتين كهيئة النافلة في كل ركعة ركوع واحد ويطول القراءة فيهما ويخفي عند أبي حنيفة وقال أبو يوسف ومحمد: يجهر ثم يدعو بعدها حتى تنجلي الشمس"]]},{"id":"q19_2","label":"باب صلاة الكسوف · الفقرة ٢","segs":[["matn","ويصلي بالناس الإمام الذي يصلي بهم الجمعة فإن لم يجمع صلاها الناس فرادى"]]},{"id":"q19_3","label":"باب صلاة الكسوف · الفقرة ٣","segs":[["matn","وليس في خسوف القمر جماعة وإنما يصلي كل واحد بنفسه وليس في الكسوف خطبة"]]}]},{"id":"q20","title":"باب الاستسقاء","group":"كتاب الصلاة","units":[{"id":"q20_1","label":"باب الاستسقاء · الفقرة ١","segs":[["matn","قال أبو حنيفة رحمه الله عليه: ليس في الاستسقاء صلاة مسنونة في جماعة فإن صلى الناس وحدانا جاز وإنما الاستسقاء الدعاء والاستغفار"]]},{"id":"q20_2","label":"باب الاستسقاء · الفقرة ٢","segs":[["matn","وقال أبو يوسف ومحمد: يصلي الإمام بالناس ركعتين يجهر فيهما بالقراءة لم يخطب ويستقبل القبلة بالدعاء ويقلب الإمام رداءه ولا يقلب القوم أرديتهم ولا يحضر أهل الذمة الاستسقاء"]]}]},{"id":"q21","title":"باب قيام شهر رمضان","group":"كتاب الصلاة","units":[{"id":"q21_1","label":"باب قيام شهر رمضان · الفقرة ١","segs":[["matn","يستحب أن يجتمع الناس في شهر رمضان بعد العشاء"]]},{"id":"q21_2","label":"باب قيام شهر رمضان · الفقرة ٢","segs":[["matn","فيصلي بهم إمامهم خمس ترويحات في كل ترويحه تسليمتان ويجلس بن كل ترويحتين مقدار ترويحة ثم يوتر بهم ولا يصلي الوتر بجماعة في غير شهر رمضان"]]}]},{"id":"q22","title":"باب صلاة الخوف","group":"كتاب الصلاة","units":[{"id":"q22_1","label":"باب صلاة الخوف · الفقرة ١","segs":[["matn","إذا اشتد الخوف جعل الإمام الناس طائفتين: طائفة في وجه العدو وطائفة خلفه فيصلي بهذه الطائفة ركعة وسجدتين فإذا رفع رأسه من السجدة الثانية مضت هذه الطائفة إلى وجه"]]},{"id":"q22_2","label":"باب صلاة الخوف · الفقرة ٢","segs":[["matn","العدو وجاءت تلك الطائفة فيصلي بهم الإمام ركعة وسجدتين وتشهد وسلم ولم يسلموا وذهبوا إلى وجه العدو وجاءت الطائفة الأولى فصلوا وحدانا ركعة وسجدتين بغير قراءة وتشهدوا وسلموا ومضوا إلى وجه العدو وجاءت الطائفة الأخرى فصلوا ركعة وسجدتين بقراءة وتشهدوا وسلموا"]]},{"id":"q22_3","label":"باب صلاة الخوف · الفقرة ٣","segs":[["matn","فإن كان الإمام مقميا صلى بالطائفة الأولى ركعتين وبالثانية ركعتين ويصلي بالطائفة الأولى ركعتين من المغرب وبالثانية ركعة"]]},{"id":"q22_4","label":"باب صلاة الخوف · الفقرة ٤","segs":[["matn","ولا يقاتلون في حال الصلاة فإن فعلوا ذلك بطلت صلاتهم وإن اشتد الخوف صلوا ركبانا وحدانا يومئون بالركوع والسجود إلى أي جهة شاءوا إذا لم يقدروا على التوجه إلى القبلة"]]}]},{"id":"q23","title":"باب صلاة الجنائز","group":"كتاب الصلاة","units":[{"id":"q23_1","label":"باب صلاة الجنائز · الفقرة ١","segs":[["matn","إذا احتضر الرجل وجه إلى القبلة على شقة الأيمن ولقن الشهادتين فإذا مات شدوا لحييته وغمضوا عينيه وإذا أرادوا غسله وضعوه على سرير وجعلوا على عورته خرقة"]]},{"id":"q23_2","label":"باب صلاة الجنائز · الفقرة ٢","segs":[["matn","ونزعوا ثيابه ووضئوة ولا يمضمض ولا يستنشق ثم يفيضون الماء عليه ويجمر سريره وترا ويغلى الماء بالسدر أو بالحرض فإن لم يكن فالماء القراح ويغتسل رأسه ولحيته بالخطمي"]]},{"id":"q23_3","label":"باب صلاة الجنائز · الفقرة ٣","segs":[["matn","ثم يضجع على شقه الأيسر فيغتسل بالماء والسدر حتى يرى أن الماء قد وصل إلى ما يلي التخت منه ثم يضجع على شقة الأيمن فيغتسل بالماء والسدر حتى يرى أن الماء قد وصل إلى ما يلي التخت منه"]]},{"id":"q23_4","label":"باب صلاة الجنائز · الفقرة ٤","segs":[["matn","ثم يجلسه ويسنده إليه ويمسح بطنه مسحا وفيقا فإن خرج منه شيء غسله ولا يعيد غسله"]]},{"id":"q23_5","label":"باب صلاة الجنائز · الفقرة ٥","segs":[["matn","ثم ينشفه بثوب ويجعله في أكفانه ويجعل الحنوط على رأسه ولحيته والكافور على مساجده"]]},{"id":"q23_6","label":"باب صلاة الجنائز · الفقرة ٦","segs":[["matn","والسنة أن يكفن الرجل في ثلاثة أثواب: إزار وقميص ولفافة فإن اقتصروا على ثوبين جاز"]]},{"id":"q23_7","label":"باب صلاة الجنائز · الفقرة ٧","segs":[["matn","وإذا أرادوا لف اللفافة عليه ابتداءوا بالجانب الأيسر فألقوه عليه ثم بالأيمن فإن خافوا أن ينشر الكفن عنه عقدوه"]]},{"id":"q23_8","label":"باب صلاة الجنائز · الفقرة ٨","segs":[["matn","وتكفن المرأة في خمسة أثواب: إزار وقميص وخمار وخرقة يربط بها ثدياها ولفافة فإن اقتصروا على"]]},{"id":"q23_9","label":"باب صلاة الجنائز · الفقرة ٩","segs":[["matn","ثلاثة أثواب جاز ويكون الخمار فوق القميص تحت اللفافة ويجعل شعرها على صدرها ولا يسرح شعر الميت ولا ليحته ولا يقص ظفره ولا يعقص شعره وتجمر الأكفان قبل أن يدرج فيها وترا"]]},{"id":"q23_10","label":"باب صلاة الجنائز · الفقرة ١٠","segs":[["matn","فإذا فرغوا منه صلوا عليه وأولى الناس بالصلاة عليه السلطان إن حضر فإن لم يحضر فيستحب تقديم إمام الحي ثم الولي"]]},{"id":"q23_11","label":"باب صلاة الجنائز · الفقرة ١١","segs":[["matn","فإن صلى عليه غير الولي والسلطان أعاد الولي وإن صلى الولي لم يجز لأحد أن يصلي بعده فإن دفن ولم يصل عليه صلي على قبره"]]},{"id":"q23_12","label":"باب صلاة الجنائز · الفقرة ١٢","segs":[["matn","والصلاة: أن يكبر تكبيرة يحمد الله تعالى عقيبها ثم يكبر تكبيرة ويصلي على النبي صلى الله عليه وسلم ثم يكبر تكبيرة يدعو فيها لنفسه وللميت وللمسليمن ثم يكبر تكبيرة رابعة ويسلم ولا يصلى"]]},{"id":"q23_13","label":"باب صلاة الجنائز · الفقرة ١٣","segs":[["matn","على ميت في مسجد جماعة"]]},{"id":"q23_14","label":"باب صلاة الجنائز · الفقرة ١٤","segs":[["matn","فإذا حملوه على سريره أخذوا بقوائمه الأربع ويمشون به مسرعين دون الخبب فإذا بلغوا إلى قبره كره للناس أن يجلسوا قبل أن يوضع عن أعناق الرجال ويحفر القبر ويلحد ويدخل الميت مما يلي القبلة فإذا وضع في لحده قال الذي يضعه: باسم الله وعلى ملة رسول الله ويوجهه إلى القبلة ويحل العقدة ويسوي اللبن عليه ويكره الآجر"]]},{"id":"q23_15","label":"باب صلاة الجنائز · الفقرة ١٥","segs":[["matn","والخشب ولا بأس بالقصب ثم ينهال التراب عليه ويسنم القبر ولا يصطح ومن استهل بعد الولادة سمي وغسل وصلي عليه وإن لم يستهل أدرج في خرقه ولم يصل عليه"]]}]},{"id":"q24","title":"باب الشهيد","group":"كتاب الصلاة","units":[{"id":"q24_1","label":"باب الشهيد · الفقرة ١","segs":[["matn","الشهيد: من قتله المشركون"]]},{"id":"q24_2","label":"باب الشهيد · الفقرة ٢","segs":[["matn","أو وجد في المعركة وبه أثر الجراحة أو قتله المسلمون ظلما ولم تجب بقتله دية فيكفن ويصلي عيه ولا يغتسل وإذا استشهد الجنب غسل عند أبي حنيفة وكذلك الصبي وقال أبو يوسف ومحمد: لا يغسلان ولا يغتسل عن الشهيد دمه ولا ينزع عنه ثيابه وينزع عنه الفرو والحف والحشو والسلاح"]]},{"id":"q24_3","label":"باب الشهيد · الفقرة ٣","segs":[["matn","ومن ارتث غسل والارتثات: أن يأكل أو يشرب أو يداوى أو يبقى حيا حتى يمضي عليه وقت صلاة وهو يعقل أو ينقل من المعركة حيا"]]},{"id":"q24_4","label":"باب الشهيد · الفقرة ٤","segs":[["matn","ومن قتل في حد أو قصاص غسل وصلي عليه ومن قتل من البغاة أو قطاع الطريق لم يصل عليه"]]}]},{"id":"q25","title":"باب الصلاة في الكعبة وحولها","group":"كتاب الصلاة","units":[{"id":"q25_1","label":"باب الصلاة في الكعبة وحولها · الفقرة ١","segs":[["matn","الصلاة في الكعبة جائزة فرضها ونفلها فإن صلى الإمام بجماعة فجعل بعضهم ظهره الإمام جاز ومن جعل منهم ظهره إلى وجه الإمام لم تجز صلاته"]]},{"id":"q25_2","label":"باب الصلاة في الكعبة وحولها · الفقرة ٢","segs":[["matn","وإذا صلى الإمام في المسجد الحرام تحلق"]]},{"id":"q25_3","label":"باب الصلاة في الكعبة وحولها · الفقرة ٣","segs":[["matn","الناس حول الكعبة وصلوا بصلاة الإمام فمن كان منهم أقرب إلى الكعبة من الإمام جازت صلاته إذا لم يكن في جانب الإمام"]]},{"id":"q25_4","label":"باب الصلاة في الكعبة وحولها · الفقرة ٤","segs":[["matn","ومن صلى على ظهر الكعبة جازت صلاته"]]}]},{"id":"q26","title":"كتاب الزكاة","group":"كتاب الزكاة","units":[{"id":"q26_1","label":"كتاب الزكاة · الفقرة ١","segs":[["matn","الزكاة: واجبة على الحر المسلم البالغ العاقل إذا ملك نصابا ملكا تاما وحال عليه الحول وليس على صبي ولا مجنون وال مكاتب زكاة"]]},{"id":"q26_2","label":"كتاب الزكاة · الفقرة ٢","segs":[["matn","ومن كان عليه دين يحيط فلا زكاة عليه"]]},{"id":"q26_3","label":"كتاب الزكاة · الفقرة ٣","segs":[["matn","وإن كان ماله أكثر من الدين زكى الفاضل إذا بلغ نصابا وليس في دور السكنى وثياب البدن وأثاث المنازل ودواب الركوب وعبيد الخدمة وسلاح الاستعمال زكاة"]]},{"id":"q26_4","label":"كتاب الزكاة · الفقرة ٤","segs":[["matn","ولا يجوز أداء الزكاة إلا بينة مقارنة للأداء أو مقارنة لعزل مقدار الواجب"]]},{"id":"q26_5","label":"كتاب الزكاة · الفقرة ٥","segs":[["matn","ومن تصدق بجميع ماله ولم ينو الزكاة سقط فرضها عنه"]]}]},{"id":"q27","title":"باب زكاة الإبل","group":"كتاب الزكاة","units":[{"id":"q27_1","label":"باب زكاة الإبل · الفقرة ١","segs":[["matn","ليس في أقل من خمس ذود من الإبل صدقة فإذا بلغت خمسا سائمة"]]},{"id":"q27_2","label":"باب زكاة الإبل · الفقرة ٢","segs":[["matn","وحال عليها الحول ففيها شاة إلى تسع فإذا كانت عشرا ففيها شاتان إلى أربع عشرة فإذا كانت خمس عشرة ففيها ثلاث شياه إلى تسع عشرة فإذا كانت عشرين ففيها أربع شياه إلى أربع وعشرين فإذا كانت خمسا وعشرين ففيها بنت مخاض إلى خمس وثلاثين فإذا كانت ستا وثلاثين ففيها بنت لبون إلى خمس وأربعين فإذا كانت ستا وأربعين ففيها حقة إلى ستين فإذا كانت إحدى وستين ففيها جذعة إلى خمس وسبعين فإذا كانت ستا وسبعين ففيها بنتا لبون إلى تسعين فإذا كانت إحدى وتسعين ففيها حقتان إلى مائة وعشرين"]]},{"id":"q27_3","label":"باب زكاة الإبل · الفقرة ٣","segs":[["matn","ثم تستأنف الفريضة فيكون في الخمس شاة مع الحقتين وفي العشر شاتان وفي خمس عشرة ثلاث شياه وفي عشرين أربع شياه وفي خمس وعشرين بنت مخاض إلى مائة وخمسين فيكون فيها"]]},{"id":"q27_4","label":"باب زكاة الإبل · الفقرة ٤","segs":[["matn","ثلاث حقاق: ثم تستأنف الفريضة فيكنون في الخمس شاة وفي العشر شاتان وفي خمس عشرة ثلاث شياه وفي عشرين أربع شياه وفي خمس وعشرين بنت مخاض وفي ست وثلاثين بنت لبون فإذا بلغت مائة وستا وتسعين ففيها أربع حقاق إلى مائتين ثم تستأنف الفريضة أبدا كما استؤنفت في الخمسين التي بعد المائة والخميسين والبخت والعراب سواء"]]}]},{"id":"q28","title":"باب صدقة البقر","group":"كتاب الزكاة","units":[{"id":"q28_1","label":"باب صدقة البقر · الفقرة ١","segs":[["matn","ليس في أقل من ثلاثين من البقر صدقة فإذا كانت ثلاثين سائمة وحال عليها الحول ففيها تبيع أو تبيعة وفي أربعين مسنة أو مسن فإذا زادت على الأربعين وجب في الزيادة بقدر ذلك إلى ستين عند أبي حنيفة ففي الواحدة ربع عشر مسنة وفي الاثنين نصف عشر مسنة وفي الثلاثة ثلاثة أرباع عشر مسنة وفي الأربع عشر"]]},{"id":"q28_2","label":"باب صدقة البقر · الفقرة ٢","segs":[["matn","وقال أبو يوسف ومحمد: لا شيء في الزيادة حتى تبلغ ستين فيكون فيها تبيعان أو تبيعتان وفي سبعين مسنة وتبيع وفي ثمانين مسنتان وفي تسعين ثلاثة أتبعة وفي مائة تبيعان ومسنة والجوامس والبقر سواء"]]}]},{"id":"q29","title":"باب صدقة الغنم","group":"كتاب الزكاة","units":[{"id":"q29_1","label":"باب صدقة الغنم · الفقرة ١","segs":[["matn","ليس في أقل من أربعين شاة صدقة فإذا كانت أربعين سائمة وحال عليها الحول ففيها شاة إلى مائة وعشرين فإذا زادت واحدة ففيها شاتان إلى مائتين فإذا زادت واحدة ففيها ثلاث شياه فإذا بلغت أربعمائة ففيها أربع شياه ثم في كل مائة شاة والضأن والمعز سواء"]]}]},{"id":"q30","title":"باب زكاة الخيل","group":"كتاب الزكاة","units":[{"id":"q30_1","label":"باب زكاة الخيل · الفقرة ١","segs":[["matn","إذا كانت الخيل سائمة ذكورا وإناثا فصاحبها بالخيار: إن شاء أعطى عن كل فرس دينارا وإن شاء قومها وأعطى عن كل مائتي درهم خمسة دراهم وليس في ذكورها منفردة زكاة"]]},{"id":"q30_2","label":"باب زكاة الخيل · الفقرة ٢","segs":[["matn","وقال أبو يوسف ومحمد: لا زكاة في الخيل"]]},{"id":"q30_3","label":"باب زكاة الخيل · الفقرة ٣","segs":[["matn","ولا في شيء من البغال والحمير إلا أن تكون للتجارة"]]},{"id":"q30_4","label":"باب زكاة الخيل · الفقرة ٤","segs":[["matn","وليس في الفصلان والحملان والعجاجيل صدقة عند أبي حنيفة"]]},{"id":"q30_5","label":"باب زكاة الخيل · الفقرة ٥","segs":[["matn","ومحمد إلا أن يكون معها كبار وقال أبو يوسف فيها واحدة منها"]]},{"id":"q30_6","label":"باب زكاة الخيل · الفقرة ٦","segs":[["matn","ومن وجب عليه سن فلم توجد عنده أخذ المصدق أعلى منها ورد الفضل أو أخذ دونها وأخذ الفضل"]]},{"id":"q30_7","label":"باب زكاة الخيل · الفقرة ٧","segs":[["matn","ويجوز دفع القيم في الزكاة وليس في العوامل والعلوفة صدقة"]]},{"id":"q30_8","label":"باب زكاة الخيل · الفقرة ٨","segs":[["matn","ولا يأخذ المصدق خيار المال ولا رذالته ويأخذ الوسط منه ومن كان له نصاب فاستفاد في أثناء الحول من جنسه"]]},{"id":"q30_9","label":"باب زكاة الخيل · الفقرة ٩","segs":[["matn","ضمه إلى ماله وزكاه به"]]},{"id":"q30_10","label":"باب زكاة الخيل · الفقرة ١٠","segs":[["matn","والسائمة هي: التي تكتفي بالرعي في أكثر حولها فإن علفها نصف الحول أو أكثر فلا زكاة فيها"]]},{"id":"q30_11","label":"باب زكاة الخيل · الفقرة ١١","segs":[["matn","والزكاة عند أبي حنيفة وأبي يوسف في النصاب دون العفو وقال محمد: فيهما وإذا هلك المال بعد وجوب الزكاة سقطت فإن قدم الزكاة على الحول وهو مالك للنصاب جاز"]]}]},{"id":"q31","title":"باب زكاة الفضة","group":"كتاب الزكاة","units":[{"id":"q31_1","label":"باب زكاة الفضة · الفقرة ١","segs":[["matn","ليس فيما دون مائتي درهم صدقة فإذا كانت مائتي درهم وحال عليها الحول ففيها خمسة دراهم ولا شيء في الزيادة حتى تبلغ أربعين درهما فيكون فيها درهم ثم في كل أربعين درهما درهم وقال أبو يوسف ومحمد: ما زاد على المائتين فزكاته بحسابه"]]},{"id":"q31_2","label":"باب زكاة الفضة · الفقرة ٢","segs":[["matn","وإذا كان الغالب على الورق الفضة فهي في حكم الفضة وإن كان الغالب عليها الغش فهي في حكم العروض ويعتبر أن تبلغ فيمتها نصابا"]]}]},{"id":"q32","title":"باب زكاة الذهب","group":"كتاب الزكاة","units":[{"id":"q32_1","label":"باب زكاة الذهب · الفقرة ١","segs":[["matn","ليس فيما دون عشرين مثفالا من الذهب صدقة فإذا كانت عشرين مثقالا وحال عليها الحول ففيها نصف مثقال ثم في كل أربعة مثاقيل قيراطان وليس فيما دون أربعة مثاقيل صدقة عند أبي حنيفة"]]},{"id":"q32_2","label":"باب زكاة الذهب · الفقرة ٢","segs":[["matn","وفي تبر الذهب والفضة وحليهما والآنية منهما الزكاة"]]}]},{"id":"q33","title":"باب زكاة العروض","group":"كتاب الزكاة","units":[{"id":"q33_1","label":"باب زكاة العروض · الفقرة ١","segs":[["matn","الزكاة واجبة في عروض التجارة كائنة ما كانت إذا بلغت قميتها نصابا من الذهب أو الورق يقومها بما هو أنفع للفقراء والمساكين منهما"]]},{"id":"q33_2","label":"باب زكاة العروض · الفقرة ٢","segs":[["matn","وإذا كان النصاب كاملا في طرفي الحول فنقصانه فيما بين ذلك لا يسقط الزكاة"]]},{"id":"q33_3","label":"باب زكاة العروض · الفقرة ٣","segs":[["matn","وتضم قيمة العروض إلى الذهب والفضة وكذلك يضم الذهب إلى الفضة بالقيمة حتى يتم النصاب عند أبي حنيفة وقال أبو يوسف ومحمد: لا يضم الذهب إلى الفضة بالقيمة ويضم بالأجزاء"]]}]},{"id":"q34","title":"باب زكاة الزروع والثمار","group":"كتاب الزكاة","units":[{"id":"q34_1","label":"باب زكاة الزروع والثمار · الفقرة ١","segs":[["matn","قال أبو حنيفة رحمه الله تعالى: في قليل ما أخرجته الأرض وكثير العشر سواء سقي سيحا أو سقته السماء إلا الحطب والقصب الحشيش"]]},{"id":"q34_2","label":"باب زكاة الزروع والثمار · الفقرة ٢","segs":[["matn","وقال أبو يوسف ومحمد: لا يجب العشر إلا فيما له ثمرة باقية إذا بلغ خمسة أوسق"]]},{"id":"q34_3","label":"باب زكاة الزروع والثمار · الفقرة ٣","segs":[["matn","والوسق: ستون صاعا بصاع النبي صلى الله عليه وسلم وليس في الخضروات عندهما عشر"]]},{"id":"q34_4","label":"باب زكاة الزروع والثمار · الفقرة ٤","segs":[["matn","وما سقي بغرب أو دالية أو سانية"]]},{"id":"q34_5","label":"باب زكاة الزروع والثمار · الفقرة ٥","segs":[["matn","ففيه نصف العشر في القولين وقال أبو يوسف فيما لا يوسق كالزعفران والقطن يجب فيه العشر إذا بلغت قيمته خمسة أوسق من أدنى ما يدخل تحت الوسق"]]},{"id":"q34_6","label":"باب زكاة الزروع والثمار · الفقرة ٦","segs":[["matn","وقال محمد: يجب العشر إذا بلغ الخارج خمسة أمثال من أعلى ما يقدر به نوعه فاعتبر في القطن خمسة أحمال وفي الزعفران خمسة أمناء وفي العسل العشر إذا أخذ من أرض العشر قل أو أكثر وقال أبو يوسف: لا شيء فيه حتى يبلغ عشرة أزقاق وقال محمد: خمسة أفراق"]]},{"id":"q34_7","label":"باب زكاة الزروع والثمار · الفقرة ٧","segs":[["matn","وليس في الخارج من أرض الخراج عشر"]]}]},{"id":"q35","title":"باب من يجوز دفع الصدقة إليه ومن لا يجوز","group":"كتاب الزكاة","units":[{"id":"q35_1","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ١","segs":[["matn","قال الله تعالى: {إنما الصدقات للفقراء والمساكين} الآية فهذه ثمانية أصناف قد سقطت منها المؤلفة قلوبهم لأن الله تعالى أعز الإسلام وأغنى عنهم"]]},{"id":"q35_2","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ٢","segs":[["matn","والفقير: من له أدنى شيء والمسكين: من لا شيء له والعامل: يدفع إليه الإمام بقدر عمله إن عمل وفي الرقاب: يعان المكاتبون في فك رقابهم والغارم: من لزمه دين وفي سبيل الله: منقطع الغزاة وابن السبيل: من كان له مال في وطنه وهو في مكان لا شيء له فيه فهذه جهات الزكاة"]]},{"id":"q35_3","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ٣","segs":[["matn","وللمالك أن يدفع إلى كل واحد منهم وله أن يقتصر على صنف واحد"]]},{"id":"q35_4","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ٤","segs":[["matn","ولا يجوز أن يدفع الزكاة إلى ذمي"]]},{"id":"q35_5","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ٥","segs":[["matn","ولا يبنى بها مسجد ولا يكفن بها ميت ولا يشترى بها رقبة تعتق ولا تدفع إلى غني ولا يدفع المزكي زكاته إلى أبيه وجده وإن علا ولا إلى ولده وولد ولده وإن سفل ولا إلى امرأته ولا تدفع المرأة إلى زوجها عند أبي حنيفة وقال أبو يوسف ومحمد: تدفع إليه"]]},{"id":"q35_6","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ٦","segs":[["matn","ولا يدفع إلى مكاتبه ولا"]]},{"id":"q35_7","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ٧","segs":[["matn","مملوكه ولا مملوك غني ولا ولد غني إذا كان صغيرا ولا تدفع إلى بني هاشم وهم: آل علي وآل عباس وآل جعفر وآل عقيل وآل حارث بن عبد المطلب ومواليهم"]]},{"id":"q35_8","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ٨","segs":[["matn","وقال أبو حنيفة ومحمد: إذا دفع الزكاة إلى رجل يظنه فقيرا ثم بان أنه غني أو هاشمي أو كافر أو دفع في ظلمة إلى فقير ثم بان أنه أبوه أو ابنه فلا إعادة عليه"]]},{"id":"q35_9","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ٩","segs":[["matn","وقال أبو يوسف عليه الإعادة"]]},{"id":"q35_10","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ١٠","segs":[["matn","ولو دفع إلى شخص ثم علم أنه عنده أو مكاتبه لم يجز في قولهم جميعا"]]},{"id":"q35_11","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ١١","segs":[["matn","ولا يجوز دفع الزكاة إلى من يملك نصابا من أي مال كان ويجوز دفعها إلى من يملك أقل من ذلك وإن كان صحيحا مكتسبا"]]},{"id":"q35_12","label":"باب من يجوز دفع الصدقة إليه ومن لا يجوز · الفقرة ١٢","segs":[["matn","ويكره نقل الزكاة من بلد إلى بلد آخر وإنما تفرق صدقة كل قوم فيهم إلا أن ينقلها الإنسان إلى قرابته أو إلى ثوم هم أحوج من أهل بلده"]]}]},{"id":"q36","title":"باب صدقة الفطر","group":"كتاب الزكاة","units":[{"id":"q36_1","label":"باب صدقة الفطر · الفقرة ١","segs":[["matn","صدقة الفطر واجبة على الحر المسلم إذا كان مالكا لمقدار النصاب فاضلا عن مسكنه وثيابه وأثاثه وفرسه وسلاحه وعبيده للخدمة يخرج ذلك عن نفسه وعن أولاده الصغار وعن مماليكه ولا يؤدي عن زوجته ولا عن أولاده الكبار وإن كانوا في عياله"]]},{"id":"q36_2","label":"باب صدقة الفطر · الفقرة ٢","segs":[["matn","ولا يخرج عن مكاتبه ولاعن مماليكه للتجارة والعبد بين شريكين لا فطرة على واحد منهما ويؤدي المولى المسلم الفطرة عن عبده الكافر"]]},{"id":"q36_3","label":"باب صدقة الفطر · الفقرة ٣","segs":[["matn","والفطرة: نصف صاع من بر أو صاع من تمر أو زبيب أو شعير"]]},{"id":"q36_4","label":"باب صدقة الفطر · الفقرة ٤","segs":[["matn","والصاع عند أبي حنيفه ومحمد ثمانية أرطال بالعراقي"]]},{"id":"q36_5","label":"باب صدقة الفطر · الفقرة ٥","segs":[["matn","وقال أبو يوسف: خمسة أرطال وثلث رطل"]]},{"id":"q36_6","label":"باب صدقة الفطر · الفقرة ٦","segs":[["matn","ووجوب الفطرة يتعلق بطلوع الفجر من يوم الفطر فمن مات قبل ذلك لم تجب فطرته ومن أسلم أو ولد بعد طلوع الفجر لم تجب فطرته"]]},{"id":"q36_7","label":"باب صدقة الفطر · الفقرة ٧","segs":[["matn","ويستحب للناس أن يخرجوا الفطرة يوم الفطر قبل الخروج إلى المصلى فإن قدموها قبل يوم الفطر جاز وإن أخروها عن يوم الفطر لم تسقط وكان عليهم إخراجها"]]}]},{"id":"q37","title":"كتاب الصوم","group":"كتاب الصوم","units":[{"id":"q37_1","label":"كتاب الصوم · الفقرة ١","segs":[["matn","الصوم ضربان: واجب ونفل فالواجب ضربان: منه ما يتعلق بزمام بعينه كصوم رمضان والنذر المعين فيجوز صومه بينة من الليل فإن لم ينو حتى أصبح"]]},{"id":"q37_2","label":"كتاب الصوم · الفقرة ٢","segs":[["matn","والضرب الثاني: ما يثبت في الذمة كقضاء رمضان والنذر المطلق والكفارات فلا يجوز إلا بنية من الليل والنفل كله يجوز بنية قبل الزوال"]]},{"id":"q37_3","label":"كتاب الصوم · الفقرة ٣","segs":[["matn","وينبغي للناس أن يلتمسوا الهلال في اليوم التاسع والعشرين من شعبان فإن رأوه صاموا وإن غم عليهم أكملوا عدة شعبان ثلاثين يوما ثم صاموا ومن رأى هلال رمضان وحده صام وإن لم يقبل الإمام شهادته وإذا كان بالسماء علة قبل الإمام شهادة الواحد العدل في رؤية الهلال رجلا أو امرأة حرا كان أو عبدا"]]},{"id":"q37_4","label":"كتاب الصوم · الفقرة ٤","segs":[["matn","فإن لم يكن بالسماء عله لم تقبل شهادته حتى يراه جمع كثير يقع"]]},{"id":"q37_5","label":"كتاب الصوم · الفقرة ٥","segs":[["matn","العلم بخبرهم ووقت الصوم من طلوع الفجر الثاني إلى غروب الشمس"]]},{"id":"q37_6","label":"كتاب الصوم · الفقرة ٦","segs":[["matn","والصوم هو: الإمساك عن الأكل واشرب والجماع نهارا مع النية فإن أكل الصائم أو شرب أو جامع ناسيا لم يفطر وإن نام فاحتلم أو نظر إلى امرأة فأنزل أو ادهن أو احتجم أو اكتحل أو اكتحل أو قبل لم يفطره فإن أنزل بقبلة أو لمس فعليه القضاء"]]},{"id":"q37_7","label":"كتاب الصوم · الفقرة ٧","segs":[["matn","ولا بأس بالقبلة إذا أمن على نفسه ويكره إن لم يأمن وإن ذرعه القيء لم يفطر وإن استقاء عامدا ملء فيه فعليه القضاء ومن ابتلع الحصاة أو الحديد أفطر"]]},{"id":"q37_8","label":"كتاب الصوم · الفقرة ٨","segs":[["matn","ومن جامع عامدا في أحد السبيلين أو أكل أو شرب ما يتغذى به أو يتداوى به فعليه القضاء والكفارة مثل كفارة الظهار ومن جامع فيما دون الفرج فأنزل فعليه القضاء ولا"]]},{"id":"q37_9","label":"كتاب الصوم · الفقرة ٩","segs":[["matn","كفارة عليه في إفساد الصوم في غير رمضان كفارة ومن احتقن أو استعط أوقطر في أذنيه أو داوى جائفة أو آمة بدواء فوصل إلى جوفه أو دماغه أفطر وإن أقطر في إحليله لم يفطر عند أبي حنيفة وقال أبو يوسف يفطر"]]},{"id":"q37_10","label":"كتاب الصوم · الفقرة ١٠","segs":[["matn","ومن ذاق شيئا بفمه لم يفطر ويكره له ذلك ويكره للمرأة أن تمضغ لصبيها الطعام إذا كان لها منه بد"]]},{"id":"q37_11","label":"كتاب الصوم · الفقرة ١١","segs":[["matn","ومضغ العلك لا يفطر الصائم ويكره"]]},{"id":"q37_12","label":"كتاب الصوم · الفقرة ١٢","segs":[["matn","ومن كان مريضا في رمضان فخاف إن صام زاد مرضه أفطر وقضى وإن كان مسافرا لا يستضر بالصوم فصومه أفضل وإن أفطر وقضى جاز وإن مات المريض أو المسافر وهما على حالهما لم يلزمهما القضاء وإن صح المريض أو أقام المسافر ثم ماتا لزمهما القضاء بقدر الصحة والإقامة"]]},{"id":"q37_13","label":"كتاب الصوم · الفقرة ١٣","segs":[["matn","وقضاء رمضان إن شاء فرقه وإن شاء تابعه فإن أخره حتى دخل رمضان آخر صام رمضان الثاني وقضى الأول بعده ولا فدية عليه"]]},{"id":"q37_14","label":"كتاب الصوم · الفقرة ١٤","segs":[["matn","والحامل والمريض إذا خافتا على ولديهما"]]},{"id":"q37_15","label":"كتاب الصوم · الفقرة ١٥","segs":[["matn","أفطرتا وقضتا ولا فدية عليهما"]]},{"id":"q37_16","label":"كتاب الصوم · الفقرة ١٦","segs":[["matn","والشيخ الفاني الذي لا يقدر على الصيام يفطر ويطعم لكل يوم مسكينا كما يطعم في الكفارات"]]},{"id":"q37_17","label":"كتاب الصوم · الفقرة ١٧","segs":[["matn","ومن مات وعليه قضاء رمضان فأوصى به أطعم عنه وليه لكل يوم مسكينا نصف صاع من بر أو صاعا من تمر أو صاعا من شعير"]]},{"id":"q37_18","label":"كتاب الصوم · الفقرة ١٨","segs":[["matn","ومن دخل في صوم التطوع أو صلاة التطوع ثم أفسده قضاه وإذا بلغ الصبي أو أسلم الكافر في رمضان أمسكا بقية يومهما وصاما ما بعده ولم يقضيا ما مضى"]]},{"id":"q37_19","label":"كتاب الصوم · الفقرة ١٩","segs":[["matn","ومن أغمي عليه في رمضان لم يقض اليوم الذي حدث فيه الإغماء وقضى ما بعده وإذا أفاق المجنون في بعض رمضان قضى ما مضى منه وإذا حاضت المرأة أفطرت وقضت وإذا قدم السافر أو طهرت الحائض في بعض النهار أمسكا عن الطعام والشراب بقية يومهما"]]},{"id":"q37_20","label":"كتاب الصوم · الفقرة ٢٠","segs":[["matn","ومن تسحر وهو يظن أن الفجر لم يطلع أو أفطر وهو يرى"]]},{"id":"q37_21","label":"كتاب الصوم · الفقرة ٢١","segs":[["matn","أن الشمس قد غربت ثم تبين أن الفجر كان قد طلع أو أن الشمس لم تغرب قضى ذلك اليوم ولا كفارة عليه"]]},{"id":"q37_22","label":"كتاب الصوم · الفقرة ٢٢","segs":[["matn","ومن رأى هلال الفطر وحده لم يفطر"]]},{"id":"q37_23","label":"كتاب الصوم · الفقرة ٢٣","segs":[["matn","وإذا كان بالسماء علة لم تقبل في هلال الفطر إلا شهادة رجلين أو رجل وامرأتين وإن لم يكن بالسماء علة لم تقبل إلا شهادة جمع كثير يقع العام بخبرهم"]]}]},{"id":"q38","title":"باب الاعتكاف","group":"كتاب الصوم","units":[{"id":"q38_1","label":"باب الاعتكاف · الفقرة ١","segs":[["matn","الاعتكاف مستحب وهو اللبث في المسجد مع الصوم ونية الاعتكاف"]]},{"id":"q38_2","label":"باب الاعتكاف · الفقرة ٢","segs":[["matn","ويحرم على المعتكف: الوط واللمس والقبلة ولا يخرج من المسجد إلا لحاجة الإنسان أو الجمعة ولا بأس بأن يبيع ويبتاع في المسجد من غير أن يحضر السلع"]]},{"id":"q38_3","label":"باب الاعتكاف · الفقرة ٣","segs":[["matn","ولا يتكام إلا بخير ويكره له الصمت فإن جامع المعتكف ليلا أو نهارا بطل اعتكافه ومن أوجب على نفسه اعتكاف أيام لزمه اعتكافها بلياليها وكانت متتابعة وإن لم يشترط التتابع"]]}]},{"id":"q39","title":"كتاب الحج","group":"كتاب الحج","units":[{"id":"q39_1","label":"كتاب الحج · الفقرة ١","segs":[["matn","الحج: واجب على الأحرار البالغين العقلاء الأصحاء إذا قدروا على الزاد والراحلة فاضلا عن مسكنه وما لا بد منه"]]},{"id":"q39_2","label":"كتاب الحج · الفقرة ٢","segs":[["matn","وعن نفقة عياله إلى حين عوده وكان الطريق آمنا"]]},{"id":"q39_3","label":"كتاب الحج · الفقرة ٣","segs":[["matn","ويعتبر في المرأة أن يكون لها محرم يحج بها أو زوج ولا يجوز لها أن تحج بغيرهما إذا كان بينها وبين مكة مسيرة ثلاثة أيام ولياليها وإذا بلغ الصبي بعد ما أحرم أو أعتق العبد فمضيا على ذلك لم يجزيهما عن حجة الإسلام"]]},{"id":"q39_4","label":"كتاب الحج · الفقرة ٤","segs":[["matn","باب تحديد المواقيت والمواقيت التي لا يجوز أن يتجاوزها الإنسان إلا محرما: لأهل المدينة ذو الحليفة ولأهل العراق ذات عرق ولأهل الشام الجحفة"]]},{"id":"q39_5","label":"كتاب الحج · الفقرة ٥","segs":[["matn","ولأهل نجد قرن المنازل ولأهل اليمن يلملم فإن قدم الإحرام على هذه المواقيت جاز"]]},{"id":"q39_6","label":"كتاب الحج · الفقرة ٦","segs":[["matn","ومن كان منزله بعد المواقيت فميقاته الحل ومن كان بمكة فميقاته في الحج الحرم وفي العمرة الحل"]]},{"id":"q39_7","label":"كتاب الحج · الفقرة ٧","segs":[["matn","وإذا أراد الإحرام اغتسل أو توضأ - والغسل أفضل - ولبس ثوبين جديدين أو غسيلين إزارا ورداء ومس طيبا إن كان له طيب وصلى ركعتين وقال: اللهم إني أريد الحج فيسره لي وتقبله مني"]]},{"id":"q39_8","label":"كتاب الحج · الفقرة ٨","segs":[["matn","ثم يلبي عقيب صلاته"]]},{"id":"q39_9","label":"كتاب الحج · الفقرة ٩","segs":[["matn","فإن كان مفردا بالحج نوى بتلبيته الحج والتلبية أن يقول: لبيك اللهم لبيك لبيك لا شريك لك لبيك إن الحمد والنعمة لك والملك لا شريك لك ولا ينبغي أن يخل بشي من هذه الكلمات فإن زاد فيها جاز"]]},{"id":"q39_10","label":"كتاب الحج · الفقرة ١٠","segs":[["matn","فإذا لبى فقد أحرم فليتق ما نهى الله عنه من الرفث والفسوق والجدال ولا يقتل صيدا ولا يشير إليه ولا يدل عليه ولا يلبس قميصا ولا سراويل ولا عمامة ولا قلنسوة ولا قباء"]]},{"id":"q39_11","label":"كتاب الحج · الفقرة ١١","segs":[["matn","ولا خفين إلا أن لا يجد النعلين فيقطعهما أسفل الكعبين ولا يغطي رأسه ولا"]]},{"id":"q39_12","label":"كتاب الحج · الفقرة ١٢","segs":[["matn","وجهه ولا يمس طيبا ولا يحلق رأسه ولا شعر بدنه ولا يقص من لحيته ولا من ظفره ولا يلبس ثوبا مصبوغا بورس زعفران ولا عصفر إلا أن يكون غسلا لا ينفض"]]},{"id":"q39_13","label":"كتاب الحج · الفقرة ١٣","segs":[["matn","ولا بأس أن يغتسل ويدخل الحمام ويستظل بالبيت والمخمل ويشد في وسطه الهميان"]]},{"id":"q39_14","label":"كتاب الحج · الفقرة ١٤","segs":[["matn","ولا يغتسل رأسه ولا لحيته بالخطمي ويكثر من التلبية عقب الصلوات وكلما علا شرفا أو هبط واديا أو لقي ركبانا وبالأسحار"]]},{"id":"q39_15","label":"كتاب الحج · الفقرة ١٥","segs":[["matn","فإذا دخل مكة ابتدأ بالمسجد الحرام فإذا عاين البيت كبر وهلل ثم ابتدأ بالحجر الأسود فاستقبله وكبر ورفع يديه واستلمه وقبله إن استطاع من غير أن يؤدي مسلما ثم آخذ عن يمينه مما يلي الباب وقد اضطبع رداءه قبل ذلك فيطوف بالبيت سبعة أشواط"]]},{"id":"q39_16","label":"كتاب الحج · الفقرة ١٦","segs":[["matn","ويجعل طوافه من وراء الحطيم ويرمل في الأشواط الثلاثة الأول ويمشي فيما بقي على هينته ويستلم الحجر كلما مر به إن استطاع ويختم الطواف بالاستلام"]]},{"id":"q39_17","label":"كتاب الحج · الفقرة ١٧","segs":[["matn","ثم يأتي المقام فيصلي عنده ركعتين أو حيث تيسر من المسجد"]]},{"id":"q39_18","label":"كتاب الحج · الفقرة ١٨","segs":[["matn","وهذا الطواف طواف القدوم وهو سنة وليس بواجب وليس على أهل مكة طواف القدوم"]]},{"id":"q39_19","label":"كتاب الحج · الفقرة ١٩","segs":[["matn","ثم يخرج إلى الصفا فيصعد عليه ويستقبل البيت ويكبر ويهلل ويصلي على النبي صلى الله عليه وسلم ويدعو الله تعالى بحاجته"]]},{"id":"q39_20","label":"كتاب الحج · الفقرة ٢٠","segs":[["matn","ثم ينحط نحو المروة ويمشي على هينته فإذا بلغ إلى بطن الوادي سعى بين الميلين الأخضرين سعيا حتى يأتي المروة فيصعد عليها ويفعل كما فعل على الصفا وهذا شوط فيطوف سبعة أشواط يبدأ بالصفا ويختم بالمروة"]]},{"id":"q39_21","label":"كتاب الحج · الفقرة ٢١","segs":[["matn","ثم يقيم بمكة حراما يطوف بالبيت كلما بدا له فإذا كان قبل يوم التروية بيوم خطب الإمام خطبة يعلم الناس فيها الخروج إلى منى والصلاة بعرفات والوقوف والإفاضة فإذا صلى الفجر يوم التروية بمكة خرج إلى منى فأقام بها حتى يصلي الفجر يوم عرفة"]]},{"id":"q39_22","label":"كتاب الحج · الفقرة ٢٢","segs":[["matn","ثم يتوجه إلى عرفات فيقيم بها"]]},{"id":"q39_23","label":"كتاب الحج · الفقرة ٢٣","segs":[["matn","فإذا زالت الشمس من يوم عرفة صلى الإمام بالناس الظهر والعصر ثم يبتدئ فيخطب خطبتين قبل الصلاة يعلم الناس فيها"]]},{"id":"q39_24","label":"كتاب الحج · الفقرة ٢٤","segs":[["matn","الصلاة والوقوف بعرفة والمزدلفة ورمي الجمار والنحر والحلق وطواف الزيارة ويصلي بهم الظهر والعصر في وقت الظهر بأذان ةإقامتين ومن صلى في رحله وحده صلى كل واحدة منهما في وقتها عند أبي حنيفة رحمه الله تعالى"]]},{"id":"q39_25","label":"كتاب الحج · الفقرة ٢٥","segs":[["matn","وقال أبو يوسف ومحمد رحمهما الله: يجمع بينهما المنفرد ثم يتوجه إلى الموقف فيقف بقرب الجبل وعرفات كلها موقف إلا بطن عرنة"]]},{"id":"q39_26","label":"كتاب الحج · الفقرة ٢٦","segs":[["matn","وينبغي للإمام أن يقف بعرفة على راحلته ويدعو ويعلم الناس المناسك ويستحب أن يغتسل قبل الوقوف ويجتهد في الدعاء فإذا غربت الشمس أفاض الإمام والناس معه على"]]},{"id":"q39_27","label":"كتاب الحج · الفقرة ٢٧","segs":[["matn","هينتهم حتى يأتوا المزدلفة فينزلوا بها والمستحب أن ينزل بقرب الجبل الذي عليه الميقدة يقال له قزح ويصلي الإمام بالناس المغرب والعشاء بأذان وإقامة ومن صلى المغرب في الطريق لم يجز عند أبي حنيفة ومحمد"]]},{"id":"q39_28","label":"كتاب الحج · الفقرة ٢٨","segs":[["matn","فإذا طلع الفجر صلى الإمام بالناس الفجر بغلس ثم وقف ووقف الناس معه فدعا: والمزدلفة كلها موقف إلا بطن محسر"]]},{"id":"q39_29","label":"كتاب الحج · الفقرة ٢٩","segs":[["matn","ثم أفاض الإمام والناس معه قبل طلوع الشمس حتى يأتوا منى فيبتدئ بجمرة العقبة فيرميها من بطن الوادي بسبع حصيات مثل الخذف"]]},{"id":"q39_30","label":"كتاب الحج · الفقرة ٣٠","segs":[["matn","ويكبر مع كل حصاة ولا يقف عندها ويقطع التلبية مع أول حصاة"]]},{"id":"q39_31","label":"كتاب الحج · الفقرة ٣١","segs":[["matn","ثم يذبح إن أحب ثم يحلق أو يقصر والحلق أفضل وقد حل له كل شيء إلا النساء"]]},{"id":"q39_32","label":"كتاب الحج · الفقرة ٣٢","segs":[["matn","ثم يأتي مكة من يومه ذلك أو من الغد أو من بعد الغد فيطوف بالبيت طواف الزيارة ستعة أشواط فإن كان سعى بين الصفا والمروة عقيب طواف القدوم لم يرمل في هذا الطواف ولا سعي عليه وإن لم يكن قدم السعي رمل في هذا الطواف وسعى بعده على ما قدمناه وقد حل له النساء وهذا الطواف هو المفروض في الحج ويكره تأخيره عن هذه الأيام فإن أخره عنها لزمه دم عند أبي حنيفة"]]},{"id":"q39_33","label":"كتاب الحج · الفقرة ٣٣","segs":[["matn","ثم يعود إلى منى فيقيم بها فإذا زالت الشمس من اليوم الثاني من النحر رمى الجمار الثلاث يبتدئ بالتي تلي المسجد فيرميها بسبع حصيات يكبر مع كل حصاة ويقف ويدعو عندها ثم يرمي التي تليها مثل ذلك ويقف عندها ثم يرمي جمرة العقبة كذلك ولا يقف عندها فإذا كان من الغد رمى الجمار الثلاث بعد زوال الشمس كذلك فإذا أراد أن يتعجل النفر نفر إلى مكة وإن أراد أن يقيم رمى الجمار الثلاث في يوم الرابع بعد زوال الشمس فإن قدم الرمي في هذا اليوم قبل الزوال بعد طلوع الفجر جاز عند"]]},{"id":"q39_34","label":"كتاب الحج · الفقرة ٣٤","segs":[["matn","أبي حنيفة رحمه الله، ويكره أن يقدم الإنسان ثقله إلى مكة ويقيم بها حتى يرمي فإذا نفر إلى مكة نزل بالمحصب ثم طاف بالبيت سبعة أشواط لا يرمل فيها وهذا طواف الصدر هو واجب إلا على أهل مكة ثم يعود إلى أهله"]]},{"id":"q39_35","label":"كتاب الحج · الفقرة ٣٥","segs":[["matn","فإن لم يدخل المحرم مكة وتوجه إلى عرفات ووقف بها على ما قدمناه فقد سقط عنه طواف القدوم ولا شيء عليه لتركه"]]},{"id":"q39_36","label":"كتاب الحج · الفقرة ٣٦","segs":[["matn","ومن أدرك الوقوف بعرفة ما بين زوال الشمس من يوم عرفة إلى طلوع الفجر من يوم النحر فقد أدرك الحج"]]},{"id":"q39_37","label":"كتاب الحج · الفقرة ٣٧","segs":[["matn","ومن اجتاز بعرفة وهو نائم أو مغمى عليه أو لم يعلم أنها عرفة أجزأه ذلك عن الوقوف"]]},{"id":"q39_38","label":"كتاب الحج · الفقرة ٣٨","segs":[["matn","والمرأة في جميع ذلك كالرجل غير أنها لا تكشف رأسها وتكشف وجهها ولا ترفع صوتها بالتلبية ولا ترمل في الطواف ولا تسعى بين الميلين ولا تحلق رأسها ولكن تقصر"]]}]},{"id":"q40","title":"باب القران","group":"كتاب الحج","units":[{"id":"q40_1","label":"باب القران · الفقرة ١","segs":[["matn","القران أفضل عندنا من التمتع والإفراد"]]},{"id":"q40_2","label":"باب القران · الفقرة ٢","segs":[["matn","وصفة القران: أن يهمل بالعمرة والحج معا من الميقيات"]]},{"id":"q40_3","label":"باب القران · الفقرة ٣","segs":[["matn","ويقول عقيب صلاته: اللهم إني أريد الحج والعمرة فيسرهما لي وتقبلهما مني فإذا دخل مكة ابتدأ فطاف بالبيت سبعة أشواط يرمل في الثلاث الأول منها ويسعى يعدها بين الصفا والمروة وهذه أفعال العمرة"]]},{"id":"q40_4","label":"باب القران · الفقرة ٤","segs":[["matn","ثم يطوف بعد السعي طواف القدوم ويسعى بين الصفا والمروة كما بينا في المفرد فإذا رمى الجمرة يوم النحر ذبح شاة أو بقرة أو بدنة أوسبع بدنة فهذا دم القران"]]},{"id":"q40_5","label":"باب القران · الفقرة ٥","segs":[["matn","فإن لم يكن له ما يذبح صام ثلاثة أيام في الحج وآخرها يوم عرفة فإن فاته الصوم حتى جاء يوم النحر لم يجزه إلا الدم ثم يصوم سبعة أيام إذا رجع إلى أهله وإن صامها بمكة بعد فراغه من الحج جاز"]]},{"id":"q40_6","label":"باب القران · الفقرة ٦","segs":[["matn","وإن لم يدخل القارن مكة وتوجه مكة وتوجه إلى عرفات فقد صار رافضا لعمرته بالوقوف وبطل عنه دم القران وعليه دم لرفض عمرته وعليه قضاؤها"]]}]},{"id":"q41","title":"باب التمتع","group":"كتاب الحج","units":[{"id":"q41_1","label":"باب التمتع · الفقرة ١","segs":[["matn","التمتع أفضل من الإفراد عندنا"]]},{"id":"q41_2","label":"باب التمتع · الفقرة ٢","segs":[["matn","والتمتع على وجهين: ومتمتع يسوق الهدي ومتمتع لا بسوق الهدي"]]},{"id":"q41_3","label":"باب التمتع · الفقرة ٣","segs":[["matn","وصفة التمتع: أن يبتدئ من الميقات فيحرم بعمرة ويدخل مكة فيطوف لها ويسعى ويحلق أو يقصر وقد حل من عمرته"]]},{"id":"q41_4","label":"باب التمتع · الفقرة ٤","segs":[["matn","ويقطع التلبية إذا ابتدأ بالطواف ويقيم بمكة حلالا فإذا كان يوم التروية أحرم بالحج من المسجد وفعل ما يفعله الحاج المفرد وعليه دم التمتع فإن لم يجد صام ثلاثة أيام في الحج وسبعة إذا رجع"]]},{"id":"q41_5","label":"باب التمتع · الفقرة ٥","segs":[["matn","وإذا أراد المتمتع أن يسوق الهدي أحرم وساق هديه فإن كانت بدنة قلدها بمزادة أو نعل وأشعر البدنة عند أبي يوسف ومحمد وهو: أن يشق سنامها من الجانب الأيمن ولا يشعرها عند أبي حنيفة"]]},{"id":"q41_6","label":"باب التمتع · الفقرة ٦","segs":[["matn","فإذا دخل مكة طاف وسعى ولم يتحلل حتى يحرم بالحج يوم التروية وإن قدم الإحرام قبله جاز وعليه دم فإذا حلق يوم النحر فقد حل من الإحرامين"]]},{"id":"q41_7","label":"باب التمتع · الفقرة ٧","segs":[["matn","وليس لأهل مكة تمتع ولا قران وإنما لهم الإفراد خاصة"]]},{"id":"q41_8","label":"باب التمتع · الفقرة ٨","segs":[["matn","وإذا عاد التمتع إلى أهله بعد فراغه من العمرة ولم يكن ساق الهدي بطل تمتعه"]]},{"id":"q41_9","label":"باب التمتع · الفقرة ٩","segs":[["matn","ومن أحرم بالعمرة قبل أشهر الحج فطاف لها أقل من أربعة أشواط ثم دخلت أشهر الحج فتممها وأحرم بالحج كان متمتعا"]]},{"id":"q41_10","label":"باب التمتع · الفقرة ١٠","segs":[["matn","وإن طاف لعمرته قبل أشهر الحج أربعة أشواط فصاعدا ثم حج من عامه ذلك لم يكن متمتعا"]]},{"id":"q41_11","label":"باب التمتع · الفقرة ١١","segs":[["matn","وأشهر الحج: شوال وذو القعدة وعشر من ذي الحجة فإن قدم الإحرام بالحج عليها جاز إحرامه وانعقد حجا"]]},{"id":"q41_12","label":"باب التمتع · الفقرة ١٢","segs":[["matn","وإذا حاضت المرأة عند الإحرام اغتسلت وأحرمت وصنعت كما يصنعة الحاج"]]},{"id":"q41_13","label":"باب التمتع · الفقرة ١٣","segs":[["matn","غير أنها لا تطوف بالبيت حتى تطهر وإن حاضت بعد الوقوف وطواف الزيارة انصرفت من مكة ولا شيء عليها لترك طواف الصدر"]]}]},{"id":"q42","title":"باب جنايات المحرم","group":"كتاب الحج","units":[{"id":"q42_1","label":"باب جنايات المحرم · الفقرة ١","segs":[["matn","إذا تطيب المحرم فعليه الكفارة فإذا طيب عضوا كاملا فما زاد فعليه دم وإن طيب أقل من عضو فعليه صدقة"]]},{"id":"q42_2","label":"باب جنايات المحرم · الفقرة ٢","segs":[["matn","وإن لبس ثوبا مخيطا أو غطى رأسه يوما كاملا فعليه دم وإن كان أقل من ذلك فعليه صدقة وإن حلق ربع رأسه فصاعدا فعليه دم وإن حلق أقل من الربع فعليه صدقة"]]},{"id":"q42_3","label":"باب جنايات المحرم · الفقرة ٣","segs":[["matn","وإن حلق مواضع المحاجم فعليه دم عند أبي حنيفة وقال أبو يوسف ومحمد: عليه صدقة وإن قص أظافير يديه ورجليه فعليه دم"]]},{"id":"q42_4","label":"باب جنايات المحرم · الفقرة ٤","segs":[["matn","وإن قص يدا أو رجلا فعليه دم وإن قص أقل من خمسة أظافير متفرقة من يديه ورجليه فعليه صدقة عند أبي حنيفة وأبي يوسف وقال محمد: عليه دم"]]},{"id":"q42_5","label":"باب جنايات المحرم · الفقرة ٥","segs":[["matn","وإن تطيب أو حلق أو لبس من عذر فهو مخير: إن شاء ذبح شاة وإن شاء تصدق على ستة مساكين بثلاثة أصوع من طعام وإن شاء صام ثلاثة أيام"]]},{"id":"q42_6","label":"باب جنايات المحرم · الفقرة ٦","segs":[["matn","وإن قبل أو لمس بشهوة فعليه دم ومن جامع في أحد السبيلين قبل الوقوف بعرفة فسد حجه وعليه شاة ويمضي في الحج كما يمضي من لم يفسد حجه وعليه القضاء وليس عليه أن يفارق امرأته إذا حج بها في القضاء"]]},{"id":"q42_7","label":"باب جنايات المحرم · الفقرة ٧","segs":[["matn","ومن جامع بعد الوقوف بعرفة لم يفسد حجه وعليه بدنة فإن جامع بعد الحلق فعليه شاة ومن جامع في العمرة يقبل أن يطوق أربعة أشواط أفسدها ومضى فيها وقضاها وعليه شاة وإن وطئ بعدها طاف أربعة أشواط فعليه شاة ولا تفسد عمرته ولا يلزمه قضاؤها ومن جامع ناسيا كمن جامع عامدا"]]},{"id":"q42_8","label":"باب جنايات المحرم · الفقرة ٨","segs":[["matn","ومن طاف طواف القدوم محدثا فعليه صدقه وإن طاف جنبا فعليه شاة ومن طاف طواف الزيارة محدثا فعليه شاة وإن كان"]]},{"id":"q42_9","label":"باب جنايات المحرم · الفقرة ٩","segs":[["matn","جنبا فلعيه بدنة والأفضل أن يعيد الطواف ما دام بمكة ولا ذبح عليه ومن طاف طواف الصدر محدثا فعليه صدقة وإن طاف جنبا فعليه شاة"]]},{"id":"q42_10","label":"باب جنايات المحرم · الفقرة ١٠","segs":[["matn","ومن ترك من طواف الزيارة ثلاثة أشواط فما دونها فعليه شاة وإن ترك أربعة أشواط بقي محرما أبدا حتى يطوفها ومن ترك ثلاثة أشواط من طواف الصدر فعليه صدقة وإن ترك طواف الصدر أو أربعة أشواط منه فعليه شاة"]]},{"id":"q42_11","label":"باب جنايات المحرم · الفقرة ١١","segs":[["matn","ومن ترك السعي بين الصفا والمروة فعليه شاة وحجه تام"]]},{"id":"q42_12","label":"باب جنايات المحرم · الفقرة ١٢","segs":[["matn","ومن أقاض من عرفه قبل الإمام فعليه دم"]]},{"id":"q42_13","label":"باب جنايات المحرم · الفقرة ١٣","segs":[["matn","ومن ترك الوقوف بالمزدلفة فعليه دم"]]},{"id":"q42_14","label":"باب جنايات المحرم · الفقرة ١٤","segs":[["matn","ومن ترك رمي الجمار في الأيام كلها فعليه دم وإن ترك رمي يوم واحد فعليه دم وإن ترك رمي إحدى الجمار الثلاث فعليه صدقة وإن ترك رمي جمرة العقبة في يوم النحر فعليه دم"]]},{"id":"q42_15","label":"باب جنايات المحرم · الفقرة ١٥","segs":[["matn","ومن أخر الحلف حتى مضت أيام النحر فعليه دم عند أبي حنيفة وكذلك لو أخر طواف الزيارة عند أبي حنيفة رحمه الله"]]},{"id":"q42_16","label":"باب جنايات المحرم · الفقرة ١٦","segs":[["matn","وإذا قتل المحرم صيدا أو دل عليه من قتله فعليه الجزاء يستوي في ذلك العامد والناسي والمبتدئ والعائد والجزاء عند أبي حنيفة وأبي يوسف أن يقوم الصيد في المكان الذي قتله فيه أو في أقرب المواضع منه إن كان في برية يقومه ذوا عدل ثم هو مخير في القيمة إن شاء ابتاع بها هديا وإن شاء اشترى بها طعاما فتصدق به على كل مسكين نصيف صاع من بر أو صاعا من تمر أوشعير وإن شاء صام عن كل نصف صاع من بر يوما وعن كل صاع من شعير يوما فإن فضل من الطعام أقل من نصف صاع فهو مخير: إن شاء تصدق به وإن شاء صام عنه يوما كاملا"]]},{"id":"q42_17","label":"باب جنايات المحرم · الفقرة ١٧","segs":[["matn","وقال محمد: يجب في الصيد النظير فيما له نظير ففي الظبي شاة وفي الضبع شاة وفي الأرنب عناق وفي النعامة بدنة وفي اليربوع جفرة ومن جرح صيدا أو نتف شعره أو قطع عضوا منه ضمن ما نقصه وإن نتف ريش طائر أو قطع قوائم صيد فخرج من حيز الامتناع فعليه قيمته كاملة ومن كسر بيض صيد فعليه قيمته فإن خرج من البيض فرخ فلعيه قيمته كاملة ومن كسر بيض صيد فعليه قيمته فإن خرج من البيض فرخ ميت فعليه قيمته حيا وليس في قتل الغراب والحدأة والذئب والحية والعقرب والفأرة جزاء"]]},{"id":"q42_18","label":"باب جنايات المحرم · الفقرة ١٨","segs":[["matn","وليس في قتل البعوض والبراغيث والقراد شيء"]]},{"id":"q42_19","label":"باب جنايات المحرم · الفقرة ١٩","segs":[["matn","ومن قتل قملة تصدق بما شاء ومن قتل جرادة تصدق بما شاء وتمرة خير من جرادة"]]},{"id":"q42_20","label":"باب جنايات المحرم · الفقرة ٢٠","segs":[["matn","ومن قتل ما لا يؤكل لحمه من الصيد كالسباع ونحوها فعليه الجزاء ولا يتجاوز بقيمتها شاة"]]},{"id":"q42_21","label":"باب جنايات المحرم · الفقرة ٢١","segs":[["matn","وإن صال السبع على محرم فقتله فلا شيء عليه"]]},{"id":"q42_22","label":"باب جنايات المحرم · الفقرة ٢٢","segs":[["matn","وإن اضطر المحرم إلى أكل لحم الصيد فقتله فعليه الجزاء ولا بأس أن يذبح المحرم الشاة والبقرة والبعير والدجاج والبط الكسكري وإن قتل حماما مسرولا أو ظبيا مستأنسا فعليه الجزاء"]]},{"id":"q42_23","label":"باب جنايات المحرم · الفقرة ٢٣","segs":[["matn","وإن ذبح المحرم صيدا فذبيحته ميتة لا يحل أكلها ولا بأس أن يأحل المحرم لحم صيد اصطاده أو ذبحه إذا لم يدله المحرم عليه ولا أمره بصيده وفي صيد الحرم إذا ذبحه الحلال فعليه الجزاء وإن قطع حشيش الحرم أو شجره الذي ليس بمملوك ولا هو مما ينبته الناس فعليه قيمته"]]},{"id":"q42_24","label":"باب جنايات المحرم · الفقرة ٢٤","segs":[["matn","وكل شيء فعله القارن مما ذكرنا أن فيه على المفرد دما فعليه دمان: دم لحجته ودم لعمرته إلا أن يتجاوز الميقات من غير إحرام ثم يحرم بالعمرة والحج فيلزمه دم واحد وإذا اشترك المحرمان في قتل صيد فعلى كل واحد منهما الجزاء كاملا وإذا اشترك الحلالان في قتل صيد الحرم فعليهما جزاء واحد"]]},{"id":"q42_25","label":"باب جنايات المحرم · الفقرة ٢٥","segs":[["matn","وإذا باع المحرم صيدا أو ابتاعه فالبيع باطل"]]}]},{"id":"q43","title":"باب الإحصار","group":"كتاب الحج","units":[{"id":"q43_1","label":"باب الإحصار · الفقرة ١","segs":[["matn","إذا أحصر المحرم بعدو أو أصابه مرض منعه من المضي جاز له التحلل وقيل له: ابعث شاة تذبح في الحرم وواعد من يحملها يوما بعينه يذبحها فيه ثم تحلل وإن كان قارنا بعث بدمين"]]},{"id":"q43_2","label":"باب الإحصار · الفقرة ٢","segs":[["matn","ولا يجوز ذبح دم الإحصار إلا في الحرم ويجوز ذبحه قبل يوم النحر عند أبي حنيفة وقال أبو يوسف ومحمد رحمهما الله: لا يجوز الذبح للمحصر بالحج إلا في يوم النحر"]]},{"id":"q43_3","label":"باب الإحصار · الفقرة ٣","segs":[["matn","ويجوز للمحصر بالعمرة أن يذبح متى شاء والمحصر بالحج إذا تحلل فعليه"]]},{"id":"q43_4","label":"باب الإحصار · الفقرة ٤","segs":[["matn","حجة وعمرة وعلى المحصر بالعمرة القضاء وعلى القارن حجة وعمرتان"]]},{"id":"q43_5","label":"باب الإحصار · الفقرة ٥","segs":[["matn","وإذا بعث المحصر هديا وواعدهم أيذبحوه في يوم بعينه ثم زال الإحصار فإن قدر على إدراك الهدي والحج لم يجز له التحلل ولزمه المضي وإن قدر على إدراك الهدي دون الحج تحلل وإن قدر على إدراك الحج دون الهدي جاز له التحلل استحسانا"]]},{"id":"q43_6","label":"باب الإحصار · الفقرة ٦","segs":[["matn","ومن أحضر بمكة وهو ممنوع من الوقوف والطواف كان محصرا وإن قدر على إحدهما فليس بمحصر"]]}]},{"id":"q44","title":"باب الفوات","group":"كتاب الحج","units":[{"id":"q44_1","label":"باب الفوات · الفقرة ١","segs":[["matn","ومن أحرم بالحج ففاته الوقوف بعرفة حتى طلع"]]},{"id":"q44_2","label":"باب الفوات · الفقرة ٢","segs":[["matn","الفجر من يوم النحر فقد فاته الحج وعليه أن يطوف ويسعى ويتحلل ويقضي الحج من قابل ولا دم عليه"]]},{"id":"q44_3","label":"باب الفوات · الفقرة ٣","segs":[["matn","والعمرة لا تفوت وهي جائزة في جميع السنة إلا خمسة أيام يكره فعلها فيها: يوم عرفة ويوم النحر وأيام التشريق"]]},{"id":"q44_4","label":"باب الفوات · الفقرة ٤","segs":[["matn","والعمرة سنة وهي: الإحرام والطواف والسعي والحلق أو التقصير"]]}]},{"id":"q45","title":"باب الهدي","group":"كتاب الحج","units":[{"id":"q45_1","label":"باب الهدي · الفقرة ١","segs":[["matn","الهدي: أدناه شاة وهو من ثلاثة نوع: الإبل والبقر والغنم يجزئ في ذلك الثني فصاعدا إلا من الضأن فإن الجذع منه يجزئ ولا يجوز في الهدي مقطوع الأذن أو أكثرها ولا مقطوع الذنب ولا اليد ولا الرجل ولا الذاهبة العين ولا العجفاء ولا العرجاء التي لا تمشي إلى المسك والشاة جائزة في كل شيء إلا في موضعين: من طاف طواف الزيارة جنبا ومن جامع بعد الوقوف بعرفة فإنه لا يجوز إلا بدنة"]]},{"id":"q45_2","label":"باب الهدي · الفقرة ٢","segs":[["matn","والبدنة والبقرة تجزئ كل واحدة منهما عن سبعة إذا كان كل"]]},{"id":"q45_3","label":"باب الهدي · الفقرة ٣","segs":[["matn","واحد من الشركاء يريد القربة فإن أراد أحدهم بنصيبه اللحم لم يجزئ عن الباقين ويجوز الأكل من هدي التطوع والمتعة والقران"]]},{"id":"q45_4","label":"باب الهدي · الفقرة ٤","segs":[["matn","ولا يجوز الأكل من بقية الهدايا ولا يجوز ذبح هدي التطوع"]]},{"id":"q45_5","label":"باب الهدي · الفقرة ٥","segs":[["matn","والمتعة والقران إلا في يوم النحر ويجوز ذبح بقية الهدايا أي وقت شاء ولا يجوز ذبح الهدايا إلا في الحرم ويجوز أن يتصدق بها على مساكين الحرم وغيرهم ولا يجب التعريف بالهدايا والأفضل في البدن النحر وفي البقر والغنم الذبح"]]},{"id":"q45_6","label":"باب الهدي · الفقرة ٦","segs":[["matn","والأولى أن يتولى الإنسان ذبحها بنفسه إذا كان يحسن ذلك ويتصدق بجلالها وخطامها ولا يعطي أجرة الجزار منها"]]},{"id":"q45_7","label":"باب الهدي · الفقرة ٧","segs":[["matn","ومن ساق بدنة فاضطر إلى ركوبها ركبها وإن استغنى عن ذلك لم يركبها وإن كان لها لبن لم يحلبها وينضح ضرعها بالماء البارد حتى ينقطع اللبن"]]},{"id":"q45_8","label":"باب الهدي · الفقرة ٨","segs":[["matn","ومن ساق هديا فعطب فإن كان تطوعا فليس عليه غيره وإن كان عن واجب فعليه أن يقيم غيره مقامه وإن أصابه عيب كبير أقام غيره مقامه"]]},{"id":"q45_9","label":"باب الهدي · الفقرة ٩","segs":[["matn","وصنع بالمغيب ما شاء وإذا عطبت البدنة في الطريق فإن كان تطوعا نحرها وصبغ نعلها بدمها وضرب بها صفحتها ولا يأكل منها هو ولا غيره من الأغنياء وإن كانت واجبة أقام غيرها مقامها وصنع بها ما شاء ويقلد هدي التطوع والمتعة والقران ولا يقلد دم الإحصار ولا دم الجنايات"]]}]},{"id":"q46","title":"كتاب البيوع","group":"كتاب البيوع","units":[{"id":"q46_1","label":"كتاب البيوع · الفقرة ١","segs":[["matn","البيع: ينعقد بالإيجاب والقبول إذا كانا بلفظ الماضي"]]},{"id":"q46_2","label":"كتاب البيوع · الفقرة ٢","segs":[["matn","وإذا أوجب أحد المتعاقدين البيع فالآخر بالخيار: إن شاء قبل في المجلس وإن شاء رده وأيهما قام من المجلس قبل القبول بطل الإيجاب وإذا حصل الإيجاب والقبول لزم البيع ولا خيار لواحد منهما إلا من عيب أو عدم رؤية والأعواض المشار إليها لا يحتاج إلى معرفة مقدراها في جواز البيع والأثمان المطلقة لا تصح إلا أن تكون معروفة القدر والصفة"]]},{"id":"q46_3","label":"كتاب البيوع · الفقرة ٣","segs":[["matn","ويجوز البيع بثمن حال ومؤجل إذا كان الأجل معلوما ومن أطلق الثمن في البيع كان على غالب نقد البلد فإن كانت النقود مختلفة فالبيع فاسد إلا أن يبين أحدها"]]},{"id":"q46_4","label":"كتاب البيوع · الفقرة ٤","segs":[["matn","ويجوز بيع الطعام والحبوب مكايلة ومجازفة وبإناء بعينه لا يعرف مقدراه وبوزن حجر بعينه لا يعرف مقداره ومن باع صبرة طعام كل قفيز بدرهم جاز البيع في قفيز واحد عند أبي حنيفة إلا أن يسمي جملة قفزانها ومن باع قطيع غنم كل شاة بدرهم فالبيع فاسد في جميعها وكذلك من باع ثوبا مذارعة كل ذراع"]]},{"id":"q46_5","label":"كتاب البيوع · الفقرة ٥","segs":[["matn","بدرهم ولم يسم جمله الذرعان ومن ابتاع صبرة على أنها قفيز بمائة درهم فوجدها أقل كان المشتري بالخيار: إن شاء أخذ الموجود بحصته من الثمن وإن شاء فسخ البيع وإن وجدها أكثر فالزيادة للبائع ومن اشترى ثوبا على أنه عشرة أذرع بعشرة دراهم أو أرضا على أنها مائة ذراع بمائة درهم فوجدها أقل فالمشتري بالخيار: إن شاء أخذها بجملة الثمن وإن شاء تركها وإن وجدها أكثر من الذراع الذي سماه فهو المشتري ولا خيار للبائع وإن قال: بعتكها على أنها مائة ذراع بمائة درهم كل ذراع بدرهم فوجدها ناقصة فهو الخيار: إن شاء أخذها بحصتها من الثمن وإن شاء تركها وإن وجدها"]]},{"id":"q46_6","label":"كتاب البيوع · الفقرة ٦","segs":[["matn","زائد كان المشتري بالخيار: إن شاء أخذ الجيمع كل ذراع بدرهم وإن شاء فسخ البيع ومن باع دارا دخل بناؤها في البيع وإن لم يسمه"]]},{"id":"q46_7","label":"كتاب البيوع · الفقرة ٧","segs":[["matn","ومن باع أرضا دخل ما فيها وإن لم يسمه ولا يدخل الزرع في بيع الأرض إلا بالتسمية ومن باع نخلا أو شجرا فيه ثمر فثمرته للبائع إلا أن يشترطها المبتاع ويقال للبائع: اقطعها وسلم المبيع ومن باع ثمرة لم يبد صلاحها أو قد بدا جاز البيع ووجب على المشتري قطعها في الحال فإن شرط تركها على النخل فسد البيع"]]},{"id":"q46_8","label":"كتاب البيوع · الفقرة ٨","segs":[["matn","ولا يجوز أن يبيع ثمرة ويستثني منها أرطالا معلومة ويجوز بيع الحنطة في سبيلها والباقلاء في قشرها ومن باع دارا دخل في المبيع مفاتيح أغلاقها وأجرة الكيال وناقد الثمن على البائع وأجرة وزان الثمن على المشتري ومن باع سلعة بثمن قيل للمشتري: ادفع الثمن أولا فإذا دفع قيل للبائع: سلم البيع ومن باع سلعة بسلعة أو ثمنا بثمن قيل لهما سلما معا"]]}]},{"id":"q47","title":"باب خيار الشرط","group":"كتاب البيوع","units":[{"id":"q47_1","label":"باب خيار الشرط · الفقرة ١","segs":[["matn","خيار الشرط: جائز في البيع للبائع والمشتري ولهما الخيار ثلاثة أيام فما دونها ولا يجوز أكثر من ذلك عند أبي حنيفة رحمه الله وقال أبو يوسف ومحمد رحمهما الله: يجوز إذا سمى مدة معلومة"]]},{"id":"q47_2","label":"باب خيار الشرط · الفقرة ٢","segs":[["matn","وخيار البائع يمنع خروج المبيع من ملكه فإن قبضه المشتري فهلك في يده صمنه بالقيمة وخيار المشتري لا يمنع خروج المبيع من ملك البائع إلا أن المشتري لا يملكه عند أبي حنيفة وعندهما يملكه فإن هلك في يده هلك بالثمن وكذلك إن دخله عيب ومن شرط له الخيار فله أن يفسخ في مدة الخيار وله أن يجيزه فإن أجازه بغير حضره صاحبه جاز وإن فسخ لم يجز إلا أن يكون الآخر حاضرا وإذا مات من له الخيار بطل خياره ولم ينتقل إلى ورثته"]]},{"id":"q47_3","label":"باب خيار الشرط · الفقرة ٣","segs":[["matn","ومن باع عبدا على أنه خباز أو كاتب بخلاف ذلك فالمشتري بالخيار: إن شاء أخذه بجميع الثمن وإن شاء ترك"]]}]},{"id":"q48","title":"باب خيار الرؤية","group":"كتاب البيوع","units":[{"id":"q48_1","label":"باب خيار الرؤية · الفقرة ١","segs":[["matn","ومن اشتر شيئا لم يره فالبيع جائز"]]},{"id":"q48_2","label":"باب خيار الرؤية · الفقرة ٢","segs":[["matn","وله الخيار إذا رآه: إن شاء أخذه وإن شاء دره ومن باع ما لم يره فلا خيار له ومن نظر إلى وجه الصبرة إلى ظاهر الثوب مطويا أو إلى وجه الجارية أو إلى وجه الدابة وكفلها فلا خيار له وإن رأى صحن الدار فلا خيار له وإن لم يشاهد"]]},{"id":"q48_3","label":"باب خيار الرؤية · الفقرة ٣","segs":[["matn","بيوتها وبيع الأعمى وشرؤاه جائز وله الخيار إذا اشترى ويسقط خياره بأن يجس المبيع إذا كان يعرف بالجس أو يشمه إذا كان يعرف بالشم أو يذوقه إذا كان يعرف بالذوق ولا يسقط خياره في العقار حتى يوصف له"]]},{"id":"q48_4","label":"باب خيار الرؤية · الفقرة ٤","segs":[["matn","ومن باع ملك غيره أمره فالمالك بالخيار: إن شاء أجاز البيع وإن شاء فسخ وله الإجازة إذا كان المعقود عليه باقيا والمتعاقدان بحالهما"]]},{"id":"q48_5","label":"باب خيار الرؤية · الفقرة ٥","segs":[["matn","ومن رأى أحد ثوبين فاشتراهما ثم رأى الآخر جاز له أن يردهما"]]},{"id":"q48_6","label":"باب خيار الرؤية · الفقرة ٦","segs":[["matn","ومن مات وله خيار الرؤية بطل خياره ومن رأى شيئا ثم اشتراه بعد مدة: فإن كان على الصفة التي رآه فلا خيار له وإن وجده متغيرا فله الخيار"]]}]},{"id":"q49","title":"باب خيار العيب","group":"كتاب البيوع","units":[{"id":"q49_1","label":"باب خيار العيب · الفقرة ١","segs":[["matn","إذا طلع المشتري على عيب في المبيع فهو الخيار: إن شاء أخذه بجميع الثمن وإن شاء رده وليس له أن يمسكه ويأخذ النقصان"]]},{"id":"q49_2","label":"باب خيار العيب · الفقرة ٢","segs":[["matn","وكل ما أوجب نقصان الثمن في عادة التجار فهو عيب والإباق والبول في الفراش والسرقة عيب في الصغير ما لم يبلغ فإذا بلغ"]]},{"id":"q49_3","label":"باب خيار العيب · الفقرة ٣","segs":[["matn","فليس ذلك بعيب حتى يعادوه بعد البلوغ والبخر والدفر عيب في الجارية وليس بعيب في الغلام إلا أن يكون من داء والزنا وولد الزنا عيب في الجارية دون الغلام"]]},{"id":"q49_4","label":"باب خيار العيب · الفقرة ٤","segs":[["matn","وإذا حدث عند المشتري عيب ثم اطلع على عيب كان عند البائع فله أن يرجع بنقصان العيب ولا يرد المبيع إلا أن يرضى البائع أن يأخذه بعيبه وإن قطع المشتري الثوب فوجد به عيبا رجع بالعيب وإن خاطه أو صبغه أو لت السويق بسمن ثم اطلع على عيب رجع بنقصانه وليس للبائع أن يأخذه ومن اشترى عبدا فأعتقه أو مات ثم اطلع على عيب رجع بنقصانه فإن قتل المشتري العبد أو كان طعاما فأكله لم يرجع عليه بشيء في قول أبي حنيفة وقال أبو يوسف ومحمد: يرجع"]]},{"id":"q49_5","label":"باب خيار العيب · الفقرة ٥","segs":[["matn","ومن باعا عبدا فباعه المشتري ثم رد عليه بعيب فإن قبله بقضاء القاضي فله أن يرده على بائعه وإن قبله بغير قضاء القاضي فليس له أن يرده"]]},{"id":"q49_6","label":"باب خيار العيب · الفقرة ٦","segs":[["matn","ومن اشترى عبدا وشرط البراءة من كل عيب فليس له أن يرده بعيب وإن لم يسم العيوب ولم يعدها"]]}]},{"id":"q50","title":"باب البيع الفاسد","group":"كتاب البيوع","units":[{"id":"q50_1","label":"باب البيع الفاسد · الفقرة ١","segs":[["matn","إذا كان أحد العوضين أو كلاهما محرما فالبيع فاسد كالبيع بالميتة أو بالدم أو بالخمر أو بالخنزير وكذلك إذا كان غير مملوك كالحر وبيع أم الولد والمدبر والمكاتب فاسد ولا يجوز بيع السمك في الماء ولا بيع الطير في الهواء ولا يجوز بيع الحمل ولا النتاج ولا بيع اللبن في الضرع والصرف على ظهر الغنم وذراع من ثوب وجذع في سقف وضربة القانص وبيع المزابنة - وهو بيع الثمر على رؤوس النخل بخرصه تمرا - ولا يجوز البيع بإلقاء الحجر والملامسة"]]},{"id":"q50_2","label":"باب البيع الفاسد · الفقرة ٢","segs":[["matn","ولا يجوز بيع ثوب من ثوبين"]]},{"id":"q50_3","label":"باب البيع الفاسد · الفقرة ٣","segs":[["matn","ومن باع عبدا على أن يعتقه المشتري أو يدبره أو يكاتبه أو باع أمة على أن يستولدها فالبيع فاسد وكذلك لو باع عبدا على أن يستخدمه البائع شهرا أو دارا"]]},{"id":"q50_4","label":"باب البيع الفاسد · الفقرة ٤","segs":[["matn","على أن يسكهنا أو على أن يقرضه المشتري درهما أو على أن يهدي له هدية"]]},{"id":"q50_5","label":"باب البيع الفاسد · الفقرة ٥","segs":[["matn","ومن باع عينا على أن لا يسلمها إلى رأس الشهر فالبيع فاسد ومن باع جارية إلا حملها فسد البيع"]]},{"id":"q50_6","label":"باب البيع الفاسد · الفقرة ٦","segs":[["matn","ومن اشترى ثوبا على أن يقطعه البائع ويخيطه قميصا أو قباء أو نعلا على أن يحذوها أو يشركها فالبيع فاسد والبيع إلى النيروز والمهرجان وصوم النصارى وفطر اليهود - إذا"]]},{"id":"q50_7","label":"باب البيع الفاسد · الفقرة ٧","segs":[["matn","لم يعرف المتبايعان ذلك فالبيع فاسد"]]},{"id":"q50_8","label":"باب البيع الفاسد · الفقرة ٨","segs":[["matn","ولا يجوز البيع إلى الحصاد والدياس والقطاف وقدوم الحاج فإن تراضيا"]]},{"id":"q50_9","label":"باب البيع الفاسد · الفقرة ٩","segs":[["matn","بإسقاط الأجل قبل أن يأخذ الناس في الحصاد والدياس وقبل قدوم الحاج جاز البيع"]]},{"id":"q50_10","label":"باب البيع الفاسد · الفقرة ١٠","segs":[["matn","وإذا قبض المشتري المبيع في البيع الفاسد بأمر البائع وفي العقد عوضان كل واحد منهما مال ملك المبيع ولزمته قيمته ولكل واحد من المتعاقدين فسخه فإن باعه المشتري نفذ بيعه"]]},{"id":"q50_11","label":"باب البيع الفاسد · الفقرة ١١","segs":[["matn","ومن جمع بين حر وعبد أو شاة ذكية وميتة بطل البيع فيهما ومن جمع بين عبد ومدبر أو عبده وعبد غيره صح العقد في العبد بحصته من الثمن"]]},{"id":"q50_12","label":"باب البيع الفاسد · الفقرة ١٢","segs":[["matn","ونهى رسول الله صلى الله عليه وسلم عن النجش وعن السوم على سوم غيره وعن تلقي الجلب وعن بيع الحاضر للبادي وعن البيع عند أذان الجمعة وكل ذلك يكره ولا يفسد به العقد"]]},{"id":"q50_13","label":"باب البيع الفاسد · الفقرة ١٣","segs":[["matn","ومن ملك مملوكين صغيرين أحدهما ذو رحم محرم من الآخر لم يفرق بينهما وكذلك إن كان أحدهما كبيرا والآخر صغيرا فإن فرق بينهما كره له ذلك وجاز البيع وإن كانا كبيرين فلا بأس بالتفريق بينهما"]]}]},{"id":"q51","title":"باب الإقالة","group":"كتاب البيوع","units":[{"id":"q51_1","label":"باب الإقالة · الفقرة ١","segs":[["matn","الإقالة: جائزة في البيع"]]},{"id":"q51_2","label":"باب الإقالة · الفقرة ٢","segs":[["matn","بمثل الثمن الأول فإن شرط أقل منه أو أكثر فالشرط باطل ويرد مثل الثمن الأول وهي فسخ في حق المتعاقدين بيع جديد في حق غيرهما في قول أبي حنيفة"]]},{"id":"q51_3","label":"باب الإقالة · الفقرة ٣","segs":[["matn","وهلاك الثمن لا يمنع صحة الإقالة وهلاك المبيع يمنع منها فإن هلك بعض المبيع جازت الإقالة في باقيه"]]}]},{"id":"q52","title":"باب المرابحة والتولية","group":"كتاب البيوع","units":[{"id":"q52_1","label":"باب المرابحة والتولية · الفقرة ١","segs":[["matn","المرابحة: نقل ما ملكه بالعقد الأول بالثمن الأول"]]},{"id":"q52_2","label":"باب المرابحة والتولية · الفقرة ٢","segs":[["matn","مع زيادة ربح والتولية: نقل ما ملكه بالعقد الأول بالثمن الأول من غير زيادة ربح"]]},{"id":"q52_3","label":"باب المرابحة والتولية · الفقرة ٣","segs":[["matn","ولا تصح المرابحة ولا التولية حتى يكون العوض مما له مثل ويجوز أن يضيف إلى رأس المال أجرة القصار والصباغ والطراز والفتل وأجرة حمل الطعام ولكن يقول: قام علي بكذا ولا يقول: اشتريته بكذا"]]},{"id":"q52_4","label":"باب المرابحة والتولية · الفقرة ٤","segs":[["matn","فإن اطلع المشتري على خيانة في المرابحة فهو بالخيار عند أبي حنيفة: إن شاء أخذه بجميع الثمن وإن شاء رده وإن اطلع على خيانة في التولية أسقطها المشتري من الثمن"]]},{"id":"q52_5","label":"باب المرابحة والتولية · الفقرة ٥","segs":[["matn","وقال أبو يوسف: يحط فيهما وقال محمد: لا يحط فيهما"]]},{"id":"q52_6","label":"باب المرابحة والتولية · الفقرة ٦","segs":[["matn","ومن اشترى شيئا مما ينقل ويحول لم يجز له بيعه حتى يقبضه ويجوز بيع العقار قبل القبض عند أبي حنيفة وأبي يوسف وقال محمد: لا يجوز"]]},{"id":"q52_7","label":"باب المرابحة والتولية · الفقرة ٧","segs":[["matn","ومن اشترى مكيلا مكايلة أو موزونا موازنة فاكتاله أو أتزنه ثم باعه مكايلة أو موازنة لم يجز للمشتري منه أن يبيعه ولا يأكله حتى يعيد الكيل والوزن والتصرف في الثمن قبل القبض في الثمن قبل القبض جائز"]]},{"id":"q52_8","label":"باب المرابحة والتولية · الفقرة ٨","segs":[["matn","ويجوز للمشتري أن يزيد البائع في الثمن ويجوز للبائع أن يزيد في المبيع ويجوز أن يحط من الثمن ويتعلق الإستحقاق بجميع ذلك"]]},{"id":"q52_9","label":"باب المرابحة والتولية · الفقرة ٩","segs":[["matn","ومن باع بثمن حال ثم أجله أجلا معلوما مؤجلا وكل دين حال إذا أجله صاحبه صار مؤجلا إلا القرض فإن تأجيله لا يصح"]]}]},{"id":"q53","title":"باب الربا","group":"كتاب البيوع","units":[{"id":"q53_1","label":"باب الربا · الفقرة ١","segs":[["matn","الربا محرم كل مكيل أو موزون إذا بيع بجنسه متفاضلا فالعلة فيه الكيل مع الجنس مع الجنس أو الوزن مع الجنس فإذا بيع المكيل أو الموزون بجنسه مثلا بمثل جاز البيع وإن تفاضلا لم يجز"]]},{"id":"q53_2","label":"باب الربا · الفقرة ٢","segs":[["matn","ولا يجوز: بيع الجيد بالرديء مما فيه إلا مثلا بمثل فإذا عدم الوصفان الجنس والمعنى المضموم إليه حل التفاضل والنساء وإذا وجدوا حرم التفاضل والنساء وإذا وجد أحدهما وعدم الآخر حل التفاضل وحرم النساء"]]},{"id":"q53_3","label":"باب الربا · الفقرة ٣","segs":[["matn","وكل شيء نص رسول الله صلى الله عليه وسلم على تحريم التفاضل فيه كيلا فهو مكيل أبدا وإن ترك الناس الكيل فيه مثل الحنطة والشعير والتمر والملح وكل ما نص على تحريم التفاضل فيه وزنا فهو موزون أبدا مثل الذهب والفضة وما لم ينص عليه فهو محمول عادات الناس"]]},{"id":"q53_4","label":"باب الربا · الفقرة ٤","segs":[["matn","وعقد الصرف: بما وقع على جنس الأثمان يعتبر فيه قبض عوضيه في وما سواه مما فيه الربا يعتبر فيه التعيين ولا يعتبر فيه التقابض ولا يجوز بيع الحنطة بالدقيق ولا بالسويق"]]},{"id":"q53_5","label":"باب الربا · الفقرة ٥","segs":[["matn","ويجوز: بيع اللحم بالحيوان عند أبي حنيفة وأبي يوسف وقال محمد: لا يجوز إلا أن يكون اللحم الذي في الحيوان أقل مما هو المعقود عليه"]]},{"id":"q53_6","label":"باب الربا · الفقرة ٦","segs":[["matn","ويجوز: بيع الرطب بالتمر مثلا بمثل والعنب بالزبيب ولا يجوز بيع الزيتون بالزيت والسمسم بالشيرج"]]},{"id":"q53_7","label":"باب الربا · الفقرة ٧","segs":[["matn","حتى يكون الزيت والشيرج أكثر مما في الزيتون والسمسم فيكون الدهن بمثله والزيادة بالثجير"]]},{"id":"q53_8","label":"باب الربا · الفقرة ٨","segs":[["matn","ويجوز بيع اللحمان المختلفة بعضها ببعض متفاضلا وكذلك ألبان البقر والغنم وحل الدقل بخل العنب ويجوز بيع الخبز بالحنطة والدهن متفاضلا"]]},{"id":"q53_9","label":"باب الربا · الفقرة ٩","segs":[["matn","ولا ربا بين المولى وعبده ولا بين المسلم والحربي في دار الحرب"]]}]},{"id":"q54","title":"باب السلم","group":"كتاب البيوع","units":[{"id":"q54_1","label":"باب السلم · الفقرة ١","segs":[["matn","السلم جائز في المكيلات والموزونات والمعدودات التي لا تتفاوت كالجوز والبيض وفي المذروعات ولا يجوز السلم في الحيوان ولا في أطرافه ولا في الجلود عددا ولا في الحطب حزما ولا في الرطبة جرزا"]]},{"id":"q54_2","label":"باب السلم · الفقرة ٢","segs":[["matn","ولا يجوز السلم حتى يكون المسلم فيه موجودا من حين العقد إلى حين المحل ولا يصح السلم إلا مؤجلا ولا يجوز إلا بأجل معلوم ولا يجوز السلم بمكيال رجل بعينه ولا بذراع رجل بعينه"]]},{"id":"q54_3","label":"باب السلم · الفقرة ٣","segs":[["matn","ولا في طعام قرية بعينها ولا ثمرة نخلة بعينها"]]},{"id":"q54_4","label":"باب السلم · الفقرة ٤","segs":[["matn","ولا يصح السلم عند أبي حنيفة إلا بسبع شرائط تذكر العقد: جنس معلوم ونوع معلوم وصفة معلومة وأجل معلوم ومعرفة مقدار رأس المال إذا كان مما يتعلق العقد على قدره كالمكيل والموزون والمعدود وتسمية المكان الذي يوافيه فيه إذا كان له حمل ومؤنة"]]},{"id":"q54_5","label":"باب السلم · الفقرة ٥","segs":[["matn","وقال أبو يوسف ومحمد: لا يحتاج إلى تسمية رأس المال إذا كان معنيا ولا إلى مكان التسليم ويسلمه في موضع العقد"]]},{"id":"q54_6","label":"باب السلم · الفقرة ٦","segs":[["matn","ولا يصح السلم حتى يقبض رأس المال قبل أن يفارقه"]]},{"id":"q54_7","label":"باب السلم · الفقرة ٧","segs":[["matn","ولا يجوز التصرف في رأس المال ولا في المسلم فيه قبل قبض ولا تجوز الشركة ولا التولية في المسلم فيه قبل قبضه"]]},{"id":"q54_8","label":"باب السلم · الفقرة ٨","segs":[["matn","ويجوز السلم في الثياب إذا سمى طولا وعرضا ورقعة ولا يجوز السلم في الجواهر ولا في الخرز ولا بأس بالسلم في اللبن والآجر إذا سمى ملبنا معلوما"]]},{"id":"q54_9","label":"باب السلم · الفقرة ٩","segs":[["matn","وكل ما أمكن ضبط صفته ومعرفة مقدراه جاز السلم فيه وما لا يمكن ضبط صفته ولا يعرف مقدراه لا يجوز السلم فيه"]]},{"id":"q54_10","label":"باب السلم · الفقرة ١٠","segs":[["matn","ويجوز بيع الكلب والفهد والسباع ولا يجوز بيع الخمر والخنزير ولا يجوز بيع دود القز إلا أن يكون مع القز ولا النحل إلا مع الكوارات"]]},{"id":"q54_11","label":"باب السلم · الفقرة ١١","segs":[["matn","وأهل الذمة في البياعات كالمسلمين إلا في الخمر والخنزير خاصة فإن عقدهم على الخمر كعقد المسلم على العصير وعقدهم على الخنزير كعقد المسلم على الشاة"]]}]},{"id":"q55","title":"باب الصرف","group":"كتاب البيوع","units":[{"id":"q55_1","label":"باب الصرف · الفقرة ١","segs":[["matn","الصرف هو: البيع إذا كان كل واحد من العوضين من جنس الأثمان فإن باع فضة بفضة أو ذهبا بذهب لم يجز إلا مثلا بمثل وإن اختلفا في الجودة والصياغة ولا بد من قبض العوضين قبل الافترق"]]},{"id":"q55_2","label":"باب الصرف · الفقرة ٢","segs":[["matn","وإذا باع الذهب بالفضة جاز التفاضل ووجب التقابض وإن افترقا في الصرف قبل قبض العوضين أو أحدهما بطل العقد"]]},{"id":"q55_3","label":"باب الصرف · الفقرة ٣","segs":[["matn","ولا يجوز التصرف في ثمن الصرف قبل قبضه"]]},{"id":"q55_4","label":"باب الصرف · الفقرة ٤","segs":[["matn","ويجوز بيع الذهب بالفضة مجازفة"]]},{"id":"q55_5","label":"باب الصرف · الفقرة ٥","segs":[["matn","ومن باع سيفا محلى بمائة درهم وحليته خمسون درهما فدفع من ثمنه خمسين جاز البيع وكان المقبوض حصة الفضة وإن لم يبين ذلك وكذلك إن قال: خذ هذه الخمسين من ثمنهما فإن لم يتقابضا حتى افترقا بطل العقد في الحلية والسيف إن كان لا يتخلص إلا بضرر وإن كان يتخلص بغير ضرر جاز البيع في السيف"]]},{"id":"q55_6","label":"باب الصرف · الفقرة ٦","segs":[["matn","وبطل في الحلية ومن باع إناء فضة ثم افترقا وقد قبض بعض ثمنه بطل العقد فيما لم يقبض وصح فيما قبض وكان الإناء مشتركا بينهما وإن استحق بعض الإناء كان المشتري بالخيار: إن شاء أخذ الباقي بحصته من الثمن وإن شاء رده"]]},{"id":"q55_7","label":"باب الصرف · الفقرة ٧","segs":[["matn","وإن باع قطعة نقرة فاستحق أخذ ما بقي بحصته ولا خياؤ له ومن باع درهمين ودينارا بدينارين ودرهم جاز البيع وجعل كل واحد من الجنسين بالجنس الآخر"]]},{"id":"q55_8","label":"باب الصرف · الفقرة ٨","segs":[["matn","ومن باع أحد عشر درهما بعشرة دراهم ودينار جاز البيع وكانت العشرة بمثلها والدينار بدرهم"]]},{"id":"q55_9","label":"باب الصرف · الفقرة ٩","segs":[["matn","ويجوز بيع درهمين صحيحين ودرهم غلة بدرهم"]]},{"id":"q55_10","label":"باب الصرف · الفقرة ١٠","segs":[["matn","صحيح ودرهمين غلة وإذا كان الغالب على الدراهم الفضة فهي فضة وإن كان الغالب على الدنانير الذهب فهي ذهب ويعتبر فيهما من تحريم التفاضل ما يعتبر في الجياد وإن كان الغالب عليهما الغش فليسا في حكم الدراهم والدنانير"]]},{"id":"q55_11","label":"باب الصرف · الفقرة ١١","segs":[["matn","فإذا بيعت بجنسها متفاضلا جاز وإذا اشترى بها سعلة ثم كسدت وترك الناس المعاملة بها بطل البيع عند أبي حنيفة"]]},{"id":"q55_12","label":"باب الصرف · الفقرة ١٢","segs":[["matn","وقال أبو يوسف: عليه قيمتها يوم البيع وقال محمد: عليه قيمتها آخر ما تعامل الناس بها"]]},{"id":"q55_13","label":"باب الصرف · الفقرة ١٣","segs":[["matn","ويجوز البيع بالفلوس النافقة وإن لم تتعين وإن كانت كاسدة لم يجز البيع بها حتى يعينها وإذا باع بالفلوس النافقة ثم كسدت بطل البيع عند أبي حنيفة"]]},{"id":"q55_14","label":"باب الصرف · الفقرة ١٤","segs":[["matn","ومن اشترى شيئا بنصف درهم فلوسا جاز البيع وعليه ما يباع بنصف درهم من الفلوس"]]},{"id":"q55_15","label":"باب الصرف · الفقرة ١٥","segs":[["matn","ومن أعطى الصيرفي درهما وقال: أعطني بنصفه فلوسا وبنصفه نصفا إلا حبة فسد البيع في الجميع عند أبي حنيفة وقال أبو يوسف ومحمد: جاز البيع في الفلوس وبطل فيما بقيي ولو قال: أعطني نصف درهم فلوسا ونصفا إلا حبة جاز البيع وكانت الفلوس والنصف إلا حبة بدرهم"]]}]},{"id":"q56","title":"كتاب الرهن","group":"كتاب الرهن","units":[{"id":"q56_1","label":"كتاب الرهن · الفقرة ١","segs":[["matn","الرهن: ينعقد بالإيجاب والقبول ويتم القبض فإذا قبض المرتهن الرهن محوزا مفرغا مميزا ثم العقد فيه وما لم يقبضه فالراهن بالخيار: إن شاء سلمه وإن شاء رجع عن الرهن فإذا سلمه إليه وقبضه دخل في ضمانه"]]},{"id":"q56_2","label":"كتاب الرهن · الفقرة ٢","segs":[["matn","ولا يصح الرهن إلا بدين مضمون وهو مضمون بالأقل من قيمته ومن الدين فإذ هلك في يد المرتهن وقيمته والدين سواء صار المرتهن مستوفيا لدينه حكما وإن كانت قيمة الرهن أكثر من الدين فالفضل أمانة في يده وإن كانت أقل سقط من الدين بقدرها ورجع المرتهن بالفضل"]]},{"id":"q56_3","label":"كتاب الرهن · الفقرة ٣","segs":[["matn","ولا يجوز رهن المشاع ولا رهن ثمرة على رؤوس النخل دون النخل ولا زرع في الأرض دون الأرض ولا يجوز رهن الأرض والنخل دونهما ولا يصح الرهن بالأمانات كالودائع والمضاربات ومال الشركة"]]},{"id":"q56_4","label":"كتاب الرهن · الفقرة ٤","segs":[["matn","ويصح الرهن برأس مال السلم وثمن الصرف والمسلم فيه فإن هلك في مجلس العقد ثم الصرف والسلم المرتهن مستوفيا لدينه"]]},{"id":"q56_5","label":"كتاب الرهن · الفقرة ٥","segs":[["matn","وإذا اتفقا على وضع الرهن على يد عدل جاز وليس للمرتهن ولا للراهن أخذه من يده فإن هلك في يده هلك من ضمان المرتهن"]]},{"id":"q56_6","label":"كتاب الرهن · الفقرة ٦","segs":[["matn","ويجوز رهن الدراهم والدنانير والمكيل والموزون فإن رهنت بجنسها وهلكت هلكت بمثلها من الدين وإن اختلفا في الجودة والصناعة"]]},{"id":"q56_7","label":"كتاب الرهن · الفقرة ٧","segs":[["matn","ومن كان له دين على غيره فأخذ منه مثل دينه فأنفقه ثم علم أنه كان زيوفا فلا شيء له عند أبي حنيفة وقال أبو يوسف ومحمد: يزد مثل الزيوف ويرجع بالجياد ومن رهن عيدين بألف"]]},{"id":"q56_8","label":"كتاب الرهن · الفقرة ٨","segs":[["matn","درهم فقضى حصة أحدهما لم يكن له أن يقضه حتى يؤدي باقي الدين"]]},{"id":"q56_9","label":"كتاب الرهن · الفقرة ٩","segs":[["matn","وإذا وكل الراهن المرتهن أو العدل أو غيرهما ببيع الرهن عند حلول الدين فالوكالة جائزة فإن شرطت في عقد الرهن فليس للراهن عزله عنها فإن عزله لم ينعزل ن وإن مات الراهن لم ينعزل"]]},{"id":"q56_10","label":"كتاب الرهن · الفقرة ١٠","segs":[["matn","وللمترتهن أن يطالب الراهن ويحبسه به وإن كان الرهن في يده فليس عليه أن يمكنه من بيعه حتى يقضه الدين من ثمنه فإن قضاه الدين قيل له: سلم الرهن إليه"]]},{"id":"q56_11","label":"كتاب الرهن · الفقرة ١١","segs":[["matn","وإذا باع الراهن الرهن بغير إذن المرتهن فالبيع موقوف فإن أجازه المرتهن جاز وإن قضاه الراهن دينه جاز البيع"]]},{"id":"q56_12","label":"كتاب الرهن · الفقرة ١٢","segs":[["matn","وإن اعتق الراهن عبد الرهن نفذ عتقه فإن كان الدين حالا طولب بأداء الدين وإن كان مؤجلا أخذ منه قيمة العبد فجعلت رهنا مكانه حتى يحل الدين وإن كان الراهن معسرا استسعي العبد في قيمته فقضى بها دينه"]]},{"id":"q56_13","label":"كتاب الرهن · الفقرة ١٣","segs":[["matn","وكذلك إذا استهلك الراهن الرهن وإن استهلكه أجنبي فالمرتهن هو الخصم في تضمينه ويأخذ القيمة فتكون رهنا في يده وجناية الراهن على الرهن مضمونة وجناية المرتهن عليه تسقط من دينه بقدرها وجناية الرهن على الراهن وعلى المرتهن وعلى مالهما هدر"]]},{"id":"q56_14","label":"كتاب الرهن · الفقرة ١٤","segs":[["matn","وأجرة البيت الذي يحفظ فيه الرهن على المرتهن وأجرة الراعي ونفقة الرهن على الراهن ونماؤه"]]},{"id":"q56_15","label":"كتاب الرهن · الفقرة ١٥","segs":[["matn","للراهن فيكون رهنا مع الأصل"]]},{"id":"q56_16","label":"كتاب الرهن · الفقرة ١٦","segs":[["matn","فإن هلك هلك بغير شيء وإن هلك الأصل وبقي النماء افتحه الراهن بحصته ويقسم الدين على قيمة الرهن يوم القبض وقيمة النماء يوم الفكاك فما أصاب الأصل سقط من الدين وما أصاب النماء افتكه الراهن به"]]},{"id":"q56_17","label":"كتاب الرهن · الفقرة ١٧","segs":[["matn","وتجوز الزيادة في الرهن ولا تجوز في الدين عند أبي حنيفة ومحمد ولا يصير الرهن رهنا بهما وقال أبو يوسف: تجوز الزيادة في الدين أيضا"]]},{"id":"q56_18","label":"كتاب الرهن · الفقرة ١٨","segs":[["matn","وإذا رهن عينا واحدة عند رجلين بدين لكل واحد منهما جاز وجميعها رهن عند كل واحد منهما والمضمون على كل واحد منهما حصة دينه منهما فإن قضى أحدهما دينه كانت كلها رهنا في يد الآخر حتى يستوفي دينه"]]},{"id":"q56_19","label":"كتاب الرهن · الفقرة ١٩","segs":[["matn","ومن باع عبدا على أن يرهنه المشتري بالثمن شيئا بعينه فإن امتنع المشتري من تسليم الهن لم يجبر عليه وكان البائع بالخيار: إن شاء رضي بترك الرهن وإن شاء فسخ البيع إلا أن يدفع المشتري الثمن حالا أو يدفع قيمة الرهن رهنا مكانه"]]},{"id":"q56_20","label":"كتاب الرهن · الفقرة ٢٠","segs":[["matn","وللمرتهن أن يحفظ الرهن بنفسه وزوجته"]]},{"id":"q56_21","label":"كتاب الرهن · الفقرة ٢١","segs":[["matn","وولده وخادمه الذي في عياله وإن حفظه بغير من في عياله أو أوده ضمن"]]},{"id":"q56_22","label":"كتاب الرهن · الفقرة ٢٢","segs":[["matn","وإذا تعدى المرتهن في الرهن ضمنه ضمان الغضب بجميع قيمته وإذا أعار المرتهن الرهن للراهن فقبضه خرج من ضمان المرتهن فإن هلك في يد الراهن هلك بغير شيء وللمرتهن أن يسترجعه إلى يده فإذا أخذه عاد الضمان"]]},{"id":"q56_23","label":"كتاب الرهن · الفقرة ٢٣","segs":[["matn","وإذا مات الراهن باع وصيه الرهن وقضى الدين فإن لم يكن له وصي نصب القاضي له وصيا وأمره ببيعه"]]}]},{"id":"q57","title":"كتاب الحجر","group":"كتاب الحجر","units":[{"id":"q57_1","label":"كتاب الحجر · الفقرة ١","segs":[["matn","الأسباب الموجبة للحجر ثلاثة: الصغر والرق والجنون ولا يجوز تصرف الصغير إلا بإذن وليه ولا تصرف العبد إلا بإذن سيده ولا يجوز تصرف المجنون المغلوب على عقله بحال"]]},{"id":"q57_2","label":"كتاب الحجر · الفقرة ٢","segs":[["matn","ومن باع من هؤلاء شيئا"]]},{"id":"q57_3","label":"كتاب الحجر · الفقرة ٣","segs":[["matn","أو اشتراه وهو يعقل البيع ويقصده فالوالي بالخيار: إن شاء أجازه إذا كان فيه مصلحة وإن شاء فسخه"]]},{"id":"q57_4","label":"كتاب الحجر · الفقرة ٤","segs":[["matn","وهذه المعاني الثلاثة توجب الحجر في الأقوال دون الأفعال فالصبي والمجنون لا تصح عقودهما ولا إقرارهما ولا يقع طلاقهما ولا عتاقهما وإن أتلفا شيئا لومهما ضمانه"]]},{"id":"q57_5","label":"كتاب الحجر · الفقرة ٥","segs":[["matn","وأما العبد فأقواله نافذة في حق نفسه غير نافذة في حق مولاه فإن أقر بمال لزمه بعد الحرية ولم يلزمه في الحال وإن أقر بحد أو قصاص لزمه في الحال وينفذ طلاقه"]]},{"id":"q57_6","label":"كتاب الحجر · الفقرة ٦","segs":[["matn","وقال أبو حنيفة: لا يحجز على السفيه إذا كان بالغا عاقلا حرا وتصرفه في ماله جائز وإن كان مبذرا مفسدا يتلف ماله فيما لا غرض له فيه ولا مصلحة إلا أنه قال: إذا بلغ الغلام غير رشيد لم يسلم إليه ماله حتى يبلغ خمسا وعشرين سنة"]]},{"id":"q57_7","label":"كتاب الحجر · الفقرة ٧","segs":[["matn","فإن تصرف فيه قبل ذلك نفذ تصرفه فإذا بلغ خمسا وعشرين سنة سلم إليه مله وإن لم يؤنس منه الرشد"]]},{"id":"q57_8","label":"كتاب الحجر · الفقرة ٨","segs":[["matn","وقال أبو يوسف ومحمد: يحجز على السفينه ويمنع من التصرف في ماله فإن باع لم ينفذ بيعه فإن كان فيه مصلحة أجازه الحاكم وإن أعتق عبدا نفذ عتقه وكان على العبد أن يسعى في قيمته وإن تزوج امرأة جاز نكاحه فإن سمى لها مهرا جاز منه مقدار"]]},{"id":"q57_9","label":"كتاب الحجر · الفقرة ٩","segs":[["matn","مهر مثلها وبطل الفضل"]]},{"id":"q57_10","label":"كتاب الحجر · الفقرة ١٠","segs":[["matn","وقالا فيمن بلغ غير رشيد: لا يدفع أليه ماله أبدا حتى يؤنس منه الرشد ولا يجوز تصرفه فيه وتخرج الزكاة من مال السفيه"]]},{"id":"q57_11","label":"كتاب الحجر · الفقرة ١١","segs":[["matn","وينفق منه على أولاده وزوجته ومن تجب نفقته عله من ذوي أرحامه فإن أراد حجة الإسلام لم يمنع منها ولا يسلم القاضي النفقة إليه ويسلمها إلى ثقة من الحاج ينفقها عليه في طريق الحج فإن مرض وأوصى بوصايا في القرب وأبواب الخير جاز ذلك في ثلث ماله"]]},{"id":"q57_12","label":"كتاب الحجر · الفقرة ١٢","segs":[["matn","وبلوغ الغلام الاحتلام والإحبال والإنزال إذا وطئ فإن لم يوجد ذلك فحتى يتم له ثماني عشرة سنة عند أبي حنيفة"]]},{"id":"q57_13","label":"كتاب الحجر · الفقرة ١٣","segs":[["matn","وبلوغ الجارية بالحيض والاحتلام والحبل فإن لم يوجد ذلك فحتى يتم لها سبع عشرة سنة وقال أبو يوسف ومحمد: إذا تم للغلام والجارية خمس عشرة سنة فقد بلغا"]]},{"id":"q57_14","label":"كتاب الحجر · الفقرة ١٤","segs":[["matn","وإذا راعق الغلام والجارية وأشكل أمرهما في البلوغ وقالا: قد بلغنا فالقول قولهما وأحكامهما أحكام البالغين"]]},{"id":"q57_15","label":"كتاب الحجر · الفقرة ١٥","segs":[["matn","وقال أبو حنيفة: لا أحجر في الدين: وإذا وجبت الديون على رجل وطلب غرماؤه حبسه والحجر عليه لم أحجر عليه وإن كان له لم يتصرف فيه الحاكم ولكن يحبسه أبدا حتى يبيعه في دينه فإن كا له دراهم ودينه دراهم قضاها القاضي بغير أمره وإن كان دينه دراهم وله دنانير باعها القاضي في دينه"]]},{"id":"q57_16","label":"كتاب الحجر · الفقرة ١٦","segs":[["matn","وقال أبو يوسف ومحمد: إذا طلب غرماء المفلس الحجرعليه حجر"]]},{"id":"q57_17","label":"كتاب الحجر · الفقرة ١٧","segs":[["matn","القاضي عليه ومنعه من البيع والتصرف والإقرار حتى لا يضر بالغرماء وباع ماله إن امتنع من بيعه وقسمه بين غرمائه الحصص فإن أقر في حال الحجر بإقرار لزمه ذلك بعد قضاء الديون"]]},{"id":"q57_18","label":"كتاب الحجر · الفقرة ١٨","segs":[["matn","وينفق على المفلس من ماله وعلى زوجته وأولاده الصغار وذوي أرحامه وإن لم يعرف للمفلس مال وطلب غرماؤه حبسه وهو يقول لا مال لي حبسه الحاكم في كل دين التزمه بدلا عن مال حصل يده كثمن مبيع وبدل القرض وفي كل دين بعقد كالمهر والكفالة ولم يحبسه فيما سوى ذلك كعوض المغضوب وأرس الجنايات إلا أن تقوم البينة أن له مالا"]]},{"id":"q57_19","label":"كتاب الحجر · الفقرة ١٩","segs":[["matn","وإذا حبسه القاضي شهرين أو ثلاثة يسأل عن حاله: فإن لم ينكشف له مال خلى سبيله وكذلك إذا أقام البينة أنه لا مال له ولا يحول بينه وبين غرمائه بعد خروجه من الحبس ويلازمونه ولا منعونه من التصرف والسفر ويأخذون فضل كسبه فيقسم بينهم بالحصص"]]},{"id":"q57_20","label":"كتاب الحجر · الفقرة ٢٠","segs":[["matn","وقال أبو يوسف ومحمد: إذا فلسه الحاكم حال بينه وبين غرمائه إلا أن يقيموا البينه أنه قد حصل له مال"]]},{"id":"q57_21","label":"كتاب الحجر · الفقرة ٢١","segs":[["matn","ولا يحجر على الفاسق إذا كان مصلحا لماله والفسق الأصلي والطاريء"]]},{"id":"q57_22","label":"كتاب الحجر · الفقرة ٢٢","segs":[["matn","سواء ومن أفلس وعنده متاع لرجل بعينه ابتاعه منه فصاحب المتاع أسوة الغرماء فيه"]]}]},{"id":"q58","title":"كتاب الإقرار","group":"كتاب الإقرار","units":[{"id":"q58_1","label":"كتاب الإقرار · الفقرة ١","segs":[["matn","إذا أقر الحر البالغ العاقل بحق لزمه إقراره مجهولا كان ما أقر به أو معلوما ويقال له: بين المجهول فإن قال لفلان على شيء لزمه أن بين ماله قيمة والقول فيه قوله مع يمينه إن ادعى المقر له أكثر من ذلك"]]},{"id":"q58_2","label":"كتاب الإقرار · الفقرة ٢","segs":[["matn","وإذا قال: له على مالد فالمرجع في بيانه إليه ويقبل قوله في القليل والكثير فإن قال: له علي مال عظيم لم يصدق في أقل من مائتي درهم وإن قال: دراهم كثيرة لم يصدق في أقل من عشرة دراهم وإن قال: دراهم فهي ثلاثة إلا أن يبين أكثر منها وإن قال: له علي كذا كذا درهما لم يصدق في أقل من أحد عشر درهما وإن قال: كذا كذا درهما لم يصدق في أقل من أحد وعشرين درهما وإن قال: له علي أو قلبي فقد أقر بدين"]]},{"id":"q58_3","label":"كتاب الإقرار · الفقرة ٣","segs":[["matn","وإن قال: عندي أو: معي فهو إقرار بأمانة في يده وإن قال له رجل لي عليك ألف فقال اتزنها أو انتقدها أو أجلني بها أو قد قضيتكها فهو إقرار"]]},{"id":"q58_4","label":"كتاب الإقرار · الفقرة ٤","segs":[["matn","ومن أقر بدين مؤجل فصدقه المقر له في الدين وكذبه في التأجيل لزمه الدين خالا ويستحلف المقر له في الأجل"]]},{"id":"q58_5","label":"كتاب الإقرار · الفقرة ٥","segs":[["matn","ومن أقر واستثنى متصلا بإقراره صح الاستثناء ولزمه الباقي سواء استثنى الأقل أو الأكثر فإن استثنى الجميع لزمه الإقرار وبطل الاستثناء"]]},{"id":"q58_6","label":"كتاب الإقرار · الفقرة ٦","segs":[["matn","وإن قال: له علي مائة درهم إلا دينار أو: إلا قفيز حنطة لزمه مائة درهم إلا قيمة الدينار أو القفيز"]]},{"id":"q58_7","label":"كتاب الإقرار · الفقرة ٧","segs":[["matn","وإن قال: له علي مائة ودرهم فالمائة كلها دراهم وإن قال: له لعي مائة وثوب لزمه ثوب واحد والمرجع في تفسير المائة إليه"]]},{"id":"q58_8","label":"كتاب الإقرار · الفقرة ٨","segs":[["matn","ومن أقر بحق وقال إن شاء الله متصلا بإقراره لم يلزمه الإقرار ومن أقر وشرط الخيار لزمه الإقرار وبطل الخيار ومن أقر بدار واستثنى بنارها لنفسه فللمقر له الدار والبناء وإن قال: بناء هذه الدار لي والعرصة لفلان فهو كما قال"]]},{"id":"q58_9","label":"كتاب الإقرار · الفقرة ٩","segs":[["matn","ومن أقر بتمر في قوصره"]]},{"id":"q58_10","label":"كتاب الإقرار · الفقرة ١٠","segs":[["matn","لزمه التمر والقوصرة ومن أقر بدابة في إصطبل لزمه الدابة خاصة وإن قال: غصبت ثوبا في"]]},{"id":"q58_11","label":"كتاب الإقرار · الفقرة ١١","segs":[["matn","منديل لزماه جميعا وإن قال: له علي ثوب في ثوب لزماه وإن قال: له علي ثوب في عشرة أثواب لم يلزمه عند أبي حنيفة وأبي يوسف إلا ثوب واحد"]]},{"id":"q58_12","label":"كتاب الإقرار · الفقرة ١٢","segs":[["matn","وقال محمد: يلزمه أحد عشر ثوبا ومن أقر بغضب ثوب وجاء بثوب معيب قالقول قلوه مع يمينه وكذلك لو أقر بدراهم وقال: هي زيوف"]]},{"id":"q58_13","label":"كتاب الإقرار · الفقرة ١٣","segs":[["matn","وإن قال: له علي خمسة في خمسة يريد الضرب والحساب لزمه خمسة واحدة وإن قال: أدرت خمسة مع خمسة لزمه عشرة"]]},{"id":"q58_14","label":"كتاب الإقرار · الفقرة ١٤","segs":[["matn","وإن قال: له علي من درهم إلى عشرة لزمه تسعة عند أبي حنيفة فيلزمه الإبتداء وما بعده وتسقط الغابة وقال أبو يوسف ومحمد: يلزمه العشرة كلها وإذا قال: له علي ألف درهم من ثمن عبد اشتريته منه ولم أقبضه فإن ذكر عبدا بعينه قيل للمقر له: إن شئت فسلم العبد وخذ الألف وإلا فلا شيء لك"]]},{"id":"q58_15","label":"كتاب الإقرار · الفقرة ١٥","segs":[["matn","وإن قال: له علي ألف من ثمن عبد ولم يعينه لزمه الألف في قول أبي حنيفة ولو قال: له عل ألف من ثمن هذا العبد لم يلزمه حتى يسلم العبد فإن سلم العبد لزمه الألف وإن لم يسلمه لم تلزمه ولو قال: له علي ألف من ثمن خمر أو خنزير لزمه"]]},{"id":"q58_16","label":"كتاب الإقرار · الفقرة ١٦","segs":[["matn","الألف ولم يقبل تفسيره ولو قال: له علي ألف من ثمن متاع وهي زيوف وقال المقر له: لزمه الجياد في قول أبي حنيفة"]]},{"id":"q58_17","label":"كتاب الإقرار · الفقرة ١٧","segs":[["matn","ومن أقر لغيره بخاتم فله الحلقة والفص وإن أقر له بسيف فله النصل والجفن والحمائل وإن أقر بحجلة فله العيدان والكسوة"]]},{"id":"q58_18","label":"كتاب الإقرار · الفقرة ١٨","segs":[["matn","وإن قال: لحمل فلانة علي ألف فإن قال أوصى به له فلان أو مات أبوه فورثه فلإقرار صحيح وإن أبهم الإقرار لم يصح عند أبي يوسف"]]},{"id":"q58_19","label":"كتاب الإقرار · الفقرة ١٩","segs":[["matn","وإذا أقر بحمل جارية أو حمل شاة لرجل صح الإقرار ولزمه وإذا أقر الرجل في مرض موتته بديون وعليه ديون في صحته وديون لزمته في مرضه بأسباب معلومة فدين الصحة والدين المعروف بالأسباب مقدم على غيره فإذا قضيت شيء"]]},{"id":"q58_20","label":"كتاب الإقرار · الفقرة ٢٠","segs":[["matn","كان فيما أقر به في حال المرض وإن لم يكن"]]},{"id":"q58_21","label":"كتاب الإقرار · الفقرة ٢١","segs":[["matn","عليه ديون في صحته جاز إقراره وكان المقر له أولى من الورثة وإقرار المريض لوارثه باطل إلا أن يصدقه فيه بقية الورثة"]]},{"id":"q58_22","label":"كتاب الإقرار · الفقرة ٢٢","segs":[["matn","ومن أقر لأجنبي في مرضه ثم قال هو ابني ثبت نسبه وبطل إقراره له ولو أقر لأجنبي' ثم تزوجها لم يبطل إقراره لها ومن طلق زوجته في مرضه ثلاثا ثم أقر لها بدين ومات فلها الأقل من الدين ومن ميراثها منه ومن أقر بغلام يولد مثله لمثله وليس له نسب معروف أنه ابنه وصدقة الغلام ثبت نسبه منه وإن كان مريضا ويشارك الورثة في الميراث"]]},{"id":"q58_23","label":"كتاب الإقرار · الفقرة ٢٣","segs":[["matn","ويجوز إقرار الرجل بالوالدين والولد والزوجة والمولى ويقبل إقرار المرأة بالوالدين والزوج والمولى ولا يقبل بالولد إلا أن يصدقها الزوج أو تشهد بولادتها قابلة ومن أقر بنسب من غير الوالدين والولد والزوج والزوجة والمولى - مثل الأخ والعم - لم يقبل إقراره في النسب فإن كان له وارث معروف قريب أو بعيد فهو أولى بالميراث من المقر له وإن لم يكن له وارث استحق المقر له ميراثه ومن مات أبوه فأقر بأخ له لم يثبت نسب أخيه ويشاركه في الميراث"]]}]},{"id":"q59","title":"كتاب الإجارة","group":"كتاب الإجارة","units":[{"id":"q59_1","label":"كتاب الإجارة · الفقرة ١","segs":[["matn","الإجارة: عقد على المنافع بعوض"]]},{"id":"q59_2","label":"كتاب الإجارة · الفقرة ٢","segs":[["matn","ولا تصح حتى تكون المنافع معلومة والأجرة معلومة وما جاز أن يكون ثمنا في البيع جاز أن يكون أجرة في الإجارة"]]},{"id":"q59_3","label":"كتاب الإجارة · الفقرة ٣","segs":[["matn","والمنافع تارة تصير معلومة بالمدة كاستئجار الدور للسكنى والأرضين للزراعة فيصح العقد على مدة معلومة أي مدة كانت وتارة تصير معلومة بالعمل والتسمية كمن استأجر رجلا على صبغ ثوب أو خياطته أو استأجر دابة ليحمل عليها مقدارا معلوما أو يركبها مسافة سماها وتارة تصير معلومة بالتعيين والإشارة كمن استأجر رجلا لينقل له هذا الطعام إلى موضع معلوم"]]},{"id":"q59_4","label":"كتاب الإجارة · الفقرة ٤","segs":[["matn","ويجوز استئجار الدور والحوانيت للسكنى وإن لم يبين ما يعمل فيها وله أن يعمل كل شيء إلا الحداد والقصار والطحان"]]},{"id":"q59_5","label":"كتاب الإجارة · الفقرة ٥","segs":[["matn","ويجوز استئجار الأراضي للزراعة ولا يصح العقد حتى يسمي ما يزرع فيها أو يقول: على أن يزرع فيها ما شاء"]]},{"id":"q59_6","label":"كتاب الإجارة · الفقرة ٦","segs":[["matn","ويجوز أن يستأجر الساحة ليبني فيها أو يغرس فيها نخلا أو شجرا فإذا انقضت مدة الإجارة لزمه أن يقلع البناء والغرس ويسلمها فارغة إلا أن يختار صاحب الأرض أن يغرم له قيمة ذلك مقلوعا فيملكه أو يرضى بتركه على حاله فيكون البناء لهذا والأرض لهذا"]]},{"id":"q59_7","label":"كتاب الإجارة · الفقرة ٧","segs":[["matn","ويجوز استئجار الدواب للركوب والحمل فإن قال: على أن يركبها فلان أو يلبس الثوب فلان فأركبها غيره أو ألبسه غيره كان ضامنا إن عطبت الدابة أو تلف الثوب"]]},{"id":"q59_8","label":"كتاب الإجارة · الفقرة ٨","segs":[["matn","وكذلك كل ما يختلف باختلاف المستعمل"]]},{"id":"q59_9","label":"كتاب الإجارة · الفقرة ٩","segs":[["matn","وأما العقار وما لا يختلف باختلاف المستعمل فلا ضمان عليه فإذا شرط سكنى واحد فله أن يسكن غيره وإن سمى نوعا أو قدرا يحمله على الدابة مثل أن يقول: خمسة أقفزة حنطة فله أن يحمل ما هو مثل الحنطة في الضرر أو أقل كالشعير والسمسم وليس له أن يحمل ما هو أضر من الحنطة كالملح والحديد"]]},{"id":"q59_10","label":"كتاب الإجارة · الفقرة ١٠","segs":[["matn","وإن استأجرها ليحمل عليها قطناه سماه فليس له أن يحمل مثل وزنه حديدا وإن استأجرها ليركبها فأردف معه رجلا فعطبت ضمن نصف قيمتها ولا يعتبر بالثقل"]]},{"id":"q59_11","label":"كتاب الإجارة · الفقرة ١١","segs":[["matn","وإن استأجرها ليحمل عليها مقدرا من الحنطة فحمل أكثر منه فعطبت ضمن ما زاد الثقل"]]},{"id":"q59_12","label":"كتاب الإجارة · الفقرة ١٢","segs":[["matn","وإذا كبح الدابة بلجامها أو ضربها فعطبت ضمن عند أبي حنيفة"]]},{"id":"q59_13","label":"كتاب الإجارة · الفقرة ١٣","segs":[["matn","والأجراء على ضربين: وأجير مشترك وأجير خاص فالمشترك: من لا يستحق الأجرة حتى يعمل كالصباغ والقصار والمتاع أمانة في يده: إن هلك لم يضمن شيئا عند أبي حنيفة وقال أبو يوسف ومحمد: يضمنه وما تلف بعمله كتخريق الثوب من دقة وزلق الحمال وانقطاع الحبل الذي يشد به المكاري الحمل وغرق السفينة من مدها مضمون إلا أنه لا يضمن به بني آدم فمن غرق في السفينة أو سقط من الدابة ثم يضمنه وإذا قصد الفصاد أو بزغ البزاغ ولم يتجاوز الموضع المعتاد فلا ضمان عليه فيما عطب من ذلك"]]},{"id":"q59_14","label":"كتاب الإجارة · الفقرة ١٤","segs":[["matn","ولأجير الخاص: الذي يستحق الأجرة بتسليم نفسه في المدة وإن لم يعمل كمن استؤجر شهرا للخدمة أو لرعي الغنم ولا ضمان على الأجير الخاص فما تلف في يده ولا ما تلف من عمله"]]},{"id":"q59_15","label":"كتاب الإجارة · الفقرة ١٥","segs":[["matn","والإجارة تفسدها الشروط كما تفسد البيع ومن استأجر عبدا للخدمة فليس له أن يسافر"]]},{"id":"q59_16","label":"كتاب الإجارة · الفقرة ١٦","segs":[["matn","به إلا أن يشترط ذلك"]]},{"id":"q59_17","label":"كتاب الإجارة · الفقرة ١٧","segs":[["matn","ومن استأجر جملا ليحمل عليه محملا وراكبين إلى مكة جاز وله المحمل المعتاد وإن شاهد"]]},{"id":"q59_18","label":"كتاب الإجارة · الفقرة ١٨","segs":[["matn","الجمال المحمل فهو أجود وإن استأجر بعيرا ليحمل عليه مقدارا من الزاد فأكل منه في الطريق جاز له أن يرد عوض ما أكل"]]},{"id":"q59_19","label":"كتاب الإجارة · الفقرة ١٩","segs":[["matn","والأجرة لا تجب بالعقد وتستحق بأحد معان ثلاثة: إما بشرط التعجيل أو بالتعجيل من غير شرط أو باستيفاء المعقود عليه"]]},{"id":"q59_20","label":"كتاب الإجارة · الفقرة ٢٠","segs":[["matn","ومن استأجر دارا فللمؤجر أن يطالبه لأجره كل يوم إلا أن يبين وقت الاستحقاق بالعقد ومن استأجر بعيرا إلى مكة فللجمال أن يطالبه بأجرة"]]},{"id":"q59_21","label":"كتاب الإجارة · الفقرة ٢١","segs":[["matn","كل مرحلة وليس للقصار والخياط أن يطالب بالأجرة حتى يفرغ من العمل إلا أن يشترط التعجيل"]]},{"id":"q59_22","label":"كتاب الإجارة · الفقرة ٢٢","segs":[["matn","ومن استأجر خبازا ليخبز له في بيته قفيز دقيق بدرهم لم يستحق الأجرة حتى يخرج الخبز من التنور ومن استأجر طباخا ليطبخ له طعاما للوليمة فالغرف عليه ومن استأجر رجلا ليضرب له لبنا استحق الأجرة إذا أقامه عند أبي حنيفة وقال أبو يوسف ومحمد: لا يستحقها حتى يشرجه"]]},{"id":"q59_23","label":"كتاب الإجارة · الفقرة ٢٣","segs":[["matn","وإذا قال للخياط: إن خطت هذا الثوب فارسيا فبدرهم وإن خطته روميا فبدرهمين جاز وأي العلمين عمل استحق الأجرة"]]},{"id":"q59_24","label":"كتاب الإجارة · الفقرة ٢٤","segs":[["matn","وإن قال: إن خطته اليوم فبدرهم وإن خطته غدا فبنصف درهم فإن خاطه اليوم فله درهم وإن خاطه غدا فله أجر مثله عند أبي حنيفة ولا يتجاوز به نصف درهم"]]},{"id":"q59_25","label":"كتاب الإجارة · الفقرة ٢٥","segs":[["matn","وإن قال: إن سكت في هذا الدكان عطارا فبدرهم في الشهر وإن سكنته حدادا فبدرهمين جاز وأي الأمرين فعل استحق المسمى فيه عند أبي حنيفة وقال أبو يوسف ومحمد: الإجارة فاسدة"]]},{"id":"q59_26","label":"كتاب الإجارة · الفقرة ٢٦","segs":[["matn","ومن استأجر دارا كل شهر بدرهم فالعقد صحيح في شهر واحد فاسد في بقية الشهور إلا أن يسمي جملة شهور معلومة فإن سكن ساعة من الشهر الثاني صح العقد فيه ولزمه ذلك الشهر ولم يكن للمؤجر أن يخرجه منها إلى أن ينقضي وكذلك كل شهر يسكن في أوله"]]},{"id":"q59_27","label":"كتاب الإجارة · الفقرة ٢٧","segs":[["matn","وإذا استأجر دارا سنة بعشرة"]]},{"id":"q59_28","label":"كتاب الإجارة · الفقرة ٢٨","segs":[["matn","دراهم جاز وإن لم يسم قسط كل شهر من الأجرة"]]},{"id":"q59_29","label":"كتاب الإجارة · الفقرة ٢٩","segs":[["matn","ويجوز أخذ أجرة الحمام"]]},{"id":"q59_30","label":"كتاب الإجارة · الفقرة ٣٠","segs":[["matn","والحجام ولا يجوز أخذ عسب التيس ولا يجوز الاستئجار على الأذان والإقامة والحج والغناء والنوح"]]},{"id":"q59_31","label":"كتاب الإجارة · الفقرة ٣١","segs":[["matn","ولا تجوز أجارة المشاع عند أبي حنيفة إلا من الشريك"]]},{"id":"q59_32","label":"كتاب الإجارة · الفقرة ٣٢","segs":[["matn","وقال أبو يوسف ومحمد: إجازة المشاع جائزة ويجوز استئجار الظئر بأجرة معلومة ويجوز بطعامها وكسوتها وليس للمستأجر أن يمنع زوجها من وطئها فإن حبلت كان لهم أن يفسخوا الإجارة إذا خافوا على الصبي من لبنها وعليها أن تصلح طعام الصبي وإن أرضعته في المدة بلبن شاة فلا أجر لها"]]},{"id":"q59_33","label":"كتاب الإجارة · الفقرة ٣٣","segs":[["matn","وكل صانع لعمله أثر في العين كالقصار والصباغ فله أن يحبس العين بعد الفراغ من عمله حتى يستوفي الأجرة"]]},{"id":"q59_34","label":"كتاب الإجارة · الفقرة ٣٤","segs":[["matn","ومن ليس لعمله أثر فلي له أن يحبس العين بالأجرة كالحمال والملاح"]]},{"id":"q59_35","label":"كتاب الإجارة · الفقرة ٣٥","segs":[["matn","وإذا شرط على الصانع أن يعمل بنفسه فليس له أن يستعمل غيره فإن أطلق له العمل فله أن يستأجر من يعلمه"]]},{"id":"q59_36","label":"كتاب الإجارة · الفقرة ٣٦","segs":[["matn","وإذا اختلف الخياط وصاحب الثوب فقال صاحب الثوب: أمرتك أن تعمله قباء وقال الخياط: قميصا أو قال صاحب الثوب للصباغ: أمرتك أن تصبغه أحمر فصبغته أصفر فالقول قول صاحب الثوب مع يمينه فإن حلف فالخياط ضامن"]]},{"id":"q59_37","label":"كتاب الإجارة · الفقرة ٣٧","segs":[["matn","وإذا قال صاحب الثوب: عملته لي بغير أجرة وقال الصانع: بأجرة فالقول قول صاحب الثوب مع يمينه عند أبي حنيفة وقال"]]},{"id":"q59_38","label":"كتاب الإجارة · الفقرة ٣٨","segs":[["matn","أبو يوسف: إن كان حريفا له فله الأجرة وإن لم يكن حريفا له فلا أجرة له وقال محمد: إن كان الصانع معروفا بهذه الصنعة أن يعمل بالأجرة فالقول قوله أنه عمله بأجرة"]]},{"id":"q59_39","label":"كتاب الإجارة · الفقرة ٣٩","segs":[["matn","والواجب في الأجارة الفاسدة أجر المثل لا يتجاوز به المسمى وإذا قبض المستأجر الدار"]]},{"id":"q59_40","label":"كتاب الإجارة · الفقرة ٤٠","segs":[["matn","فعليه الأجرة وإن لم يسكنها فإن غصبها غاصب من يده سقطت الأجرة وإن وجد به اعيبا يضر بالسكنى فله الفسخ وإذا"]]},{"id":"q59_41","label":"كتاب الإجارة · الفقرة ٤١","segs":[["matn","خربت الدار أو انقطع شرب الضيعة أو انقطع الماء عن الرحى انفسخت الإجارة"]]},{"id":"q59_42","label":"كتاب الإجارة · الفقرة ٤٢","segs":[["matn","وإذا مات أحد المتعاقدين وقد عقد الإجارة لنفسه انفسخت الإجارة وإن عقدها لغيره لم تنفسخ ويصح شرط الخيار في الإجارة وتنفسخ الإجارة بالأعذار كمن استأجر دكانا في السوق ليتجر فيه فذهب ماله وكمن آجر دارا أو دكانا ثم أفلس ولزمته ديون لا يقدر على قضائها إلا من ثمن ما آجر فسخ القاضي العقد وباعها في الدين"]]},{"id":"q59_43","label":"كتاب الإجارة · الفقرة ٤٣","segs":[["matn","وكمن استأجر دابة ليسافر عليها ثم بدا له من السفر فهو عذر وإن بدا للمكاري من السفر فليس ذلك بعذر"]]}]},{"id":"q60","title":"كتاب الشفعة","group":"كتاب الشفعة","units":[{"id":"q60_1","label":"كتاب الشفعة · الفقرة ١","segs":[["matn","الشفعة: واجبة للخيلط في نفس المبيع ثم للخليط في حق المبيع كالشرب والطريق ثم للجار وليس للشريك في الطريق والشرب والجار شفعة مع الخليط فإن سلم فالشفعة للشريك في الطريق فإن سلم أخذها الجار"]]},{"id":"q60_2","label":"كتاب الشفعة · الفقرة ٢","segs":[["matn","والشفعة تجب بعقد البيع وتستقر بالإشهاد وتملك بالأخذ إذا سلمها المشتري أو حكم بها حاكم وإذا علم الشفيع بالبيع أشهد في مجلسه ذلك على المطالبة ثم ينهض منه فيشهد على البائع إن كان المبيع في يده أو على المبتاع أو عند العقار"]]},{"id":"q60_3","label":"كتاب الشفعة · الفقرة ٣","segs":[["matn","فإذا فعل ذلك استقرت شفعته ولم تسقط بالتأخير عند أبي حنيفة وقال محمد: إن تركها شهرا بعد الإشهاد بطلت شفعته"]]},{"id":"q60_4","label":"كتاب الشفعة · الفقرة ٤","segs":[["matn","والشفعة واجبة في العقار وإن كان مما لا يقسم ولا شفعة في العروض والسفن والمسلم والذمي في الشفعة سواء"]]},{"id":"q60_5","label":"كتاب الشفعة · الفقرة ٥","segs":[["matn","وإذا ملك العقار بعوض هو مال وجبت فيه الشفعة ولا شفعة في الدار التي يتزوج الجل عيها أو يخالع المرأة بها أو يستأجر بها دارا أو يصالح بها عن دم عمد أو يعتق عليها عبدا أو يصالح عنها بإنكار أو سكوت فإن صالح عنها بإقرار وجبت فيها الشفعة"]]},{"id":"q60_6","label":"كتاب الشفعة · الفقرة ٦","segs":[["matn","وإذا تقدم الشفيع إلى القاضي فادعى الشراء وطلب الشفعة سأل القاضي المدعى عليه فإن اعترف بملكه الذي يشفع به وإلا كلفه إقامة البينة فإن عجز عن البينة استحلف المشتري بالله ما"]]},{"id":"q60_7","label":"كتاب الشفعة · الفقرة ٧","segs":[["matn","يعلم أنه مالك للذي ذكره مما يشفع به فإن نكل أو قامت بينه سأله القاضي: هل ابتاع أم لا؟ فإن أنكر الابتياع قيل للشفيع أقم البينة فإن عجز عنها اتحلف المشتري بالله ما اتباع أو بالله ما يستحق علي في هذه الدار شفعة من الوجه الذي ذكره وتجوز المنازعة في الشفعة وإن لم يحضر الشفيع الثمن إلى مجلس القاضي"]]},{"id":"q60_8","label":"كتاب الشفعة · الفقرة ٨","segs":[["matn","فإذا قضى القاضي له بالشفعة لزمه إحضار الثمن وللشفيع أن يرد الدار بخيار العيب والرؤية"]]},{"id":"q60_9","label":"كتاب الشفعة · الفقرة ٩","segs":[["matn","فإن أحضر الشفيع البائع والمبيع في يده فله أن يخاصمه في الشفعة ولا يسمع القاضي البينة حتى يحضر المشتري فيفسخ البيع بمشهد منه ويقضي بالشفعة على البائع ويجعل العهدة عليه"]]},{"id":"q60_10","label":"كتاب الشفعة · الفقرة ١٠","segs":[["matn","وإذا ترك الشفيع الإشهاد حين علم وهو يقدر على ذلك"]]},{"id":"q60_11","label":"كتاب الشفعة · الفقرة ١١","segs":[["matn","بطلت شفعته وكذلك إن أشهد في المجلس ولم يشهد على أحد المتبايعين ولا عند العقار وإن صالح من شفعته على عوض أخذه بطلت شفعته ويرد العوض"]]},{"id":"q60_12","label":"كتاب الشفعة · الفقرة ١٢","segs":[["matn","وإذا مات الشفيع بطلت شفعته"]]},{"id":"q60_13","label":"كتاب الشفعة · الفقرة ١٣","segs":[["matn","وإن مات المشتري لم تسقط وإن باع الشفيع ما يشفع به قبل أن يقضى له بالشفعة بطلت شفعته ووكيل البائع إذا باع وكان هو الشفيع فلا شفعة له وكذلك إن ضمن الدرك عن البائع الشفيع ووكيل المشتري إذا ابتاع فله الشفعة ومن باع بشرط الخيار فلا شفعة للشفيع فإن أسقط الخيار وجبت الشفعة ومن اشترى بشرط الخيار وجبت الشفعة"]]},{"id":"q60_14","label":"كتاب الشفعة · الفقرة ١٤","segs":[["matn","ومن ابتاع دارا شراء فاسدا فلا شفعة لها ولكل"]]},{"id":"q60_15","label":"كتاب الشفعة · الفقرة ١٥","segs":[["matn","واحد من المتعاقدين الفسخ فإن سقط الفسخ وجبت الشفعة"]]},{"id":"q60_16","label":"كتاب الشفعة · الفقرة ١٦","segs":[["matn","وإذا اشترى ذمي دارا بخمر أو خنزير وشفيعها ذمي أخذها بمثل الخمر وقيمة الخنزير وإن كان شفيعها مسلما أخذها بقمة الخمر والخنزير"]]},{"id":"q60_17","label":"كتاب الشفعة · الفقرة ١٧","segs":[["matn","ولا شفعة في الهبة إلا أن تكون بعوض مشروط وإذا اختلف الشفيع والمشتري في الثمن فالقول قول المشتري فإن أقاما البينة فالبينة بينة الشفيع عند أبي حنيفة ومحمد وإذا ادعى المشتري ثمنا أكثر وادعى البائع أقل منه ولم يقبض الثمن أخذها الشفيع بما قال البائع وكان ذلك حطا عن المشتري"]]},{"id":"q60_18","label":"كتاب الشفعة · الفقرة ١٨","segs":[["matn","وإن كان قبض الثمن بما قال المشتري ولم"]]},{"id":"q60_19","label":"كتاب الشفعة · الفقرة ١٩","segs":[["matn","يلتفت إلى قول البائع وإذا حط البائع عن المشتري بعض الثمن سقط ذلك عن الشفيع وإن حط جميع الثمن لم يسقط عن الشفيع وإذا زاد المشتري البائع في الثمن لم تلزم الزيادة الشفيع"]]},{"id":"q60_20","label":"كتاب الشفعة · الفقرة ٢٠","segs":[["matn","وإذا جمع الشفعاء فالشفعة بينهم على عدد رؤوسهم ولا يعتبر اختلاف الأملاك"]]},{"id":"q60_21","label":"كتاب الشفعة · الفقرة ٢١","segs":[["matn","ومن اشترى دارا بعرض أخذها الشفيع بقيمته وإن اشتراها بمكيل أو موزون أخذها بمثله"]]},{"id":"q60_22","label":"كتاب الشفعة · الفقرة ٢٢","segs":[["matn","وإذا باع عقارا بعقار أخذ الشفيع كل واحد منهما بقيمة الآخر وإذا بلغ الشفيع أنها بيعت بألف فسلم ثم علم أنها بيعت بأقل أو بحنطة أو شعير قيمتها ألف أو أكثر فتسليمه باطل وله الشفعة وإن بان أنها بيعت بدنانير قيمتها ألف فلا شفعة له"]]},{"id":"q60_23","label":"كتاب الشفعة · الفقرة ٢٣","segs":[["matn","وإذا قيل له إن المشتري فلان فسلم الشفقة ثم علم أنه غيره فله الشفعة"]]},{"id":"q60_24","label":"كتاب الشفعة · الفقرة ٢٤","segs":[["matn","ومن اشترى دارا لغيره فهو الخصم في الشفعة إلا أن يسلمها إلى الموكل"]]},{"id":"q60_25","label":"كتاب الشفعة · الفقرة ٢٥","segs":[["matn","وإذا باع دارا إلا مقدار ذراع في طول الحد يلي الشفيع فلا شفعة له وإن اتباع منها سهما بثمن ثم ابتاع بقيتها فالشفعة للجار في السهم الأول دون الثاني"]]},{"id":"q60_26","label":"كتاب الشفعة · الفقرة ٢٦","segs":[["matn","وإذا ابتاعها بثمن ثم دفع إليه ثوبا عنه فالشفعة بالثمن دون الثوب"]]},{"id":"q60_27","label":"كتاب الشفعة · الفقرة ٢٧","segs":[["matn","ولا تكره الحيلة في إسقاط الشفعة عند أبي يوسف وقال محمد رحمه الله"]]},{"id":"q60_28","label":"كتاب الشفعة · الفقرة ٢٨","segs":[["matn","تكره وإذا بنى المشتري أو غرس ثم قضي للشفيع بالشفعة فهو بالخيار: إن شاء أخذها بالثمن وقمتة البناء والغرس مقلوعا وإن شاء كلف المشتري قلعه وإذا أخذها الشفيع فبنى أو غرس ثم استحقت رجع بالثمن ولا يرجع بقمة البناء والغرس"]]},{"id":"q60_29","label":"كتاب الشفعة · الفقرة ٢٩","segs":[["matn","وإذا انهدمت الدار أو احترق بناؤها أو جف شجر البستان بغير فعل أحد فالشفيع بالخيار: إن شاء أخذها بجميع الثمن وإن شاء ترك وإن نقض المشتري البناء قيل للشفيع: إن شئت فخذ العرصة بحصتها وإن شئت فدع وليس له أن يأخذ النقض"]]},{"id":"q60_30","label":"كتاب الشفعة · الفقرة ٣٠","segs":[["matn","ومن ابتاع أرضا وعلى نخلها ثمر أخذها الشفيع بثمرها فإن أخذها المشتري سقط عن الشفيع حصته وإذا قضي للشفيع بالدار ولم يكن رآها فله خيار الرؤية وإن وجد بها عيبا فله أن يردها به وإن كان المشتري شرط البراءة منه"]]},{"id":"q60_31","label":"كتاب الشفعة · الفقرة ٣١","segs":[["matn","وإذا ابتاع بثمن مؤجل فالشفيع بالخيار: إن شاء أخذها بثمن حال وإن شاء صبر حتى ينقضي الأجل ثم يأخذها وإذا قسم الشركاء العقار فلا شفعة لجارهم بالقسمة وإذا اشترى دارا فسلم الشفيع الشفعة ثم ردها المشتري بخيار رؤية أو شرط إو عيب بقضاء قاض فلا شفعة للشفيع وإن ردها بغير قضاء أو تقاتلا فللشفيع الشفعة"]]}]},{"id":"q61","title":"كتاب الشركة","group":"كتاب الشركة","units":[{"id":"q61_1","label":"كتاب الشركة · الفقرة ١","segs":[["matn","الشركة على ضربين: شركة أملاك وشركة عقود"]]},{"id":"q61_2","label":"كتاب الشركة · الفقرة ٢","segs":[["matn","فشركة الأملاك: العين يرثها رجلان أو يشتريانها فلا يجوز لأحدهما أن ينصرف في نصيب الآخر إلا بإذنه وكل واحد منهما في نصيب صاحبه كالأجنبي"]]},{"id":"q61_3","label":"كتاب الشركة · الفقرة ٣","segs":[["matn","والضرب الثاني: شركة العقود"]]},{"id":"q61_4","label":"كتاب الشركة · الفقرة ٤","segs":[["matn","وهي على أربعة أوجه: مفاوضة وعنان وشركة الصنائع وشركة الوجوه"]]},{"id":"q61_5","label":"كتاب الشركة · الفقرة ٥","segs":[["matn","فأما شركة المفاوضة فهي: إن يشتري الرجلان فيستويان في مالهما وتصرفهما ودينهما فتجوز بين الحرين المسلمين العاقلين البالغين ولا تجوز بين الحر والمملوك ولا بين الصبي والبالغ ولا بين المسلم والكافر وتنعقد على الوكالة والكفالة"]]},{"id":"q61_6","label":"كتاب الشركة · الفقرة ٦","segs":[["matn","وما يشتريه كل واحد منهما يكون على الشركة إلا طعام أهله وكسوتهم وما يلزم كل واحد منهما من الديون بدلا عما يصح فيه الاشتراك فالآخر ضامن له فإن ورث أحدهما مالا تصح فيه الشركة أو وهب له ووصل إلى يده بطلت المفاوضة وصارت الشركة عنانا"]]},{"id":"q61_7","label":"كتاب الشركة · الفقرة ٧","segs":[["matn","ولا تنعقد الشركة إلا بالدراهم والدنانير والفلوس"]]},{"id":"q61_8","label":"كتاب الشركة · الفقرة ٨","segs":[["matn","النافقة ولا يجوز بما سوى ذلك إلا أن يتعامل الناس بها كالتبر والنقرة فتصح الشركة بهما وإذا أرادا الشركة بالعروض باع كل واحد منهما نصف ماله بنصف مال الآخر ثم عقدا الشركة"]]},{"id":"q61_9","label":"كتاب الشركة · الفقرة ٩","segs":[["matn","وأما الشركة العنان: فتنعقد على الوكالة دون الكفالة ويصح التفاضل في المال ويصح أن يتساويا في المال ويتفاضلا في الربح"]]},{"id":"q61_10","label":"كتاب الشركة · الفقرة ١٠","segs":[["matn","ويجوز أن يعقدها كل واحد منهما ببعض ماله دون بعض ولا تصح إلا بما بينا أن المفاوضة تصح به"]]},{"id":"q61_11","label":"كتاب الشركة · الفقرة ١١","segs":[["matn","ويجوز أن يشتركا ومن جهة أحدهما دراهم ومن جهة الآخر دنانير وما اشتراه كل واحد منهما للشركة طولب بثمنه دون الآخر ثم يرجع على شريكه بحصته منه"]]},{"id":"q61_12","label":"كتاب الشركة · الفقرة ١٢","segs":[["matn","وإذا هلك مال الشركة أو أحد المالين قبل أن يشتريا شيئا بطلت الشركة وإن اشترى أحدهما بماله وهلك مال الآخر قبل الشراء فالمشترى بينهما على ما شرطا"]]},{"id":"q61_13","label":"كتاب الشركة · الفقرة ١٣","segs":[["matn","ويرجع على شريكه بحصته من ثمنه"]]},{"id":"q61_14","label":"كتاب الشركة · الفقرة ١٤","segs":[["matn","وتجوز الشركة وإن لم يخلطا المالين ولا تصح الشركة إذا شرطا لأحدهما دارهم مسماة من الربح"]]},{"id":"q61_15","label":"كتاب الشركة · الفقرة ١٥","segs":[["matn","ولكل واحد من المتفاوضين وشريكي العنان أن يبضع المال ويدفعه مضاربة ويوكل من يتصرف فيه ويده في المال يد أمانة"]]},{"id":"q61_16","label":"كتاب الشركة · الفقرة ١٦","segs":[["matn","وأما شركة الصنائع فالخياطان والصباغان يشتركان على أن يتقبلا الأعمال ويكون اكسب بينهما فيجوز ذلك وما يتقبله كل واحد منهما من العمل يلزمه ويلزم شريكه"]]},{"id":"q61_17","label":"كتاب الشركة · الفقرة ١٧","segs":[["matn","فإن عمل أحدهما دون الآخر فالكسب بينهما نصفان"]]},{"id":"q61_18","label":"كتاب الشركة · الفقرة ١٨","segs":[["matn","وأما شركة الوجوه: فالرجلان يشتركان ولا مال لهما على أن يشتريا بوجوههما ويبيعا فتصح الشركة على هذا وكل واحد منهما وكيل الآخر فيما يشتريه فإن شرطا أن يكون المشتري بينهما نصفين فالربح"]]},{"id":"q61_19","label":"كتاب الشركة · الفقرة ١٩","segs":[["matn","كذلك ولا يجوز أن يتفاضلا فيه وإن شرطا أن يكون المشتري بينهما أثلاثا فالربح كذلك"]]},{"id":"q61_20","label":"كتاب الشركة · الفقرة ٢٠","segs":[["matn","ولا تجوز الشركة في الاحتطاب والاحتشاش والاصطياد وما اصطاده كل واحد منهما أو احتطبه فهو له دون صاحبه"]]},{"id":"q61_21","label":"كتاب الشركة · الفقرة ٢١","segs":[["matn","وإذا اشتركا ولأحدهما بغل وللآخر رواية يستقي عليها الماء والكسب بينهما لم تصح الشركة والكسب كله للذي استقى وعليه أجر مثل الراوية إن كان صاحب البغل وإن كان صاحب الراية فعليه أجر مثل البغل"]]},{"id":"q61_22","label":"كتاب الشركة · الفقرة ٢٢","segs":[["matn","وكل شركة فاسدة فالربح فيها على قدر المال ويبطل شرط التفاضل"]]},{"id":"q61_23","label":"كتاب الشركة · الفقرة ٢٣","segs":[["matn","وإذا مات أحد الشريكين أو ارتد ولحق بدار الحرب بطلت الشركة"]]},{"id":"q61_24","label":"كتاب الشركة · الفقرة ٢٤","segs":[["matn","وليس لواحد من الشركين أن يؤدي زكاة مال الأخر إلا بإذنه"]]},{"id":"q61_25","label":"كتاب الشركة · الفقرة ٢٥","segs":[["matn","فإن أذن كل واحد منهما لصاحبه أن يؤدي زكاته فأدى كل واحد منهما فالثاني ضامن"]]},{"id":"q61_26","label":"كتاب الشركة · الفقرة ٢٦","segs":[["matn","علم بأداء الأول أو لم يعلم"]]}]},{"id":"q62","title":"كتاب المضاربة","group":"كتاب المضاربة","units":[{"id":"q62_1","label":"كتاب المضاربة · الفقرة ١","segs":[["matn","المضاربة: عقد على الشركة بمال من أحد الشريكين وعمل من الآخر"]]},{"id":"q62_2","label":"كتاب المضاربة · الفقرة ٢","segs":[["matn","ولا تصح المضاربة إلا بالمال الذي بيننا أن الشركة تصح به"]]},{"id":"q62_3","label":"كتاب المضاربة · الفقرة ٣","segs":[["matn","ومن شرطها: أن يكون الربح بينهما مشاعا لا يستحق أحدهما منه دراهم مسماة ولا بد أن يكون المال مسلما إلى المضارب ولا بد لرب المال فيه"]]},{"id":"q62_4","label":"كتاب المضاربة · الفقرة ٤","segs":[["matn","فإذا صحت المضاربة مطلقة جاز للمضارب أن يشتري ويبيع ويسافر ويبضع ويوكل وليس له أن يدفع المال مضاربة إلا أن يأذن له رب المال في ذلك"]]},{"id":"q62_5","label":"كتاب المضاربة · الفقرة ٥","segs":[["matn","وإن خص له رب المال التصرف في بلد بعينه أو في سلعة بعينها لم يجز له أن يتجاوز ذلك"]]},{"id":"q62_6","label":"كتاب المضاربة · الفقرة ٦","segs":[["matn","وكذلك إن وقت للمضاربة مدة بعينها جاز وبطل العقد بمضيها"]]},{"id":"q62_7","label":"كتاب المضاربة · الفقرة ٧","segs":[["matn","وليس للمضارب أن يشتري أبا رب المال ولا ابنه ولا من يعتق عليه فإن اشتراهم كان مشتريا لنفسه دون المضاربة وإن كان في المال ربح فليس له أن يشتري من يعتق عله فإن اشتراهم ضمن مال المضاربة وإن لم يكن في المال ربح جاز أن يشتريهم فإن زادت قيمتهم عتق نصيبه منهم ولم يضمن لرب المال شيئا ويسعى المعتق لرب المال في قيمة نصيبه منه وإذا دفع المضارب المال مضاربة ولم يأذن له رب المال في ذلك لم يضمن بالدفع ولا بتصرف المضارب الثاني حتى يربح فإذا ربح ضمن المضارب الأول المال"]]},{"id":"q62_8","label":"كتاب المضاربة · الفقرة ٨","segs":[["matn","وإذا دفع إليه المال مضاربة"]]},{"id":"q62_9","label":"كتاب المضاربة · الفقرة ٩","segs":[["matn","بالنصف فأذن له أن يدفعها مضاربة فدفعها بالثلث فإن كان رب المال قال له على أن رزق الله بيننا نصفان فلرب المال نصف الربح وللمضارب الثاني ثلث الربح وللأول السدس وإن قال على أن ما رزقك الله بيننا نصفان فللمضارب الثاني الثلث وما بقي بين رب المال والمضارب الأول نصفان فإن قال له على أن ما رزق الله فلي نصفه فدفع المال إلى آخر مضاربة بالنصف فللمضارب الثاني نصف الربح ولرب المال النصف ولا شيء للمضارب الأول فإن شرط للمضارب الثاني ثلثي الربح فلرب المال نصف الربح وللمضارب الثاني نصف الربح ويضمن الأول للمضارب الثاني سدس الربح من ماله"]]},{"id":"q62_10","label":"كتاب المضاربة · الفقرة ١٠","segs":[["matn","وإذا مات رب المال أو المضارب بطلت المضاربة وإن ارتد رب المال عن الإسلام ولحق بدار الحرب بطلت المضاربة"]]},{"id":"q62_11","label":"كتاب المضاربة · الفقرة ١١","segs":[["matn","وإذا عزل رب المال المضارب ولم يعلم بعزله حتى اشترى وباع فتصرفه جائز وإن علم بعزله والمال عروض فله أن يبيعها ولا يمنعه العزل من ذلك ثم لا يجوز أن يشتري بثمنها شيئا آخر"]]},{"id":"q62_12","label":"كتاب المضاربة · الفقرة ١٢","segs":[["matn","وإن عزله ورأس المال دراهم أو دنانير قد نصت فليس له أن يتصرف فيه"]]},{"id":"q62_13","label":"كتاب المضاربة · الفقرة ١٣","segs":[["matn","وإذا افترقا وفي المال ديون وقد ربح المضارب فيه أجبره"]]},{"id":"q62_14","label":"كتاب المضاربة · الفقرة ١٤","segs":[["matn","الحاكم على اقتضاء الديون وإن لم يكن له ربح لم يلزمه الاقتضاء ويقال له: وكل رب المال في الاقتضاء"]]},{"id":"q62_15","label":"كتاب المضاربة · الفقرة ١٥","segs":[["matn","وما هلك من مال المضاربة فهو من الربح دون رأس المال فإن زاد الهالك على الربح فلا ضمان على المضارب فيه وإن كانا قد اقتسما الربح والمضاربة بحالها ثم هلك المال أو بعضه ترادا الربح حتى يستوفي رب المال رأس المال فإن فضل بشيء كان بينهما وإن عجز عن رأس المال لم يضمن المضارب وإن كانا قد اقتسما الربح وفسخا المضاربة ثم عقداها فهلك المال لم يترادا الربح الأول"]]},{"id":"q62_16","label":"كتاب المضاربة · الفقرة ١٦","segs":[["matn","ويجوز للمضارب أن يبيع بالنقد والسيئة ولا يزوج عبدا ولا أمة من مال المضاربة"]]}]},{"id":"q63","title":"كتاب الوكالة","group":"كتاب الوكالة","units":[{"id":"q63_1","label":"كتاب الوكالة · الفقرة ١","segs":[["matn","كل عقد جاز أن يعقده الإنسان بنفسه جاز أن يوكل به غيره ويجوز التوكيل بالخصومة في سائر الحقوق وبإثباتها ويجوز التوكيل بالاستيفاء إلا في الحدود والقصاص فإن الوكالة لا تصح باستيفائهما مع غيبة الموكل عن المجلس"]]},{"id":"q63_2","label":"كتاب الوكالة · الفقرة ٢","segs":[["matn","وقال أبو حنيفة: لا يجوز التوكيل بالخصومة إلا برضا الخصم إلا أن يكون الموكل مريضا أو غائبا مسيرة ثلاثة أيام فصاعدا"]]},{"id":"q63_3","label":"كتاب الوكالة · الفقرة ٣","segs":[["matn","وقال أبو يوسف ومحمد: يجوز التوكيل بغير رضا الخصم"]]},{"id":"q63_4","label":"كتاب الوكالة · الفقرة ٤","segs":[["matn","ومن شرط الوكالة: أن يكون الموكل ممن يملك التصرف وتلزمه الأحكام والوكيل ممن يعقل العقد"]]},{"id":"q63_5","label":"كتاب الوكالة · الفقرة ٥","segs":[["matn","ويقصده وإذا وكل الحر البالغ أو المأذون مثلهما جاز وإن وكلا صبيا محجورا يعقل البيع والشراء أو عبدا محجورا جاز ولا تتعلق بهما الحقوق وتتعلق بموكليهما"]]},{"id":"q63_6","label":"كتاب الوكالة · الفقرة ٦","segs":[["matn","والعقود التي يعقدها الوكلاء على ضربين: فكل عقد يضيفه الوكيل إلى نفسه - مثل البيع والإجارة - فحقوق ذلك العقد تتعلق بالوكيل دون الموكل فيسلم المبيع ويقبض الثمن ويطالب بالثمن إذا اشترى"]]},{"id":"q63_7","label":"كتاب الوكالة · الفقرة ٧","segs":[["matn","ويقبض المبيع ويخاصم بالعيب"]]},{"id":"q63_8","label":"كتاب الوكالة · الفقرة ٨","segs":[["matn","وكل عقد يضيفه إلى موكله - كالنكاح والخلع والصلح من دم العمد - فإن حقوقه تتعلق بالموكل دون الوكيل فلا يطالب وكيل الزوج بالمهر ولا يلزم وكيل المرأة تسليمها وإذا طالب الموكل المشتري فله أن يمنعه إياه فإن دفعه إليه جاز ولم يكن للوكيل أن يطالبه به ثانيا"]]},{"id":"q63_9","label":"كتاب الوكالة · الفقرة ٩","segs":[["matn","ومن وكل رجلا بشراء شيء فلا بد من تسمية جنسه وصفته أو جنسه ومبلغ ثمنه إلا أن يوكله وكالة عامة فيقول: ابتع لي ما رأيت"]]},{"id":"q63_10","label":"كتاب الوكالة · الفقرة ١٠","segs":[["matn","وإذا اشترى الوكيل وقبض المبيع ثم اطلع على عيب فله"]]},{"id":"q63_11","label":"كتاب الوكالة · الفقرة ١١","segs":[["matn","أن يرد بالعيب ما دام المبيع في يد وإن سلمه إلى الموكل لم يدره إلا بإذنه"]]},{"id":"q63_12","label":"كتاب الوكالة · الفقرة ١٢","segs":[["matn","ويجوز التوكيل بعقد الصرف والسلم فإن فارق الوكيل صاحبه قبل القبض بطل العقد ولا تعتبر مفارقة الموكل وإذا دفع الوكيل بالشراء الثمن من ماله وقبض المبيع فله أن يرجع به على الموكل فإن هلك المبيع في يده قبل حبسه هلك من مال الموكل ولم يسقط الثمن"]]},{"id":"q63_13","label":"كتاب الوكالة · الفقرة ١٣","segs":[["matn","وله أن يحبسه حتى يستوفي الثمن فإن حبسه فهلك كان مضمونا ضمان الرهن عند أبي يوسف وضمان المبيع عند محمد"]]},{"id":"q63_14","label":"كتاب الوكالة · الفقرة ١٤","segs":[["matn","وإذا وكل رجلين فليس لأحدهما أن يتصرف فيما وكلا فيه دون الآخر إلا أن يوكلهما بالخصومة أو بطلاق زوجته بغير عوض أو برد وديعة عنده أو بقضاء دين عليه"]]},{"id":"q63_15","label":"كتاب الوكالة · الفقرة ١٥","segs":[["matn","وليس للوكيل أن يوكل فيما وكل به"]]},{"id":"q63_16","label":"كتاب الوكالة · الفقرة ١٦","segs":[["matn","إلا أن يأذن له الموكل أو يقول له: اعمل برأيك فإن وكل بغير إذن موكله فعقد وكيله بحضرته جاز وإن عقد بغير حضرته فأجازه الوكيل الأول جاز وللموكل أن يغزل الوكيل عن الوكالة فإن لم يبلغه العزل فهو على وكالته وتصرفه جائز حتى يعلم"]]},{"id":"q63_17","label":"كتاب الوكالة · الفقرة ١٧","segs":[["matn","وتبطل الوكالة بموت الموكل وجنوبه جنوبا مطبقا ولحاقه بدرا الحرب مرتدا وإذا وكل المكاتب ثم عجز أو المأذون فحجر عليه أو الشريكان فافترقا فهذه الوجوه تبطل الوكالة علم الوكيل أو لم يعلم"]]},{"id":"q63_18","label":"كتاب الوكالة · الفقرة ١٨","segs":[["matn","وإذا مات الوكيل أو جن جنونا مطبقا بطلت وكالته وإن لحق بدار الحرب مرتدا لم يجز له التصرف إلا أن يعود مسلما ومن وكل آخر بشيء ثم تصرف فيما وكل به بطلت الوكالة والوكيل بالبيع والشراء لا يجوز أن يعقد عند أبي"]]},{"id":"q63_19","label":"كتاب الوكالة · الفقرة ١٩","segs":[["matn","حنيفة مع أبيه وجده وولده ولده وزوجته وعبده ومكاتبه"]]},{"id":"q63_20","label":"كتاب الوكالة · الفقرة ٢٠","segs":[["matn","وقال أبو يوسف ومحمد: يجوز بيعه منهم بمثل القيمة"]]},{"id":"q63_21","label":"كتاب الوكالة · الفقرة ٢١","segs":[["matn","إلا في عبده ومكاتبه والوكيل بالبيع يجوز بيعه بالقليل والكثير عند أبي حنيفة"]]},{"id":"q63_22","label":"كتاب الوكالة · الفقرة ٢٢","segs":[["matn","وقال أبو يوسف ومحمد: لا يجوز بيعه بنقصان لا يتغابن الناس في مثله والوكيل بالشراء يجوز عقده بمثل القيمة وزيادة يتغابن الناس في مثلها ولا يجوز بما لا يتغابن الناس في مثله والذي لا يتغابن الناس فيه: ما لا يدخل تحت تقويم المقومين"]]},{"id":"q63_23","label":"كتاب الوكالة · الفقرة ٢٣","segs":[["matn","وإذا ضمن الوكيل بالبيع الثمن عن المبتاع فضمانه باطل وإذا وكله ببيع عبده فباع نصفه جاز عند أبي حنيفة وإن وكله بشراء عبد فاشترى نصفه فالشراء موقوف فإن اشترى باقية لزم الموكل وإذا وكله بشراء عشرة أرطال لحم بدرهم فاشترى عشرين رطلا بدرهم من لحم يباع مثله عشرة بدرهم لزم الموكل منه عشرة أرطال بنصف درهم عند أبي حنيفة وقال أبو يوسف ومحمد: يلزمه العشرون وإذا وكله بشراء شيء بعينه فليس له أن يشتريه لنفسه"]]},{"id":"q63_24","label":"كتاب الوكالة · الفقرة ٢٤","segs":[["matn","وإن وكله بشراء عبد بغير عينه فاشترى عبدا فهو للوكيل إلا أن يقول: نويت الشراء للموكل أو يشتريه بمال الموكل"]]},{"id":"q63_25","label":"كتاب الوكالة · الفقرة ٢٥","segs":[["matn","والوكيل بالخصومة وكيل بالقبض عند أبي حنيفة وأبي يوسف ومحمد والوكيل بقبض الدين وكيل بالخصومة فيه عند أبي حنيفة"]]},{"id":"q63_26","label":"كتاب الوكالة · الفقرة ٢٦","segs":[["matn","وإذا أقر الوكيل بالخصومة على موكله عند القاضي جاز إقراره ولا يجوز إقراره عليه عند غير القاضي عند أبي حنيفة ومحمد إلا أنه يخرج من الخصومة"]]},{"id":"q63_27","label":"كتاب الوكالة · الفقرة ٢٧","segs":[["matn","وقال أبو يوسف: يجوز إقراره عليه عند غير القاضي ومن ادعى أنه وكيل الغائب في قبض دينه فصدقه الغريم أمر بتسليم الدين إليه فإن حضر الغائب فصدقه وإلا دفع إليه الغريم الدين ثانيا ورجع به على الوكيل إن كان باقيا في يده"]]},{"id":"q63_28","label":"كتاب الوكالة · الفقرة ٢٨","segs":[["matn","وإن قال إني وكيل بقبض الوديعة فصدقه المودع لم يؤمر بالتسليم إليه"]]}]},{"id":"q64","title":"كتاب الكفالة","group":"كتاب الكفالة","units":[{"id":"q64_1","label":"كتاب الكفالة · الفقرة ١","segs":[["matn","الكفالة ضربان: كفالة بالنفس وكفالة بالمال"]]},{"id":"q64_2","label":"كتاب الكفالة · الفقرة ٢","segs":[["matn","فالكفالة بالنفس جائزة والمضمون بها إحضار المكفول به وتنعقد إذا قال تكفلت بنفس فلان أوبرقبته أو بروحه أو بجسده أو برأسه أو بنصفه أو بثلثه وكذلك إن قال ضمنته أو هو علي أو إلي أو أنا زعيم به أو قبيل"]]},{"id":"q64_3","label":"كتاب الكفالة · الفقرة ٣","segs":[["matn","فإن شرط في الكفالة تسليم المكفول به في وقت بعينه لزمه إحضاره إذا طالبه به في ذلك الوقت فإن أحضره وإلا حبسه الحاكم حتى يحضره وإذا أحضره وسلمه في مكان يقدر المكفول له على محاكمته برئ الكفيل من الكفالة وإذا تكفل به على أن يسلمه في مجلس القاضي فسلمه في السوق برئ وإن سلمه في برية لم يبرأ"]]},{"id":"q64_4","label":"كتاب الكفالة · الفقرة ٤","segs":[["matn","وإن مات المكفول به برئ الكفيل بالنفس من الكفالة فإن تكفل بنفسه على أنه إن لم يواف به في وقت كذا فهو ضامن لما عليه وهو ألف ولم يحضره في ذلك الوقت لزمه ضمان المال ولم يبرأ من الكفالة بالنفس"]]},{"id":"q64_5","label":"كتاب الكفالة · الفقرة ٥","segs":[["matn","ولا يجوز الكفالة بالنفس في الحدود والقصاص عند أبي حنيفة وقالا: يجوز"]]},{"id":"q64_6","label":"كتاب الكفالة · الفقرة ٦","segs":[["matn","وأما الكفالة بالمال فجائزة معلوما كان المال المكفول به أو مجهولا إذا كان دينا صحيحا"]]},{"id":"q64_7","label":"كتاب الكفالة · الفقرة ٧","segs":[["matn","مثل أن يقول: تكلفت عنه بألف أو بما لك عليه أو بما يدركك في هذا البيع والمكفول به بالخيار: إن شاء طالب الذي عليه الأصل وإن شاء طالب كفيله"]]},{"id":"q64_8","label":"كتاب الكفالة · الفقرة ٨","segs":[["matn","ويجوز تعليق الكفالة بالشرط مثل أن يقول: ما بايعت فلانا فعلي أو ما ذاب لك عليه"]]},{"id":"q64_9","label":"كتاب الكفالة · الفقرة ٩","segs":[["matn","فعلي أو ما غصبك فلانا فعلي وإذا قال: تكفلت بما لك عليه فقامت البينة بألف عليه ضمنه الكفيل فإن لم تقم البينة فالقول قول الكفيل مع يمينه في مقدار ما يعترف به"]]},{"id":"q64_10","label":"كتاب الكفالة · الفقرة ١٠","segs":[["matn","فإن اعترف المكفول عنه بأكثر من ذلك لم يصدق على كفيله"]]},{"id":"q64_11","label":"كتاب الكفالة · الفقرة ١١","segs":[["matn","وتجوز الكفالة بأمر المكفول عنه وبغير أمره فإن كفل بأمره رجع بما يؤدي عليه وإن كفل بغير أمره لم يرجع بما يؤديه وليس للكفيل أن يطالب المكفول عنه بالمال قبل أن يؤدي عنه فإن لوزم بالمال كان له أن يلازم المكفول عنه حتى يخلصه وإذا أبرأ الطالب المكفول عنه أو استوفى منه برئ الكفيل وإن أبرأ الكفيل لم يبرإ المكفول عنه"]]},{"id":"q64_12","label":"كتاب الكفالة · الفقرة ١٢","segs":[["matn","ولا يجوز تعليق البراءة من الكفالة بشرط"]]},{"id":"q64_13","label":"كتاب الكفالة · الفقرة ١٣","segs":[["matn","وكل حق لا يمكن استيفاؤه من الكفيل لا تصح الكفالة به كالحدود والقصاص وإذا تكفل عن المشتري بالثمن جاز وإن تكفل عن البائع بالمبيع لم يصح ومن استأجر دابة للحمل فإن كانت بعينها لم تصح الكفالة بالحمل وإن كانت بغير عينها جازت الكفالة"]]},{"id":"q64_14","label":"كتاب الكفالة · الفقرة ١٤","segs":[["matn","ولا تصح الكفالة إلا بقبول المكفول له في مجلس العقد إلا في مسألة واحدة وهي أن يقول المريض لوارثه: تكفل عني بما علي من الدين فتكفل به مع غيبة الغرماء"]]},{"id":"q64_15","label":"كتاب الكفالة · الفقرة ١٥","segs":[["matn","وإذا كان الدين على اثنين وكل واحد منهما كفيل ضامن عن الآخر فما أدرى أحدهما لم يرجع به على شريكه حتى يزيد ما يؤديه على النصف فيرجع بالزيادة"]]},{"id":"q64_16","label":"كتاب الكفالة · الفقرة ١٦","segs":[["matn","وإذا كفل اثنان عن رجل بألف على أن كل واحد منهما كفيل عن صاحبه فما أداره أحدهما يرجع بنصفه على شريكه قليلا كان أو كثيرا ولا تجوز الكفالة بمال الكتابة حر تكفل به أو عبد"]]},{"id":"q64_17","label":"كتاب الكفالة · الفقرة ١٧","segs":[["matn","وإذا مات الرجل وعليه ديون ولم يترك شيئا فتكفل رجل عنه للغرماء لم تصح الكفالة عند أبي حنيفة وقالا: تصح"]]}]},{"id":"q65","title":"كتاب الحوالة","group":"كتاب الحوالة","units":[{"id":"q65_1","label":"كتاب الحوالة · الفقرة ١","segs":[["matn","الحوالة: جائزة بالديون وتصح برضا المحيل والمحتال له والمحال عليه وإذا تمت الحوالة برىء المحيل من الدين ولم يرجع المحتال على المحيل إلاأن يتوى حقه والتوى عند أبي حنيفة أحد أمرين: إما أن يجحد الحوالة ويحلف ولا بينة عليه أو يموت مفلسا وقال أبو يوسف ومحمد هاذان ووجه ثالث وهو أن يحكم الحاكم بإفلاسه في حال حياته"]]},{"id":"q65_2","label":"كتاب الحوالة · الفقرة ٢","segs":[["matn","وإذا طالب المحال عليه المحيل بمثل مال الحواله فقال المحيل: أحلت بدين لي عليك لم يقبل قوله وكان عليه مثل الدين وإن طالب المحيل المحتال بما أحاله به فقال: إنما أحلتك لتقبضه لي وقال المحتال: بل أحلتني بدين"]]}]},{"id":"q66","title":"كتاب الصلح","group":"كتاب الصلح","units":[{"id":"q66_1","label":"كتاب الصلح · الفقرة ١","segs":[["matn","الصلح: على ثلاثة أضرب: صلح مع إقرار وصلح مع سكوت وهو أن لا يقر المدعى عليه ولا ينكره وصلح مع إنكار وكل ذلك جائز"]]},{"id":"q66_2","label":"كتاب الصلح · الفقرة ٢","segs":[["matn","فإن وقع الصلح عن إقرار اعتبر فيه ما يعتبر في البياعات إن وقع عن مال بمال وإن وقع عن مال بمنافع فيعتبر بالإجارات"]]},{"id":"q66_3","label":"كتاب الصلح · الفقرة ٣","segs":[["matn","والصلح عن السكوت والإنكار في حق المدعى عليه لافتداء اليمين وقطع الخصومة وفي حق المدعي بمعنى المعاوضة"]]},{"id":"q66_4","label":"كتاب الصلح · الفقرة ٤","segs":[["matn","وإذا صالح عن دار لم تجب فيه شفعة وإذا صالح على دار وجبت فيها الشفعة"]]},{"id":"q66_5","label":"كتاب الصلح · الفقرة ٥","segs":[["matn","وإذا كان الصلح عن إقرار فاستحق بعض المصالح عنه رجع المدعى عليه بحصة ذلك من العوض"]]},{"id":"q66_6","label":"كتاب الصلح · الفقرة ٦","segs":[["matn","وإن وقع الصلح عن سكوت أو إنكار فاستحق المتنازع فيه رجع المدعي بالخصومة ورد العوض وإن استحق بعض ذلك رد حصته ورجع بالخصومة فيه وإن ادعى حقا في دار لم يبينه فصولح من ذلك على شيء ثم استحق بعض الدار لم يرد شيئا من العوض لأن دعواه يجوز أن تكون فيما بقي"]]},{"id":"q66_7","label":"كتاب الصلح · الفقرة ٧","segs":[["matn","والصلح جائز من دعوى الأموال والمنافع وجنابة العمد والخطإ ولا يجوز من دعوى حد"]]},{"id":"q66_8","label":"كتاب الصلح · الفقرة ٨","segs":[["matn","وإذا ادعى رجل على امرأة نكاحا وهي تجحد فصالحته على مال بذلته"]]},{"id":"q66_9","label":"كتاب الصلح · الفقرة ٩","segs":[["matn","حتى يترك الدعوى جاز وكان في معنى الخلع وإن ادعت امرأة نكاحا على رجل فصالحها على مال بذله لها لم تجز وإن ادعى على رجل أنه عبده فصالحته على مال أعطاه جاز وكان في حق المدعي في معنى العتق على مال وكل شيء وقع عليه الصلح وهو مستحق بعقد المداينة لم يحمل على المعاوضة لم يحمل على المعاوضة وإنما يحمل على أنه استوفى بعض حقه وأسقط باقية"]]},{"id":"q66_10","label":"كتاب الصلح · الفقرة ١٠","segs":[["matn","كمن له على رجل ألف دلاهم جياد فصالحه على خمسمائة زيوف جاز وصار كأنه أبرأه عن بعض حقه وأخذ باقيه ولو صالحه على ألف مؤجل جاز وصار كأنه أجل نفس الحق"]]},{"id":"q66_11","label":"كتاب الصلح · الفقرة ١١","segs":[["matn","ولو صالحه على دنانير إلى شهر لم يجز ولو كان له ألف مؤجلة فصالحه على خمسمائة حالة لم يجز ولو كان له ألف سود فصالحه على خمسمائة بيض لم يجز"]]},{"id":"q66_12","label":"كتاب الصلح · الفقرة ١٢","segs":[["matn","ومن وكل رجلا بالصلح عنه فصالحه لم يلزم الوكيل ما صالح عليه إلا أن يضمنه والمال لازم للموكل"]]},{"id":"q66_13","label":"كتاب الصلح · الفقرة ١٣","segs":[["matn","فإن صالح عنه على شيء بغير أمره فهو على أربعة أوجه: إن صالح بمال وضمنه تم الصلح"]]},{"id":"q66_14","label":"كتاب الصلح · الفقرة ١٤","segs":[["matn","وكذلك لو قال: صالحتك على ألفي هذه تم الصلح ولزمه تسليمها وكذلك لو قال: صالحتك على ألف وسلمها وإن قال: صالحتك على ألف ولم يسلمها فالعقد موقوف: فإن أجازه المدعى عليه جاز ولزمه الألف وإن لم يجزه بطل"]]},{"id":"q66_15","label":"كتاب الصلح · الفقرة ١٥","segs":[["matn","وإذا كان الدين بين شريكين فصالح أحدهما من نصيبه على ثوب فشريكه بالخيار: إن شاء اتبع عليه الدين بنصفه وإن شاء أخذ نصف الثوب إلا أن يضمن له شريكه ربع الدين ولو استوفى نصف نصيبه من الدين كان لشريكه أن يشركه فيما قبض"]]},{"id":"q66_16","label":"كتاب الصلح · الفقرة ١٦","segs":[["matn","ثم يرجعان على الغريم بالباقي ولو اشترى أحدهما نصيبه من الدين سلعة كان لشريكه أن يضمنه ربع الدين"]]},{"id":"q66_17","label":"كتاب الصلح · الفقرة ١٧","segs":[["matn","وإذا كان السلم بين شريكين فصالح أحدهما من نصيبه على رأس المال لم يجز عند أبي حنيفة ومحمد رحمهما"]]},{"id":"q66_18","label":"كتاب الصلح · الفقرة ١٨","segs":[["matn","الله وقال أبو يوسف رحمه الله: يجوز الصلح"]]},{"id":"q66_19","label":"كتاب الصلح · الفقرة ١٩","segs":[["matn","وإذا كانت التركة بين ورثة فأخرجوا أحدهم منها بمال أعطوه إياه والتركة عقار أو عروض جاز قليلا كان ما أعطوه أو كثيرا"]]},{"id":"q66_20","label":"كتاب الصلح · الفقرة ٢٠","segs":[["matn","وإن كانت التركة فضة فأعطوه ذهبا أو كانت ذهبا فأعطوه فضة فهو كذلك"]]},{"id":"q66_21","label":"كتاب الصلح · الفقرة ٢١","segs":[["matn","وإن كانت التركة ذهبا وفضة وغير ذلك فصالحوه على فضة أو ذهب فلا بد أن يكون ما أعطوه أكثر من نصيبه من ذلك الجنس حتى يكون نصيبه بمثله والزيادة بحقه من بقية الميراث"]]},{"id":"q66_22","label":"كتاب الصلح · الفقرة ٢٢","segs":[["matn","وإن كان في التركة دين على الناس فأدخلوه في الصلح على أن يخرجوا المصالح عنه ويكون الدين لهم فالصلح باطل فإن شرطوا أن يبرئ الغرماء منه ولا يرجع عليهم بنصيب المصالح فالصلح جائز"]]}]},{"id":"q67","title":"كتاب الهبة","group":"كتاب الهبة","units":[{"id":"q67_1","label":"كتاب الهبة · الفقرة ١","segs":[["matn","الهبة: تصح بالإيجاب والقبول وتتم القبض فإذا قبض الموهوب له في المجلس بغير أمر الواهب جاز"]]},{"id":"q67_2","label":"كتاب الهبة · الفقرة ٢","segs":[["matn","وإن قبض بعد الافتراق لم تصح إلا أن يأذن له الواهب في القبض"]]},{"id":"q67_3","label":"كتاب الهبة · الفقرة ٣","segs":[["matn","وتنعقد الهبة بقوله: وهبت ونحلت وأعطيت وأطعمتك هذا الطعام وجعلت هذا الثوب لك وأعمرتك هذا الشيء وحملتك على هذه الدابة إذا نوى بالحملان الهبة"]]},{"id":"q67_4","label":"كتاب الهبة · الفقرة ٤","segs":[["matn","ولا تجوز الهبة فيما يقسم إلا محوزة مقسومة"]]},{"id":"q67_5","label":"كتاب الهبة · الفقرة ٥","segs":[["matn","وهبة المشاع فيما لا يقسم جائزة"]]},{"id":"q67_6","label":"كتاب الهبة · الفقرة ٦","segs":[["matn","ومن وهب شقصا مشاعا فالهبة فاسدة"]]},{"id":"q67_7","label":"كتاب الهبة · الفقرة ٧","segs":[["matn","فإن قسمه وسلمه جاز"]]},{"id":"q67_8","label":"كتاب الهبة · الفقرة ٨","segs":[["matn","ولو وهب دقيقا في حنطة أو دهنا في سمسم فالهبة فاسدة فأن طحن وسلم لم يجز"]]},{"id":"q67_9","label":"كتاب الهبة · الفقرة ٩","segs":[["matn","وإذا كانت العين في يد الموهوب ملكها بالهبة وإن لم يجددفيها قبضا وإذا وهب الأب لابنه الصغير هبة ملكها الابن بالعقد فإن وهب له أجنبي هبة تمت بقبض الأب"]]},{"id":"q67_10","label":"كتاب الهبة · الفقرة ١٠","segs":[["matn","وإذا وهب لليتيم هبة فقبضها له وليه جاز فأن كان في حجر أمه فقبضها له جائز وكذلك إن كان في حجر أجنبي يربيه فقبضه له جائز"]]},{"id":"q67_11","label":"كتاب الهبة · الفقرة ١١","segs":[["matn","وإن قبض الصبي الهبة بنفسه له جاز"]]},{"id":"q67_12","label":"كتاب الهبة · الفقرة ١٢","segs":[["matn","وإن وهب اثنان من واحد دارا جاز وإن وهب واحد من اثنين دارا لم يصح عند أبي حنيفة وقال أبو يوسف ومحمد: يصح"]]},{"id":"q67_13","label":"كتاب الهبة · الفقرة ١٣","segs":[["matn","وإذا وهب هبة لأجنبي فله الرجوع فيها"]]},{"id":"q67_14","label":"كتاب الهبة · الفقرة ١٤","segs":[["matn","إلا أن يعوضه عنها أو تزيد زيادة متصلة أو يموت أحد المتعاقدين أو"]]},{"id":"q67_15","label":"كتاب الهبة · الفقرة ١٥","segs":[["matn","تخرج الهبة من ملك الموهوب له"]]},{"id":"q67_16","label":"كتاب الهبة · الفقرة ١٦","segs":[["matn","وإن وهب هبة لذي رحم محرم منه فلا رجوع فيها"]]},{"id":"q67_17","label":"كتاب الهبة · الفقرة ١٧","segs":[["matn","وكذلك ما وهب أحد الزوجين لآخر"]]},{"id":"q67_18","label":"كتاب الهبة · الفقرة ١٨","segs":[["matn","وإذا قال الموهوب له للواهب: خذ هذا عوضا عن هبتك أو بدلا عنها أو في مقابلتها فقبضه الواهب سقط الرجوع وإن عوضه أجنبي عن الموهوب له متبرعا فقبض الواهب العوض سقط الرجوع"]]},{"id":"q67_19","label":"كتاب الهبة · الفقرة ١٩","segs":[["matn","وإذا استحق نصف الهبة رجع بنصف العوض وإن استحق نصف العوض لم يرجع في الهبة إلا أن يرد ما بقي من العوض ثم يرجع"]]},{"id":"q67_20","label":"كتاب الهبة · الفقرة ٢٠","segs":[["matn","ولا يصح الرجوع إلا بتراضيهما أو بحكم الحاكم"]]},{"id":"q67_21","label":"كتاب الهبة · الفقرة ٢١","segs":[["matn","وإذا تلفت العين الموهوبة فاستحقها مستحق فضمن"]]},{"id":"q67_22","label":"كتاب الهبة · الفقرة ٢٢","segs":[["matn","الموهوب له لم يرجع على الواهب بشي"]]},{"id":"q67_23","label":"كتاب الهبة · الفقرة ٢٣","segs":[["matn","وإذا وهب بشرط العوض اعتبر التقابض في العوضين وإذا تقابضا صح العقد وصار في حكم البيع: يرد بالعيب وخيار الرؤية وتجيب فيه الشفعة"]]},{"id":"q67_24","label":"كتاب الهبة · الفقرة ٢٤","segs":[["matn","والعمرى جائزة للمعمر في حال حياته ولورثته من بعده"]]},{"id":"q67_25","label":"كتاب الهبة · الفقرة ٢٥","segs":[["matn","والرقبى باطلة عند أبي حنيفة ومحمد وقال أبو يوسف: جائزة"]]},{"id":"q67_26","label":"كتاب الهبة · الفقرة ٢٦","segs":[["matn","ومن وهب جارية إلا حملها صحت الهبة وبطل الاستثناء"]]},{"id":"q67_27","label":"كتاب الهبة · الفقرة ٢٧","segs":[["matn","والصدقة كالهبة: لا تصح إلا بالقبض ولا تجوز في مشاع يحتمل القسمة وإذا تصدق على فقيرين بشي جاز ولا يجوز الرجوع في الصدقة بعد القبض"]]},{"id":"q67_28","label":"كتاب الهبة · الفقرة ٢٨","segs":[["matn","ومن نذر أن يتصدق بماله لزمه أن يتصدق"]]},{"id":"q67_29","label":"كتاب الهبة · الفقرة ٢٩","segs":[["matn","بجنس ما تجب فيه الزكاة ومن نذر أن يتصدق بجنس ما تجب في الزكاة ومن نذر أن يتصدق بملكه لزمه أن يتصدق بالجميع ويقال له: أمسك منه مقدار ما تنفقه على نفسك وعيالك إلى أن تكسب مالا فإذا اكتسبت مالا تصدق بمثل ما أمسكت لنفسك"]]}]},{"id":"q68","title":"كتاب الوقف","group":"كتاب الوقف","units":[{"id":"q68_1","label":"كتاب الوقف · الفقرة ١","segs":[["matn","لا يزول ملك الواقف عن الوقف عند أبي حنيفة إلا أن يحكم به الحاكم أو يعلقه بموته فيقول: إذا مت فقد وقفت داري على كذا وقال أبو يوسف: يزول الملك بمجرد القول"]]},{"id":"q68_2","label":"كتاب الوقف · الفقرة ٢","segs":[["matn","وقال محمد: لا يزول الملك حتى يجعل للوقف وليا ويسلمه إليه"]]},{"id":"q68_3","label":"كتاب الوقف · الفقرة ٣","segs":[["matn","وإذا صح الوقف - على اختلافهم - خرج عن ملك الواقف ولم يدخل في ملك الموقوف عليه"]]},{"id":"q68_4","label":"كتاب الوقف · الفقرة ٤","segs":[["matn","ووقف المشاع جائز عند أبي يوسف وقال محمد: لا يجوز"]]},{"id":"q68_5","label":"كتاب الوقف · الفقرة ٥","segs":[["matn","ولا يتم الوقف عند أبي حنيفة ومحمد حتى يجعل آخره لجهة لا تنقطع أبدا وقال أبو يوسف: إذا سمو فيه جهة تنقطع جاز وصار بعدها للفقراء وإن لم يسمهم"]]},{"id":"q68_6","label":"كتاب الوقف · الفقرة ٦","segs":[["matn","ويصح وقف العقار ولا يجوز وقف ما ينقل ويحول وقال أبو يوسف: إذا وقف ضيعة ببقرها وهم عبيده جاز"]]},{"id":"q68_7","label":"كتاب الوقف · الفقرة ٧","segs":[["matn","وقال محمد: يجوز حبس الكراع والسلاح"]]},{"id":"q68_8","label":"كتاب الوقف · الفقرة ٨","segs":[["matn","وإذا صاح الوقف لم يجز بيعه ولا تمليكه إلا أن يكون مشاعا عند أبي يوسف فيطلب الشريك القسمة فتصح مقاسمته"]]},{"id":"q68_9","label":"كتاب الوقف · الفقرة ٩","segs":[["matn","والواجب: أن يبدأ من ريع الوقف بعمارته شرط الواقف ذلك أو لم يشرط"]]},{"id":"q68_10","label":"كتاب الوقف · الفقرة ١٠","segs":[["matn","وإن وقف دارا على سكنى ولده فالعمارة على من له السكنى"]]},{"id":"q68_11","label":"كتاب الوقف · الفقرة ١١","segs":[["matn","فإن امتنع من ذلك أو كان فقيرا أجرها الحاكم"]]},{"id":"q68_12","label":"كتاب الوقف · الفقرة ١٢","segs":[["matn","وعمرها بأجرتها فإذا عمرت رجها إلى من له السكنى"]]},{"id":"q68_13","label":"كتاب الوقف · الفقرة ١٣","segs":[["matn","وما انهدم من بناء الوقف وآلته صرفه الحاكم في عمارة الوقف إن احتاج إليه وإن استغنى"]]},{"id":"q68_14","label":"كتاب الوقف · الفقرة ١٤","segs":[["matn","عنه أمسكه حتى يحتاج إلى عمارته فيصرفه فيها ولا يجوز أن يقسمه بين مستحقي الوقف"]]},{"id":"q68_15","label":"كتاب الوقف · الفقرة ١٥","segs":[["matn","وإذا جعل الوقف غلة الوقف لنفسه أو جعل الولاية إليه جاز عند أبي يوسف"]]},{"id":"q68_16","label":"كتاب الوقف · الفقرة ١٦","segs":[["matn","وإذا بنى مسجدا لم يزل ملكه عنه حتى يفرزه عن ملكه بطريقه ويأذن للناس بالصلاة فيه فإذا صلى فيه واحد زال ملكه عنه عند أبي حنيفة ومحمد وقال أبو يوسف: يزول ملكه عنه بقوله: جعلته مسجدا"]]},{"id":"q68_17","label":"كتاب الوقف · الفقرة ١٧","segs":[["matn","ومن بنى سقاية للمسلمين أو خانا يسكنه بنو السبيل أو رباطا أو جعل أرضه مقبرة لم يزل ملكه عن ذلك عند أبي حنيفة حتى يحكم به حاكم"]]},{"id":"q68_18","label":"كتاب الوقف · الفقرة ١٨","segs":[["matn","وقال أبو يوسف: يزول ملكه بالقول وقال محمد: إذا استقى الناس من السقاية وسكنوا ألخان والرباط ودفنوا في المقبرة زال الملك"]]}]},{"id":"q69","title":"كتاب الغصب","group":"كتاب الغصب","units":[{"id":"q69_1","label":"كتاب الغصب · الفقرة ١","segs":[["matn","ومن غصب شيئا مما له مثل فهلك في يده فعليه ضمان مثله وإن كان مما لا مثل له فعليه قيمته يوم الغصب"]]},{"id":"q69_2","label":"كتاب الغصب · الفقرة ٢","segs":[["matn","وعلى الغاصب رد العين المغصوبة فإن ادعى هلاكها حبسه الحاكم حتى يعلم أنها لو كانت باقية لأظهرها ثم قضى عليه ببدلها"]]},{"id":"q69_3","label":"كتاب الغصب · الفقرة ٣","segs":[["matn","والغصب فيما ينقل ويحول وإذا غصب عقارا فهلك في يده لم يضمنه عند أبي حنيفة وأبي يوسف وقال محمد: يضمنه كهدمه وما نقص منه بفعله وسكناه ضمنه في قولهم جميعا"]]},{"id":"q69_4","label":"كتاب الغصب · الفقرة ٤","segs":[["matn","وإذا هلك المغصوب في يد الغاصب بفعله أو بغير فعله فعليه ضمانه"]]},{"id":"q69_5","label":"كتاب الغصب · الفقرة ٥","segs":[["matn","وإن نقص في يده فعليه ضمان النقصان"]]},{"id":"q69_6","label":"كتاب الغصب · الفقرة ٦","segs":[["matn","ومن ذبح شاة غيره فمالكها بالخيار: إن شاء ضمنه قيمتها وسلمها إليه وإن شاء ضمنه نقصانها ومن خرق ثوب غيره خرقا يسيرا ضمن نقصانه وإن خرقه خرقا كثيرا يبطل عامة منفعته فلمالكه أن يضمنه جميع قيمته"]]},{"id":"q69_7","label":"كتاب الغصب · الفقرة ٧","segs":[["matn","وإذا تغيرت العين المغصوبة بفعل الغاصب"]]},{"id":"q69_8","label":"كتاب الغصب · الفقرة ٨","segs":[["matn","حتى زال اسمها وأعظم منافعها زال ملك المغصوب منه عنها وملكها الغاصب وضمنها ولم يحل له الانتفاع بها حتى يؤدي بدلها وهذا كمن غصب شاة فذبحها وشواها أو طبخها أو غصب حنطة فطحنها أو حديدا فاتخذه سيفا أو صفرا فعلمه آنية"]]},{"id":"q69_9","label":"كتاب الغصب · الفقرة ٩","segs":[["matn","وإن غصب فضة أو ذهبا فضربها دنانير أو دراهم أو"]]},{"id":"q69_10","label":"كتاب الغصب · الفقرة ١٠","segs":[["matn","دنانير أو آنية لم يزل ملك مالكها عنها عند أبي حنيفة ومن غصب ساجة فبنى عليها زال ملك مالكها عنها ولزم الغاصب قيمتها"]]},{"id":"q69_11","label":"كتاب الغصب · الفقرة ١١","segs":[["matn","ومن غصب أرضا فغرس فيها أو بنى قيل له: اقلع الغرس والبناء وردها فارغة فإن كانت الأرض تنقص بقلع ذلك فللمالك أن يضمن له قيمة البناء والغرس مقلوعا فيكون له"]]},{"id":"q69_12","label":"كتاب الغصب · الفقرة ١٢","segs":[["matn","ومن غصب ثوبا فصبغه أحمر أو سويقا فلته بسمن فصاحبه بالخيار: إن شاء ضمنه قيمة ثوبه أبيض ومثل السويق وسلمها للغاصب وإن شاء أخذهما وضمن ما زاد الصبغ والسمن فيهما"]]},{"id":"q69_13","label":"كتاب الغصب · الفقرة ١٣","segs":[["matn","ومن غصب عينا فغيبها فضمنه المالك قيمتها ملكها الغاصب والقول في القيمة قول الغاصب مع يمينه إلا أن يقيم المالك البينة بأكثر من ذلك فإن ظهرت العين وقيمتها أكثر مما ضمن وقد ضمنها بقول المالك أو ببينة أقامها أو بنكول الغاصب عن اليمين فلا خيار للمالك وإن كان ضمنها بقول الغاصب مع يمينه فالمالك بالخيار: إن شاء أمضى الضمان وإن شاء أخذ العين ورد العوض"]]},{"id":"q69_14","label":"كتاب الغصب · الفقرة ١٤","segs":[["matn","وولد المغصوبة ونماؤها وثمرة البستان المغصوب أمانة في يد الغاصب فإن هلك فلا ضمان عليه إلا أن يتعدى فيها أو يطلبها مالكها فيمنعها إياه"]]},{"id":"q69_15","label":"كتاب الغصب · الفقرة ١٥","segs":[["matn","وما نقصت الجارية بالولادة في ضمان الغاصب فإن كان في قيمة الولد وفاء به خير النقصان بالولد وسقط ضمانه عن الغاصب ولا يضمن الغاصب منافع ما غصبه إلا أن بنقص باستعماله فيغرم النقصان"]]},{"id":"q69_16","label":"كتاب الغصب · الفقرة ١٦","segs":[["matn","وإذا استهلك المسلم خمر الذمي أو خنزيره ضمن قيمتهما وإن استهلكهما المسلم على المسلم لم يضمن"]]}]},{"id":"q70","title":"كتاب الوديعة","group":"كتاب الوديعة","units":[{"id":"q70_1","label":"كتاب الوديعة · الفقرة ١","segs":[["matn","الوديعة: أمانة في يد المودع إذا هلكت لم يضمنها وللمودع أن يحفظها بنفسه وبمن في عياله فإن حفظها بغيرهم أو أودعها ضمن"]]},{"id":"q70_2","label":"كتاب الوديعة · الفقرة ٢","segs":[["matn","إلا أن يقع في داره حريق فيسلمها إلى جاره أو يكون في سفينة يخاف الغرق فلقيها إلى سفينة أخرى"]]},{"id":"q70_3","label":"كتاب الوديعة · الفقرة ٣","segs":[["matn","وإن خلطها المودع بماله حتى لا تتميز ضمنها فإن طلبها صاحبها فحبسها عنه وهو يقدر على تسليمها ضمنها"]]},{"id":"q70_4","label":"كتاب الوديعة · الفقرة ٤","segs":[["matn","وإن اختلطت بماله من غيره فعله فهو شريك لصاحبها وإن أنفق المودع بعضها ثم رد مثله فخلطه بالباقي ضمن الجميع"]]},{"id":"q70_5","label":"كتاب الوديعة · الفقرة ٥","segs":[["matn","وإذا تعدى المودع في الوديعة - بأن كانت دابة فركبها أو ثوبا فلبسه أو عبدا فاستخدمه أو أودعها عند غيره - ثم أزال التعدي وردها إلى يده زال الضمان فإن طلبها صاحبها فجحدها إياه فهلكت ضمنها فإن عاد إلى الاعتراف لم يبرأ من الضمان"]]},{"id":"q70_6","label":"كتاب الوديعة · الفقرة ٦","segs":[["matn","وللمودع أن يسافر بالوديعة وإن كان لها حمل ومؤنة"]]},{"id":"q70_7","label":"كتاب الوديعة · الفقرة ٧","segs":[["matn","وإذا أودع رجلان عند رجل وديعة ثم حضر أحدهما فطلب نصيبه منها لم يدفع إليه شيئا حتى يحضر الآخر عند أبي حنيفة وقال أبو يوسف ومحمد: يدفع إليه نصيبه"]]},{"id":"q70_8","label":"كتاب الوديعة · الفقرة ٨","segs":[["matn","وإن أودع رجل عند رجلين شيئا مما يقسم لم يجز أن يدفعه أحدهما إلى الآخر ولكنهما يقتسمانه فيحفظ كل واحد منهما نصفه وإن كان مما لا يقسم جاز أن يحفظه أحدهما بإذن الآخر"]]},{"id":"q70_9","label":"كتاب الوديعة · الفقرة ٩","segs":[["matn","وإذا قال صاحب الوديعة للمودع: لا تسلمها إلى زوجتك فسلمها إليها لم يضمن"]]},{"id":"q70_10","label":"كتاب الوديعة · الفقرة ١٠","segs":[["matn","وإن قال له: احفظها في هذا البيت فحفظها في بيت آخر من الدار لم يضمن فإن"]]},{"id":"q70_11","label":"كتاب الوديعة · الفقرة ١١","segs":[["matn","حفظهما في دار أخرى ضمن"]]}]},{"id":"q71","title":"كتاب العارية","group":"كتاب العارية","units":[{"id":"q71_1","label":"كتاب العارية · الفقرة ١","segs":[["matn","العارية: جائزة وهي: تمليك المنافع بغير عوض وتصح بقوله: أعرتك وأطعمتك هذه الأرض ومنحتك هذا الثوب وحملتك على هذه الدابة إذا لم يرد به الهبة وأخدمتك هذا العبد"]]},{"id":"q71_2","label":"كتاب العارية · الفقرة ٢","segs":[["matn","وداري لك سكنى وداري لك عمرى سكنى"]]},{"id":"q71_3","label":"كتاب العارية · الفقرة ٣","segs":[["matn","وللمعير أن يرجع في العارية متى شاء"]]},{"id":"q71_4","label":"كتاب العارية · الفقرة ٤","segs":[["matn","والعارية أمانة: إن هلكت من غير تعد لم يضمن شيئا"]]},{"id":"q71_5","label":"كتاب العارية · الفقرة ٥","segs":[["matn","وليس للمستعير أن يؤاجر ما استعاره ولا أن يرهنه وله أن يعيره إذا كان مما لا يختلف باختلاف المستعمل"]]},{"id":"q71_6","label":"كتاب العارية · الفقرة ٦","segs":[["matn","وعارية الدراهم والدنانير والمكيل والموزون قرض"]]},{"id":"q71_7","label":"كتاب العارية · الفقرة ٧","segs":[["matn","وإذا استعار أرضا ليبني فيها أو يغرس نخلا جاز وللمعير أن يرجع فيها ويكلفه قلع البناء والغرس فإن لم يكن وقت العارية فلا ضمان عليه وإن كان وقت العارية فرجع قبل الوقت ضمن المعير ما نقض البناء والغرس بالقلع"]]},{"id":"q71_8","label":"كتاب العارية · الفقرة ٨","segs":[["matn","وأجرة رد العارية على المستعمر وأجرة رد العين المستأجرة على المؤجر وأجرة المغصوبة على الغاصب"]]},{"id":"q71_9","label":"كتاب العارية · الفقرة ٩","segs":[["matn","وإذا استعار دابة فردها إلى دار مالكها ولم يسلمها إليه ضمن وإن رد الوديعة إلى درا المالك ولم يسلمها إليه ضمن"]]}]},{"id":"q72","title":"كتاب اللقيط","group":"كتاب اللقيط","units":[{"id":"q72_1","label":"كتاب اللقيط · الفقرة ١","segs":[["matn","اللقيط: حر مسلم ونفقته من بيت المال"]]},{"id":"q72_2","label":"كتاب اللقيط · الفقرة ٢","segs":[["matn","فإن التقطه رجل لم يكن لغيره أن يأخذه من يده فإن ادعى مدع أنه ابنه فالقول قوله وإن ادعاه اثنان ووصف أحدهما علامة في جسده فهو أولى به"]]},{"id":"q72_3","label":"كتاب اللقيط · الفقرة ٣","segs":[["matn","وإذا وجد في مصر من أمصار المسلمين أو في قرية من قراهم فادعى ذمي أنه ابنه ثبث نسبه منه وكان مسلما وإن وجد في قرية من قرى أهل الذمة أو في بيعة أو كنيسة كان ذميا"]]},{"id":"q72_4","label":"كتاب اللقيط · الفقرة ٤","segs":[["matn","ومن ادعى أن اللقيط عبده لم يقبل منه فإن ادعى عبد أنه ابنه ثبت نسبه منه وكان حرا"]]},{"id":"q72_5","label":"كتاب اللقيط · الفقرة ٥","segs":[["matn","وإن وجد مع اللقيط مال مشدود عليه فهو له ولا يجوز تزويج الملتقط ولا تصرفه في مال اللقيط"]]},{"id":"q72_6","label":"كتاب اللقيط · الفقرة ٦","segs":[["matn","ويجوز أن يقبض له الهبة ويسلمه في صناعة ويؤاجره"]]}]},{"id":"q73","title":"باب اللقطة","group":"كتاب اللقيط","units":[{"id":"q73_1","label":"باب اللقطة · الفقرة ١","segs":[["matn","اللقطة: أمانة إذا أشهد الملتقط أنه يأخذها ليحفظها ويردها على صاحبها فإن كانت أقل من عشرة دراهم عرفها أياما وإن كانت عشرة فصاعدا عرفها حولا"]]},{"id":"q73_2","label":"باب اللقطة · الفقرة ٢","segs":[["matn","فإن جاء صاحبها وإلا تصدق بها فإن جاء صاحبها فهو بالخيار: إن شاء أمضى الصدقة وإن شاء ضمن الملتقط"]]},{"id":"q73_3","label":"باب اللقطة · الفقرة ٣","segs":[["matn","ويجوز الالتقاط في الشاة والبقرة والبعير"]]},{"id":"q73_4","label":"باب اللقطة · الفقرة ٤","segs":[["matn","فإن أنفق الملتقط عليها بغير إذن الحاكم فهو متبرع وإن أنفق بأمره كان ذلك دينا على مالكها"]]},{"id":"q73_5","label":"باب اللقطة · الفقرة ٥","segs":[["matn","وإذا رفع ذلك إلى الحاكم نظر فيه فإن كان للبهيمة منفعة أجرها وأنفق عليها من أجرتها وإن لم يكن لها منفعة وخاف أن تستغرق النفقة قيمتها باعها وأمره بحفظ ثمنها وإن كان الأصلح الإنفاق عليها أذن له في ذلك وجعل النفقة دينا على مالكها"]]},{"id":"q73_6","label":"باب اللقطة · الفقرة ٦","segs":[["matn","فإذا حضر مالكها فللملتقط أن يمنعه منها حتى يأخذ النفقة"]]},{"id":"q73_7","label":"باب اللقطة · الفقرة ٧","segs":[["matn","ولقطه الحل والحرم سواء"]]},{"id":"q73_8","label":"باب اللقطة · الفقرة ٨","segs":[["matn","وإذا حضر الرجل فادعى"]]},{"id":"q73_9","label":"باب اللقطة · الفقرة ٩","segs":[["matn","أن اللقطة له لم تدفع إليه حتى يقم البينة فإن أعطى علامتها حل للملتقط أن يدفعها إليه ولا يجبر على ذلك في القضاء"]]},{"id":"q73_10","label":"باب اللقطة · الفقرة ١٠","segs":[["matn","ولا يتصدق باللقطة على غني وإن كان الملتقط غنيا لم يجز له أن ينتفع بها وإن كان فقيرا فلا بأس أن ينتفع بها ويجوز أن يتصدق بها إذا كان غنيا على أبيه وابنه وزوجته إذا كانوا فقراء والله أعلم"]]}]},{"id":"q74","title":"كتاب الخنثى","group":"كتاب الخنثى","units":[{"id":"q74_1","label":"كتاب الخنثى · الفقرة ١","segs":[["matn","إذا كان للمولود فرج وذكر فهو خنثى فإن كان يبول من الذكر فهو غلام وإن كان يبول من الفرج فهو أنثى وإن كان يبول منهما والبول يسبق من أحدهما نسب إلى الأسبق فإن كانا في السبق سواء فلا عبرة بالكثرة عند أبي حنيفة وقال أبو يوسف ومحمد: ينسب إلى أكثرهماز"]]},{"id":"q74_2","label":"كتاب الخنثى · الفقرة ٢","segs":[["matn","وإذا بلغ الخنثى وخرجت له لحية أو وصل إلى النساء فهو رجل وإن ظهر له ثدي كثدي المرأة أو نزل له لبن في ثديه أو حاض أو حبل أو أمكن الوصول إليه من الفرج فهو امرأة فإن لم تظهر إحدى هذه العلامات فهو خنثى مشكل"]]},{"id":"q74_3","label":"كتاب الخنثى · الفقرة ٣","segs":[["matn","وإذا وقف خلف الإمام قام بين صف الرجال والنساء وتبتاع له أمة تختنه إن كان له مال فإن لم يكن له مال ابتاع له الإمام من بيت المال فإذا ختنته باعها ورد ثمنها إلى بيت المال"]]},{"id":"q74_4","label":"كتاب الخنثى · الفقرة ٤","segs":[["matn","وإذا مات أبوه وخلف ابنا وخنثى فالمال بينهما عند أبي حنيفة على ثلاثة أسهم: للابن سهمان وللخنثى سهم وهو أنثى عنده في الميراث إلا أن يثبت غير ذلك فيتبع"]]},{"id":"q74_5","label":"كتاب الخنثى · الفقرة ٥","segs":[["matn","وقال أبو يوسف ومحمد: للخنثى نصف ميراث الذكر ونصف ميراث الأنثى وهو قول الشعبي واختلفا في قياس قوله قال أبو يوسف: المال بينهما على سبعة أسهم: للابن أربعة وللخنثى ثلاثة وقال محمد: المال بينهما على اثني عشر منهما: للابن سبعة وللخنثى خمسة"]]}]},{"id":"q75","title":"كتاب المفقود","group":"كتاب المفقود","units":[{"id":"q75_1","label":"كتاب المفقود · الفقرة ١","segs":[["matn","إذا غاب الرجل ولم يعرف له موضع ولا يعلم أحي هو أم ميت نصب القاضي من يحفظ ماله ويقوم عليه ويستوفي حقوقه وينفق على زوجته وأولاده من ماله"]]},{"id":"q75_2","label":"كتاب المفقود · الفقرة ٢","segs":[["matn","ولا يفرق بينه وبين امرأته"]]},{"id":"q75_3","label":"كتاب المفقود · الفقرة ٣","segs":[["matn","فإذا تم له مائة وعشرون سنة من يوم ولد حكمنا بموته واعتدت امرأته وقسم ماله بين ورثته الموجودين في ذلك الوقت ومن مات منهم قبل ذلك لم يرث منه ولا يرث المفقود من أحد مات في حال فقده"]]}]},{"id":"q76","title":"كتاب الإباق","group":"كتاب الإباق","units":[{"id":"q76_1","label":"كتاب الإباق · الفقرة ١","segs":[["matn","إذا أبق مملوك فرده رجل على مولاه من مسيرة ثلاثة أيام فصاعدا فله عليه الجعل أربعون درهما وإن رده لأقل من ذلك فبحسابه وإن كانت قيمته أقل من أربعين درهما قضي له بقيمته إلا درهما وإن أبق من الذي رده فلا شيء عليه وينبغي أن يشهد إذا أخذه أنه يأخذه ليرده فإن كان العبد الآبق رهنا فالجعل على المرتهن"]]}]},{"id":"q77","title":"كتاب إحياء الموات","group":"كتاب إحياء الموات","units":[{"id":"q77_1","label":"كتاب إحياء الموات · الفقرة ١","segs":[["matn","الموات: ما لا ينتفع به من الأرض لانقطاع الماء عنه أو لغلبه الماء عليه أو ما أشبه ذلك مما يمنع الزراعة فما كان منها عاديا لا مالك له أو كان مملوكا في الإسلام لا يعرف له مالك بعينه وهو بعيد من القرية بحيث إذا وقف إنسان"]]},{"id":"q77_2","label":"كتاب إحياء الموات · الفقرة ٢","segs":[["matn","في أقصى العامر فصاح لم يسمع الصوت فيه فهو موات"]]},{"id":"q77_3","label":"كتاب إحياء الموات · الفقرة ٣","segs":[["matn","من أحياه بإذن الإمام ملكه وإن أحياه بغير إذنه لم يملكه عند أبي حنيفة وقال أبو يوسف ومحمد: يملكه"]]},{"id":"q77_4","label":"كتاب إحياء الموات · الفقرة ٤","segs":[["matn","ويملك الذمي بالإحياء كما يملك المسلم"]]},{"id":"q77_5","label":"كتاب إحياء الموات · الفقرة ٥","segs":[["matn","ومن حجر أرضا ولم يعمرها ثلاث سنين أخذها الإمام ودفعها إلى غيره"]]},{"id":"q77_6","label":"كتاب إحياء الموات · الفقرة ٦","segs":[["matn","ولا يجوز إحياء ما قرب من العامر ويترك مرعى لأهل القرية ومطرحا لحصائدهم"]]},{"id":"q77_7","label":"كتاب إحياء الموات · الفقرة ٧","segs":[["matn","ومن حفر بئرا في برية فله حريمها فإن كانت البئر للعطن فحريمها أربعون ذراعا وإن كانت للناضح فستون ذراعا وإن كانت عينا فحريمها ثلاثمائة ذراع"]]},{"id":"q77_8","label":"كتاب إحياء الموات · الفقرة ٨","segs":[["matn","ومن أراد أن يحفر في حريمها منع منه"]]},{"id":"q77_9","label":"كتاب إحياء الموات · الفقرة ٩","segs":[["matn","وما ترك الفرات أو الدجلة وعدل عنه فإن كان يجوز عوده إليه لم يجز إحياؤه وإن كان لا يجوز أن يعود إليه فهو كالموات إذا لم يكن حريما لعامر يملكه من أحياه بإذن الإمام عند الإمام"]]},{"id":"q77_10","label":"كتاب إحياء الموات · الفقرة ١٠","segs":[["matn","ومن كان له نهر في أرض غيره فليس له حريمه عند أبي حنيفة إلا أن يقيم بينة على ذلك وقال أبو يوسف ومحمد: له مسناة يمشي عليها ويلقي عليها طينه"]]}]},{"id":"q78","title":"كتاب المأذون","group":"كتاب المأذون","units":[{"id":"q78_1","label":"كتاب المأذون · الفقرة ١","segs":[["matn","إذا أذن المولى لعبده في التجارة إذنا عاما جاز تصرفه في سائر التجارات: يشتري ويبيع ويرهن ويسترهن"]]},{"id":"q78_2","label":"كتاب المأذون · الفقرة ٢","segs":[["matn","وإن أذن له في نوع منها دون غيره فهو مأذون في جمعيها"]]},{"id":"q78_3","label":"كتاب المأذون · الفقرة ٣","segs":[["matn","وإن أذن له في شيء بعينه فليس بمأذون"]]},{"id":"q78_4","label":"كتاب المأذون · الفقرة ٤","segs":[["matn","وإقرار المأذون بالديون والغصوب جائز وليس له أن يتزوج ولا أن يزوج مماليكه ولا يكاتب ولا يعتق على مال ولا يهب بعوض ولا بغير عوض إلا أن يهدي اليسير من الطعام أو يضيف من يطعمه"]]},{"id":"q78_5","label":"كتاب المأذون · الفقرة ٥","segs":[["matn","وديونه متعلقة برقبته: يباع للغرماء إلا أن يفديه المولى ويقسم ثمنه بينهم بالحصص فإن فضل من ديونه شيء طولب به بعد الحرية"]]},{"id":"q78_6","label":"كتاب المأذون · الفقرة ٦","segs":[["matn","وإن حجر عليه لم يصر محجورا عليه حتى يظهر الحجر بين أهل سوقه فإن مات المولى أو جن أو لحق بدار الحرب مرتدا صار المأذون محجورا عليه"]]},{"id":"q78_7","label":"كتاب المأذون · الفقرة ٧","segs":[["matn","وإن أبق العبد صار محجورا عليه"]]},{"id":"q78_8","label":"كتاب المأذون · الفقرة ٨","segs":[["matn","وإذا حجر عليه فإقراره جائز فيما في يده من المال عند أبي حنيفة"]]},{"id":"q78_9","label":"كتاب المأذون · الفقرة ٩","segs":[["matn","وإن لزمته ديون تحيط بماله ورقبته لم يملك المولى ما في يده فإن أعتق عبيده لم يعتقوا عند أبي حنيفة وقال أبو يوسف ومحمد: يملك ما في يده"]]},{"id":"q78_10","label":"كتاب المأذون · الفقرة ١٠","segs":[["matn","وإذا باع من المولى شيئا بمثل قيمته جاز فإن باعه بنقصان لم يجز فإن باعه المولى شيئا بمثل القيمة جاز البيع فإن سلمه إليه قبل قبض الثمن بطل الثمن وإن أمسكه في يده حتى يستوفي"]]},{"id":"q78_11","label":"كتاب المأذون · الفقرة ١١","segs":[["matn","الثمن جاز وإن أعتق المولى المأذون وعليه ديون فعتقه جائز والمولى ضامن لقيمته للغرماء وما بقي من الديون يطالب به المعتق وإذا ولدت المأذونة من مولاها فذلك حجر عليها"]]},{"id":"q78_12","label":"كتاب المأذون · الفقرة ١٢","segs":[["matn","وإن أذن ولي الصبي في التجارة فهو في الشراء والبيع كالعبد المأذون إذا كان يعقل البيع والشراء"]]}]},{"id":"q79","title":"كتاب المزارعة","group":"كتاب المزارعة","units":[{"id":"q79_1","label":"كتاب المزارعة · الفقرة ١","segs":[["matn","قال أبو حنيفة رحمه الله: المزارعة بالثلث والربع باطلة وقال أبو يوسف ومحمد: جائزة"]]},{"id":"q79_2","label":"كتاب المزارعة · الفقرة ٢","segs":[["matn","وهي عندهما على أربعة أوجه: إذا كانت الأرض والبذر لواحد والعمل والبقر لواحد جازت المزارعة"]]},{"id":"q79_3","label":"كتاب المزارعة · الفقرة ٣","segs":[["matn","وإن كانت الأرض لواحد والعمل والبقر والبذر لآخر جازت"]]},{"id":"q79_4","label":"كتاب المزارعة · الفقرة ٤","segs":[["matn","وإن كانت الأرض والبقر والبذر لواحد والعمل لآخر جازت"]]},{"id":"q79_5","label":"كتاب المزارعة · الفقرة ٥","segs":[["matn","وإن كانت الأرض والبقر لواحد والبذر والعمل لآخر فهي باطلة"]]},{"id":"q79_6","label":"كتاب المزارعة · الفقرة ٦","segs":[["matn","ولا تصح المزارعة إلا على مدة معلومة"]]},{"id":"q79_7","label":"كتاب المزارعة · الفقرة ٧","segs":[["matn","ومن شرائطها: أن يكون الخارج مشاعا بينهما فإن شرطا لأحدهما قفزانا مسماة فهي باطلة وكذلك إن شرطا ما على الماذيانات والسواقي"]]},{"id":"q79_8","label":"كتاب المزارعة · الفقرة ٨","segs":[["matn","وإذا صحت المزارعة فالخارج بينهما على الشرط فإن لم تخرج الأرض شيئا فلا شيء للعامل"]]},{"id":"q79_9","label":"كتاب المزارعة · الفقرة ٩","segs":[["matn","وإذا فسدت المزارعة فالخارج لصاحب البذر فإن كان البذر من قبل رب الأرض فللعامل أجر مثله لا يزاد على مقدار ما شرط له من الخارج وإن كان البذر من قبل العامل فلصاحب الأرض أجر مثلها"]]},{"id":"q79_10","label":"كتاب المزارعة · الفقرة ١٠","segs":[["matn","وإذا عقدت المزارعة فامتنع صاحب البدر من العمل لم يجبر عليه وإن امتنع الذي ليس من قبله البذر أجبره الحاكم على العمل"]]},{"id":"q79_11","label":"كتاب المزارعة · الفقرة ١١","segs":[["matn","وإذا مات أحد المتعاقدين بطلت المزارعة وإذا"]]},{"id":"q79_12","label":"كتاب المزارعة · الفقرة ١٢","segs":[["matn","انقضت مدة المزارعة والزرع لم يدرك كان على المزارع أجر مثل نصيبه من الأرض إلى أن يستحصد والنفقة على الزرع عليهما على مقدار حقوقهما وأجره الحصاد والرفاع والدياس والتذرية عليهما بالحصص فإن شرطاه في المزارعة على العامل فسدت"]]},{"id":"q79_13","label":"كتاب المزارعة · الفقرة ١٣","segs":[["matn","باب المساقاة قال أبو حنيفة: المسافاة بجزء من الثمرة باطلة وقال أبو يوسف ومحمد: جائزة إذا ذكرا مدة معلومة وسميا جزاءا من الثمرة مشاعا"]]},{"id":"q79_14","label":"كتاب المزارعة · الفقرة ١٤","segs":[["matn","وتجوز المساقاة في النخل والشجر والكرم والرطاب وأصول"]]},{"id":"q79_15","label":"كتاب المزارعة · الفقرة ١٥","segs":[["matn","الباذنجان فإن دفع نخلا فيه ثمره مساقاة والثمرة تزيد بالعمل جاز وإن كانت قد انتهت لم يجز"]]},{"id":"q79_16","label":"كتاب المزارعة · الفقرة ١٦","segs":[["matn","وإذا فسدت المساقاة فللعامل أجر مثله وتبطل المساقاة بالموت وتفسخ بالإعذار كما تفسخ الإجارة"]]}]},{"id":"q80","title":"كتاب النكاح","group":"كتاب النكاح","units":[{"id":"q80_1","label":"كتاب النكاح · الفقرة ١","segs":[["matn","النكاح ينعقد بالإيجاب والقبول بلفظين يعبر بهما عن الماضي أو يعبر بأحدهما عن الماضي وبالآخر عن المستقبل مثل أن يقول: زوجتي فيقول زوجتك"]]},{"id":"q80_2","label":"كتاب النكاح · الفقرة ٢","segs":[["matn","ولا يعقد نكاح المسلمين إلا بحضور شاهدين حرين بالغين عاقلين مسلمين أو رجل"]]},{"id":"q80_3","label":"كتاب النكاح · الفقرة ٣","segs":[["matn","وامرأتين عدولا كانوا غيرا عدول أو محدودين في قذف فإن تزوج مسلم ذمية بشهادة ذميين جاز عند أبي حنيفة وأبي يوسف وقال محمد: لا يجوز"]]},{"id":"q80_4","label":"كتاب النكاح · الفقرة ٤","segs":[["matn","ولا يحل للرجل أن يتزوج بأمه ولا بجداته من قبل الرجال والنساء ولا ببنته ولا ببنت ولده وإن سفلت ولا بأخته ولا ببنات أخته ولا ببنات أخيه ولا بعمته وال بخالته ولا بأم دخل بابنتها أو لم يدخل ولا ببنت امرأته التي دخل بها سواء كانت في حجره أو في حجر غيره ولا بامرأة أبيه وأجداده ولا بامرأة ابنه وبني أولاده ولا بأمه من الرضاعة ولا بأخيه من الرضاعة"]]},{"id":"q80_5","label":"كتاب النكاح · الفقرة ٥","segs":[["matn","ولا يجمع بين أختين بنكاح ولا بملك يمين وطئا ولا يجمع بين المرأة وبين عمتها وخالتها ولا ابنة أخيها ولا ابنة أختها ولا يجمع بين امرأتين لو كانت كل واحدة منهما رجلا لم يجز له أن يتزوج بالأخرى ولا بأس أن يجمع بين امرأة وابنة زوج كان لها من قبل"]]},{"id":"q80_6","label":"كتاب النكاح · الفقرة ٦","segs":[["matn","ومن زنى بامرأة حرمت عليه أمها وابنتها"]]},{"id":"q80_7","label":"كتاب النكاح · الفقرة ٧","segs":[["matn","وإذا طلق الجل امرأته طلاقا بائنا لم يجز له أن يتزوج بأختها حتى تنقضي عدتها"]]},{"id":"q80_8","label":"كتاب النكاح · الفقرة ٨","segs":[["matn","ولا يجوز أن يتزوج المولى أمته ولا المرأة عبدها"]]},{"id":"q80_9","label":"كتاب النكاح · الفقرة ٩","segs":[["matn","ويجوز تزوج الكتابيات ولا يجوز تزوج المجوسيات ولا الوثنيات ويجوز تزوج الصابئيات إذا"]]},{"id":"q80_10","label":"كتاب النكاح · الفقرة ١٠","segs":[["matn","كانوا يؤمنون بنبي ويقرون بكتاب وإن كانوا يعبدون الكواكب ولا كتاب لهم لم تجز مناكحتهم"]]},{"id":"q80_11","label":"كتاب النكاح · الفقرة ١١","segs":[["matn","ويجوز للمحرم والمحرمة أن يتزوجا في حال الإحرام"]]},{"id":"q80_12","label":"كتاب النكاح · الفقرة ١٢","segs":[["matn","وينعقد نكاح المرأة الحرة البالغة العاقلة برضاها وإن لم يعقد عليها ولي عند أبي حنيفة بكر كانت أو ثيبا وقال أبو يوسف ومحمد: لا ينعقد إلا بولي"]]},{"id":"q80_13","label":"كتاب النكاح · الفقرة ١٣","segs":[["matn","ولا يجوز للولي إجبار البكر البالغة على النكاح وإذا استأذنها فسكتت أو ضحكت أو بكت فذلك إذن منها وإن أبت لم يزوجها وإذا استأذن الثيب فلا بد من رضاها بالقول وإذا زالت بكارتها بوثبة أو حيضة أو جراح فهي في حكم الأبكار وإن زالت بزنا فهي كذلك عند أبي حنيفة"]]},{"id":"q80_14","label":"كتاب النكاح · الفقرة ١٤","segs":[["matn","وإذا قال الزوج: بلغك النكاح فسكت وقال: بل رددت فالقول قولها ولا يمين عليها ولا يستحلف في النكاح عند أبي حنيفة وقال أبو يوسف ومحمد: يستحلف فيه"]]},{"id":"q80_15","label":"كتاب النكاح · الفقرة ١٥","segs":[["matn","وينعقد النكاح بلفظ النكاح والتزويج والتمليك والهبة والصدقة ولا ينعقد بلفظ الإجارة والإباحة"]]},{"id":"q80_16","label":"كتاب النكاح · الفقرة ١٦","segs":[["matn","ويجوز نكاح الصغير إذا زوجهما الولي بكرا كانت الصغيرة أو ثيبا والولي هو العصبة فإن زوجهما الأب أو الجد فلا خيار لهما بعد بلوغهما وإن زوجهما غير الأب والجد فلكل"]]},{"id":"q80_17","label":"كتاب النكاح · الفقرة ١٧","segs":[["matn","واحد منهما الخيار إذا بلغ إن شاء أقام على النكاح وإن شاء فسخ"]]},{"id":"q80_18","label":"كتاب النكاح · الفقرة ١٨","segs":[["matn","ولا ولاية لعبد ولا صغير ولا مجنون ولا كافر على مسلمة"]]},{"id":"q80_19","label":"كتاب النكاح · الفقرة ١٩","segs":[["matn","وقال أبو حنيفة: يجوز لغير العصبات من الأقارب التزويج"]]},{"id":"q80_20","label":"كتاب النكاح · الفقرة ٢٠","segs":[["matn","ومن لا ولي لها إذا زوجها مولاها الذي أعتقها جاز وإذا غاب الولي الأقرب غيبة جاز لمن هو أبعد منه أن يزوج"]]},{"id":"q80_21","label":"كتاب النكاح · الفقرة ٢١","segs":[["matn","والغيبة المنقطعة: أن يكون في بلد لا تصل إليه القوافل في السنة إلا مرة واحدة"]]},{"id":"q80_22","label":"كتاب النكاح · الفقرة ٢٢","segs":[["matn","والكفاءة في النكاح معتبرة فإذا تزوجت المرأة غير كفء فللأولياء أن يفرقوا بينهما"]]},{"id":"q80_23","label":"كتاب النكاح · الفقرة ٢٣","segs":[["matn","والكفاءة تعتبر في النسب"]]},{"id":"q80_24","label":"كتاب النكاح · الفقرة ٢٤","segs":[["matn","والدين والمال وهو: أن يكون مالكا للمهر والنفقة وتعتبر في الصنائع وإذا تزوجت المرأة ونقصت من مهرها فللأولياء الاعتراض عليها عند أبي حنيفة حتى يتم لها مهر مثلها أو يفارقها"]]},{"id":"q80_25","label":"كتاب النكاح · الفقرة ٢٥","segs":[["matn","وإذا تزوج الأب ابنيه الصغيرة ونقص من مهرها أو ابنه الصغير وزاد في مهر جاز ذلك عليهما"]]},{"id":"q80_26","label":"كتاب النكاح · الفقرة ٢٦","segs":[["matn","ولا يجوز ذلك لغير الأب والجد"]]},{"id":"q80_27","label":"كتاب النكاح · الفقرة ٢٧","segs":[["matn","ويصح النكاح إذا سمى فيه مهرا ويصح وإن لم يسم فيه مهرا"]]},{"id":"q80_28","label":"كتاب النكاح · الفقرة ٢٨","segs":[["matn","وأقل المهر عشرة دراهم فإن سمى أقل من عشرة فلها العشرة ومن سمى مهرا عشرة فما زاد فعليه المسمى إن دخل بها أو مات عنها وإن طلقها قبل الدخول والخلوة فلها نصف المسمى"]]},{"id":"q80_29","label":"كتاب النكاح · الفقرة ٢٩","segs":[["matn","وإن تزوجها ولم يسم لها مهرا أو تزوجها على أن لا مهر لها فلها مهر مثلها إن دخل بها أو مات عنها"]]},{"id":"q80_30","label":"كتاب النكاح · الفقرة ٣٠","segs":[["matn","وإن طلقها قبل الدخول فلها المتعة وهي ثلاثة أثواب من كسوة مثلها"]]},{"id":"q80_31","label":"كتاب النكاح · الفقرة ٣١","segs":[["matn","وإن تزوج المسلم على خمر أو خنزير فالنكاح جائز ولها مهر مثلها"]]},{"id":"q80_32","label":"كتاب النكاح · الفقرة ٣٢","segs":[["matn","وإن تزوجها ولم يسلم لها مهرا ثم تراضيا على تسمية مهر فهو لها إن دخل بها أو مات عنها وإن طلقها قبل الدخول لها المتعة"]]},{"id":"q80_33","label":"كتاب النكاح · الفقرة ٣٣","segs":[["matn","وإن زادها في المهر بعد العقد لزمته الزيادة وتسقط"]]},{"id":"q80_34","label":"كتاب النكاح · الفقرة ٣٤","segs":[["matn","بالطلاق قبل الدخول وإن حطت عنه من مهرها صح الحط وإذا خلا الزوج بامرأته ولي هناك مانع من الوطء ثم طلقها فلها كمال المهر وإن كان أحدهما مريضا أو صائما في رمضان أو محرما بفرض أو نفل بحج أو عمرة أو كانت حائضا فليست بخلوة صحيحة وإذا خلا المجبوب بامرأته ثم طلقها فلها كمال المهر عند أبي حنيفة"]]},{"id":"q80_35","label":"كتاب النكاح · الفقرة ٣٥","segs":[["matn","وتستحب المتعة لكل مطلقة إلا لمطلقة واحدة وهي: التي طلقها قبل الدخول ولم يسم لها مهرا"]]},{"id":"q80_36","label":"كتاب النكاح · الفقرة ٣٦","segs":[["matn","وإذا تزوج الرجل ابنته على أن يزوجه الرجل أخته أو ابنته ليكون أحد العقدين عوضا عن الآخر فالعقدان جائزان ولكل واحدة منهما مهر مثلها"]]},{"id":"q80_37","label":"كتاب النكاح · الفقرة ٣٧","segs":[["matn","وإن تزوج حر امرأة على خدمته سنة أو على تعليم القرآن فلها مهر مثلها وإن تزوج عبد حرة بإذن مولاه على خدمتها سنة جاز"]]},{"id":"q80_38","label":"كتاب النكاح · الفقرة ٣٨","segs":[["matn","وإذا اجمع في المجنونة أبوها وابنها فالولي"]]},{"id":"q80_39","label":"كتاب النكاح · الفقرة ٣٩","segs":[["matn","في نكاحها ابنها عند أبي حنيفة وأبي يوسف وقال محمد: أبوها"]]},{"id":"q80_40","label":"كتاب النكاح · الفقرة ٤٠","segs":[["matn","ولا يجوز نكاح العبد والأمة إلا بإذن مولاهما وإذا تزوج العبد بإذن مولاه فالمهر دين في رقبته يباع فيه وإذا زوج المولى أمته فليس عليه أن يبوئها بيت الزوج ولكنها تخدم المولى ويقال للزوج: متى ظفرت بها وطئتها"]]},{"id":"q80_41","label":"كتاب النكاح · الفقرة ٤١","segs":[["matn","وإذا تزوج امرأة على ألف درهم على أن لا يخرجها من البلد أو على أن لا يتزوج عليها فإن وفى بالشرط فلها المسمى وإن تزوج عليها أو أخرجها من البلد فلها مهر مثلها"]]},{"id":"q80_42","label":"كتاب النكاح · الفقرة ٤٢","segs":[["matn","وإذا تزوجها على حيوان غير موصوف"]]},{"id":"q80_43","label":"كتاب النكاح · الفقرة ٤٣","segs":[["matn","صحت التسمية ولها الوسط منه والزوج مخير: إن شاء أعطاها ذلك وإن شاء أعطاها قيمته"]]},{"id":"q80_44","label":"كتاب النكاح · الفقرة ٤٤","segs":[["matn","ولو تزوجها على ثوب غير موصوف فلها مهر مثلهاز"]]},{"id":"q80_45","label":"كتاب النكاح · الفقرة ٤٥","segs":[["matn","ونكاح المتعة والنكاح المؤقت"]]},{"id":"q80_46","label":"كتاب النكاح · الفقرة ٤٦","segs":[["matn","باطل وتزويج العبد والأمة بغير إذن مولاهما موقوف: فإن أجازه المولى جاز وإن رده بطل وكذلك لو زوج امرأة بغير رضاها أو رجلا بغير رضاه"]]},{"id":"q80_47","label":"كتاب النكاح · الفقرة ٤٧","segs":[["matn","ويجوز لابن العم أن يزوج بنت عمه من نفسه وإذا أذنت المرأة لرجل أن يزوجها من نفسه فقعد بحضرة شاهدين جاز"]]},{"id":"q80_48","label":"كتاب النكاح · الفقرة ٤٨","segs":[["matn","وإذا ضمن الولي المهر صح ضمانه وللمرأة الخيار في مطالبة زوجها أو وليها"]]},{"id":"q80_49","label":"كتاب النكاح · الفقرة ٤٩","segs":[["matn","وإذا فرق القاضي بين الزوجين في النكاح الفاسد قبل الدخول فلا مهر لها وكذلك بعد الخلوة وإن دخل بها فلها مهر مثلها لا يزاد على المسمى وعليها العدة ويثبت نسب ولدها"]]},{"id":"q80_50","label":"كتاب النكاح · الفقرة ٥٠","segs":[["matn","ومهر مثلها يعتبر بأخواتها وعماتها وبنا عمها ولا يعتبر بأمها وخالتها إذا لم يكونا من قبيلتها"]]},{"id":"q80_51","label":"كتاب النكاح · الفقرة ٥١","segs":[["matn","ويعتبر في مهر المثل: أن تتساوى المرأتان في السن والجمال والعفة والمال والعقل والدين والبلد والعصر"]]},{"id":"q80_52","label":"كتاب النكاح · الفقرة ٥٢","segs":[["matn","ويجوز تزويج الأمة مسلمة كانت أو كتابية ولا يجوز أن يتزوج أمة على حرة ويجوز الحرة عليها"]]},{"id":"q80_53","label":"كتاب النكاح · الفقرة ٥٣","segs":[["matn","وللحر أن يتزوج أربعا من الحرائر والإماء وليس له أن يتزوج أكثر من ذلك"]]},{"id":"q80_54","label":"كتاب النكاح · الفقرة ٥٤","segs":[["matn","ولا يتزوج العبد أكثر من اثنتين"]]},{"id":"q80_55","label":"كتاب النكاح · الفقرة ٥٥","segs":[["matn","فإن طلق الحر إحدى الأربع طلاقا بائنا لم يجز له"]]},{"id":"q80_56","label":"كتاب النكاح · الفقرة ٥٦","segs":[["matn","أن يتزوج رابعة حتى تنقضي عدتها"]]},{"id":"q80_57","label":"كتاب النكاح · الفقرة ٥٧","segs":[["matn","وإذا زوج الأمة مولاها ثم أعتقت فلها الخيار حرا كان زوجها أو عبدا وكذلك المكاتبة"]]},{"id":"q80_58","label":"كتاب النكاح · الفقرة ٥٨","segs":[["matn","وإن تزوجت أمه بغير إذن مولاها ثم أعتقت صح النكاح ولا خيار لها"]]},{"id":"q80_59","label":"كتاب النكاح · الفقرة ٥٩","segs":[["matn","ومن تزوج امرأتين في عقد واحد إحداهما لا يحل له نكاحها صح نكاح التي يحل له نكاحها وبطل نكاح الأخرى"]]},{"id":"q80_60","label":"كتاب النكاح · الفقرة ٦٠","segs":[["matn","وإن كان بالزوجة عيب فلا خيار لزوجها وإذا كان بالزوج جنون أو جذام أو برص فلا خيار للمرأة عند أبي حنيفة وأبي يوسف وقال محمد: لها الخيار فإن كان عنينا أجله الحاكم حولا فإن وصل إليها وإلا فرق بينهما إن طلبت المرأة ذلك"]]},{"id":"q80_61","label":"كتاب النكاح · الفقرة ٦١","segs":[["matn","والفرقة تطليقه بائنة ولها كمال المهر إن كان قد خلا بها وإن كان"]]},{"id":"q80_62","label":"كتاب النكاح · الفقرة ٦٢","segs":[["matn","مجنونا فرق القاضي بينهما في الحال ولم يؤجله والخصي يؤجل كما يؤجل العنين"]]},{"id":"q80_63","label":"كتاب النكاح · الفقرة ٦٣","segs":[["matn","وإذا سلمت المرأة وزوجها كافر عرض عليه القاضي الإسلام فإن أسلم فهي امرأته وإن أبى عن الإسلام فرق بينهما وكان ذلك طلاقا بائنا عند أبي حنيفة ومحمد: وقال أبو يوسف: هي فرقة بغير طلاق"]]},{"id":"q80_64","label":"كتاب النكاح · الفقرة ٦٤","segs":[["matn","فإن أسلم الزوج وتحته مجوسية عرض عليها الإسلام فإن أسلمت فهي امرأته وإن أبت فرق القاضي بينهما ولم تكن هذه الفرقة طلاقا فإن كان قد دخل لها فلها المهر وإن لم يكن دخل بها فلا مهر لها"]]},{"id":"q80_65","label":"كتاب النكاح · الفقرة ٦٥","segs":[["matn","وإذا أسلمت المرأة في دار الحرب لم تقع الفرقة عليها حتى"]]},{"id":"q80_66","label":"كتاب النكاح · الفقرة ٦٦","segs":[["matn","تحيض ثلاث حيض فإذا حاضت بانت من زوجها"]]},{"id":"q80_67","label":"كتاب النكاح · الفقرة ٦٧","segs":[["matn","وإذا أسلم زوج الكتابية فهما على نكاحهما"]]},{"id":"q80_68","label":"كتاب النكاح · الفقرة ٦٨","segs":[["matn","وإذا خرج أحد الزوجين إلينا من دار الحرب مسلما وقعت البينونة بينهما وإن سبي أحدهما البينونة بينهما وإن سبيا معا لم تقع البينونة وإذا خرجت المرأة إلينا مهاجرة جاز لها أن تتزوج ولا عدة عليها عند أبي حنيفة فإن كانت حاملا لم تتزوج حتى تضع حملها"]]},{"id":"q80_69","label":"كتاب النكاح · الفقرة ٦٩","segs":[["matn","وإذا أرتد أحد الزوجين عن الإسلام وقعت الفرقة بينهما بغير طلاق فإن كان الزوج هو المرتد وقد دخل بها فلها كمال المهر وإن كان لم يدخل بها"]]},{"id":"q80_70","label":"كتاب النكاح · الفقرة ٧٠","segs":[["matn","فلها نصف المهر وإن كانت المرأة هي المرتدة فإن كان قبل الدخول فلا مهر لها وإن كانت الردة بعد الدخول فلها المهر وإن ارتدا معا وأسلما فهما على نكاحهما"]]},{"id":"q80_71","label":"كتاب النكاح · الفقرة ٧١","segs":[["matn","ولا يجوز أن يتزوج المرتد مسلمة ولا كافرة ولا مرتدة وكذلك المرتدة لا يتزوجها مسلم ولا كافر ولا مرتد"]]},{"id":"q80_72","label":"كتاب النكاح · الفقرة ٧٢","segs":[["matn","وإذا كان أحد الزوجين مسلما فالولد على دينه وكذلك إن أسلم أحدهما وله ولد صغير صار"]]},{"id":"q80_73","label":"كتاب النكاح · الفقرة ٧٣","segs":[["matn","ولده مسلما بإسلامه وإن كان أحد الأبوين كتابيا والآخر مجوسيا فالولد كتابي"]]},{"id":"q80_74","label":"كتاب النكاح · الفقرة ٧٤","segs":[["matn","وإذا تزوج الكافر بغير شهود أو في عدة الكافر وذلك في دينهم جائ ثم أسلما أقرا عليه وإذا تزوج المجوسي أمه أو ابنته ثم أسلما فرق بينهما"]]},{"id":"q80_75","label":"كتاب النكاح · الفقرة ٧٥","segs":[["matn","وإذا كان للرجل امرأتان حرتان فعليه أن يعد بينهما في القسم بكرين كانتا أو ثيبتين أو إحداهما بكرا والأخرى ثيبا"]]},{"id":"q80_76","label":"كتاب النكاح · الفقرة ٧٦","segs":[["matn","وإن كانت إحداهما والأخرى أمة فللحرة الثلثان من القسم وللأمة الثلث"]]},{"id":"q80_77","label":"كتاب النكاح · الفقرة ٧٧","segs":[["matn","ولا حق لهن في القسم حالة السفر ويسافر الزوج بمن شاء منهن والأولى أن يفرغ بينهن فيسافر بمن خرجت قرعتها وإن رضيت الزوجات بترك قسمها لصاحبتها جاز ولها أن ترجع في ذلك"]]}]},{"id":"q81","title":"كتاب الرضاع","group":"كتاب الرضاع","units":[{"id":"q81_1","label":"كتاب الرضاع · الفقرة ١","segs":[["matn","قليل الرضاع وكثيره سواء إذا حصل في مدة الرضاع تعلق به التحريم"]]},{"id":"q81_2","label":"كتاب الرضاع · الفقرة ٢","segs":[["matn","ومدة الرضاع عند أبي حنيفة ثلاثون شهرا وقال أبو يوسف ومحمد: سنتان فإذا مضت مدة الرضاع لم يتعلق بالرضاع تحريم"]]},{"id":"q81_3","label":"كتاب الرضاع · الفقرة ٣","segs":[["matn","ويحرم من الرضاع ما يحرم من النسب إلا أم أخته من الرضاع فإنه يجوز أن يتزوجها ولا يجوز أن يتزوج أم أخته من النسب وأخت ابنه من الرضاع يجوز أن يتزوجها ولا يجوز أخت ابنه من النسب وامرأة ابنه من الرضاع لا يجوز أن يتزوجها كما لا يجوز أن يتزوج امرأة ابنه من النسب وامرأة أبيه من الرضاع لا يجوز أن يتزوجها كما لا يجوز أن يتزوج امرأة أبيه من النسب"]]},{"id":"q81_4","label":"كتاب الرضاع · الفقرة ٤","segs":[["matn","ولبن الفحل يتعلق به التحريم وهو: أن ترضع المرأة صبية فتحرم هذه الصبية على زوجها وعلى آبائه وأبنائه ويصير الزوج الذي نزل منه اللبن أبا للمرضعة"]]},{"id":"q81_5","label":"كتاب الرضاع · الفقرة ٥","segs":[["matn","ويجوز أن يتزوج الرجل بأخت أخيه من الرضاع كما يجوز أن يتزوج بأخت أخيه من النسب وذلك مثل الأخ من الأب إذا كان له أخت من أمه جاز لأخيه من أبيه أن يتزوجهل"]]},{"id":"q81_6","label":"كتاب الرضاع · الفقرة ٦","segs":[["matn","وكل صبيين اجتمعا على ثدي واحد لم يجز لأحدهما أن يتزوج بالآخر ولا يجوز أن تتزوج المرضعة أحدا من ولد التي أرضعتها ولا ولد ولدها ولا يتزوج الصبي المرضع أخت زوج المرضعة لأنها عمته من الرضاع"]]},{"id":"q81_7","label":"كتاب الرضاع · الفقرة ٧","segs":[["matn","وإذا اختلط اللبن بالماء واللبن هو الغالب تعلق به التحريم وإن غلب الماء لم يتعلق به التحريم وإذا اختلط بالطعام لم يتعلق به التحريم وإن كان اللبن غالبا عند أبي حنيفة وإذا اختلط بالدواء وهو الغالب تعلق به التحريم"]]},{"id":"q81_8","label":"كتاب الرضاع · الفقرة ٨","segs":[["matn","وإذا حلب اللبن من المرأة"]]},{"id":"q81_9","label":"كتاب الرضاع · الفقرة ٩","segs":[["matn","بعد موتها فأوجر به الصبي تعلق به التحريم وإذا اختلط اللبن بلبن شاة واللبن هو الغالب تعلق به التحريم وإن غلب لبن الشاة لم يتعلق به التحريم"]]},{"id":"q81_10","label":"كتاب الرضاع · الفقرة ١٠","segs":[["matn","وإذا اختلط لبن امرأتين تعلق التحريم بأكثرهما عند أبي حنيفة وأبي يوسف وقال محمد: يتعلق بهما"]]},{"id":"q81_11","label":"كتاب الرضاع · الفقرة ١١","segs":[["matn","وإذا نزل للبكر لبن فأرضعت به صبيا تعلق به التحريم وإذا نزل للرجل لبن فأرضع به صبيا لم يتعلق به التحريم"]]},{"id":"q81_12","label":"كتاب الرضاع · الفقرة ١٢","segs":[["matn","وإذا شرب صبيان من لبن شاو فلا رضاع بينهما"]]},{"id":"q81_13","label":"كتاب الرضاع · الفقرة ١٣","segs":[["matn","وإذا تزوج الرجل صغيرة وكبيرة فأرضعت الكبيرة الصغيرة حرمتا على الزوج"]]},{"id":"q81_14","label":"كتاب الرضاع · الفقرة ١٤","segs":[["matn","فإن كان لم يدخل بالكبيرة فلا مهر لها وللصغيرة نصف المهر ويرجع به الزوج على الكبيرة إن كانت تعمدت به الفساد"]]},{"id":"q81_15","label":"كتاب الرضاع · الفقرة ١٥","segs":[["matn","وإن لم تتعمد فلا شيء عليها"]]},{"id":"q81_16","label":"كتاب الرضاع · الفقرة ١٦","segs":[["matn","ولا تقبل في الرضاع شهادة النساء منفردات وإنما يثبت بشهادة رجلين أو رجل وامرأتين"]]}]},{"id":"q82","title":"كتاب الطلاق","group":"كتاب الطلاق","units":[{"id":"q82_1","label":"كتاب الطلاق · الفقرة ١","segs":[["matn","الطلاق على ثلاثة أوجه: أحسن الطلاق وطلاق السنة وطلاق البدعة"]]},{"id":"q82_2","label":"كتاب الطلاق · الفقرة ٢","segs":[["matn","فأحسن الطلاق: أن يطلق الرجل امرأته تطليقه واحدة في طهر لم يجامعها فيه ويتركها حتى تنقضي عدتها وطلاق السنة: أن يطلق المدخول بها ثلاثا في ثلاثة أطهار"]]},{"id":"q82_3","label":"كتاب الطلاق · الفقرة ٣","segs":[["matn","وطلاق البدعة: إن يطلقها ثلاثا بكلمة واحدة أو ثلاثا في طهر واحد فإذا فعل ذلك وقع الطلاق وبانت منه وكان عاصيا"]]},{"id":"q82_4","label":"كتاب الطلاق · الفقرة ٤","segs":[["matn","والسنة ي الطلاق من وجهين: سنة في العدد فالسنة في العدد يستوي فيها المدخول بها وغير المدخول بها والسنة في الوقت تثبت في المدخول بها خاصة وهو: أن يطلقها في طهر لم يجامعها فيه وغير المدخول بها يطلقها في حال الطهر والحيض وإذا كانت المرأة لا تحيض من صغر أو كبر فأراد أن يطلقها للسنة طلقها واحدة فإذا مضى شهر طلقها أخرى"]]},{"id":"q82_5","label":"كتاب الطلاق · الفقرة ٥","segs":[["matn","فإذا مضى شهر آخر طلقها آخرى ويجوز أن يطلقها ولا يفصل بين وطئها وطلاقها بزمان"]]},{"id":"q82_6","label":"كتاب الطلاق · الفقرة ٦","segs":[["matn","وطلاق الحامل يجوز عقيب الجماع ويطلقها للسنة ثلاثا يفصل بين كل تطليقتين بشهر"]]},{"id":"q82_7","label":"كتاب الطلاق · الفقرة ٧","segs":[["matn","عند أبي حنيفة وأبي يوسف وقال محمد: لا يطلقها للسنة إلا واحدة"]]},{"id":"q82_8","label":"كتاب الطلاق · الفقرة ٨","segs":[["matn","وإذا طلق الرجل امرأته في حال الحيض وقع الطلاق ويستحب له أن يراجعها وإن شاء أمسكها"]]},{"id":"q82_9","label":"كتاب الطلاق · الفقرة ٩","segs":[["matn","فإذا طهرت وحاضت وطهرت فهو مخير: إن شاء طلقها وإن شاء أمسكها"]]},{"id":"q82_10","label":"كتاب الطلاق · الفقرة ١٠","segs":[["matn","ويقع طلاق كل زوج إذا كان عاقلا بالغا ولا يقع طلاق الصبي والمجنون والنائم وإذا تزود العبد ثم طلق وقع طلاقه ولا يقع طلاق مولاه على امرأته"]]},{"id":"q82_11","label":"كتاب الطلاق · الفقرة ١١","segs":[["matn","والطلاق على ضربين: صريح وكناية فالصريح قوله: أنت طالق ومطلقه وطلقتك فهذا يقع به الطلاق الرجعي ولا يقع به إلا واحدة وإن نوى أكثر من ذلك ولا يفتقر إلى النية"]]},{"id":"q82_12","label":"كتاب الطلاق · الفقرة ١٢","segs":[["matn","وقوله: أنت الطلاق أو أنت طالق الطلاق أو أنت طالق طلاقا فإن لم تكن له نية فهي واحدة رجعية وإن نوى به ثلاثا كان ثلاثا"]]},{"id":"q82_13","label":"كتاب الطلاق · الفقرة ١٣","segs":[["matn","والضرب الثاني: والكنايات ولا يقع بها الطلاق إلا بينة أو دلاله حال وهي على ضربين منها ثلاثة ألفاظ بها الطلاق الرجعي ولا يقع بها إلا واحدة وهي قوله: اعتدي واستبرئي رحمك وأنت واحدة"]]},{"id":"q82_14","label":"كتاب الطلاق · الفقرة ١٤","segs":[["matn","وبقيه الكنايات إذا نوى بها الطلاق كانت واحدة بائنة"]]},{"id":"q82_15","label":"كتاب الطلاق · الفقرة ١٥","segs":[["matn","وإن نوى ثلاثا كانت وإن نوى اثنتين كانت واحدة مثل قوله: أنت بائن وبتة وبتلة وحرام وحبلك على غاربك والحقي بأهلك وخلية وبرية ووهبتك لأهلك وسرحتك وفارقتك وأنت حرة وتقنعي وتخمري واستتري واعزبي واغربي وابتغي الأزواج فإن لم يكن له نية لم يقع بهذه الألفاظ طلاق إلا أن يكونا في مذاكرة الطلاق فيقع بها الطلاق في القضاء ولايقع فيما بينه وبين الله تعالى إلا أن ينويه وإن لم يكونا في مذاكرة الطلاق وكانا في غضب أو خصومة وقع الطلاق"]]},{"id":"q82_16","label":"كتاب الطلاق · الفقرة ١٦","segs":[["matn","بكل لفظ لا يقصد به السب والشتيمة ولم يقع بما يقصد به السب والشتيمه إلا أن ينويه"]]},{"id":"q82_17","label":"كتاب الطلاق · الفقرة ١٧","segs":[["matn","وإذا وصف الطلاق بضرب من الزيادة والشدة كان بائنا مثل أن يقول: أنت طالق بائن أو طالق أشد الطلاق أو أفحش الطلاق أو طلاق الشيطان والبدعة وكالجبل وملء البيت"]]},{"id":"q82_18","label":"كتاب الطلاق · الفقرة ١٨","segs":[["matn","وإذا أضاف الطلاق إلى جملها أو إلى ما يعبر به عن الجملة وقع الطلاق"]]},{"id":"q82_19","label":"كتاب الطلاق · الفقرة ١٩","segs":[["matn","مثل أن يقول: أنت طالق أو رقبتلك طالق أو عنقك طالق أو روحك طالق أو بدنك أو جسدك أو فرجك أو وجهك"]]},{"id":"q82_20","label":"كتاب الطلاق · الفقرة ٢٠","segs":[["matn","وكذلك أن طلق جزءا شائعا منها مثل أن يقول: نصفك أو ثلثك"]]},{"id":"q82_21","label":"كتاب الطلاق · الفقرة ٢١","segs":[["matn","وإن قال: يدك أو رجلك طالق لم يقع الطلاق"]]},{"id":"q82_22","label":"كتاب الطلاق · الفقرة ٢٢","segs":[["matn","وإن طلقها نصف تطليقة أو ثلث تطليقة كانت طلقة واحدة"]]},{"id":"q82_23","label":"كتاب الطلاق · الفقرة ٢٣","segs":[["matn","وطلاق المكره والسكران واقع ويقع طلاق الأخرس بالإشارة"]]},{"id":"q82_24","label":"كتاب الطلاق · الفقرة ٢٤","segs":[["matn","وإذا أضاف الطلاق إلى النكاح وقع عقيب النكاح مثل أن يقول: إن تزوجتك فأنت طالق أو كل امرأة أتزوجها فهي طالق"]]},{"id":"q82_25","label":"كتاب الطلاق · الفقرة ٢٥","segs":[["matn","وإن أضافه إلى شرط وقع عقب الشرط مثل أن يقول لامرأته: إن دخلت الدار فأنت طالق"]]},{"id":"q82_26","label":"كتاب الطلاق · الفقرة ٢٦","segs":[["matn","ولا يصح إضافة الطالق إلا أن يكون الحالف مالكا أو يضيفه إلى ملك"]]},{"id":"q82_27","label":"كتاب الطلاق · الفقرة ٢٧","segs":[["matn","وإن قال لأجنبية: إن دخلت الدار فأنت طالق ثم تزوجها فدخلت الدار لم تطلق"]]},{"id":"q82_28","label":"كتاب الطلاق · الفقرة ٢٨","segs":[["matn","وألفاظ الشرط: إن وإذا وإذ ما وكل وكلما ومتى ومتى ما"]]},{"id":"q82_29","label":"كتاب الطلاق · الفقرة ٢٩","segs":[["matn","ففي كل هذه الشروط إذا وجد الشرط انحلت اليمين إلا في كلما فإن الطلاق يتكرر بتكرار الشرط حتى يقع ثلاث"]]},{"id":"q82_30","label":"كتاب الطلاق · الفقرة ٣٠","segs":[["matn","تطليقات فإن تزوجها بعد ذلك وتكرر الشرط لم يقع شيء وزوال الملك بعد اليمين لا يبطلها"]]},{"id":"q82_31","label":"كتاب الطلاق · الفقرة ٣١","segs":[["matn","فإن وجد في ملكه انحلت اليمين"]]},{"id":"q82_32","label":"كتاب الطلاق · الفقرة ٣٢","segs":[["matn","ووقع الطلاق وإن وجد في غير الملك انحلت اليمين ولم يقع شيء وإذا اختلفا في وجود الشرط فالقول قول الزوج فيه إلا أن تقيم البينة"]]},{"id":"q82_33","label":"كتاب الطلاق · الفقرة ٣٣","segs":[["matn","فإن كان الشرط لا يعلم إلا من وجهتها فالقول قولها في حق نفسها مثل أن يقول: إن حضت فأنت طالق فقالت: قد حضت طلقت وإذا قال: إذا حضت فأنت طالق وفلانة فقالت: قد حضت طلقت هي ولم تطلق فلانة وإذا قال لها: إذا حضت فأنت طالق فرأت الدم لم يقع الطلاق حتى يستمر ثلاثة أيام فإذا تمت ثلاثة أيام"]]},{"id":"q82_34","label":"كتاب الطلاق · الفقرة ٣٤","segs":[["matn","حكمنا بوقوع الطلاق من حين حاضت وإذا قال لها: إذا حضت حيضة فأنت طالق لم تطلق حتى تطهر من حيضها"]]},{"id":"q82_35","label":"كتاب الطلاق · الفقرة ٣٥","segs":[["matn","وطلاق الأمة تطليقتان حرل كان زوجها أو عبدا وطلاق الحرة ثلاث حرا كان زوجها أو عبدا"]]},{"id":"q82_36","label":"كتاب الطلاق · الفقرة ٣٦","segs":[["matn","وإذا طلق الرجل امرأته قبل الدخول بها ثلاثا وقعن عليها فإن فرق الطلاق بانت بالأولى ولم تقع الثانية وإذا قال لها: أنت طالق وواحدة وقعت عليها واحدة"]]},{"id":"q82_37","label":"كتاب الطلاق · الفقرة ٣٧","segs":[["matn","وإن قال لها أنت طالق واحدة وقعت واحدة وإن قال لها واحدة قبلها واحدة وقعت اثنتان"]]},{"id":"q82_38","label":"كتاب الطلاق · الفقرة ٣٨","segs":[["matn","وإن قال واحدة بعدها وقعت واحدة وإن قال واحدة بعد واحدة أو مع واحدة أو معها واحدة وقعت اثنتان"]]},{"id":"q82_39","label":"كتاب الطلاق · الفقرة ٣٩","segs":[["matn","وإذا قال لها: إن دخلت الدار فأنت طالق واحدة فدخلت الدار وقعت عليها واحدة عند أبي حنيفة وإذا قال لها أنت طالق بمكة فهي طالق في كل البلاد"]]},{"id":"q82_40","label":"كتاب الطلاق · الفقرة ٤٠","segs":[["matn","وكذلك إذا قال أنت طالق في الدار وإن قال لها أنت طالق إذا دخلت مكة لم تطلق حتى تدخل مكة وإن قال لها: أنت طالق غدا وقع الطلاق عليها بطلوع الفجر"]]},{"id":"q82_41","label":"كتاب الطلاق · الفقرة ٤١","segs":[["matn","وإذا قال لامرأته:: اختاري نفسك ينوي بذلك الطلاق أو قال لها: طلقي نفسك فلها أن تطلق نفسها ما دامت في مجلسها ذلك فإن قامت منه أو أخذت في عمل آخر خرج الأمر من يدها وإن اختارت نفسها في قوله: اختاري كانت"]]},{"id":"q82_42","label":"كتاب الطلاق · الفقرة ٤٢","segs":[["matn","واحدة بائنة ولا يكون ثلاثا وإن نوى الزوج ذلك"]]},{"id":"q82_43","label":"كتاب الطلاق · الفقرة ٤٣","segs":[["matn","ولا بد من ذكر النفس في كلامه أو في كلامها وإن طلقت نفسها في قوله: طلقي نفسك فهي واحدة رجعية وإن طلقت نفسها ثلاثا وقد أراد الزوج ذلك وقعن عليها وإن قال لها: طلقي نفسك متى شئت فلها أن تطلق نفسها في المجلس وبعده"]]},{"id":"q82_44","label":"كتاب الطلاق · الفقرة ٤٤","segs":[["matn","وإذا قال لرجل: طلق امرأتي فله أن يطلقها في المجلس وبعده وإن قال: طلقها إن شئت فله أن يطلقها في المجلس خاصة وإن قال لها: إن كنا تحبيني أو تبغضيني فأنت طالق فقالت: أنا أحبك أو أبغضك وقع الطلاق وإن كان في قلبها خلاف ما أظهرت"]]},{"id":"q82_45","label":"كتاب الطلاق · الفقرة ٤٥","segs":[["matn","وإذا طلق الرجل امرأته في مرض موته طلاقا بائنا وهي في العدة ورثت منه وإن مات بعد انقضاء عدتها فلا ميراث لها"]]},{"id":"q82_46","label":"كتاب الطلاق · الفقرة ٤٦","segs":[["matn","وإذا قال الزوج لامرأته: أنت طالق إن شاء الله متصلا لم يقع الطلاق عليها"]]},{"id":"q82_47","label":"كتاب الطلاق · الفقرة ٤٧","segs":[["matn","وإن قال: لها أنت طالق ثلاثا إلا واحدة طلقت اثنتين وإن قال: ثلاثا إلا اثنتين طلقت واحدة"]]},{"id":"q82_48","label":"كتاب الطلاق · الفقرة ٤٨","segs":[["matn","وإذا ملك الزوج امرأته أو شقصا منها أو ملكت المرأة زوجها أو شقصا منه وقعت الفرقة بينهما"]]}]},{"id":"q83","title":"باب الرجعة","group":"كتاب الطلاق","units":[{"id":"q83_1","label":"باب الرجعة · الفقرة ١","segs":[["matn","إذا طلق الرجل امرأته تطليقة رجعية أو تطليقتين فله أن يراجعها في عدتها رضيت بذلك أو لم ترض"]]},{"id":"q83_2","label":"باب الرجعة · الفقرة ٢","segs":[["matn","والرجعة أن يقول: راجعتك أو راجعت امرأتي"]]},{"id":"q83_3","label":"باب الرجعة · الفقرة ٣","segs":[["matn","أو يطأها أو يقبلها أو يلمسها شهوة أو ينظر إلى فرجها بشهوة"]]},{"id":"q83_4","label":"باب الرجعة · الفقرة ٤","segs":[["matn","ويستحب أن يشهد على الرجعة شاهدين فإن لم يشهد صحت الرجعة"]]},{"id":"q83_5","label":"باب الرجعة · الفقرة ٥","segs":[["matn","وإذا انقضت العدة فقال: قد كنت راجعتها في العدة فصدقته فهي رجعة وإن كذبته فالقول قولها ولا يمين عليها عند أبي حنيفة"]]},{"id":"q83_6","label":"باب الرجعة · الفقرة ٦","segs":[["matn","وإذا قال الزوج: قد راجعتك فقالت مجيبة له: قد انقضت عدتي لم تصح الرجعة عند أبي حنيفة"]]},{"id":"q83_7","label":"باب الرجعة · الفقرة ٧","segs":[["matn","وإذا قال زوج الأمة بعد انقضاء عدتها: قد كنت راجعتها في العدة فصدقه المولى وكذبته الأمة فالقول قولها"]]},{"id":"q83_8","label":"باب الرجعة · الفقرة ٨","segs":[["matn","وإذا انقطع الدم من الحيضة الثالثة لعشرة أيام انقطعت الرجعة وإن لم تغتسل وإن انقطع لأقل من عشرة أيام لم تنقطع الرجعة حتى تغتسل أو يمضي عليها وقت صلاة أو تتيمم وتصلي عند أبي حنيفة وأبي يوسف"]]},{"id":"q83_9","label":"باب الرجعة · الفقرة ٩","segs":[["matn","وقال محمد: إذا تيممت انقطعت الرجعة وإن لم تصل"]]},{"id":"q83_10","label":"باب الرجعة · الفقرة ١٠","segs":[["matn","وإن اغتسلت ونسيت شيئا من بدنها لم يصبه الماء فإن كان عضوا فما فوقه لم تنقطع الرجعة وإن كان أقل من عضو انقطعت"]]},{"id":"q83_11","label":"باب الرجعة · الفقرة ١١","segs":[["matn","والمطقة الرجعية تتشوف وتتزين ويستحب لزوجها أن لا يدخل عليها حتى يستأذنها أو يسمعها خفق نعليه"]]},{"id":"q83_12","label":"باب الرجعة · الفقرة ١٢","segs":[["matn","والطلاق الرجعي لا يحرم الوطء وإذا كان الطلاق بائنا دون الثلاث فله أن يتزوجها في عدتها وبعد انقضاء عدتها"]]},{"id":"q83_13","label":"باب الرجعة · الفقرة ١٣","segs":[["matn","وإن كان الطلاق ثلاثا في الحرة أو اثنتين في الأمة لم تحل له حتى تنكح زوجا غيره نكاحا صحيحا ويدخل بها ثم يطلقها أو يموت عنها"]]},{"id":"q83_14","label":"باب الرجعة · الفقرة ١٤","segs":[["matn","والصبي المراهق في التحليل كالبالغ"]]},{"id":"q83_15","label":"باب الرجعة · الفقرة ١٥","segs":[["matn","ووطء المولى أمته لا يحللها وإذا تزوجها بشرط التحليل فالنكاح مكروه فإن طلقها بعد وطئها حلت للأول"]]},{"id":"q83_16","label":"باب الرجعة · الفقرة ١٦","segs":[["matn","وإذا طلق الرجل الحرة تطليقه أو تطليقتين وانقضت عدتها وتزوجت بزوج آخر ثم عادت إلى الأول عادت بثلاث تطليقات ويهدم الزوج الثاني ما دون الثلاث من الطلاق كما يهدم الثلاث"]]},{"id":"q83_17","label":"باب الرجعة · الفقرة ١٧","segs":[["matn","وقال محمد: لا يهدم ما دون الثلاث"]]},{"id":"q83_18","label":"باب الرجعة · الفقرة ١٨","segs":[["matn","وإذا طلقها ثلاثا فقالت: قد انقضت عدتي وتزوجت ودخل بي وطلقني وانقضت عدتي والمدة تحتمل ذلك جاز للزوج أن يصدقها إذا كان في غالب ظنه أنها صادقة"]]}]},{"id":"q84","title":"كتاب الإيلاء","group":"كتاب الإيلاء","units":[{"id":"q84_1","label":"كتاب الإيلاء · الفقرة ١","segs":[["matn","إذا قال الرجل لامرأته: والله لا أقربك أو لا أقربك أربعة أشهرفهو مول فإن وطئها في الأربعة الأشهر حنث في يمينه ولزمته الكفارة وسقط الإيلاء"]]},{"id":"q84_2","label":"كتاب الإيلاء · الفقرة ٢","segs":[["matn","وإن لم يقربها حتى مضت أربعة أشهر بانت منه بتطليقة"]]},{"id":"q84_3","label":"كتاب الإيلاء · الفقرة ٣","segs":[["matn","فإن كان خلف على أربعة أشهر فقد سقطت اليمين وإن كان حلف على الأبد فاليمين باقية فإن عاد فتزوجها عاد الإيلاء فإن وطئها لزمته الكفارة وإلا وقعت بمضي أربعة أشهر تطليقه أخرى فإن تزوجها عاد الإيلاء ووقع بمضي أربعة أشهر تطليقه أخرى فإن تزوجها بعد"]]},{"id":"q84_4","label":"كتاب الإيلاء · الفقرة ٤","segs":[["matn","زوج آخر لم يقع بذلك الإيلاء طلاق واليمين باقية فإن وطئها كفر عن يمينه"]]},{"id":"q84_5","label":"كتاب الإيلاء · الفقرة ٥","segs":[["matn","وإذا حلف على أقل من أربعة أشهر لم يكن موليا وإن حلف بحج أو صوم أوصدقة أو عتق أو طلاق فهو مول"]]},{"id":"q84_6","label":"كتاب الإيلاء · الفقرة ٦","segs":[["matn","وإن آلى من المطلقة الرجعية كان موليا وإن آلى من البائنة لم يكن موليا ومدة إيلاء الأمة شهران"]]},{"id":"q84_7","label":"كتاب الإيلاء · الفقرة ٧","segs":[["matn","وإن كان المولى مريضا لا يقدر على الجماع أو كانت المرأة مريضة أو كانت بينهما مسافة لا يقدر أن يصل إليها في مدة الإيلاء ففيئه أن يقول بلسانه: فئت إليها فإن قال ذلك سقطر الإيلاء وإن صح في المدة بطل ذلك الفيء وصار فيئه بالجماع"]]},{"id":"q84_8","label":"كتاب الإيلاء · الفقرة ٨","segs":[["matn","وإذا قال لامرأته أنت علي حرام سئل عن نيته فإن قال: أردت الكذب فهو كما قال"]]},{"id":"q84_9","label":"كتاب الإيلاء · الفقرة ٩","segs":[["matn","وإن قال: أردت الطلاق فهي تطليقة بائنة إلا أن ينوي الثلاث وإن قال: أردت الظهار فهو ظهار وإن قال: أردت التحريم أو لم أرد به شيئا فهو يمين يصير بها موليا"]]}]},{"id":"q85","title":"باب الخلع","group":"كتاب الإيلاء","units":[{"id":"q85_1","label":"باب الخلع · الفقرة ١","segs":[["matn","إذا اشتاق الزوجان وخافا أن لا يقيما حدود الله فلا بأس أن تفتدي نفسها منه بمال يخلعها به فإذ فعل ذلك وقع بالخلع تطليقة بائنة ولزمها المال"]]},{"id":"q85_2","label":"باب الخلع · الفقرة ٢","segs":[["matn","وإن كان النشوز من قبله كره له أن يأخذ منها عوضا وإن كان النشوز من قبلها كره له أيأخذ منها أكثر مما أعطاها فإن فعل ذلك جاز في القضاء"]]},{"id":"q85_3","label":"باب الخلع · الفقرة ٣","segs":[["matn","وإن طلقها على مال فقبلت وقع الطلاق ولزمها المال وكان الطلاق بائنا"]]},{"id":"q85_4","label":"باب الخلع · الفقرة ٤","segs":[["matn","وإذا بطل العوض في الخلع مثل أن تخالع المرأة المسلمة على خمر أو خنزير فلا شيء للزوج والفرقة بائنة وإن بطل العوض في الطلاق كان رجعيا"]]},{"id":"q85_5","label":"باب الخلع · الفقرة ٥","segs":[["matn","وما جاز أن يكون مهرا جاز أن يكون بدلا في الخلع"]]},{"id":"q85_6","label":"باب الخلع · الفقرة ٦","segs":[["matn","فإن قالت له: خالعني على ما في يدي فخالعها ولم يكن في يدها شيء فلا شيء له عليها وإن قالت: خالعني على ما في يدي من مال ولم يكن في يدها شيء ردت عليه مهرها وإن قالت: خالعني على ما في يدي من دراهم فخالها ولم يكن في يدها شيء فعليها ثلاثة دراهم وإن قالت: طلقني ثلاثا بألف فطلقها واحدة فعليها ثلث الألف وإن قالت: طلقني ثلاثا على ألف فطلقها واحدة فلا شيء عليها عند أبي حنيفة"]]},{"id":"q85_7","label":"باب الخلع · الفقرة ٧","segs":[["matn","ولو قال الزوج: طلقي نفسك ثلاثا بألف أو على ألف فطلقت نفسها واحدة لم يقع عليها شيء"]]},{"id":"q85_8","label":"باب الخلع · الفقرة ٨","segs":[["matn","والمبارأة كالخلع والخلع كالمبارأة يسقطان كل حق لكل واحد من الزوجين على الآخر مما يتعلق بالنكاح عند أبي حنيفة رحمه الله إلا نفقة العدة وقال أبو يوسف رحمه الله المبارأة تسقط والخلع لا تسقط وقال محمد رحمه الله لا تسقطان إلا ما سمياه."]]}]},{"id":"q86","title":"كتاب الظهار","group":"كتاب الظهار","units":[{"id":"q86_1","label":"كتاب الظهار · الفقرة ١","segs":[["matn","إذا قال الزوج لامرأته: أنت علي كظهر أمي فقد حرمت عليه ولا يحل له وطؤها ولا لمسها ولا تقبيلها حتى يكفر عن ظهاره فإن وطئها قبل أن يكفر استغفر"]]},{"id":"q86_2","label":"كتاب الظهار · الفقرة ٢","segs":[["matn","الله تعالى ولا شيء عليه غير الكفارة الأولى ولا يعاودها حتى يكفر"]]},{"id":"q86_3","label":"كتاب الظهار · الفقرة ٣","segs":[["matn","والعود الذي تجب به الكفارة أن يعزم على وطئها"]]},{"id":"q86_4","label":"كتاب الظهار · الفقرة ٤","segs":[["matn","وإذا قال: أنت علي كبطن أمي أو كفخذها أو كفرجها فهو مظاهر وكذلك إن شبهها بمن لا يحل له النظر على التأييد من محارمه مثل أخته أو عمته أو أمه من الرضاعة وكذلك إن قال: رأسك علي كظهر أمي أو فرجك أو وجهك أو رقبتك أو نصفك أو ثلثك وإن قال: أنت علي مثل أمي رجع إلى نيته"]]},{"id":"q86_5","label":"كتاب الظهار · الفقرة ٥","segs":[["matn","فإن قال أردت الكرامة فهو كما قال وإن قال: أردت الظهار فهو ظهار وإن قال: أردت الطلاق فهو طلاق بائن وإن لم يكن له نية"]]},{"id":"q86_6","label":"كتاب الظهار · الفقرة ٦","segs":[["matn","فليس شيء ولا يكون الظهار إلا من زوجته فإن ظاهر من أمته لم يكن مظاهرا ومن قال لنسائه: أنتن علي كظهر أمي كان مظاهرا من جماعتهن وعليه لكل واحدة منهن كفارة"]]},{"id":"q86_7","label":"كتاب الظهار · الفقرة ٧","segs":[["matn","وكفارة الظهار: عتق رقبة فإن لم يجد فصيام شهرين متتابعين فإن لم يستطع فإطعام مسكينا كل ذلك قبل المسيس ويجزئ في ذلك عتق الرقبة الكافرة والمسلمة والذكر والأنثى والصغير والكبير ولا تجزئ العمياء ولا المقطوعة اليدين أو الرجلين"]]},{"id":"q86_8","label":"كتاب الظهار · الفقرة ٨","segs":[["matn","ويجوز الأصم والمقطوع إحدى اليدين وإحدى الرجلين من خلاف ولا يجوز مقطوع إبهامي اليدين ولا المجنون الذي"]]},{"id":"q86_9","label":"كتاب الظهار · الفقرة ٩","segs":[["matn","لا يعقل ولا يجوز عتق المدبر وأم الولد والمكاتب الذي أدى بعض المال"]]},{"id":"q86_10","label":"كتاب الظهار · الفقرة ١٠","segs":[["matn","فإن أعتق مكاتبا لم يود شيئا جاز فإن اشترى أباه أو ابنه ينوي بالشراء الكفارة جاز عنها وإن أعتق نصف عبد مشترك عن الكفارة وضمن قيمة باقية فأعتقه لم يجز عند أبي حنيفة وإن أعتق نصف عبده عن كفارته ثم أعتق باقية عنها جاز"]]},{"id":"q86_11","label":"كتاب الظهار · الفقرة ١١","segs":[["matn","وإن أعتق نصف عبده عن كفارته ثم جامع التي ظاهر منها ثم أعتق باقية لم يجز عند أب حنيفة وإذا لم يجد المظاهر ما يعتق فكفارته صوم شهرين متتابعين ليس فيهما شهر رمضان ولا يوم الفطر ولا يوم النحر ولا أيام التشريق"]]},{"id":"q86_12","label":"كتاب الظهار · الفقرة ١٢","segs":[["matn","فإن جامع التي ظاهر منها في خلال الشهرين ليلا عامدا أو نهارا ناسيا استأنف الصوم عند أبي حنيفة ومحمد وإن أفطر يوما بعذر أو بغير عذر استأنف"]]},{"id":"q86_13","label":"كتاب الظهار · الفقرة ١٣","segs":[["matn","وإن ظاهر العبد لم يجزه في الكفارة إلا الصوم"]]},{"id":"q86_14","label":"كتاب الظهار · الفقرة ١٤","segs":[["matn","فإن أعتق المولى عنه أو أطعم لم يجزه"]]},{"id":"q86_15","label":"كتاب الظهار · الفقرة ١٥","segs":[["matn","وإذا لم يستطع المظاهر الصيام أطعم ستين مسكينا كل مسكين نصف صاع من بر أو صاعا من تمر أو شعير أو قيمة تلك فإن غداهم وعشاهم جاز قليلا ما أكلوا أو كثيرا فإن أعطى مسكينا واحدا ستين يوما أجزأه وإن أعطاه في يوم واحد لم يجزه إلا عن يومه وإن قرب التي ظاهر منها في خلال الإطعام لم يستأنف"]]},{"id":"q86_16","label":"كتاب الظهار · الفقرة ١٦","segs":[["matn","ومن وجب عليه كفارتا ظهار فأعتق رقبتين لا ينوي عن إحداهما بعينها جاز عنهما وكذلك إن صام أربعة كفارتا ظهار فأعتق رقبتين لا ينوي عن إحداهما بعينها جاز عنهما وكذلك إن صام أربعة أشهر أطعم مائة وعشرين مسكينا جاز وإن أعتق رقبة واحدة أو صام شهرين كان له أن يجعل ذلك عن أيتهما شاء"]]}]},{"id":"q87","title":"باب اللعان","group":"كتاب الظهار","units":[{"id":"q87_1","label":"باب اللعان · الفقرة ١","segs":[["matn","إذا قذف الرجل امرأته بالزنا وهما من أهل الشهادة والمرأة ممن يحد قاذفها أو نفى نسب ولدها وطالبته بموجب القذف فعليه اللعان فإن امتنع منه حبسه الحاكم حتى يلاعن أو يكذب نفسه فيحد وإن لاعن وجب عليها اللعان"]]},{"id":"q87_2","label":"باب اللعان · الفقرة ٢","segs":[["matn","فإن امتنعت حبسها الحاكم حتى تلاعن أو تصدقه"]]},{"id":"q87_3","label":"باب اللعان · الفقرة ٣","segs":[["matn","وإذا كان من أهل الشهادة وهي أمة أو كافر أو محدودة في قذف أو كانت ممن لا يحد قاذفها فلا حد عليه في قذفها ولا لعان"]]},{"id":"q87_4","label":"باب اللعان · الفقرة ٤","segs":[["matn","وصفة اللعان: أن يبتدئ القاضي بالزوج فيشهد أربع مرات يقول في كل مرة: أشهد بالله إني لمن الصادقين فيما رميتها به من الزنا"]]},{"id":"q87_5","label":"باب اللعان · الفقرة ٥","segs":[["matn","ثم يقول في الخامسة: لعنة الله عليه إن كان من الكاذبين فيما رماها به من الزنا ويشير إليها في جميع ذلك ثم تشهد المرأة أربع مرات تقول في كل مرة: أشهد بالله إنه لمن الكاذبين فيما رماني به من الزن وتقول في الخامسة: إن غضب الله عليها إن كان من الصادقين فيما رماني به من الزنا فإذا التعنا فرق القاضي بينهما وكانت الفرقة تطليقه بائنة عند أبي حنيفة ومحمد وقال أبو يوسف: تحريم مؤبد"]]},{"id":"q87_6","label":"باب اللعان · الفقرة ٦","segs":[["matn","وإن كان القذف بولد نفى القاضي نسبه وألحقه بأمه"]]},{"id":"q87_7","label":"باب اللعان · الفقرة ٧","segs":[["matn","فإن عاد الزوج فأكذب نفسه حده القاضي وحل له أن يتزوجها وكذلك إن قذف غيرها فحد أو زنت فحدت"]]},{"id":"q87_8","label":"باب اللعان · الفقرة ٨","segs":[["matn","وإذا قذف امرأته وهي صغيرة أو مجنونة فلا لعان بينهما"]]},{"id":"q87_9","label":"باب اللعان · الفقرة ٩","segs":[["matn","وقذف الأخرس لا يتعلق به اللعان"]]},{"id":"q87_10","label":"باب اللعان · الفقرة ١٠","segs":[["matn","وإذا قال الزوج: ليس حملك مني فلا لعان بينهما"]]},{"id":"q87_11","label":"باب اللعان · الفقرة ١١","segs":[["matn","وإن قال: زنيت وهذا الحمل من الزنا تلاعنا ولم ينف القاضي الحمل"]]},{"id":"q87_12","label":"باب اللعان · الفقرة ١٢","segs":[["matn","وإذا نفى الرجل ولد امرأته عقيب الولادة أو في الحال التي تقبل التهنئة أو تبتاع له آلة الولادة صح نفيه ولاعن به وإن نفاه بعد ذلك لاعن وثبت النسب"]]},{"id":"q87_13","label":"باب اللعان · الفقرة ١٣","segs":[["matn","وقال أبو يوسف ومحمد: يصح نفيه في مدة النفاس وإذا ولدت ولدين في بطن واحد فنفى الأول واعترف بالثاني ثبت نسبهما وحد الزوج وإن اعترف بالأول ونفى الثاني ثبت نسبهما ولاعن"]]}]},{"id":"q88","title":"باب العدة","group":"كتاب الظهار","units":[{"id":"q88_1","label":"باب العدة · الفقرة ١","segs":[["matn","إذا طلق الرجل امرأته طلاقا بائنا أو رجعيا أو وقعت الفرقة بينهما بغير طلاق وهي حرة ممن تحيض فعدتها ثلاثة أقراء والأقراء: الحيض وإن كانت لا تحيض من صغر أو كبر فعدتها ثلاثة أشهر وإن كانت حاملا فعدتها أن تضع حملها"]]},{"id":"q88_2","label":"باب العدة · الفقرة ٢","segs":[["matn","وإن كانت أمة فعدتها حيضتان وإن كانت لا تحيض فعدتها شهر ونصف"]]},{"id":"q88_3","label":"باب العدة · الفقرة ٣","segs":[["matn","وإذا مات الرجل عن امرأته الحرة فعدتها أربعة أشهر وعشر وإن كانت أمة فعدتها شهران وخمسة أيام وإن كانت حاملا فعدتها أن تضع حملها وإذا ورثت المطلقة في المرض فعدتها أبعد الأجلين"]]},{"id":"q88_4","label":"باب العدة · الفقرة ٤","segs":[["matn","فإن أعتقت الأمة في عدتها من طلاق رجعي انتقلت عدتها إلى عدة"]]},{"id":"q88_5","label":"باب العدة · الفقرة ٥","segs":[["matn","الحرائر وإن أعتقت وهي مبتوتة أو متوفى عنه زوجها لم تنتقل عدتها وإن كانت آيسة فاعتدت بالشهور ثم رأت الدم انتقض ما مضى من عدتها وكان عليها أن تستأنف العدة بالحيض"]]},{"id":"q88_6","label":"باب العدة · الفقرة ٦","segs":[["matn","والمنكوحة نكاحا فاسدا والموطوءة بشبهة عدتها الحيض في الفرفة والموت"]]},{"id":"q88_7","label":"باب العدة · الفقرة ٧","segs":[["matn","وإذا مات مولى أم الولد عنه أو أعتقها فعدتها ثلاث حيض"]]},{"id":"q88_8","label":"باب العدة · الفقرة ٨","segs":[["matn","وإذا مات الصغير عن امرأته وبها حبل فعدتها أن تضع حملها وإن حدث الحبل بعد الموت فعدتها أربعة أشهر وعشر"]]},{"id":"q88_9","label":"باب العدة · الفقرة ٩","segs":[["matn","وإذا طلق الرجل امرأته في حال"]]},{"id":"q88_10","label":"باب العدة · الفقرة ١٠","segs":[["matn","الحيض لم تعتد بالحيضة التي وقع فيها الطلاق"]]},{"id":"q88_11","label":"باب العدة · الفقرة ١١","segs":[["matn","وإذا وطئت المعتدة بشبهة فعليها عدة أخرى وتداخلت العدتان فيكون ما تراه من الحيض محتسبا به منهما جميعا وإذا انقضت العدة الأولى ولم تكمل الثانية فإن عليها تمام العدة الثانية"]]},{"id":"q88_12","label":"باب العدة · الفقرة ١٢","segs":[["matn","وابتداء العدة في الطلاق عقيب الطلاق وفي الوفاة عقيب الوفاة فإن لم تعلم بالطلاق أو الوفاة حتى مضت مدة العدة فقد انقضت عدتها"]]},{"id":"q88_13","label":"باب العدة · الفقرة ١٣","segs":[["matn","والعدة في النكاح الفاسد عقيب التفريق بينهما أو عزم الواطئ على ترك وطئها"]]},{"id":"q88_14","label":"باب العدة · الفقرة ١٤","segs":[["matn","وعلى المبتوتة والمتوفى عنها زوجها - إذا كانت بالغة مسلمة - الإحداد وهو: ترك الطيب والزينة والدهن"]]},{"id":"q88_15","label":"باب العدة · الفقرة ١٥","segs":[["matn","والكحل إلا من عذر ولا تختضب بالحناء ولا تلبس ثوبا مصبوغا بعصفر ولا بزعفران"]]},{"id":"q88_16","label":"باب العدة · الفقرة ١٦","segs":[["matn","ولا إحداد على كافرة ولا صغيرة وعلى الأمة الإحداد وليس في عدة النكاح الفاسد ولا في عدة أم الولد إحداد"]]},{"id":"q88_17","label":"باب العدة · الفقرة ١٧","segs":[["matn","ولا ينبغي أن تخطب المعتدة ولا بأس بالتعريض في الخطبة"]]},{"id":"q88_18","label":"باب العدة · الفقرة ١٨","segs":[["matn","ولا يجوز للمطلقة الرجعية والمبتوتة الخروج من بيتها ليلا ولا نهارا"]]},{"id":"q88_19","label":"باب العدة · الفقرة ١٩","segs":[["matn","والمتوفى عنها زوجها تخرج نهارا وبعض الليل ولا تبيت في غير منزلها"]]},{"id":"q88_20","label":"باب العدة · الفقرة ٢٠","segs":[["matn","وعلى المعتدة أن تعتد في المنزل الذي يضاف إليها بالسكنى حال وقوع الفرقة فإن كان نصيبها من دار الميت لا يكفيها وأخرجها الورثة من نصيبهم انتقلت"]]},{"id":"q88_21","label":"باب العدة · الفقرة ٢١","segs":[["matn","ولا يجوز أن يسافر الزوج بالمطلقة الرجعية"]]},{"id":"q88_22","label":"باب العدة · الفقرة ٢٢","segs":[["matn","وإذا طلق الرجل امرأته طلاقا بائنا ثم تزوجها في عدتها وطلقها قبل أن يدخل بها فعليه مهر كامل وعليها عدة مستقبلة وقال محمد: لها نصف المهر وعليها إتمام العدة الأولى"]]},{"id":"q88_23","label":"باب العدة · الفقرة ٢٣","segs":[["matn","ويثبت نسب ولد المطلقة الرجعية إذا جاءت به لسنتين أو أكثر ما لم تقر بانقضاء عدتها فإن جاءت به"]]},{"id":"q88_24","label":"باب العدة · الفقرة ٢٤","segs":[["matn","لأقل من سنتين بانت من زوجها وإن جاءت به لأكثر من سنتين ثبت نسبه وكانت رجعة"]]},{"id":"q88_25","label":"باب العدة · الفقرة ٢٥","segs":[["matn","والمبتوتة يثبت نسب ولدها إذا جاءت به لأقل من سنتين فإن جاءت به لتمام سنتين من يوم الفرقة لم يثبت نسبه"]]},{"id":"q88_26","label":"باب العدة · الفقرة ٢٦","segs":[["matn","إلا أن يدعيه ويثبت نسب ولد المتوفى عنها زوجها ما بين الوفاة وبين سنتين"]]},{"id":"q88_27","label":"باب العدة · الفقرة ٢٧","segs":[["matn","وإذا اعترفت المعتدة بانقضاء عدتها ثم جاءت بولد لأقل من ستة أشهر ثبت نسبه وإن جاءت به لستة أشهر لم يثبت نسبه"]]},{"id":"q88_28","label":"باب العدة · الفقرة ٢٨","segs":[["matn","وإذا ولدت المعتدة ولدا لم يثبت نسبه عند أبي حنيفة إلا أن يشهد بولادتها رجلان أول رجل وامرأتان إلا أن يكون هناك حبل ظاهر"]]},{"id":"q88_29","label":"باب العدة · الفقرة ٢٩","segs":[["matn","أو اعتراف من قبل الزوج فيثبت النسب من غير شهادة وقال أبو يوسف ومحمد: يثبت في الجميع بشهادة امرأة واحدة"]]},{"id":"q88_30","label":"باب العدة · الفقرة ٣٠","segs":[["matn","وإذا تزوج امرأة فجاءت بولد لأقل من ستة أشهر منذ يوم تزوجها لم يثبت نسبه وإن جاءت به لستة أشهر فصاعدا ثبت إن اعترف به الزوج أو سكت وإن جحد الولادة ثبت بشهادة امرأة واحدة تشهد بالولادة"]]},{"id":"q88_31","label":"باب العدة · الفقرة ٣١","segs":[["matn","وأكثر مدة الحمل سنتان وأقله ستة أشهر"]]},{"id":"q88_32","label":"باب العدة · الفقرة ٣٢","segs":[["matn","وإذا طلق الذمي الذمية فلا عدة عليها"]]},{"id":"q88_33","label":"باب العدة · الفقرة ٣٣","segs":[["matn","وإذا تزوجت الحامل من الزنا جاز النكاح ولا يطؤها حتى تضع حملها والله أعلم"]]}]},{"id":"q89","title":"كتاب النفقات","group":"كتاب النفقات","units":[{"id":"q89_1","label":"كتاب النفقات · الفقرة ١","segs":[["matn","النفقة واجبة على زوجها مسلمة كانت أو كافرة إذا سملت نفسها في منزله فعليه نفقتها وكسوتها وسكناها"]]},{"id":"q89_2","label":"كتاب النفقات · الفقرة ٢","segs":[["matn","يعتبر ذلك لحالهما جميعا موسرا كان الزوج أو معسرا"]]},{"id":"q89_3","label":"كتاب النفقات · الفقرة ٣","segs":[["matn","فإن امتنعت من تسليم نفسها حتى يعطيها مهرها فلها النفقة"]]},{"id":"q89_4","label":"كتاب النفقات · الفقرة ٤","segs":[["matn","وإن نشزت فالا نفقة لها حتى تعود إلى منزله"]]},{"id":"q89_5","label":"كتاب النفقات · الفقرة ٥","segs":[["matn","وإن كانت صغيرة لا يستمتع بها فلا نفقة لها وإن سلمت نفسها إليه"]]},{"id":"q89_6","label":"كتاب النفقات · الفقرة ٦","segs":[["matn","وإن كان الزوج صغيرا لا يقدر على الوطء والمرأة كبيرة فلها النفقة من ماله"]]},{"id":"q89_7","label":"كتاب النفقات · الفقرة ٧","segs":[["matn","وإذا طلق الرجل امرأته فلها النفقة والسكنى في عدتها رجعيا كان أو بائنا"]]},{"id":"q89_8","label":"كتاب النفقات · الفقرة ٨","segs":[["matn","ولا نفقة للمتوفى عنها زوجها وكل فرقة جاءت من قبل المرأة بمعصية فلا نفقة لها وإن طلقها ثم ارتدت سقطت نفقتها"]]},{"id":"q89_9","label":"كتاب النفقات · الفقرة ٩","segs":[["matn","وإن أمكنت ابن زوجها من نفسها إن كان بعد الطلاق فلها النفقة وإن كان قبل الطلاق فلا نفقة لها"]]},{"id":"q89_10","label":"كتاب النفقات · الفقرة ١٠","segs":[["matn","وإذا حبست المرأة في دين أو غصبها رجل كرها فذهب بها أو حجت مع محرم فلا نفقة لها"]]},{"id":"q89_11","label":"كتاب النفقات · الفقرة ١١","segs":[["matn","وإن مرضت في منزل الزوج فلها النفقة"]]},{"id":"q89_12","label":"كتاب النفقات · الفقرة ١٢","segs":[["matn","وتفرض على الزوج نفقة خادمها إذا كان موسرا ولا تفرض لأكثر من خادم واحد"]]},{"id":"q89_13","label":"كتاب النفقات · الفقرة ١٣","segs":[["matn","وعليه أن يسكنها في دار منفردة ليس فيها أحد من أهله إلا أن تختار ذلك وإن كان له ولد من غيرها فليس له أن يسكنه معها"]]},{"id":"q89_14","label":"كتاب النفقات · الفقرة ١٤","segs":[["matn","للزوج أن يمنع والديها وولدها من غيره وأهلها من الدخول"]]},{"id":"q89_15","label":"كتاب النفقات · الفقرة ١٥","segs":[["matn","عليها ولا يمنعهم من النظر إليها وكلامها أي وقت اختاروا"]]},{"id":"q89_16","label":"كتاب النفقات · الفقرة ١٦","segs":[["matn","ومن أعسر بنفقة امرأته لم يفرق بينهما ويقال لها: استديني عليه"]]},{"id":"q89_17","label":"كتاب النفقات · الفقرة ١٧","segs":[["matn","وإذا غاب الرجل وله مال في يد رجل وهو يعرف به وبالزوجية فرض القاضي في ذلك المال نفقة زوجة الغائب وأولاده الصغار ووالديه ويأخذ منها كفيلا بها ولا يقضى بنفقة في مال الغائب إلا لهؤلاء"]]},{"id":"q89_18","label":"كتاب النفقات · الفقرة ١٨","segs":[["matn","وإذا قضى القاضي لها بنفقة الإعسار ثم أيسر فخاصمته تمم لها نفقة الموسر"]]},{"id":"q89_19","label":"كتاب النفقات · الفقرة ١٩","segs":[["matn","وإذا مضت مدة لم ينفق الزوج عليها وطالبته بذلك فلا شيء لها إلا أن يكون القاضي فرض لها النفقة أو صالحت الزوج على مقدارها فيقضي لها بنفقة ما مض وإذا مات الزوج بعد ما قضي عليه بالنفقة ومضت شهور سقطت النفقة"]]},{"id":"q89_20","label":"كتاب النفقات · الفقرة ٢٠","segs":[["matn","وإن أسلفها نفقة سنة ثم مات يسترجع منها شيء وقال محمد: يحتسب لها نفقة ما مضى وما بقي للزوج"]]},{"id":"q89_21","label":"كتاب النفقات · الفقرة ٢١","segs":[["matn","وإذا تزوج العبد حرة فنفقتها دين عليه يباع فيها"]]},{"id":"q89_22","label":"كتاب النفقات · الفقرة ٢٢","segs":[["matn","وإذا تزوج الرجل أمة فبوأها مولاها معه منزلا فعليه النفقة وإن لم يبوئها فلا نفقة لها"]]},{"id":"q89_23","label":"كتاب النفقات · الفقرة ٢٣","segs":[["matn","ونفقة الأولاد الصغار على الأب لا يشاركه فيها أحد"]]},{"id":"q89_24","label":"كتاب النفقات · الفقرة ٢٤","segs":[["matn","كما لا يشاركه في نفقة الزوجة أحد"]]},{"id":"q89_25","label":"كتاب النفقات · الفقرة ٢٥","segs":[["matn","فإن كان الصغير وضيعا فليس على أمه أن ترضعه ويستأجر له الأب من ترضعه عندها فإن استأجرها وهي زوجته أو معتدته لترضع ولدها لم يجز وإن انقضت عدتها فاستأجرها على إرضاعه جاز"]]},{"id":"q89_26","label":"كتاب النفقات · الفقرة ٢٦","segs":[["matn","فإن قال الأب لا أستأجرها وجاء بغيرها"]]},{"id":"q89_27","label":"كتاب النفقات · الفقرة ٢٧","segs":[["matn","فرضيت الأم بمثل أجر الأجنبية كانت الأم أحق به وإن التمست زيادة لم يجبر الزوج عليها"]]},{"id":"q89_28","label":"كتاب النفقات · الفقرة ٢٨","segs":[["matn","ونفقة الصغير واجبة على أبيه وإن خالفه في دينه كما تجب نفقة الزوجة على الزوج وإن خالفته في دينه"]]},{"id":"q89_29","label":"كتاب النفقات · الفقرة ٢٩","segs":[["matn","43 - كتاب الحضانة"]]},{"id":"q89_30","label":"كتاب النفقات · الفقرة ٣٠","segs":[["matn","وإذا وقعت الفرقة بين الزوجين فالأم أحق بالولد فإن لم تكن الأم فأم الأم أولى من أم الأب فإن لم تكن فأم الأب أولى من الأخوات فإن لم تكن جدة فلأخوات أولى من العمات والخالات وتقدم الأخت من الأب والأم ثم الأخت من الأم ثم الأخت من"]]},{"id":"q89_31","label":"كتاب النفقات · الفقرة ٣١","segs":[["matn","الأب ثم الخالات أولى من العمات وينزلن كذلك ثم العمات ينزلن كذلك"]]},{"id":"q89_32","label":"كتاب النفقات · الفقرة ٣٢","segs":[["matn","وكل من تزوجت من هؤلاء سقط حقها إلا الجدة إذا كان زوجها الجد وإن لم تكن للصبي امرأة من أهله واختصم فيه الرجال فأولاهم به أقربهم تعصبيا"]]},{"id":"q89_33","label":"كتاب النفقات · الفقرة ٣٣","segs":[["matn","والأم والجدة أحق بالغلام حتى يأكل وحده ويلبس وحده ويستنجي وحده وبالجارية حتى تحيض ومن سوى الأم والجدة أحق بالجارية حتى تبلغ حدا تشتهى"]]},{"id":"q89_34","label":"كتاب النفقات · الفقرة ٣٤","segs":[["matn","والأمة إذا أعتقها مولاها وأم الولد إذا أعتقت في الولد كالحرة وليس للأمة وأم الولد قبل العتق حق في الولد والذمية أحق بولدها المسلم ما لم يعقل الأديان ويخاف أن يألف الكفر"]]},{"id":"q89_35","label":"كتاب النفقات · الفقرة ٣٥","segs":[["matn","وإذا أرادت المطلقة أن تخرج بولدها من المصر فليس لها ذلك إلا أن تخرجه إلى وطنها وقد كان الزوج تزوجها فيه"]]},{"id":"q89_36","label":"كتاب النفقات · الفقرة ٣٦","segs":[["matn","وعلى الرجل أن ينفق على أبويه وأجداده وجداته إذا كانوا فقراء وإن خالفوه في دينه ولا تجب النفقة مع اختلاف الدين إلا للزوجة والأبوين والأجداد والجدات والولد وولد الولد ولا يشارك الولد في نفقة أبويه أحد"]]},{"id":"q89_37","label":"كتاب النفقات · الفقرة ٣٧","segs":[["matn","والنفقة لكل ذي رحم محرم إذا كان صغيرا فقيرا أو كانت امرأة بالغة فقيرة أو كان ذكرا زمنا أو أعمى فقيرا"]]},{"id":"q89_38","label":"كتاب النفقات · الفقرة ٣٨","segs":[["matn","ويجب ذلك على مقدار الميراث"]]},{"id":"q89_39","label":"كتاب النفقات · الفقرة ٣٩","segs":[["matn","وتجب نفقة الابنة البالغة والابن الزمن على أبويه أثلاثا: على الأب الثلثان وعلى الأم الثلث"]]},{"id":"q89_40","label":"كتاب النفقات · الفقرة ٤٠","segs":[["matn","ولا تجب نفقتهم مع اختلاف الدين ولا تجب على الفقير"]]},{"id":"q89_41","label":"كتاب النفقات · الفقرة ٤١","segs":[["matn","وإذا كان للابن الغائب مال فضي عليه بنفقة أبويه وإن باع"]]},{"id":"q89_42","label":"كتاب النفقات · الفقرة ٤٢","segs":[["matn","أبوه متاعه في نفقته جاز عند أبي حنيفة وإن باع العقار لم يجز"]]},{"id":"q89_43","label":"كتاب النفقات · الفقرة ٤٣","segs":[["matn","وإن كان للابن الغائب مال في يد أبويه فانفقا منه لم يضمنا"]]},{"id":"q89_44","label":"كتاب النفقات · الفقرة ٤٤","segs":[["matn","وإن كان له مال في يد أجنبي فأنفق عليهما بغير إذن القاضي ضمن"]]},{"id":"q89_45","label":"كتاب النفقات · الفقرة ٤٥","segs":[["matn","وإذا قضى القاضي للولد والوالدين وذوي الأرحام بالنفقة فمضت مدة سقطت إلا أن يأذن القاضي في الاستدانة عليه"]]},{"id":"q89_46","label":"كتاب النفقات · الفقرة ٤٦","segs":[["matn","وعلى المولى أن ينفق على عبده وأمته فإن امتنع وكن لهما كسب اكتسبا وأنفقها على أنفسهما"]]},{"id":"q89_47","label":"كتاب النفقات · الفقرة ٤٧","segs":[["matn","وإن لم يكن لهما كسب أجبر المولى على بيعهما"]]}]},{"id":"q90","title":"كتاب العتاق","group":"كتاب العتاق","units":[{"id":"q90_1","label":"كتاب العتاق · الفقرة ١","segs":[["matn","العتق يقع من الحر البالغ في مكه فإذا قال لعبده أو أمتهأنت حر أو محرر أو قد حررتك أو أعتقتك فقد عتق نوى المولى العتق أو لم ينو وكذلك إذا قال: رأسك حر أو وجهك أو رقبتك أو بدن: أو قال لأمته: فرجك حر ولو قال: لا ملك لي عليك ونوي به الحرية عتق وإن لم ينو لم يعتق وكذلك كنايات العتق وإن قال: لا سلطان لي عليك ونوى به العتق لم يعتق وإن قال: هذا ابني وثبت على ذلك أو قال: هذا مولاي أو يا مولاي عتق وإن قال يا ابني أو يا أخي لم يعتق وإن قال لغلام لا يولد مثله لمثله هذا ابني عتق عليه عند أبي حنيفة رحمه الله وعندها لا يعتق وإن قال لأمته أنت طالق ونوى به الحرية وإن قال لعبده أنت مثل الحر لم يعتق وإن قال ما أنت إلا حر عتق عليه وإذا ملك الرجل ذا رحم محرم منه عتق عليه وإذا أعتق المولى بعض عبده عتق عليه ذلك البعض ويسعى في بقية قيمته لمولاه عند أبي حنيفة رحمه الله وقالا يعتق كله وإذا كان العبد بين شريكين فأعتق أحدهما نصيبه"]]},{"id":"q90_2","label":"كتاب العتاق · الفقرة ٢","segs":[["matn","عتق فإن كان المعتق موسرا فشريكه بالخيار إن شاء أعتقه وإن شاء ضمن شريكه قيمة نصيبه وإن شاء استسعى العبد وإن كان المعتق معسرا فالشريك بالخيار إن شاء أعتق نصيبه وإن شاء استسعى العبد وهذا عند أبي حنيفة رحمه الله وقال أبو يوسف ومحمد: ليس له إلا الضمان مع اليسار والسعاية مع الإعسار وإذا اشترى رجلان ابن أحدهما عتق نصيب الأب ولا ضمان عليه وكذلك إذا ورثاه فالشريك بالخيار إن شاء أعتق نصيبه وإن شاء استسعى وإذا شهد كل واحد من الشريكين على الآخر بالحرية عتق كله وسعى العبد لكل واحد منهما في نصيبه موسرين كانا أو معسرين عند أبي حنيفة وقال أبو يوسف ومحمد: إن كانا موسرين فلا سعاية عليه"]]},{"id":"q90_3","label":"كتاب العتاق · الفقرة ٣","segs":[["matn","وإن كانا معسرين سعى لهما وإن كان أحدهما موسرا والآخر معسرا سعى للموسر ولم يسع للمعسر ومن أعتق عبده لوجه الله تعالى أو للشيطان أو للصنم عتق"]]},{"id":"q90_4","label":"كتاب العتاق · الفقرة ٤","segs":[["matn","وعتق المكره والسكران واقع وإذا أضاف العتق إلى ملك أو شرط صح كما يصح في الطلاق وإذا خرج عبد من دار الحرب إلينا مسلما عتق وإذا أعتق جارية حاملا عتق حملها وإن أعتق الحمل خاصة عتق ولم تعتق الأم"]]},{"id":"q90_5","label":"كتاب العتاق · الفقرة ٥","segs":[["matn","وإذا أعتق عبده على مال فقبل العبد عتق ولزمه المال ولو قال: إن أديت إلي ألفا فأنت حر صح وصار مأذونا فإن أحضر المال أجبر الحاكم المولى على قبضه وعتق العبد"]]},{"id":"q90_6","label":"كتاب العتاق · الفقرة ٦","segs":[["matn","وولد الأمة من مولاها حر وولدها من زوجها مملوك لسيدها وولد الحرة من العبد حر"]]}]},{"id":"q91","title":"باب التدبير","group":"كتاب العتاق","units":[{"id":"q91_1","label":"باب التدبير · الفقرة ١","segs":[["matn","إذا قال المولى لمملوكه: إذا مت فأنت حر أو أنت حر عن دبر مني أو أمن مدبر أو قد دبرتك فقد صار مدبرا لا يجوز بيعه ولا هبته وللمولى أن يستخدمه ويؤاجره وإن كانت أمة وطئها وله أن يزوجه فإذا مات المولى عتق المدبر من ثلث ماله إن خرج من الثلث وإن لم يكن له مال غيره سعى في ثلثي قيمته وإن كان على المولى دين سعى في جميع قيمته لغرمائه وولد المدبرة مدبر فإن علق التدبير بموته على صفة - مثل أن يقول: إن مت من مرضي هذا أو سفري هذا أو من مرض كذا - فليس بمدبر ويجوز بيعه فإن مات المولى على الصفة التي ذكرها عتق كما يعتق المدبر"]]}]},{"id":"q92","title":"باب الاستيلاد","group":"كتاب العتاق","units":[{"id":"q92_1","label":"باب الاستيلاد · الفقرة ١","segs":[["matn","إذا ولدت الأمة من مولاها فقد صارت أم ولد له لا يجوز بيعها ولا تمليكها وله وطؤها واستخدامها وإجارتها وتزويجها ولا يثبت نسب ولدها إلا أن يعترف به المولى فإن جاءت بعد ذلك بولد ثبت نسبه بغير إقرار وإن نفاه انتفى بقوله وإن زوجها فجاءت بولد فهو حكم أمه وإذا مات المولى عتقت من جميع المال ولا تلزمها السعاية للغرماء إن كان على المولى دين"]]},{"id":"q92_2","label":"باب الاستيلاد · الفقرة ٢","segs":[["matn","وإذا وطئ أمة غيره بنكاح فولدت منه ثم ملحها صارت أم ولد له وإذا وطئ الأب جارية ابنه فجاءت بولد فادعاه ثبت نسبه وصارت أم ولد له وعليه قيمتها وليس عليه عقرها ولا قيمة ولدها وإن وطئ أب مع بقاء الأب لم يثبت النسب فإن كان الأب ميتا يثبت النسب من الجد كما يثبت من الأب وإذا كانت الجارية بين شريكين فجاءت بولد فادعاه أحدهما ثبت نسبه منه وصارت أم ولد له"]]},{"id":"q92_3","label":"باب الاستيلاد · الفقرة ٣","segs":[["matn","وعليه نصف عقرها ونصف قيمتها وليس عليه شيء من قيمة ولدها وإذا ادعياه معا ثبت نسبه منهما وكانت الأم أم ولد لهما وعلى كل واحد منهما نصف العقر قصاصا بما له على الآخر ويرث الابن من كل واحد منهما ميراث ابن كامل وهما يرثان منه ميراث أب واحد وإذا وطئ المولى جارية مكاتبه فجاءت بولد فادعاه: فإن صدقه المكاتب ثبت نسب الولد منه وكان عليه عقرها وقيمة ولدها ولا تصير أم ولد له وإن كذبه في النسب لم يثبت"]]}]},{"id":"q93","title":"كتاب المكاتب","group":"كتاب المكاتب","units":[{"id":"q93_1","label":"كتاب المكاتب · الفقرة ١","segs":[["matn","وإذا كاتب المولى عبده أو أمته على مال شرطه عليه وقبل العبد ذلك صار مكاتبا ويجوز أن يشترط المال حالا ومؤجلا ومنجما وتجوز كتابة العبد الصغير إذا كان يعقل البيع والشراء"]]},{"id":"q93_2","label":"كتاب المكاتب · الفقرة ٢","segs":[["matn","وإذا صحت الكتابة خرج المكاتب من يد المولى ولم يخرج من ملكه فيجوز له البيع والشراء والسفر ولا يجوز له التزويج إلا بإذن المولى ولا يهب ولا يصدق إلا بشيء اليسير ولا يتكفل"]]},{"id":"q93_3","label":"كتاب المكاتب · الفقرة ٣","segs":[["matn","فإنه ولد له ولد من أمة له دخل في كتابته وكان حكمه كحكمه وكسبه له وإن زوج المولى عبده من أمته ثم كاتبهما فولدت منه ولدا دخل في كتابتها وكان كسبه لها"]]},{"id":"q93_4","label":"كتاب المكاتب · الفقرة ٤","segs":[["matn","وإن وطئ المولى مكاتبته لزمه العقر وإن جنى عليها أو على ولدها لزمته الجناية وإن أتلف مالا لها غرمه"]]},{"id":"q93_5","label":"كتاب المكاتب · الفقرة ٥","segs":[["matn","وإذا اشترى المكاتب أباه أو أبنه دخل في كتابته وإن اشترى أم ولده دخل ولدها في الكتابة ولم يجز بيعها وإن اشترى ذا رحم محرم منه لا ولاد له لم يدخل في كتابته عند أبي حنيفة"]]},{"id":"q93_6","label":"كتاب المكاتب · الفقرة ٦","segs":[["matn","وإذا عجز المكاتب عن نجم نظر الحاكم في حاله فإن كان له دين يقتضيه أو مال يقدم إليه ولم يعجل بتعجيزه وانتظر عليه اليومين"]]},{"id":"q93_7","label":"كتاب المكاتب · الفقرة ٧","segs":[["matn","والثلاثة وإن لم يكن له وجه وطلب المولى تعجيزه عجزه الحاكم وفسخ الكتابة عند أبي حنيفة رحمه الله وقالا"]]},{"id":"q93_8","label":"كتاب المكاتب · الفقرة ٨","segs":[["matn","رحمهما الله: حتى يتوالى عليه نجمان وإذا عجز المكاتب عاد إلى أحكام الرق وكان ما في يده من الأكساب لمولاه"]]},{"id":"q93_9","label":"كتاب المكاتب · الفقرة ٩","segs":[["matn","وإن مات المكاتب وله مال لم تنفسخ الكتابة وقضيت كتابته من أكسابه وحكم بعتقه في آخر جزء من أجزاء حياته وإن لم يترك وفاء وترك ولدا مولودا في الكتابة سعى في كتابة أبيه على نجومه وإذا أدى حكمنا بعتق أبيه قبل موته وعتق الولد وإن ترك ولدا مشترى في الكتابة قيل له: إما أن تؤدي الكتابة حالا وإلا رددت في الرق"]]},{"id":"q93_10","label":"كتاب المكاتب · الفقرة ١٠","segs":[["matn","وإذا كاتب المسلم عبده على خمر أو خنزير أو على قيمة نفسه فالكتابة فاسدة"]]},{"id":"q93_11","label":"كتاب المكاتب · الفقرة ١١","segs":[["matn","فإن أدى الخمر عتق ولزمه أن يسعى في قيمته ولا ينقص من المسمى ويزاد عليه"]]},{"id":"q93_12","label":"كتاب المكاتب · الفقرة ١٢","segs":[["matn","وإن كاتبه على حيوان غير موصوف فالكتابة جائزة وإذا كاتب عبديه كتابة واحدة ضامن عن الآخر جازت الكتابة وأيهما أدى عتقا ويرجع على شريكه بنصف ما أدى"]]},{"id":"q93_13","label":"كتاب المكاتب · الفقرة ١٣","segs":[["matn","وإذا أعتق المولى مكاتبه عتق بعتقه وسقط عنه مال الكتابة"]]},{"id":"q93_14","label":"كتاب المكاتب · الفقرة ١٤","segs":[["matn","وإذا مات مولى المكاتب لم تنفسخ الكتابة وقيل له: أد المال إلى ورثة المولى على نجومه فإن أعتقه أحد الورثة لم ينفذ عتقه وإن أعتقوه جميعا عتق وسقط عنه مال الكتابة"]]},{"id":"q93_15","label":"كتاب المكاتب · الفقرة ١٥","segs":[["matn","وإذا كاتب المولى أم ولده جاز وإن مات المولى سقط عنها مال الكتابة وإن"]]},{"id":"q93_16","label":"كتاب المكاتب · الفقرة ١٦","segs":[["matn","ولدت مكاتبته منه فهي بالخيار: إن شاءت مضت على الكتابة وإن شاءت عجزت نفسها وصارت أم ولد له"]]},{"id":"q93_17","label":"كتاب المكاتب · الفقرة ١٧","segs":[["matn","وإذا كاتب مدبرته جاز فإن مات المولى ولا مال له كانت بالخيار بين أن تسعى في ثلثي قيمتها أو جميع مال الكتابة وإن دبر مكاتبته صح التدبير ولها الخيار: إن شاءت مضت على الكتابة وإن شاءت عجزت نفسها وصارت مدبرة وإن مضت على كتابتها فمات المولى ولا مال له فهي بالخيار: إن شاءت سعت في ثلثي مال الكتابة أو ثلثي قيمتها عند أبي حنيفة"]]},{"id":"q93_18","label":"كتاب المكاتب · الفقرة ١٨","segs":[["matn","وإذا أعتق المكاتب عبده على مال لم يجز"]]},{"id":"q93_19","label":"كتاب المكاتب · الفقرة ١٩","segs":[["matn","وإن وهب على عوض لم يصح وإن كاتب عبده جاز فإن أدى الثاني قبل أن يعتق الأول فولاؤه للمولى وإن أدى بعد عتق المكاتب الأول فولاؤه له"]]}]},{"id":"q94","title":"كتاب الولاء","group":"كتاب الولاء","units":[{"id":"q94_1","label":"كتاب الولاء · الفقرة ١","segs":[["matn","إذا أعتق الرجل مملوكه فولاؤه له وكذلك المرأة تعتق فإن شرط أنه سائبه فالشرط باطل والولاء لمن أعتق"]]},{"id":"q94_2","label":"كتاب الولاء · الفقرة ٢","segs":[["matn","وإذا أدى المكاتب عتق وولاؤه للمولى"]]},{"id":"q94_3","label":"كتاب الولاء · الفقرة ٣","segs":[["matn","وكذلك إن عتق بعد موت المولى فولاؤه لورثة المولى فإن مات المولى عتق مدبره وأمهات أولاده وولاؤهم له ومن ملك ذا رحم محرم منه عتق عليه وولاؤه له"]]},{"id":"q94_4","label":"كتاب الولاء · الفقرة ٤","segs":[["matn","وإذا تزوج عبد رجل أمة لآخر فأعتق مولى الأمة الأمة وهي حامل من العبد عتقت وعتق حملها وولاء الحمل لمولى الأم لا ينتقل عنه أبدا فإن ولدت بعد عتقها لأكثر من ستة أشهر ولدا فولاؤه لمولى الأم فإن أعتق العبد جر ولاء ابنه وانتقل عن مولى الأم إلى مولى الأب"]]},{"id":"q94_5","label":"كتاب الولاء · الفقرة ٥","segs":[["matn","ومن تزوج من العجم بمعتقه من العرب فولدت له أولاد فولاء أولادها لمواليها عند أبي حنيفة"]]},{"id":"q94_6","label":"كتاب الولاء · الفقرة ٦","segs":[["matn","وولاء العتاقة تعصيب فإن كان للمعتق عصبة من النسب فهو أولى منه وإن لم يكن له عصبة من النسب فميراثه للمعتق"]]},{"id":"q94_7","label":"كتاب الولاء · الفقرة ٧","segs":[["matn","فإن مات المولى ثم مات المعتق فميراثه لبني المولى دون بناته وليس للنساء من الولاء إلا ما أعتقن أو أعتق من أعتقن أو كاتبن أو كاتب من كاتبن إذا ترك المولى ابنا أولاد ابن آخر فميراث المعتق للابن دون بني البن والولاء للكبر"]]},{"id":"q94_8","label":"كتاب الولاء · الفقرة ٨","segs":[["matn","وإذا أسلم رجل على يد رجل ووالاه على أن يرثه ويعقل عنه أو أسلم على يد غيره ووالاه فالولاء صحيح وعقله على مولاه فإن مات ولا وارث له فميراثه للمولى وإن كان له وارث فهو أولى منه وللمولى أن ينتقل عنه بولائه إلى غيره ما لم يعقل عنه فإذا عقل عنه لم يكن له أن يتحول بولائه إلى غيره وليس لمولى العتاقة أن يوالي أحد"]]}]},{"id":"q95","title":"كتاب الجنايات","group":"كتاب الجنايات","units":[{"id":"q95_1","label":"كتاب الجنايات · الفقرة ١","segs":[["matn","القتل على خمسة أوجه: عمد وشبه عمد وخطإ وما أجزي مجرى الخطإ والقتل بسبب"]]},{"id":"q95_2","label":"كتاب الجنايات · الفقرة ٢","segs":[["matn","فالعمد: ما تعمد ضربه بسلاح أو ما أجزي مجرى السلاح في تفريق الأجزاء كالمحدد من الخشب والحجر والنار وموجب ذلك"]]},{"id":"q95_3","label":"كتاب الجنايات · الفقرة ٣","segs":[["matn","المأثم والقرد إلا أن يعفو الأولياء ولا كفار فيه"]]},{"id":"q95_4","label":"كتاب الجنايات · الفقرة ٤","segs":[["matn","وشبه العمد عند أبي حنيفة: أن يتعمد الضرب بما ليس بسلاح ولا ما أجري مجرى السلاح وقال أبو يوسف ومحمد: إذا ضربه بحجر عظيم أو خشبة عظيمة فهو عمد وشبه العمد: أن يتعمد ضربه بما لا يقتل غالبا وموجب ذلك على القولين والمأثم والكفارة ولا قود وفيه دية مغلظة على العاقلة"]]},{"id":"q95_5","label":"كتاب الجنايات · الفقرة ٥","segs":[["matn","والخطأ على وجهين: خطأ في القصد وهو: أن يرمي شخصا يظنه صيدا فإذا هو آدمي وخطأ في الفعل وهو: أن يرمي غرضا فيصيب آدميا وموجب ذلك: الكفارة والدية على العاقلة ولا مأثم فيه"]]},{"id":"q95_6","label":"كتاب الجنايات · الفقرة ٦","segs":[["matn","وما أجري مجرى الخطإ: مثل النائم ينقلب على رجل فيقتله فحكمه حكم الخطإ"]]},{"id":"q95_7","label":"كتاب الجنايات · الفقرة ٧","segs":[["matn","وأما القتل بسبب: كحافر البئر وواضع الحجر في غير ملكه وموجبه إذا تلف فيه آدمي: الدية على العاقلة ولا كفارة فيه"]]},{"id":"q95_8","label":"كتاب الجنايات · الفقرة ٨","segs":[["matn","والقصاص واجب بقتل كل محقون الدم على التأبيد إذا قتل عمدا"]]},{"id":"q95_9","label":"كتاب الجنايات · الفقرة ٩","segs":[["matn","ويقتل الحر بالحر والحر بالعبد والمسلم بالذمي ولا يقتل والمسلم بالمستأمن ويقتل الرجل بالمرأة والكبير بالصغير والصحيح بالأعمى والزمن ولا يقتل الرجل بابنه ولا بعبده ولا مدبره ولا مكاتبه ولا بعبد ولده ومن ورث قصاصا على أبيه سقط ولا يستوفى"]]},{"id":"q95_10","label":"كتاب الجنايات · الفقرة ١٠","segs":[["matn","القصاص إلا بالسيف وإذا قتل المكاتب عمدا وليس له وارث إلا المولى وترك وفاء فله القصاص فإن ترك وفاء ووارثه غير المولى فلا قصاص لهم وإن اجتمعوا مع المولى"]]},{"id":"q95_11","label":"كتاب الجنايات · الفقرة ١١","segs":[["matn","وإذا قتل عبد الرهن لم يجب القصاص حتى يجتمع الراهن والمرتهن"]]},{"id":"q95_12","label":"كتاب الجنايات · الفقرة ١٢","segs":[["matn","ومن جرح رجلا عمدا فلم يزل صاحب فراش حتى مات فعليه القصاص ومن قطع يد غيره عمدا من المفصل قطعت يده وكذلك الرجل ومارن الأنف والأذن"]]},{"id":"q95_13","label":"كتاب الجنايات · الفقرة ١٣","segs":[["matn","ومن ضرب عين رجل فقلعها فلا قصاص عليه وإن كانت قائمة فذهب ضوؤها فعليه القصاص تحمى له المرآة ويجعل على وجهه قطن رطب وتقابل عينه بالمرآة حتى يذهب ضوءها"]]},{"id":"q95_14","label":"كتاب الجنايات · الفقرة ١٤","segs":[["matn","وفي السن القصاص وفي كل شجة يمكن فيها المماثلة القصاص ولا قصاص في عظم إلا في السن وليس فيما دون النفس شبه عمد إنما هو عمد أو خطأ"]]},{"id":"q95_15","label":"كتاب الجنايات · الفقرة ١٥","segs":[["matn","ولا قصاص بين الرجل والمرأة فيما دون النفس ولا بين الحر والعبد ولا بين العبدين"]]},{"id":"q95_16","label":"كتاب الجنايات · الفقرة ١٦","segs":[["matn","ويجب القصاص في الأطراف بين المسلم والكافر ومن قطع يد رجل من نصف الساعد أو جرحه جائفة فبرأ منها فلا قصاص عليه"]]},{"id":"q95_17","label":"كتاب الجنايات · الفقرة ١٧","segs":[["matn","وإذا كانت يد المقطوع ويد القاطع شلاء أو ناقصه الأصابع فالمقطوع بالخيار: إن شاء قطع اليد المعيبة ولا شيء له غيرها وإن شاء آخذ الأرض كاملا"]]},{"id":"q95_18","label":"كتاب الجنايات · الفقرة ١٨","segs":[["matn","ومن شج رجلا فاستوعب الشجة ما بين قرنية وهي لا تستوعب ما بين قرني الشاج فالمشجوج بالخيار: إن شاء اقتض بمقدار شجته يبتدئ من أي الجانبين شاء وإن شاء أخذ الأرش"]]},{"id":"q95_19","label":"كتاب الجنايات · الفقرة ١٩","segs":[["matn","ولا قصاص في اللسان ولا في الذكر إلا أن تقطع الحشفة"]]},{"id":"q95_20","label":"كتاب الجنايات · الفقرة ٢٠","segs":[["matn","وإذا اصطلح القاتل وأولياء المقتول على مال سقط القصاص ووجب المال قليلا كان أو كثيرا فإن عفا أحد الشركاء أو صالح من نصيبه على عوض سقط حق الباقين من القصاص وكان لهم نصيبهم من الدية وإذا قتل جماعة واحدا عمدا اقتض من جميعهم"]]},{"id":"q95_21","label":"كتاب الجنايات · الفقرة ٢١","segs":[["matn","وإذا قتل واحد جماعة فحضر أولياء المقتولين قتل بجماعتهم ولا شيء لهم غير ذلك فإن حضر واحد قتل له وسقط حق الباقين ومن وجب عليه القصاص فمات"]]},{"id":"q95_22","label":"كتاب الجنايات · الفقرة ٢٢","segs":[["matn","سقط عنه القصاص وإذا قطع رجلان يد رجل فلا قصاص على واحد منهما وعليهما نصف الدية وإن قطع واحد يميني رجلين فحضرا فلهما أن يقطعا يده ويأخذا منه نصف الدية ويقتسمانه نصفين وإن حضر واحد منهما فقطع يده فللآخر عليه نصف الدية"]]},{"id":"q95_23","label":"كتاب الجنايات · الفقرة ٢٣","segs":[["matn","وإذا أقر العبد بقتل العمد لزمه القود"]]},{"id":"q95_24","label":"كتاب الجنايات · الفقرة ٢٤","segs":[["matn","ومن رمى رجلا عمدا فنفذ السهم منه إلى آخر فماتا فعليه القصاص للأول والدية الثاني على عاقلته"]]}]},{"id":"q96","title":"كتاب الديات","group":"كتاب الديات","units":[{"id":"q96_1","label":"كتاب الديات · الفقرة ١","segs":[["matn","إذا قتل رجل رجلا عمد فعلى عاقلته دية مغلظة وعليه كفارة ودية شبه العمد عند أبي حنيفة وأبي يوسف مائة من الإبل أرباعا: خمس وعشرون بنت مخاض وخمس وعشرون بنت لبون وخمس وعشرون حقة وخمس وعشرون جذعة ولا يثبت"]]},{"id":"q96_2","label":"كتاب الديات · الفقرة ٢","segs":[["matn","التغليظ إلا في الإبل خاصة فإن قضي بالدية من غير الإبل لم تتغلظ"]]},{"id":"q96_3","label":"كتاب الديات · الفقرة ٣","segs":[["matn","وقتل الخطإ جب به الدية على العاقلة والكفارة على القاتل"]]},{"id":"q96_4","label":"كتاب الديات · الفقرة ٤","segs":[["matn","والدية في الخطأ مائة من الإبل أخماسا: عشرون بنت مخاض وعشرون ابن مخاض وعشرون بنت لبون وعشرون حقة ولا تثبت الدية إلا من هذه الأنواع الثلاثة عند أبي حنيفة وقال أبو يوسف ومحمد: من البقر مائتا بقرة ومن الغنم ألفا شاة ومن الحلل مائتا حلة كل حلة ثوبان ودية المسلم والذمي سواء"]]},{"id":"q96_5","label":"كتاب الديات · الفقرة ٥","segs":[["matn","وفي النفس الدية وفي المارن الدية وفي اللسان الدية وفي الذكر الدية وفي العقل إذا ضرب رأسه فذهب عقله الدية وفي اللحية إذا حلقت فلم تنبت الدية وفي شعر الرأس الدية وفي الحاجبين الدية وفي العينين الدية وفي اليدين الدية وفي الرجلين الدية وفي الأذنين الدية وفي الشفتين الدية وفي الأنثيين الدية وفي ثديي"]]},{"id":"q96_6","label":"كتاب الديات · الفقرة ٦","segs":[["matn","المرأة الدية وفي كل واحد من هذه الأشياء نصف الدية وفي أشفار العينين الدية وفي أحدهما ربع الدية وفي كل إصبع من أصابع اليدين والرجلين عشر الدية والأصابع كلها سواء وكل إصبع فيها ثلاثة مفاصل ففي أحدهما ثلث دية الإصبع وما فيها مفصلان ففي أحدهما نصف دية الإصبع وفي كل سن خمس من الإبل والأسنان والأضراس كلها سواء"]]},{"id":"q96_7","label":"كتاب الديات · الفقرة ٧","segs":[["matn","ومن ضرب عضوا فأذهب منفعة ففيه دية كاملة"]]},{"id":"q96_8","label":"كتاب الديات · الفقرة ٨","segs":[["matn","كما لو قطعه كاليد إذا شلت والعين إذا ذهب ضوءها"]]},{"id":"q96_9","label":"كتاب الديات · الفقرة ٩","segs":[["matn","والشجاج عشرة: الحارصة والدامعة والدامية والباضعة والمتلاحمة والسمحاق والموضحه والهاشمة والمنقلة والأمة"]]},{"id":"q96_10","label":"كتاب الديات · الفقرة ١٠","segs":[["matn","ففي الموضحه القصاص إن كانت عمدا ولا قصاص في بقية الشجاج وما دون الموضحة ففيه حكومة عدل"]]},{"id":"q96_11","label":"كتاب الديات · الفقرة ١١","segs":[["matn","وفي الموضحة إن كانت خطأ نصف عشر الدية وفي الهاشمية عشر الدية وفي المنقلة عشر ونصف عشر الدية وفي الأمة ثلث الدية وفي الجائفة ثلث الدية"]]},{"id":"q96_12","label":"كتاب الديات · الفقرة ١٢","segs":[["matn","فإن نفذت فهي جائفتان ففيها ثلثا الدية وفي أصابع اليد نصف الدية"]]},{"id":"q96_13","label":"كتاب الديات · الفقرة ١٣","segs":[["matn","وإن قطعها مع الكف ففيها الدية وإن قطعها مع نصف الساعد ففي الكف نصف الدية وفي الزيادة حكومة عدل وفي الإصبع الزائدة حكومة عدل"]]},{"id":"q96_14","label":"كتاب الديات · الفقرة ١٤","segs":[["matn","وفي عين الصبي وذكره ولسانه إذا لم تعلم صحته حكومة عدل ومن شج رجلا موضحة فذهب عقله أو شعر رأسه دخل أرش الموضحة في الدية"]]},{"id":"q96_15","label":"كتاب الديات · الفقرة ١٥","segs":[["matn","وإن ذهب سمعة أو بصره أو كلامه فعليه أرش الموضحة مع الدية ومن قطع إصبع رجل فشلت أخرى إلى جنبها ففيهما الأرش ولا قصاص فيه عند أبي حنيفة"]]},{"id":"q96_16","label":"كتاب الديات · الفقرة ١٦","segs":[["matn","ومن قلع سن رجل فنبتت أخرى سقط الأرش ومن شج رجلا"]]},{"id":"q96_17","label":"كتاب الديات · الفقرة ١٧","segs":[["matn","فالتحمت الجراحة ولم يبق لها أثر ونبت الشعر سقط الأرش عند أبي حنيفة وقال أبو يوسف: عليه أرش الألم وقال محمد: عليه أجرة الطبيب ومن جرح رجلا جراحة لم يقتض منه حتى يبرأ"]]},{"id":"q96_18","label":"كتاب الديات · الفقرة ١٨","segs":[["matn","ومن قطع يد رجل خطأ ثم قتله قبل البرء فعليه الدية وسقط"]]},{"id":"q96_19","label":"كتاب الديات · الفقرة ١٩","segs":[["matn","أرش اليد وكل عمد سقط فيه القصاص بشبهة فالدية في مال القاتل وكل أرش وجب بالصلح فهو في مال القاتل"]]},{"id":"q96_20","label":"كتاب الديات · الفقرة ٢٠","segs":[["matn","وإذا قتل الأب ابنه عمدا فالدية في ماله في ثلاث سنين وكل جناية اعترف بها الجاني فهي في ماله ولا يصدق على عاقلته"]]},{"id":"q96_21","label":"كتاب الديات · الفقرة ٢١","segs":[["matn","وعمد الصبي والمجنون خطأ وفيه الدية على العاقلة"]]},{"id":"q96_22","label":"كتاب الديات · الفقرة ٢٢","segs":[["matn","ومن حفر بئرا في طريق المسلمين أو وضع حجرا فتلف بذلك إنسان فديته على عاقلته وإن تلف فيه بهيمة فضمانها في ماله وإن أشرع في الطريق ورشنا أو ميزابا فسقط على إنسان فعطب فالدية على عاقلته ولا كفارة على حافر البئر وواضع الحجر"]]},{"id":"q96_23","label":"كتاب الديات · الفقرة ٢٣","segs":[["matn","ومن حفر بئرا في ملكه فعطب به إنسان لم يضمن والراكب ضامن لما وطئت الدابة وما أصابت بيدها أو كدمت ولا يضمن ما نفخت برجلها أو ذنبها"]]},{"id":"q96_24","label":"كتاب الديات · الفقرة ٢٤","segs":[["matn","فإن راثت أو بالت في الطريق فعطب به إنسان لم يضمن والسائق ضامن لما أصابت بيدها أو رجلها والقائد ضامن لما أصابت بيدها دون رجلها"]]},{"id":"q96_25","label":"كتاب الديات · الفقرة ٢٥","segs":[["matn","ومن قاد قطارا فهو ضامن لما وطئ فإن كان معه سائق"]]},{"id":"q96_26","label":"كتاب الديات · الفقرة ٢٦","segs":[["matn","فالضمان عليهما وإذا جنى البعد جناية خطإ قيل لمولاه: إما أن تدفعه بها أو تفديه"]]},{"id":"q96_27","label":"كتاب الديات · الفقرة ٢٧","segs":[["matn","فإن دفعه ملكه ولي الجناية وإن فداه بأرشها فإن عاد فجنى كان حكم الجناية الثانية حكم الألى فإن جنى قيل للمولى: إما أن تدفعه إلى ولي الجنايتين يقتسمان على قدر حقيهما وإما أن تفديه بأرش كل واحدة منهما وإن أعتقه المولى وهو لا يعلم بالجناية ضمن الأقل من قيمته ومن أرشها وإن باعه المولى أو أعتقه بعد العلم بالجناية وجب عليه الأرش"]]},{"id":"q96_28","label":"كتاب الديات · الفقرة ٢٨","segs":[["matn","وإذا جنى المدبر أو أم الولد جناية خطأ ضمن المولى الأقل من قيمته ومن أرشها فإن جنى أخرى وقد دفع المولى القيمة إلى ولي الأولى بقضاء فلا شيء عليه ويتبع ولي الجناية الثانية ولي الجناية الأولى فيشاركه فيما أخذ وإن كان المولى دفع القيمة بغير قضاء فالولي بالخيار: إن شاء اتبع المولى وإن شاء اتبع ولي الجناية الأولى"]]},{"id":"q96_29","label":"كتاب الديات · الفقرة ٢٩","segs":[["matn","وإذا مال الحائط إلى طريق المسلمين فطولب صاحبه بنقضه وأشهد عليه فلم ينقض في مدة يقدر على نقضه حتى سقط ضمن ما تلف به من نفس أو مال"]]},{"id":"q96_30","label":"كتاب الديات · الفقرة ٣٠","segs":[["matn","ويستوي أن يطالبه بنقضه مسلم أو ذمي وإن مال إلى دار رجل فالمطالبة إلى مالك الدار خاصة وإذا اصطدم فارسان فماتا فعلى عاقلة كل واحد منهما دية الآخر"]]},{"id":"q96_31","label":"كتاب الديات · الفقرة ٣١","segs":[["matn","وإذا قتل رجل عبدا خطأ فعليه قيمته لا يزاد على عشرة آلاف درهم فإن كانت قيمته عشرة آلاف أو أكثر قضي عليه بعشرة آلاف إلا عشرة"]]},{"id":"q96_32","label":"كتاب الديات · الفقرة ٣٢","segs":[["matn","وفي الأمة إذا زادت قيمتها على الدية خمسة آلاف إلا عشرة"]]},{"id":"q96_33","label":"كتاب الديات · الفقرة ٣٣","segs":[["matn","وفي يد العبد نصف القيمة لا يزاد على خمسة آلاف إلا خمسة وكل ما يقدر من دية الحر فهو مقدر من قيمة العبد"]]},{"id":"q96_34","label":"كتاب الديات · الفقرة ٣٤","segs":[["matn","وإذا ضرب بطن امرأة فألقت جنينا ميتا فعليه غرة"]]},{"id":"q96_35","label":"كتاب الديات · الفقرة ٣٥","segs":[["matn","والغرة نصف عشر الدية فإن ألقته حيا ثم مات فعليه دية كاملة وإن ألقته ميتا ثم ماتت الأم فعليه دية وغرة وإن ماتت الأم ثم ألقته ميتا فعليه دية في الأم ولا شيء في الجنين"]]},{"id":"q96_36","label":"كتاب الديات · الفقرة ٣٦","segs":[["matn","وما يجب في الجنين موروث عنه وفي جنين الأمة إذا كان ذكرا نصف عشر قيمته لو كان حيا وعشر قيمته إن كان أنثى ولا كفارة في الجنين"]]},{"id":"q96_37","label":"كتاب الديات · الفقرة ٣٧","segs":[["matn","والكفارة في شبه العمد والخطإ: عتق رقبة مؤمنة فإن لم يجد فصيام شهرين متتابعين ولا يجزئ فيها الإطعام"]]}]},{"id":"q97","title":"باب القسامة","group":"كتاب الديات","units":[{"id":"q97_1","label":"باب القسامة · الفقرة ١","segs":[["matn","وإذا وجد القتيل في محلة ولا يعلم من قتله استحلف خمسون رجلا منهم"]]},{"id":"q97_2","label":"باب القسامة · الفقرة ٢","segs":[["matn","يتخيرهم الولي: بالله ما قتلناه ولا علمنا له قاتلا فإذا حلفوا قضي على أهل المحلة بالدية ولا يستحلف الولي ولا يقضي له بالجناية وإن لم يكمل أهل المحلة كررت الأيمان عليهم حتى يتم خمسون"]]},{"id":"q97_3","label":"باب القسامة · الفقرة ٣","segs":[["matn","ولا يدخل في القسامة صبي ولا مجنون"]]},{"id":"q97_4","label":"باب القسامة · الفقرة ٤","segs":[["matn","ولا امرأة ولا عبد وإن وجد ميت لا أثر به فلا قسامة ولا دية وكذلك إن كان الدم يسيل من أنفه أو من دبره أو من فمه فإن كان يخرج من عينيه أو من أذنه فهو قتيل"]]},{"id":"q97_5","label":"باب القسامة · الفقرة ٥","segs":[["matn","وإذا وجد القتيل على دابة يسوقها رجل فالدية على عاقلته دون أهل المحلة وإن وجد القتيل في دار إنسان فالقسامة عليه والدية على عاقلته"]]},{"id":"q97_6","label":"باب القسامة · الفقرة ٦","segs":[["matn","ولا يدخل السكان في القسامة مع الملاك عند أبي حنيفة وهي على أهل الخطة"]]},{"id":"q97_7","label":"باب القسامة · الفقرة ٧","segs":[["matn","دون المشترين ولو بقي منهم واحد وإن وجد القتيل في سفينة فالقسامة على من فيها من الركاب والملاحين وإن وجد القتيل في مسجد محلة فالقسامة على أهلها وإن وجد في الجامع أو الشارع الأعظم فلا قسامة فيه والدية على بيت المال وإن وجد في برية ليس بقربها عمارة فهو هدر وإن وجد بين قريتين كان على أقربهما وإن وجد في وسط الفرات بمر به الماء فهو هدر"]]},{"id":"q97_8","label":"باب القسامة · الفقرة ٨","segs":[["matn","فإن كان محتسبا بالشاطئ فهو على أقرب القرى من ذلك"]]},{"id":"q97_9","label":"باب القسامة · الفقرة ٩","segs":[["matn","المكان وإن ادعى الولي على واحد من أهل المحلة بعينه لم تسقط القسامة عنهم وإن ادعى على واحد من غيرهم سقطت عنهم القسامة"]]},{"id":"q97_10","label":"باب القسامة · الفقرة ١٠","segs":[["matn","وإذا قال المستحلف: قتله فلان استحلف بالله ما قتلت ولا عرفت له قاتلا غير فلان"]]},{"id":"q97_11","label":"باب القسامة · الفقرة ١١","segs":[["matn","وإذا شهد اثنان من أهل المحلة على رجل من غيرهم أنه قتله لم تقبل شهادتهما"]]}]},{"id":"q98","title":"باب المعاقل","group":"كتاب الديات","units":[{"id":"q98_1","label":"باب المعاقل · الفقرة ١","segs":[["matn","الدية في شبه العمد والخطإ وكل دية وجبت بنفس القتل على العاقلة"]]},{"id":"q98_2","label":"باب المعاقل · الفقرة ٢","segs":[["matn","والعاقلة: أهل الديوان إن كان القاتل من أهل الديوان يؤخذ من عطاياهم في ثلاث سنين فإن خرجت العطايا في أكثر من ثلاث سنين أو أقل أخذت منها ومن لم يكن من أهل الديوان فعاقلته قبيلته تقسط عليهم في ثلاث سنين لا يزاد الواحد على أربعة دراهم في كل سنة وينقض منها فإن لم تتسع القبيلة لذلك ضم إليهم أقرب القبائل من غيرهم"]]},{"id":"q98_3","label":"باب المعاقل · الفقرة ٣","segs":[["matn","ويدخل القاتل مع العاقلة فيكون فيما يؤدي مثل أحدهم"]]},{"id":"q98_4","label":"باب المعاقل · الفقرة ٤","segs":[["matn","وعاقلة المعتق قبيلة مولاه ومولى الموالاة يعقل عنه مولاه وقبيلته ولا تتحمل العاقلة أقل من نصف عشر الدية وتتحمل نصف العشر فصاعدا وما ينقص من ذلك فهو في مال الجاني"]]},{"id":"q98_5","label":"باب المعاقل · الفقرة ٥","segs":[["matn","ولا تعتقل العاقلة جناية العبد ولا تعقل الجناية التي اعترف بها الجاني إلا أن يصدقوه ولا تعقل ما لزم بالصلح"]]},{"id":"q98_6","label":"باب المعاقل · الفقرة ٦","segs":[["matn","وإذا جنى الحر على العبد جناية خطأ كانت على عاقلته"]]}]},{"id":"q99","title":"كتاب الحدود","group":"كتاب الحدود","units":[{"id":"q99_1","label":"كتاب الحدود · الفقرة ١","segs":[["matn","الزنا يثبت بالبينة والإقرارز"]]},{"id":"q99_2","label":"كتاب الحدود · الفقرة ٢","segs":[["matn","فالبينة: أن تشهد أربعة من الشهود على رجل أو امرأة بالزنا فيسألهم الإمام عن الزنا"]]},{"id":"q99_3","label":"كتاب الحدود · الفقرة ٣","segs":[["matn","ما هو؟ وكيف هو؟ وأين زنى؟ وبمن زنى؟ ومتى زنى؟ فإذا بينوا ذلك وقالوا: رأيناه وطئها في فرجها كالميل في المكحلة وسأل القاضي عنهم فعدلوا في السر والعلانية حكم بشهادتهم"]]},{"id":"q99_4","label":"كتاب الحدود · الفقرة ٤","segs":[["matn","والإقرار: أن يقر البالغ العاقل على نفسه بالزنا أربع مرات في أربعة مجالس من مجالس المقر كلما أقر رده القاضي فإذا تم إقراره أربع مرات سأله الإمام عن الزنا: ما هو؟ وكيف هو؟ وأين زنى؟ وبمن زنى؟ فإذا بين ذلك لزمه الحد"]]},{"id":"q99_5","label":"كتاب الحدود · الفقرة ٥","segs":[["matn","فإن كان الزاني محصنا رجمه بالحجارة حتى يموت يخرجه إلى أرض فضاء يبتدئ الشهود برجمه ثم الإمام ثم الناس فإن امتنع الشهود من الابتداء سقط الحد"]]},{"id":"q99_6","label":"كتاب الحدود · الفقرة ٦","segs":[["matn","وإن كان مقرا ابتدأ الإمام ثم الناس ويغسل ويكفن ويصلي عليه"]]},{"id":"q99_7","label":"كتاب الحدود · الفقرة ٧","segs":[["matn","وإن لم يكن محصنا وكان حرا فحده مائة جلدة يأمر الإمام بضربه بسوط لا ثمرة له ضربا متوسطا تنزع عنه ثيابه ويفرق الضرب على أعضائه إلا رأسه ووجهه وفرجه وإن كان عبدا جلده"]]},{"id":"q99_8","label":"كتاب الحدود · الفقرة ٨","segs":[["matn","خمسين وكذلك الأمة فإن رجع المقر عن إقراره قبل إقامة الحد عليه أو في وسطه قبل رجوعه وخلي سبيله"]]},{"id":"q99_9","label":"كتاب الحدود · الفقرة ٩","segs":[["matn","ويستحب للإمام أن يلقن المقر الرجوع ويقول له: لعلك لمست أو قبلت"]]},{"id":"q99_10","label":"كتاب الحدود · الفقرة ١٠","segs":[["matn","والرجل والمرأة في ذلك سواء غير أن المرأة لا تنزع عنها ثيابها إلا الفرو والحشو وإن حفر لها في الرجم جاز"]]},{"id":"q99_11","label":"كتاب الحدود · الفقرة ١١","segs":[["matn","ولا يقيم المولى الحد على عبده إلا بإذن الإمام"]]},{"id":"q99_12","label":"كتاب الحدود · الفقرة ١٢","segs":[["matn","وإذا رجع أحد الشهود بعد الحكم وقبل الرجم ضربوا الحد وسقط الرجم فإن رجع بعد الرجم حد الراجع وحده"]]},{"id":"q99_13","label":"كتاب الحدود · الفقرة ١٣","segs":[["matn","وضمن ربع الدية وإن نقص عدد الشهود عن أربعة حدوا"]]},{"id":"q99_14","label":"كتاب الحدود · الفقرة ١٤","segs":[["matn","وشرط إحصان الرجم: أن يكون حرا بالغا عاقلا مسلما قد تزوج امرأة نكاحا صحيحا ودخل بها وهما على صفة الإحصان"]]},{"id":"q99_15","label":"كتاب الحدود · الفقرة ١٥","segs":[["matn","ولا يجمع في المحصن بين الجلد والرجم ولا يجمع في البكر بين الجلد والنفي إلا أن يرى الإمام ذلك مصلحة فيغربه على قدر ما يراهوإذا زنى المريض وحده الرجم رجم وإن كان حده الجلد لم يجلد حتى يبرأ"]]},{"id":"q99_16","label":"كتاب الحدود · الفقرة ١٦","segs":[["matn","وإذا زنت الحامل لم تحد حتى تضع حملها فإن كان حدها الجلد فحتى تتعالى من نفسها وإذا كان حدها الرجم رجمت"]]},{"id":"q99_17","label":"كتاب الحدود · الفقرة ١٧","segs":[["matn","وإذا شهد الشهود بحد متقادم لم يقطعهم عن إقامته بعدهم عن الإمام لم تقبل"]]},{"id":"q99_18","label":"كتاب الحدود · الفقرة ١٨","segs":[["matn","شهادتهم إلا في حد القذف خاصة"]]},{"id":"q99_19","label":"كتاب الحدود · الفقرة ١٩","segs":[["matn","ومن وطئ أجنبية فيما دون الفرج عزز"]]},{"id":"q99_20","label":"كتاب الحدود · الفقرة ٢٠","segs":[["matn","ولا حد على من وطئ جارية ولده وولد ولده وإن قال: علمت أنها علي حرام: وإذا وطئ جارية أبيه أو أمه أو زوجته أو وطئ العبد جارية مولاه وقال: علمت أنها علي حرام حد وإن قال: ظننت أنها حلال حد"]]},{"id":"q99_21","label":"كتاب الحدود · الفقرة ٢١","segs":[["matn","ومن زفت إليه غير امرأته وقالت النساء: إنها زوجتك فوطئها فلا حد عليه"]]},{"id":"q99_22","label":"كتاب الحدود · الفقرة ٢٢","segs":[["matn","وعليه المهر ومن وجد امرأة على فراشه فوطئها فعليه الحد ومن تزوج امرأة لا يحل له نكاحها فوطئها لم يجب عليه الحد ومن أتى امرأة في الموضع المكروه أو عمل عمل قوم لوط فلا حد عليه عند أبي حنيفة ويعزر وقال أبو يوسف ومحمد: هو كالزنا ومن وطئ بهيمة فلا حد عليه"]]},{"id":"q99_23","label":"كتاب الحدود · الفقرة ٢٣","segs":[["matn","ومن زنى في دار الحرب أو دار البغي ثم خرج إلينا لم نقم عليه الحد"]]}]},{"id":"q100","title":"باب حد الشرب","group":"كتاب الحدود","units":[{"id":"q100_1","label":"باب حد الشرب · الفقرة ١","segs":[["matn","ومن شرب الخمر فأخذ وريحها موجود فشهد الشهود بذلك عليه أو أقل فعليه الحد وإن أقر بعد ذهاب رائحتها لم يحد"]]},{"id":"q100_2","label":"باب حد الشرب · الفقرة ٢","segs":[["matn","ومن سكر من النبيذ حد"]]},{"id":"q100_3","label":"باب حد الشرب · الفقرة ٣","segs":[["matn","ولا حد على من وجد منه رائحة الخمر أو تقيأها ولا يحد السكران حتى يعلم أنه سكر من النبيذ وشربه طوعا ولا يحد حتى يزول عنه السكر"]]},{"id":"q100_4","label":"باب حد الشرب · الفقرة ٤","segs":[["matn","وحد الخمر والسكر في الحد ثمانون سوطا يفرق على بدنه كما ذكرنا في الزنا وإن كان عبدا فحده أربعون سوطا"]]},{"id":"q100_5","label":"باب حد الشرب · الفقرة ٥","segs":[["matn","ومن أقرب بشرب الخمر أو السكر ثم رجع لم يحد"]]},{"id":"q100_6","label":"باب حد الشرب · الفقرة ٦","segs":[["matn","ويثبت الشرب بشهادة شاهدين وبإقراره مرة واحدة ولا تقبل فيه شهادة النساء مع الرجال"]]}]},{"id":"q101","title":"باب حد القذف","group":"كتاب الحدود","units":[{"id":"q101_1","label":"باب حد القذف · الفقرة ١","segs":[["matn","إذا قذف رجل رجلا محصنا أو امرأة محصنة بصريح الزنا وطالب المقذوف بالحد حده الحاكم ثمانين سوطا إن كان حرا يفرق على أعضائه ولا يجرد عن ثيابه غير أنه ينزع عنه الفرو والحشو وإن كان عبدا جلده أربعين"]]},{"id":"q101_2","label":"باب حد القذف · الفقرة ٢","segs":[["matn","والإحصان: أن يكون المقذوف حرا عاقلا بالغا مسلما عفيفا عن فعل الزنا"]]},{"id":"q101_3","label":"باب حد القذف · الفقرة ٣","segs":[["matn","ومن نفى نسب غيره فقال: لست لأبيك أو: يا ابن الزانية وأمه ميتة محصنة وطالب الابن بالحد حد القاذف ولا يطالب بحد القذف للميت إلا من يقع القدح في نسبه بقذفه"]]},{"id":"q101_4","label":"باب حد القذف · الفقرة ٤","segs":[["matn","وإن كان المقذوف محصنا جاز لابنه الكافر والعبد أن يطالب بالحد وليس للعبد أن يطالب مولاه بقذف أمه الحرة"]]},{"id":"q101_5","label":"باب حد القذف · الفقرة ٥","segs":[["matn","وإن أقر بالقذف ثم رجع لم يقبل رجوعه"]]},{"id":"q101_6","label":"باب حد القذف · الفقرة ٦","segs":[["matn","ومن قال لعربي: يا نبطئ لم يحد ومن قال لرجل: يا ابن ماء السماء فليس"]]},{"id":"q101_7","label":"باب حد القذف · الفقرة ٧","segs":[["matn","بقاذف وإذا نسبه إلى عمه أو خاله أو زوج أمه فليس بقاذف"]]},{"id":"q101_8","label":"باب حد القذف · الفقرة ٨","segs":[["matn","ومن وطئ وطئا حراما في غير ملكه لم يحد قاذفه والملاعنة بولد لا يحد قاذفها"]]},{"id":"q101_9","label":"باب حد القذف · الفقرة ٩","segs":[["matn","ومن قذف عبدا أو أمة أو كافرا بالزنا أو قذف مسلما"]]},{"id":"q101_10","label":"باب حد القذف · الفقرة ١٠","segs":[["matn","بغير الزنا فقال: يا فاسق أو يا كافر أو يا خبيث عزر وإن قال: يا حمار أو يا خنزير لم يعزر"]]},{"id":"q101_11","label":"باب حد القذف · الفقرة ١١","segs":[["matn","والتعزير: أكثره تسعة وثلاثون سوطا وأقله ثلاث جلدات وقال أبو يوسف: يبلغ بالتعزير خمسة وسبعين سوطا فإن رأى الإمام أن يضم إلى الضرب في التعزير الحبس فعل"]]},{"id":"q101_12","label":"باب حد القذف · الفقرة ١٢","segs":[["matn","وأشد الضرب التعزير ثم حد الزنا ثم حد الشرب ثم حد القذف"]]},{"id":"q101_13","label":"باب حد القذف · الفقرة ١٣","segs":[["matn","ومن حده الإمام أو عزره فمات فدمه هدر"]]},{"id":"q101_14","label":"باب حد القذف · الفقرة ١٤","segs":[["matn","وإذا حد المسلم في القذف سقطت شهادته وإن تاب وإن حد الكافر في القذف ثم أسلم قبلت شهادته والله أعلم"]]}]},{"id":"q102","title":"كتاب السرقة","group":"كتاب السرقة","units":[{"id":"q102_1","label":"كتاب السرقة · الفقرة ١","segs":[["matn","إذا سرق العاقل البالغ عشرة دارهم أو ما قيمته عشرة دراهم مضروبة أو غير مضروبة من حرز لا شبهة فيه وجب عليه القطع"]]},{"id":"q102_2","label":"كتاب السرقة · الفقرة ٢","segs":[["matn","والعبد والحر في القطع سواء"]]},{"id":"q102_3","label":"كتاب السرقة · الفقرة ٣","segs":[["matn","ويجب القطع بإقراره مرة واحدة أو بشهادة شاهدين"]]},{"id":"q102_4","label":"كتاب السرقة · الفقرة ٤","segs":[["matn","وإذا اشترك جماعة في سرقة فأصاب كل واحد منهم عشرة دراهم قطع وإن أصابه أقل من ذلك لم يقطع"]]},{"id":"q102_5","label":"كتاب السرقة · الفقرة ٥","segs":[["matn","ولا يقطع فيما يوجد تافها مباحا في دار الإسلام كالخشب والقصب والحشيس والسمك والطير والصيد وكذلك فيما يسرع إليه الفساد كالفواكه الرطبة واللبن واللحم والبطيخ والفاكهة على الشجر والزرع الذي لم يحص"]]},{"id":"q102_6","label":"كتاب السرقة · الفقرة ٦","segs":[["matn","ولا قطع في الأشربة المطربة"]]},{"id":"q102_7","label":"كتاب السرقة · الفقرة ٧","segs":[["matn","ولا في الطيور ولا في السرقة المصحف وإن كان عليه حلية ولا في الصليب الذهب ولا في الشطرنج ولا النرد ولا قطع على سارق الصبي الحر وإن كان عليه حلي ولا قطع في سرقة العبد الكبير ويقطع في سرقة العبد الصغير ولا قطع في الدفاتر كلها إلا في دفاتر الحساب ولا قطع في سرقة الكلب ولا فهد ولا دف ولا طبل ولا مزمار ويقطع في الساج والقنا والآبنوس والصندل وإذا اتخذ من الخشب أوان أو أبواب قطع فيها ولا قطع على خائن ولا خائنة ولا نباش"]]},{"id":"q102_8","label":"كتاب السرقة · الفقرة ٨","segs":[["matn","ولا منتهب ولا مختلس"]]},{"id":"q102_9","label":"كتاب السرقة · الفقرة ٩","segs":[["matn","ولا يقطع السارق من بيت المال ولا من مال للسارق فيه شركة ومن"]]},{"id":"q102_10","label":"كتاب السرقة · الفقرة ١٠","segs":[["matn","سرق من أبويه أو ولده أو ذي رحم محرم منه لم يقطع وكذلك إذا سرق أحد الزوجين من الآخر أو العبد من سيده أو من امرأة سيده أو زوج سيدته والمولى من مكاتبه والسارق من المغنم"]]},{"id":"q102_11","label":"كتاب السرقة · الفقرة ١١","segs":[["matn","والحرز على ضربين: حرز لمعنى فيه"]]},{"id":"q102_12","label":"كتاب السرقة · الفقرة ١٢","segs":[["matn","كالبيوت والدور وحرز بالحافظ فمن سرق شيئا من حرز أو غير حرز وصاحبه عنده يحفظه وجب عليه القطع ولا قطع على من سرق من حمام أو من بيت أذن للناس في دخوله"]]},{"id":"q102_13","label":"كتاب السرقة · الفقرة ١٣","segs":[["matn","ومن سرق من المسجد متاعا وصاحبه عنده قطع ولا قطع على الضيف إذا سرق ممن أضافه وإذا نقب اللص البيت فدخل فأخذ المال وناوله آخر خارج البيت فلا قطع عليهما وإن ألقاه في الطريق ثم خرج فأخذه قطع"]]},{"id":"q102_14","label":"كتاب السرقة · الفقرة ١٤","segs":[["matn","وكذلك إن حمله على حمار فساقه فأخرجه وإذا دخل الحرز جماعة فتولى بعضهم الأخذ قطعوا جميعا"]]},{"id":"q102_15","label":"كتاب السرقة · الفقرة ١٥","segs":[["matn","ومن نقب البيت وأدخل يده فيه فأخذ شيئا لم يقطع وإذا أدخل يده في صندوق الصيرفي أو في كم غيره فأخذ المال قطع"]]},{"id":"q102_16","label":"كتاب السرقة · الفقرة ١٦","segs":[["matn","وتقطع يمين السارق من الزند وتحسم فإن سرق ثانيا قطعت رجله اليسرى فإن سرق ثالثا لم يقطع وخلد في السجن حتى يتوب"]]},{"id":"q102_17","label":"كتاب السرقة · الفقرة ١٧","segs":[["matn","وإذا كان السارق أشل اليد اليسرى أو أقطع أو مقطوع الرجل"]]},{"id":"q102_18","label":"كتاب السرقة · الفقرة ١٨","segs":[["matn","اليمنى لم يقطع ولا يقطع السارق إلا أن يحضر المسروق منه فيطالب بالسرقة فإن وهبها من السارق أو باعها إياه أو نقصت قيمتها من النصاب لم يقطع"]]},{"id":"q102_19","label":"كتاب السرقة · الفقرة ١٩","segs":[["matn","ومن سرق عنيا فقطع فيها وردها ثم عاد فسرقها وهي بحالها لم يقطع فإن تغيرت عن حالها مثل أن كان غزلا فسرقة فقطع فيه فرده ثم نسج فعاد فسرقة قطع وإذا قطع السارق والعين قائمة في يده ردها وإن كانت هالكة لم يضمن وإذا ادعى السارق أن العين المسروقة ملكه سقط القطع عنه وإن لم يقم بنية"]]},{"id":"q102_20","label":"كتاب السرقة · الفقرة ٢٠","segs":[["matn","وإذا خرج جماعة ممتنعين أو واحد يقدر على الامتناع فقصدوا قطع الطريق فأخذوا قبل أن يأخذوا مالا ولا قتلوا نفسا حبسهم الإمام حتى يحدثوا توبة وإن أخذوا مال مسلم أو ذمي والمأخوذ إذا قسم على"]]},{"id":"q102_21","label":"كتاب السرقة · الفقرة ٢١","segs":[["matn","جماعتهم أصاب كل واحد منهم عشرة دراهم فصاعدا أو ما قيمته ذلك قطع الإمام أيديهم وأرجلهم من خلاف"]]},{"id":"q102_22","label":"كتاب السرقة · الفقرة ٢٢","segs":[["matn","وإن قتلوا ولم يأخذوا مالا قتلهم الإمام حدا فإن عفا الأولياء عنهم لم يلتفت إلى عفوهم وإن قتلوا وأخذوا المال فالإمام بالخيار: إن"]]},{"id":"q102_23","label":"كتاب السرقة · الفقرة ٢٣","segs":[["matn","شاء قطع أيديهم وأرجلهم من خلاف وقتلهم وصلبهم وإن شاء قتلهم وإن شاء صلبهم: يصلب حيا ويبعج بطنه بالرمح إلى أن يموت ولا يصلب أكثر من ثلاثة أيام"]]},{"id":"q102_24","label":"كتاب السرقة · الفقرة ٢٤","segs":[["matn","فإن كان فيهم صبي أو مجنون أو ذو رحم محرم من المقطوع عليه سقط الحد عن الباقين وصار القتل إلى الأولياء: إن شاؤوا قتلوا وإن شاؤا عفوا"]]},{"id":"q102_25","label":"كتاب السرقة · الفقرة ٢٥","segs":[["matn","وإن باشر الفعل واحد أجري الحد على جماعتهم"]]}]},{"id":"q103","title":"كتاب الأشربة","group":"كتاب الأشربة","units":[{"id":"q103_1","label":"كتاب الأشربة · الفقرة ١","segs":[["matn","الأشربة المحرمة أربعة: الخمر وهي: عصير العنب إذا إلى واشتد وقذف بالزبد والعصير إذا طبخ حتى ذهب أقل من ثلثيه ونقيع التمر والزبيب إذا اشتد ونبيذ التمر والزبيب إذا طبخ كل واحد منهما أدنى طبخ حلال وإن اشتد إذا شرب منه ما يغلب في ظنه أنه لا يسكره من غير لهو ولا طرب ولا بأس بالخليطين ونبيذ العسل والتين والحنطة والشعير والذرة حلال وإن لم يطبخ"]]},{"id":"q103_2","label":"كتاب الأشربة · الفقرة ٢","segs":[["matn","وعصير العنب إذا طبخ حتى ذهب منه ثلثاه وبقي ثلثه حلال وإن اشتد ولا بأس بالانتباذ في الدباء والحنتم والمزفت والنقير"]]},{"id":"q103_3","label":"كتاب الأشربة · الفقرة ٣","segs":[["matn","وإذا تخللت الخمر حلت سواء صارت خلا بنفسها أو بشيء طرح فيها ولا يكره تخليلها"]]}]},{"id":"q104","title":"كتاب الصيد والذبائح","group":"كتاب الصيد والذبائح","units":[{"id":"q104_1","label":"كتاب الصيد والذبائح · الفقرة ١","segs":[["matn","يجوز الاصطياد بالكلب المعلم والفهد والبازي وسائر الجوارح المعلمة"]]},{"id":"q104_2","label":"كتاب الصيد والذبائح · الفقرة ٢","segs":[["matn","وتعليم الكلب: أن يترك الأكل ثلاث مرات"]]},{"id":"q104_3","label":"كتاب الصيد والذبائح · الفقرة ٣","segs":[["matn","وتعليم البازي: أن يرجع إذا دعوته"]]},{"id":"q104_4","label":"كتاب الصيد والذبائح · الفقرة ٤","segs":[["matn","فإذا أرسل كلبه العلم أو بازيه أوصقره وذكر اسم الله تعالى عليه عند إرساله فأخذ الصيد وجرحه فمات حل أكله وإن أكل منه الكلب لم يؤكل وأن أكل منه البازي أكل وإذا أدرك المرسل الصيد حيا وجب عليه أن يذكيه فإن ترك تذكيته حتى مات لم يؤكل وإن خنقه الكلب ولم يجرحه لم يؤكل"]]},{"id":"q104_5","label":"كتاب الصيد والذبائح · الفقرة ٥","segs":[["matn","وإن شاركه كلب غير معلم أو كلب مجوسي أو كلب لم يذكر اسم الله تعالى عليه لم يؤكل"]]},{"id":"q104_6","label":"كتاب الصيد والذبائح · الفقرة ٦","segs":[["matn","وإذا رمى الرجل سهما إلى صيد فسمى عند الرمي أكل ما أصاب إذا جرحه السهم فمات وإن أدركه حيا ذكاه وإن ترك تذكيته حتى مات لم يؤكل وإن وقع السهم فتحامل حتى غاب عنه ولم يزل في طلبه حتى أصابه ميتا أكل وإن قعد عن طلبه ثم أصابه ميتا لم يؤكل وإذا رمة صيدا فوقع في الماء فمات لم يؤكل"]]},{"id":"q104_7","label":"كتاب الصيد والذبائح · الفقرة ٧","segs":[["matn","وكذلك إن وقع على سطح أو جبل ثم تردى منه إلى الأرض لم يؤكل وإن وقع على الأرض ابتداء أكل"]]},{"id":"q104_8","label":"كتاب الصيد والذبائح · الفقرة ٨","segs":[["matn","وما أصاب المعراض بعرضه لم يؤكل وإن جرحه أكل ولا يؤكل ما أصابته النبدقة إذا مات منها"]]},{"id":"q104_9","label":"كتاب الصيد والذبائح · الفقرة ٩","segs":[["matn","وإذا رمى إلى صيد فقطع عضوا منه أكل ولا يؤكل العضو وإن قطعه أثلاثا والأكثر مما يلي العجز"]]},{"id":"q104_10","label":"كتاب الصيد والذبائح · الفقرة ١٠","segs":[["matn","أكل وإن كان الأكثر مما يلي الرأس أكل الأكثر ولا يؤكل الأقل ولا يؤكل صيد المجوسي والمرتد والوثني"]]},{"id":"q104_11","label":"كتاب الصيد والذبائح · الفقرة ١١","segs":[["matn","ومن رمى صيدا فأصابه ولم يثخنه ولم يخرجه من حيز الإمتناع فرماه آخر فقتله فهو للثاني ويؤكل"]]},{"id":"q104_12","label":"كتاب الصيد والذبائح · الفقرة ١٢","segs":[["matn","وإن كان الأول أثخنه فرماه الثاني فقتله لم يؤكل والثاني ضامن بقيمته للأول غير ما نقصته جراحته"]]},{"id":"q104_13","label":"كتاب الصيد والذبائح · الفقرة ١٣","segs":[["matn","ويجوز اصطياد ما يؤكل لحمه من الحيوان"]]},{"id":"q104_14","label":"كتاب الصيد والذبائح · الفقرة ١٤","segs":[["matn","وما لا يؤكل وذبيحة المسلم والكتابي حلال ولا تؤكل ذبيحة المجوسي والمرتد والوثني والمحرم وإن ترك الذابح التسمية عمدا فالذبيحة ميتة لا تؤكل وإن تركها ناسيا أكلت"]]},{"id":"q104_15","label":"كتاب الصيد والذبائح · الفقرة ١٥","segs":[["matn","والذبح في الحلق واللبة"]]},{"id":"q104_16","label":"كتاب الصيد والذبائح · الفقرة ١٦","segs":[["matn","والعروق التي تقطع في الذكاة أربعة: الحلقوم والمريء والودجان فإذا قطعها حل الأكل وإن قطع أكثرها فكذلك عند أبي حنيفة وقال أبو يوسف ومحمد: لا بد من قطع الحلقوم والمريء وأحد الودجين"]]},{"id":"q104_17","label":"كتاب الصيد والذبائح · الفقرة ١٧","segs":[["matn","ويجوز الذبح بالليطة والمروة وبكل شيء أنهر الدم إلا السن القائم والظفر القائم"]]},{"id":"q104_18","label":"كتاب الصيد والذبائح · الفقرة ١٨","segs":[["matn","ويستحب أن يحد الذابح شفرته ومن بلغ بالسكين النخاع أو قطع الرأس كره له ذلك وتؤكل ذبيحته وإن ذبح الشاة من قفاها فإن بقيت حية قطع العروق جاز ويكره وإن ماتت قبل قطع العروق لم تؤكل"]]},{"id":"q104_19","label":"كتاب الصيد والذبائح · الفقرة ١٩","segs":[["matn","وما استأنس من الصيد فذكاته الذبح وما توحش من النعم فذكاته العقر والجرح"]]},{"id":"q104_20","label":"كتاب الصيد والذبائح · الفقرة ٢٠","segs":[["matn","والمستحب في الإبل النحر"]]},{"id":"q104_21","label":"كتاب الصيد والذبائح · الفقرة ٢١","segs":[["matn","فإن ذبحها جاز ويكره"]]},{"id":"q104_22","label":"كتاب الصيد والذبائح · الفقرة ٢٢","segs":[["matn","والمستحب في البقر والغنم الذبح فإن نحرهما جاز ويكره"]]},{"id":"q104_23","label":"كتاب الصيد والذبائح · الفقرة ٢٣","segs":[["matn","ومن نحر ناقة أو ذبح بقرة أو شاة فوجد في بطنها جنينا ميتا لم يؤكل أشعر أو لم يشعر"]]},{"id":"q104_24","label":"كتاب الصيد والذبائح · الفقرة ٢٤","segs":[["matn","ولا يجوز أكل كل ذي ناب من السباع وكل ذي مخلب من الطير ول ابأس بغراب الزرع ولا يؤكل الأبقع الذي يأكل الجيف"]]},{"id":"q104_25","label":"كتاب الصيد والذبائح · الفقرة ٢٥","segs":[["matn","ويكره أكل الضبع والضب والحشرات كلها"]]},{"id":"q104_26","label":"كتاب الصيد والذبائح · الفقرة ٢٦","segs":[["matn","ولا يجوز أكل لحم الحمر الأهلية والبغال ويكره لحم الفرس عند أبي حنيفة ولا بأس"]]},{"id":"q104_27","label":"كتاب الصيد والذبائح · الفقرة ٢٧","segs":[["matn","بأكل الأرنب وإذا ذبح ما لا يؤكل لحمه طهر لحمه وجلده"]]},{"id":"q104_28","label":"كتاب الصيد والذبائح · الفقرة ٢٨","segs":[["matn","إلا الآدمي والخنزير فإن الذكاة لا تعمل فيهما"]]},{"id":"q104_29","label":"كتاب الصيد والذبائح · الفقرة ٢٩","segs":[["matn","ولا يؤكل من حيوان الماء إلا السمك ويكره أكل الطافي منه ولا بأس بأكل الجريث والمارماهي"]]},{"id":"q104_30","label":"كتاب الصيد والذبائح · الفقرة ٣٠","segs":[["matn","ويجوز أكل الجراد ولا ذكاة له"]]}]},{"id":"q105","title":"كتاب الأضحية","group":"كتاب الأضحية","units":[{"id":"q105_1","label":"كتاب الأضحية · الفقرة ١","segs":[["matn","الأضحية واجبة على كل حر مسلم مقيم موسر في يوم الأضحى عن نفسه وولده الصغار يذبح عن"]]},{"id":"q105_2","label":"كتاب الأضحية · الفقرة ٢","segs":[["matn","كل واحد منهم شاة أو يذبح بدنة أو بقرة عن سبعة وليس على الفقير والمسافر أضحية ووقت الأضحية يدخل بطلوع الفجر من يوم النحر إلا أنه لا يجوز لأهل الأمصار الذبح حتى يصلي الإمام صلاة العيد فأما أهل السواد فيذبحون بعد الفجر"]]},{"id":"q105_3","label":"كتاب الأضحية · الفقرة ٣","segs":[["matn","وهي جائزة في ثلاثة أيام: يوم النحر ويومان بعده"]]},{"id":"q105_4","label":"كتاب الأضحية · الفقرة ٤","segs":[["matn","ولا يضحي بالعمياء والعوراء والعرجاء التي لا تمشي إلى المنسك ولا العجفاء ولا تجزئ مقطوعة الأذن والذنب ولا التي ذهب أكثر أذنها فإن بقي الأكثر من الأذن والذنب جاز"]]},{"id":"q105_5","label":"كتاب الأضحية · الفقرة ٥","segs":[["matn","ويجوز أن يضحى بالجماء والخصي والجرباء والثولاء"]]},{"id":"q105_6","label":"كتاب الأضحية · الفقرة ٦","segs":[["matn","والأضحية من الإبل والبقر والغنم يجزئ من ذلك كله الثني فصاعدا إلا الضمان فإن الجذع منه يجزئ"]]},{"id":"q105_7","label":"كتاب الأضحية · الفقرة ٧","segs":[["matn","ويأكل من لحم الأضحية ويطعم الأغنياء والفقراء ويدخر"]]},{"id":"q105_8","label":"كتاب الأضحية · الفقرة ٨","segs":[["matn","ويستحب أن لا ينقص الصدقة من الثلث ويتصدق بجلدها أو يعمل منه آلة تستعمل في البيت"]]},{"id":"q105_9","label":"كتاب الأضحية · الفقرة ٩","segs":[["matn","والأفضل أن يذبح أضحيته بيده إن كان يحسن الذبح"]]},{"id":"q105_10","label":"كتاب الأضحية · الفقرة ١٠","segs":[["matn","ويكره أن يذبحها الكتابي"]]},{"id":"q105_11","label":"كتاب الأضحية · الفقرة ١١","segs":[["matn","وإذا غلط رجلان فذبح كل واحد منهما أضحية الآخر أجزأ عنهما ولا ضمان عليهما"]]}]},{"id":"q106","title":"كتاب الأيمان","group":"كتاب الأيمان","units":[{"id":"q106_1","label":"كتاب الأيمان · الفقرة ١","segs":[["matn","الأيمان على ثلاثة أضرب: يمين غموس ويمين منعقدة ويمين لغو فاليمين الغموس هي: الحلف على أمر ماض يتعمد الكذب فيه"]]},{"id":"q106_2","label":"كتاب الأيمان · الفقرة ٢","segs":[["matn","فهذه اليمين يأثم بها صاحبها ولا كفارة فيها إلا الاستغفار"]]},{"id":"q106_3","label":"كتاب الأيمان · الفقرة ٣","segs":[["matn","واليمين المنعقدة: هي الحلف على الأمر المستقبل أن يفعله أو لا يفعله فإذا حنث في ذلك لزمته الكفارةز"]]},{"id":"q106_4","label":"كتاب الأيمان · الفقرة ٤","segs":[["matn","واليمين اللغو: أن يحلف على أمر ماض وهو يظن أنه كمال قال والأمر بخلافه فهذه نرجو أن لا يؤاخذ الله بها صاحبها"]]},{"id":"q106_5","label":"كتاب الأيمان · الفقرة ٥","segs":[["matn","والقاصد في اليمين والمكره والناسي سواء"]]},{"id":"q106_6","label":"كتاب الأيمان · الفقرة ٦","segs":[["matn","ومن فعل المحلوف عليه مكرها أو ناسيا سواء"]]},{"id":"q106_7","label":"كتاب الأيمان · الفقرة ٧","segs":[["matn","واليمين بالله تعالى أو باسم من أسمائه كالرحمن والرحيم"]]},{"id":"q106_8","label":"كتاب الأيمان · الفقرة ٨","segs":[["matn","أو بصفة من صفات ذاته كعزة الله وجلالته وكبريائه إلا قوله: وعلم الله فإنه لا يكون يمينا وإن حلف بصفة من صفات الفعل كغضب الله وسخطه لم يكن حالفا"]]},{"id":"q106_9","label":"كتاب الأيمان · الفقرة ٩","segs":[["matn","ومن حلف بغير الله لم يكن حالفا كالنبي والقرآن والكعبة"]]},{"id":"q106_10","label":"كتاب الأيمان · الفقرة ١٠","segs":[["matn","والحلف بحروف القسم وحروف القسم: الواو كقوله: والله والباء كقوله: بالله والتاء كقوله: تالله وقد تضمر الحروف فيكون حالفا كقوله: الله لا أفعل كذا وقال أبو حنيفة: إذا قال: وحق الله فليس بحالف"]]},{"id":"q106_11","label":"كتاب الأيمان · الفقرة ١١","segs":[["matn","وإذا قال: أقسم أو أقسم بالله أو أحلف بالله أو أشهد أو أشهد بالله فهو حالف وكذلك قوله: وعهد الله وميثاقه وعلي نذر أو نذر الله وإن فعلت كذا فأنا يهودي أو نصراني أو كافر فهو يمين"]]},{"id":"q106_12","label":"كتاب الأيمان · الفقرة ١٢","segs":[["matn","وإن قال: علي غضب الله أو سخطه أو أنا زان أو شارب خمر أو آكل ربا فليس بحالف"]]},{"id":"q106_13","label":"كتاب الأيمان · الفقرة ١٣","segs":[["matn","وكفارة اليمين: عتق رقبة يجزئ فيها ما يجزئ في الطهار"]]},{"id":"q106_14","label":"كتاب الأيمان · الفقرة ١٤","segs":[["matn","وإن شاء كسا عشرة مساكين كل واحد ثوبا فما زاد وأذناه ما تجزئ فيه الصلاة وإن شاء أطعم عشرة مساكين كالإطعام في كفارة الظهار فإن لم يقدر على أحد الأشياء الثلاثة صام ثلاثة أيام متتابعات فإن قدم الكفارة على الحنث لم يجزه"]]},{"id":"q106_15","label":"كتاب الأيمان · الفقرة ١٥","segs":[["matn","ومن حلف على معصية مثل أن لا يصلي أو لا يكلم أباه أو ليقتلن فلانا فينبغي أن يحنث ويكفر عن يمينه"]]},{"id":"q106_16","label":"كتاب الأيمان · الفقرة ١٦","segs":[["matn","وإذا حلف الكافر ثم حنث في حال الكفر أو بعد إسلامه فلا حنث عليه"]]},{"id":"q106_17","label":"كتاب الأيمان · الفقرة ١٧","segs":[["matn","ومن حرم على نفسه شيئا مما يملكه لم يصر محرما لعينه وعليه أن استباحه كفارة يمين فإن قال: كل حلال علي حرام فهو على الطعام والشراب إلا أن ينوي غير ذلك"]]},{"id":"q106_18","label":"كتاب الأيمان · الفقرة ١٨","segs":[["matn","ومن نذر نذرا مطلقا فعليه الوفاء به"]]},{"id":"q106_19","label":"كتاب الأيمان · الفقرة ١٩","segs":[["matn","وإن علق نذره بشرط فوجد الشرط فعليه الوفاء بنفس النذر وروي أن أبا حنيفة رجع عن ذلك وقال: إذا قال: إن"]]},{"id":"q106_20","label":"كتاب الأيمان · الفقرة ٢٠","segs":[["matn","فعلت كذا فعلي حجة أو صوم سنة أو صدقة ما أملكه أجزأه من ذلك كفارة يمين وهو قول محمد"]]},{"id":"q106_21","label":"كتاب الأيمان · الفقرة ٢١","segs":[["matn","ومن خلف لا يدخل بيتا فدخل الكعبة أو المسجد أو البيعة أو الكنيسة لم يحنث"]]},{"id":"q106_22","label":"كتاب الأيمان · الفقرة ٢٢","segs":[["matn","ومن حلف لا يتكلم فقرأ في الصلاة لم يحنث"]]},{"id":"q106_23","label":"كتاب الأيمان · الفقرة ٢٣","segs":[["matn","ومن حلف لا يلبس ثوبا وهو لابسه فنزعه في الحال لم"]]},{"id":"q106_24","label":"كتاب الأيمان · الفقرة ٢٤","segs":[["matn","يحنث وكذا إذا حلف لا يركب هذه الدابة وهو راكبها فنزل في الحال وإن لبث ساعة حنث وإن حلف لا يدخل هذه الدار وهو فيها لم يحنث بالقعود حتى يخرج ثم يدخل"]]},{"id":"q106_25","label":"كتاب الأيمان · الفقرة ٢٥","segs":[["matn","ومن حلف لا يدخل دارا فدخل دارا خرابا لم يحنث"]]},{"id":"q106_26","label":"كتاب الأيمان · الفقرة ٢٦","segs":[["matn","ومن حلف لا يدخل هذه الدار فدخلها بعد ما انهدمت وصارت صحراء حنث ولو حلف لا يدخل هذا البيت فدخله بعد ما انهدم لم يحنث"]]},{"id":"q106_27","label":"كتاب الأيمان · الفقرة ٢٧","segs":[["matn","ومن حلف لا يكلم زوجة فلان فطلقها فلان ثم كلمها حنث"]]},{"id":"q106_28","label":"كتاب الأيمان · الفقرة ٢٨","segs":[["matn","ولو حلف لا يكلم عبد فلان أو لا يدخل دار فلان فباع عبده وداره ثم كلم العبد ودخل الدار لم يحنث وإن حلف لا يكلم صاحب هذا الطيلسان فباعه ثم كلمه حنث وكذلك إن حلف لا يكلم هذا الشاب فكلمه بعد ما صار شيخا حنث أو لا يأكل لحم هذا الحمل فصار كبشا فأكله حنث وإن حلف لا يأكل من هذه النخلة فهو على ثمرها وإن حلف لا يأكل من هذا البسر فصار رطبا فأكله لم يحنث وإن حلف لا يأكل بسرا فأكل رطبا لم يحنث"]]},{"id":"q106_29","label":"كتاب الأيمان · الفقرة ٢٩","segs":[["matn","ومن حلف لا يأكل رطبا فأكل بسرا مذنبا حنث عند أبي حنيفة"]]},{"id":"q106_30","label":"كتاب الأيمان · الفقرة ٣٠","segs":[["matn","ومن حلف لا يأكل لحما فأكل السمك لم يحنث"]]},{"id":"q106_31","label":"كتاب الأيمان · الفقرة ٣١","segs":[["matn","ومن حلف لا يشرب من دجله فشرب منها بإناء لم يحنث حتى يكرع منها كرعا في قول أبي حنيفة ومن حلف لا يشرب من ماء دجلة فشرب منها بإناء حنث"]]},{"id":"q106_32","label":"كتاب الأيمان · الفقرة ٣٢","segs":[["matn","ومن حلف لا يأكل من هذه الحنطة فأكل من خبزها لم يحنث"]]},{"id":"q106_33","label":"كتاب الأيمان · الفقرة ٣٣","segs":[["matn","ولو حلف لا يأكل من هذا الدقيق بأكل من خبزه حنث ولو استفه كما هو لم يحنث ولو حلف لا يكلم فلانا فكلمه وهو بحيث يسمع إلا أنه نائم حنث وإن حلف لا يكلمه إلا بإذنه فأذن له ولم يعلم بالأذن حتى كلمه حنث"]]},{"id":"q106_34","label":"كتاب الأيمان · الفقرة ٣٤","segs":[["matn","وإذا استحلف الوالي رجلا ليعلمه بكل داعر دخل البلد فهذا على حال ولايته خاصة"]]},{"id":"q106_35","label":"كتاب الأيمان · الفقرة ٣٥","segs":[["matn","ومن حلف لا يركب دابة فلان فركب دابة عبده لم يحنث"]]},{"id":"q106_36","label":"كتاب الأيمان · الفقرة ٣٦","segs":[["matn","ومن حلف لا يدخل هذه الدار فوقف على سطحها أو دخل دهليزها حنث"]]},{"id":"q106_37","label":"كتاب الأيمان · الفقرة ٣٧","segs":[["matn","وإن وقف في طاق الباب يحيث إذا أغلق الباب كان خارجا لم يحنث"]]},{"id":"q106_38","label":"كتاب الأيمان · الفقرة ٣٨","segs":[["matn","ومن حلف لا يأكل الشواء فهو على اللحم دون الباذنجان والجزر"]]},{"id":"q106_39","label":"كتاب الأيمان · الفقرة ٣٩","segs":[["matn","ومن حلف لا يأكل الطبيخ فهو على ما يطبخ من اللحم"]]},{"id":"q106_40","label":"كتاب الأيمان · الفقرة ٤٠","segs":[["matn","ومن حلف لا يأكل الرؤوس فيمتنه على ما يكبس في التنانير ويباع في المصر"]]},{"id":"q106_41","label":"كتاب الأيمان · الفقرة ٤١","segs":[["matn","ومن حلف لا يأكل الخبز فيمتنه على ما يعتاد أهل البلد أكله خبزا فإن أكل خبز القطائف أو خبز الأرز بالعراق لم يحنث"]]},{"id":"q106_42","label":"كتاب الأيمان · الفقرة ٤٢","segs":[["matn","ومن حلف لا يبيع أو لا يشتري أولا يؤاجر فوكل بذلك لم يحنث"]]},{"id":"q106_43","label":"كتاب الأيمان · الفقرة ٤٣","segs":[["matn","ومن حلف لا يتزوج أو لا يطلق أو لا يعلق لوكل بذلك حنث"]]},{"id":"q106_44","label":"كتاب الأيمان · الفقرة ٤٤","segs":[["matn","ومن حلف لا يجلس على الأرض فجلس على بساط أو حصير لم يحنث"]]},{"id":"q106_45","label":"كتاب الأيمان · الفقرة ٤٥","segs":[["matn","ومن حلف لا يجلس على سرير فجلس على سرير فوقه بساط حنث وإن جعل"]]},{"id":"q106_46","label":"كتاب الأيمان · الفقرة ٤٦","segs":[["matn","فوقه سريرا فجلس عليه لم يحنث"]]},{"id":"q106_47","label":"كتاب الأيمان · الفقرة ٤٧","segs":[["matn","وإن حلف لا ينام على فراش فنام عليه وفوقه قوام حنث وإن جعل فوقه فراشا آخر لم يحنث"]]},{"id":"q106_48","label":"كتاب الأيمان · الفقرة ٤٨","segs":[["matn","ومن حلف بيمين وقال: إن شاء الله متصلا بيمينه فلا حنث عليه وإن حلف ليأتينه إن استطاع فهذا على استطاعة الصحة دون القدرة"]]},{"id":"q106_49","label":"كتاب الأيمان · الفقرة ٤٩","segs":[["matn","وإن حلف لا يكلم فلانا حينا أو زمانا أو الحين أو الزمان فهو على ستة أشهر وكذلك الدهر عند أبي يوسف ومحمد"]]},{"id":"q106_50","label":"كتاب الأيمان · الفقرة ٥٠","segs":[["matn","ولو حلف لا يكلمه أياما على ثلاثة أيام ولو حلف لا يكلمه الأيام فهو على عشرة أيام عند أبي حنيفة وقال أبو يوسف ومحمد: على أيام الأسبوع ولو حلف لا يكلمه الشهور فهو على عشرة أشهر عند أبي حنيفة وقال أبو يوسف ومحمد: على اثني عشر شهرا"]]},{"id":"q106_51","label":"كتاب الأيمان · الفقرة ٥١","segs":[["matn","وإذا حلف لا يفعل كذا تركه أبدا وإن حلف ليفعلن كذا ففعله مرة واحدة بر في يمينه"]]},{"id":"q106_52","label":"كتاب الأيمان · الفقرة ٥٢","segs":[["matn","ومن حلف لا تخرج امرأته إلا بإذنه فأذن لها مرة"]]},{"id":"q106_53","label":"كتاب الأيمان · الفقرة ٥٣","segs":[["matn","فخرجت ثم خرجت مرة أخرى بغير إذنه حنث ولا بد من إذن في كل خروج وإن قال: إلا أن آذن لك فأذن لها مرة ثم خرجت بعدها بغير إذنه لم يحنث"]]},{"id":"q106_54","label":"كتاب الأيمان · الفقرة ٥٤","segs":[["matn","وإذا حلف لا يتغدى فالغداء الأكل من طلوع الفجر إلى الظهر والعشاء من صلاة الظهر إلى نصف الليل والسحور من نصف الليل إلى طلوع الفجر"]]},{"id":"q106_55","label":"كتاب الأيمان · الفقرة ٥٥","segs":[["matn","وإن حلف ليقضين دينه إلى قريب فهو ما دون الشهر وإن قال: إلى بعيد فهو أكثر من الشهر"]]},{"id":"q106_56","label":"كتاب الأيمان · الفقرة ٥٦","segs":[["matn","ومن حلف لا يسكن هذه الدار فخرج منها نفسه وترك فيها"]]},{"id":"q106_57","label":"كتاب الأيمان · الفقرة ٥٧","segs":[["matn","أهله ومتاعه حنث ومن حلف ليصعد السماء أوليقلبن هذا الحجر ذهبا انعقدت يمينه وحنث عقيبها"]]},{"id":"q106_58","label":"كتاب الأيمان · الفقرة ٥٨","segs":[["matn","ومن حلف ليقضين فلانا دينه اليوم فقضاه ثم وجد فلان بعضه زيوفا أو نبهرجة أو مستحقة لم يحنث وإن وجدها رصاصا أو ستوقة حنث"]]},{"id":"q106_59","label":"كتاب الأيمان · الفقرة ٥٩","segs":[["matn","ومن حلف لا يقبض دينه درهما دون درهم فقبض بعضه لم يحنث"]]},{"id":"q106_60","label":"كتاب الأيمان · الفقرة ٦٠","segs":[["matn","حتى يقبض متفرقا وإن قبض دينه في وزنتين لم يتشاغل بينهما إلا بعمل الوزن لم يحنث وليس ذلك بتفريق"]]},{"id":"q106_61","label":"كتاب الأيمان · الفقرة ٦١","segs":[["matn","ومن حلف ليأتين البصرة فلم يأتها حتى مات حنث في آخر جزء من أجزاء حياته"]]}]},{"id":"q107","title":"كتاب الدعوى","group":"كتاب الدعوى","units":[{"id":"q107_1","label":"كتاب الدعوى · الفقرة ١","segs":[["matn","المدعي: من لا يجبر على الخصومة إذا تركها"]]},{"id":"q107_2","label":"كتاب الدعوى · الفقرة ٢","segs":[["matn","والمدعى عليه: من يجبر على الخصومة"]]},{"id":"q107_3","label":"كتاب الدعوى · الفقرة ٣","segs":[["matn","ولا تقبل الدعوى حتى يذكر شيئا معلوما في جنسه وقدره فإن كان عينا في يد المدعى عليه كلف إحضارها ليشير إليها بالدعوى وإن لم تكن حاضرة ذكر قيمتها وإن ادعى عقارا حدده وذكر أنه في يد المدعى عليه وأنه يطالبه به وإن كان حقا في الذمة ذكر أنه يطالبه به"]]},{"id":"q107_4","label":"كتاب الدعوى · الفقرة ٤","segs":[["matn","فإذا صحت الدعوى سأل القاضي المدعى عليه عنها فإن اعترف قضى عليه بها"]]},{"id":"q107_5","label":"كتاب الدعوى · الفقرة ٥","segs":[["matn","وإن أنكر سأل المدعى البينة فإن أحضرها قضى بها وإن عجز عن ذلك وطلب يمين خصمه استحلف عليها"]]},{"id":"q107_6","label":"كتاب الدعوى · الفقرة ٦","segs":[["matn","فإن قال: لي بينة وطلب اليمين لم يستحلف عند أبي حنيفة"]]},{"id":"q107_7","label":"كتاب الدعوى · الفقرة ٧","segs":[["matn","ولا ترد اليمين على المدعي"]]},{"id":"q107_8","label":"كتاب الدعوى · الفقرة ٨","segs":[["matn","ولا تقبل بينه صاحب اليد في الملك المطلق"]]},{"id":"q107_9","label":"كتاب الدعوى · الفقرة ٩","segs":[["matn","وإذا نكل المدعى عليه عن اليمين قضي عليه بالنكول ولزمه ما ادعى عليه"]]},{"id":"q107_10","label":"كتاب الدعوى · الفقرة ١٠","segs":[["matn","وينبغي للقاضي أن يقول له: إني أعرض اليمين عليك ثلاثا فإن حلفت وإلا قضيت عليك بما ادعاه فإذا كرر العرض ثلاث مرات قضى عليه بالنكول"]]},{"id":"q107_11","label":"كتاب الدعوى · الفقرة ١١","segs":[["matn","وإن كانت الدعوى نكاحا لم يستحلف المنكر عند أبي حنيفة"]]},{"id":"q107_12","label":"كتاب الدعوى · الفقرة ١٢","segs":[["matn","ولا يستحلف في النكاح والرجعة"]]},{"id":"q107_13","label":"كتاب الدعوى · الفقرة ١٣","segs":[["matn","والفيء في الإيلاء والرق والاستيلاد والنسب والولاء والحدود"]]},{"id":"q107_14","label":"كتاب الدعوى · الفقرة ١٤","segs":[["matn","وقال أبو يوسف ومحمد: يستحلف في ذلك كله إلا في الحدود والقصاص"]]},{"id":"q107_15","label":"كتاب الدعوى · الفقرة ١٥","segs":[["matn","وإذا ادعى اثنان عينا في يد آخر كل واحد منهما يزعم أنها له وأقاما البينة قضي بها بينهما"]]},{"id":"q107_16","label":"كتاب الدعوى · الفقرة ١٦","segs":[["matn","وإن ادعى كل واحد منهما نكاح امرأة وأقاما البينة لم يقض بواحدة من البينتين ويرجع إلى تصديق المرأة لأحدهما"]]},{"id":"q107_17","label":"كتاب الدعوى · الفقرة ١٧","segs":[["matn","وإن ادعى اثنان كل واحد منهما أنه اشترى منه هذا العبد وأقاما البينة فكل واحد منهما بالخيار: إن شاء أخذ نصف العبد بنصف الثمن وإن شاء ترك فإن قضى القاضي بينهما به فقال أحدهما: لا أختار لم يكن للآخر أن يأخذ جميعه وإن ذكر واحد منهما تاريخا فهو للأول منهما وإن لم يذكرا ومع أحدهما قبض فهو أولى به"]]},{"id":"q107_18","label":"كتاب الدعوى · الفقرة ١٨","segs":[["matn","وإن ادعى أحدهما شراء والآخر هبة وقبضا وأقاما"]]},{"id":"q107_19","label":"كتاب الدعوى · الفقرة ١٩","segs":[["matn","البينة ولا تاريخ معهما فالشراء أولى"]]},{"id":"q107_20","label":"كتاب الدعوى · الفقرة ٢٠","segs":[["matn","وإن ادعى أحدهما الشراء وادعت امرأة أنه تزوجها عليه فهما سواء"]]},{"id":"q107_21","label":"كتاب الدعوى · الفقرة ٢١","segs":[["matn","وإن ادعى أحدهما رهنا وقبضا والآخر هبة وقبضا فالرهن أولى وإن أقام الخارجان البينة على الملك والتاريخ فصاحب التاريخ الأبعد أولى وإن ادعيا الشراء من واحد وأقاما البينة على التاريخين فالأول أولى وإن أقام كل واحد منهما بينة على الشراء من آخر وذكرا تاريخا فهما سواء وإن أقام الخارج البينة على ملك مؤرخ وأقام صاحب اليد البينة على ملك أقدم تاريخا كان أولى"]]},{"id":"q107_22","label":"كتاب الدعوى · الفقرة ٢٢","segs":[["matn","وإن أقام الخارج وصاحب اليد كل واحد منهما بينة بالنتاج فصاحب اليد أولى وكذلك النسج في الثياب التي لا تنسج إلا مرة واحدة وكل سبب في الملك لا يتكرر فهو كذلك وإن أقام الخارج البينة على الملك وصاحب اليد بينة على الشراء منه كان أولى وإن أقام كل واحد منهما البينة على الشراء من الآخر ولا تاريخ معهما تهاترت البينتان"]]},{"id":"q107_23","label":"كتاب الدعوى · الفقرة ٢٣","segs":[["matn","وإن أقام أحد المدعيين شاهدين والآخر أربعة فهما سواء"]]},{"id":"q107_24","label":"كتاب الدعوى · الفقرة ٢٤","segs":[["matn","ومن ادعى قصاصا على غيره فجحد"]]},{"id":"q107_25","label":"كتاب الدعوى · الفقرة ٢٥","segs":[["matn","استحلف فإن نكل عن اليمين فيما دون النفس لزمه القصاص وإن نكل في النفس حبس حتى يقر أو يحلف وقال أبو يوسف ومحمد: يلزمه الأرض فيهما"]]},{"id":"q107_26","label":"كتاب الدعوى · الفقرة ٢٦","segs":[["matn","وإذا قال المدعي: لي بينة حاضرة قيل لخصمه: أعطه كفيلا بنفسك ثلاثة أيام فإن فعل وإلا أمر بملازمته إلا أن يكون غريبا على الطريق فيلازمه مقدار مجلس القاضي"]]},{"id":"q107_27","label":"كتاب الدعوى · الفقرة ٢٧","segs":[["matn","وإن قال المدعى عليه: هذا الشيء أودعنيه فلان الغائب أو رهنه عندي أو غصبته منه وأقام بينة على ذلك فلا خصومة بينه وبين المدعي"]]},{"id":"q107_28","label":"كتاب الدعوى · الفقرة ٢٨","segs":[["matn","وإن قال: ابتعته من الغائب فهو خصم"]]},{"id":"q107_29","label":"كتاب الدعوى · الفقرة ٢٩","segs":[["matn","وإن قال المدعي: سرق مني وأقام البينة وقال صاحب اليد: أودعينه فلان وأقام البينة لم تندفع الخصومة"]]},{"id":"q107_30","label":"كتاب الدعوى · الفقرة ٣٠","segs":[["matn","وإن قال المدعي: ابتعته من فلان وقال صاحب اليد: أودعنيه فلان ذلك سقطت الخصومة بغير بينة"]]},{"id":"q107_31","label":"كتاب الدعوى · الفقرة ٣١","segs":[["matn","واليمين بالله تعالى دون غيره ويؤكد بذكر أوصافه ولا يستحلف بالطلاق ولا بالعتاق ويستحلف اليهوديث بالله الذي أنزل التوراة على موسى والنصراي بالله الذي أنزل الإنجيلع على عيسى والمجوسي بالله الذي حلق النار"]]},{"id":"q107_32","label":"كتاب الدعوى · الفقرة ٣٢","segs":[["matn","ولا يحلفون في بيوت عباداتهم"]]},{"id":"q107_33","label":"كتاب الدعوى · الفقرة ٣٣","segs":[["matn","ولا يجب تغليظ اليمين على المسلم بزمان ولا بمكان"]]},{"id":"q107_34","label":"كتاب الدعوى · الفقرة ٣٤","segs":[["matn","ومن ادعى أنه ابتاع من هذا عبده بألف فجحد يستحلف بالله ما بينكما بيع قائم فيه ولا يستحلف بالله ما بعت ويستحلف في الغضب بالله ما يستحق عليك رده ولا يحلف بالله ما غصبت وفي النكاح بالله ما بينكما نكاح قائم"]]},{"id":"q107_35","label":"كتاب الدعوى · الفقرة ٣٥","segs":[["matn","في الحال وفي دعوى الطلاق بالله ما هي بائن منك الساعة بما ذكرت ولا يستحلف بالله ما طلقتها"]]},{"id":"q107_36","label":"كتاب الدعوى · الفقرة ٣٦","segs":[["matn","وإذا كانت دار في يد رجل ادعاها أحدهما جميعها والآخر نصفها وأقاما البينة فللصاحب الجميع ثلاثة أرباعها ولصاحب النصف ربعها عند أبي حنيفة وقال أبو يوسف ومحمد: هي بينهما أثلاثا ولو كانت في أيديهما سلمت لصاحب الجميع: نصفها على وجه القضاء ونصفها لا على وجه القضاء"]]},{"id":"q107_37","label":"كتاب الدعوى · الفقرة ٣٧","segs":[["matn","وإذا تنازعا في دابة وأقام كل واحد منهما بينة أنها نتجت عنده وذكرا تاريخا وسن الدابة يوافق أحد التاريخين فهو أولى وإن أشكل ذلك كانت بينهما"]]},{"id":"q107_38","label":"كتاب الدعوى · الفقرة ٣٨","segs":[["matn","وإذا تنازعا دابة أحدهما راكبها والآخر متعلق بلجامها فالراكب أولى وكذلك إذا تنازعا بعيرا وعليه حمل لأحدهما الحمل أولى وكذلك إذا تنازعا قميصا أحدهما لابسه والآخر متعلق بكمه فاللابس أولى"]]},{"id":"q107_39","label":"كتاب الدعوى · الفقرة ٣٩","segs":[["matn","وإذا اختلف المتبايعان في البيع فادعى أحدهما ثمنا وادعى البائع أكثر منه أو اعترف البائع بقدر من المبيع وادعى المشتري أكثر منه وأقام أحدهما البينة قضي له بها"]]},{"id":"q107_40","label":"كتاب الدعوى · الفقرة ٤٠","segs":[["matn","وإن أقام كل واحد منهما البينة كانت البينة المثبتة للزيادة أولى وإن لم تكن لكل واحد بينة قيل للمشتري: إما أن ترضى بالثمن الذي ادعاه البائع وإلا فسخنا البيع وقيل للبائع: إما أن تسلم ما ادعاه المشتري من المبيع وإلا فسخنا البيع فإن لم يتراضيا استحلف الحاكم كل واحد منهما على دعوى الآخر يبتدئ بيمين المشتري فإذا حلفا فسخ القاضي البيع بينهما وإن نكل أحدهما عن اليمين لزمه دعوى الآخر"]]},{"id":"q107_41","label":"كتاب الدعوى · الفقرة ٤١","segs":[["matn","وإن اختلفا في الأجل أو في شرط الخيار أو في استيفاء بعض الثمن فلا تحالف بينهما والقول قول من ينكر الخيار والأجل مع يمينه"]]},{"id":"q107_42","label":"كتاب الدعوى · الفقرة ٤٢","segs":[["matn","وإن هلك المبيع ثم اختلفا لم يتحالفا عند أبي حنيفة وأبي يوسف وجعل القول قول المشتري وقال محمد: يتحالفان ويفسخ البيع على قيمة الهالك"]]},{"id":"q107_43","label":"كتاب الدعوى · الفقرة ٤٣","segs":[["matn","وإن هلك أحد العبدين ثم اختلفا في الثمن لم يتحالفا عند أبي حنيفة إلا أن يرضى البائع أن يترك حصة الهالك وقال أبو يوسف: يتحالفان ويفسخ العقد في الحي وقال محمد رحمه الله يتحالفان عليهما ويفسخ العقد ويرد الحي وقيمة الهالك"]]},{"id":"q107_44","label":"كتاب الدعوى · الفقرة ٤٤","segs":[["matn","وإذا اختلف الزوجان في المهر فادعى الزوج أنه تزوجها بألف وقالت: تزوجتني بألفين فأيهما أقام البينة قبلت بينة"]]},{"id":"q107_45","label":"كتاب الدعوى · الفقرة ٤٥","segs":[["matn","وإن أقاما البينة فالبينة بينة المرأة وإن لم تكن لهما بينة تحالفا عند أبي حنيفة ولم يفسخ النكاح ولكن يحكم مهر المثل"]]},{"id":"q107_46","label":"كتاب الدعوى · الفقرة ٤٦","segs":[["matn","فإن كان مثل ما اعترف به الزوج أو أقل قضي بما قال الزوج وإن كان مثل ما ادعته المرأة أو أكثر قضي بما ادعته المرأة وإن كان مهر المثل أكثر مما اعترف به الزوج وأقل مما ادعته المرأة قضي لها بمهر المثل"]]},{"id":"q107_47","label":"كتاب الدعوى · الفقرة ٤٧","segs":[["matn","وإذا اختلفا في الإجازة قبل استيفاء المعقود عله تحالفا وترادا وإن اختلفا بعد الاستيفاء لم يتحالفا وكان القول قول المستأجر"]]},{"id":"q107_48","label":"كتاب الدعوى · الفقرة ٤٨","segs":[["matn","وإن اختلفا بعد استيفاء بعض العقود عليه تحالفا وفسخ العقد فيما بقي وكان القول في الماضي قول المستأجر"]]},{"id":"q107_49","label":"كتاب الدعوى · الفقرة ٤٩","segs":[["matn","وإذا اختلف المولى والمكاتب في مال الكتابة لم يتحالفا عند أبي حنيفة وقال أبو يوسف ومحمد: يتحالفان وتفسخ الكتابة"]]},{"id":"q107_50","label":"كتاب الدعوى · الفقرة ٥٠","segs":[["matn","وإذا اختلف الزوجان في متاع البيت فما يصلح للرجال فهو للرجل وما يصلح للنساء فهو للمرأة وما يصلح لهما فهو للرجل"]]},{"id":"q107_51","label":"كتاب الدعوى · الفقرة ٥١","segs":[["matn","وإذا مات أحدهما واختلف ورثته مع"]]},{"id":"q107_52","label":"كتاب الدعوى · الفقرة ٥٢","segs":[["matn","الآخر فما يصلح للرجال والنساء فهو للباقي منهما وقال أبو يوسف: يدفع إلى المرأة ما يجهز به مثلها والباقي للزوج"]]},{"id":"q107_53","label":"كتاب الدعوى · الفقرة ٥٣","segs":[["matn","وإذا باع الرجل الجارية فجاءت لولد فادعاه البائع فإن جاءت به لأقل من ستة أشهر من يوم البيع فهو ابن البائع وأمة أم ولد له فيفسخ البيع فيه ويرد الثمن وإن ادعاه المشتري مع دعوى البائع أو بعده فدعوى البائع أولى وإن جاءت به لأكثر من ستة أشهر لم تقبل دعوى البائع فيه إلا أن يصدقه المشتري"]]},{"id":"q107_54","label":"كتاب الدعوى · الفقرة ٥٤","segs":[["matn","وإن مات الولد فادعاه البائع وقد جاءت به لأقل من ستة أشهر لم يثبت الاستيلاد في الأم وإن ماتت الأم فادعى البائع الابن وقد جاءت به لأقل من ستة أشهر يثبت النسب منه في الولد وأخذه البائع ويرد الثمن كله في قول أبي حنيفة وقال أبو يوسف ومحمد: يرد حصة الولد ولا يرد حصة الأم"]]},{"id":"q107_55","label":"كتاب الدعوى · الفقرة ٥٥","segs":[["matn","ومن ادعى نسب أحد التوأمين ثبت نسبهما منه والله أعلم"]]}]},{"id":"q108","title":"كتاب الشهادات","group":"كتاب الشهادات","units":[{"id":"q108_1","label":"كتاب الشهادات · الفقرة ١","segs":[["matn","الشهادة: فرض يلزم الشهود اداؤها ولا يسعهم كتمانها إذا طالبهم المدعي"]]},{"id":"q108_2","label":"كتاب الشهادات · الفقرة ٢","segs":[["matn","والشهادة في الحدود يخير فيها الشاهد بين"]]},{"id":"q108_3","label":"كتاب الشهادات · الفقرة ٣","segs":[["matn","الستر والإظهار والستر أفضل إلا أنه يجب أن يشهد بالمال في السرقة فيقول: أخذ ولا يقول: سرق"]]},{"id":"q108_4","label":"كتاب الشهادات · الفقرة ٤","segs":[["matn","والشهادة على مراتب: منها الشهادة في الزنا يعتبر فيها أربعة من الرجال ولا تقبل فيها شهادة النساء ومنها الشهادة ببقية الحدود والقصاص تقبل فيها شهادة رجلين ولا تقبل فيها شهادة النساء"]]},{"id":"q108_5","label":"كتاب الشهادات · الفقرة ٥","segs":[["matn","وما سوى ذلك من الحقوق تقبل فيها شهادة رجلين"]]},{"id":"q108_6","label":"كتاب الشهادات · الفقرة ٦","segs":[["matn","أو رجلين وامرأتين سواء كان الحق مالا أو غير مال مثل النكاح مثل النكاح والطلاق والوكالة والوصية"]]},{"id":"q108_7","label":"كتاب الشهادات · الفقرة ٧","segs":[["matn","وتقبل في الولادة والبكارة والعيوب بالنساء في موضع لا يطلع عليه الرجال شهادة امرأة واحدة"]]},{"id":"q108_8","label":"كتاب الشهادات · الفقرة ٨","segs":[["matn","ولا بد في ذلك كله من العدالة"]]},{"id":"q108_9","label":"كتاب الشهادات · الفقرة ٩","segs":[["matn","ولفظ الشهادة فإن لم يذكر الشاهد لفظ الشهادة وقال: أعلم أو أتيقن لم تقبل شهادته"]]},{"id":"q108_10","label":"كتاب الشهادات · الفقرة ١٠","segs":[["matn","وقال أبو حنيفة: يقتصر الحاكم على ظاهر عدالة المسلم إلا في الحدود والقصاص فإنه يسأل عن الشهود وإن طعن الخصم فيهم سأل عنهم وقال أبو يوسف"]]},{"id":"q108_11","label":"كتاب الشهادات · الفقرة ١١","segs":[["matn","ومحمد: لا بد أن يسأل عنهم في السر والعلانية"]]},{"id":"q108_12","label":"كتاب الشهادات · الفقرة ١٢","segs":[["matn","وما يتحمله الشاهد على ضربين: أحدهما: ما يثبت حكمه بنفسه مثل البيع والإقرار والغصب والقتل وحكم الحاكم فإذا سمع ذلك الشاهد أو رآه وسعه أن يشهد به وإن لم يشهد عليه ويقول: أشهد أنه باع ولا يقول: أشهدني"]]},{"id":"q108_13","label":"كتاب الشهادات · الفقرة ١٣","segs":[["matn","ومنه ما لا يثبت حكمه بنفسه مثل الشهادة على الشهادة فإن سمع شاهدا يشهد بشيء لم يجز أن يشهد على شهادته"]]},{"id":"q108_14","label":"كتاب الشهادات · الفقرة ١٤","segs":[["matn","إلا أن يشهده وكذلك لو سمعه يشهد الشاهد على شهادته لم يسع السامع أن يشهد"]]},{"id":"q108_15","label":"كتاب الشهادات · الفقرة ١٥","segs":[["matn","ولا يحل للشاهد إذا رأى خطه أن يشهد إلا أن يذكر الشهادة"]]},{"id":"q108_16","label":"كتاب الشهادات · الفقرة ١٦","segs":[["matn","ولا تقبل شهادة الأعمى ولا المملوك ولا المحدود في قذف وإن تاب ولا شهادة الوالد لولده وولد ولده ولا شهادة الولد لأبويه وأجداده"]]},{"id":"q108_17","label":"كتاب الشهادات · الفقرة ١٧","segs":[["matn","ولا تقبل شهادة أحد الزوجين للآخر"]]},{"id":"q108_18","label":"كتاب الشهادات · الفقرة ١٨","segs":[["matn","ولا شهادة المولى لعبده ولا لمكاتبه ولا شهادة الشريك لشريكه فيما هو من شركتهما"]]},{"id":"q108_19","label":"كتاب الشهادات · الفقرة ١٩","segs":[["matn","وتقبل شهادة الرجل لأخيه وعمه"]]},{"id":"q108_20","label":"كتاب الشهادات · الفقرة ٢٠","segs":[["matn","ولا تقبل شهادة مخنث ولا نائحة ولا مغنية ولا مدمن الشرب على اللهو ولا من يلعب بالطيور ولا من يغني للناس"]]},{"id":"q108_21","label":"كتاب الشهادات · الفقرة ٢١","segs":[["matn","ولا من يأتي بابا من الكبائر التي يتعلق بها الحد ولا من يدخل الحمام بغير إزار أو يأكل الربا ولا المقامر بالنرد والشطرنج ولا من يفعل الأفعال المستخفة كالبول على الطريق والأكل على الطريق"]]},{"id":"q108_22","label":"كتاب الشهادات · الفقرة ٢٢","segs":[["matn","ولا تقبل شهادة من يظهر سب السلف وتقبل شهادة أهل الأهواء إلا الخطابية"]]},{"id":"q108_23","label":"كتاب الشهادات · الفقرة ٢٣","segs":[["matn","وتقبل شهادة أهل الذمة بعضهم على بعض وإن اختلفت مللهم ولا تقبل شهادة الحربي على الذمي"]]},{"id":"q108_24","label":"كتاب الشهادات · الفقرة ٢٤","segs":[["matn","وإن كانت الحسنات أغلب من السيئات والرجل ممن يجتنب الكبائر قبلت شهادته وإن أمل بمعصية"]]},{"id":"q108_25","label":"كتاب الشهادات · الفقرة ٢٥","segs":[["matn","وتقبل شهادة الأقلف والخصي وولد الزنا وشهادة الخنثى جائزة"]]},{"id":"q108_26","label":"كتاب الشهادات · الفقرة ٢٦","segs":[["matn","وإذا وافقت الشهادة الدعوى قبلت وإن خالفتها لم تقبل ويعتبر اتفاق الشاهدين في اللفظ والمعنى عند أبي حنيفة"]]},{"id":"q108_27","label":"كتاب الشهادات · الفقرة ٢٧","segs":[["matn","فإن شهد أحدهما بألف والآخر بألفين لم تقبل الشهادة وإن شهد أحدهما بألف والآخر بألف وخمسمائة والمدعي يدعي ألفا وخمسمائة قبلت شهادتهما بألف"]]},{"id":"q108_28","label":"كتاب الشهادات · الفقرة ٢٨","segs":[["matn","وإذا شهد أحدهما لأفل وقال: قضاه منها خمسمائة قبلت شهادته بألف ولم يسمع قوله: إنه قضاه إلا أن يشهد معه آخر وينبغي للشاهد إذا علم ذلك أن لا يشهد بألف حتى يقر المدعي أنه قبض خمسمائة"]]},{"id":"q108_29","label":"كتاب الشهادات · الفقرة ٢٩","segs":[["matn","وإذا شهد شاهدان أن زيدا قتل يوم النحر بمكة وشهد آخران أنه قتل يوم النحر بالكوفة واجتمعوا عند الحاكم لم يقبل الشهادتين فإن سبقت إحداهما فقضى بها ثم حضرت الأخرى لم تقبل ولا يسمع القاضي الشهادة على جرح ولا يحكم بذلك"]]},{"id":"q108_30","label":"كتاب الشهادات · الفقرة ٣٠","segs":[["matn","ولا يجوز للشاهد أن يشهد بشيء لم يعاينه إلا النسب والموت والنكاح والدخول وولاية القاضي فإنه يسعه أن يشهد بهذه الأشياء إذا اخبره بها من يثق به"]]},{"id":"q108_31","label":"كتاب الشهادات · الفقرة ٣١","segs":[["matn","والشهادة على الشهادة جائزة في كل حق لا يسقط بالشبهة ولا تقبل في الحدود والقصاص"]]},{"id":"q108_32","label":"كتاب الشهادات · الفقرة ٣٢","segs":[["matn","وتجوز شهادة شاهدين على شهادة شاهدين ولا تقبل شهادة واحد على شهادة واحد"]]},{"id":"q108_33","label":"كتاب الشهادات · الفقرة ٣٣","segs":[["matn","وصفة الإشهاد أن يقول شاهد لشاهد الفرع: اشهد على شهادتين أني أشهد أن فلان ابن فلان أقر عندي بكذا وأشهدني على نفسه وإن لم يقل: أشهدني على نفسه جاز ويقول شاهد الفرع عند الأداء: أشهد أن فلان ابن فلان أشهدني على شهادته أنه يشهد أن فلانا أقر عنده بكذا وقال لي: اشهد على شهادتي بذلك"]]},{"id":"q108_34","label":"كتاب الشهادات · الفقرة ٣٤","segs":[["matn","ولا تقبل شهادة شهود الفرع إلا أن يموت شهود الأصل أو يغيبوا مسيرة ثلاثة أيام فصاعدا أو يمرضوا مرضا لا يستطيعون معه حضور مجلس الحاكم"]]},{"id":"q108_35","label":"كتاب الشهادات · الفقرة ٣٥","segs":[["matn","وإن عدل شهود الأصل شهود الفرع جاز"]]},{"id":"q108_36","label":"كتاب الشهادات · الفقرة ٣٦","segs":[["matn","فإن سكتوا عن تعديلهم جاز وينظر القاضي في حالهم وإن أنكر شهود الأصل الشهادة لم تقبل شهادة شهود الفرع"]]},{"id":"q108_37","label":"كتاب الشهادات · الفقرة ٣٧","segs":[["matn","وقال أبو حنيفة في شاهد الزور: أشهر في السوق ولا أعزره وقال أبو يوسف ومحمد: نوجعه ضربا ونحبسه"]]}]},{"id":"q109","title":"باب الرجوع عن الشهادة","group":"كتاب الشهادات","units":[{"id":"q109_1","label":"باب الرجوع عن الشهادة · الفقرة ١","segs":[["matn","إذا رجع الشهود عن شهادتهم قبل الحكم بها سقطت وإن حكم بشهادتهم ثم رجعوا لم يفسخ الحكم ووجب عليهم ضمان ما أتلفوه بشهادتهم ولا يصح الرجوع إلا بحضرة الحاكم"]]},{"id":"q109_2","label":"باب الرجوع عن الشهادة · الفقرة ٢","segs":[["matn","وإذا شهد شاهدان بمال فحكم الحاكم به ثم رجعا ضمنا المال المشهود عليه وإن رجع أحدهما ضمن النصف وإن شهد بالمال ثلاثة فرجع أحدهم فلا ضمان عليه فإن رجع آخر ضمن الراجعان نصف المال"]]},{"id":"q109_3","label":"باب الرجوع عن الشهادة · الفقرة ٣","segs":[["matn","وإن شهد رجل وامرأتان فرجعت امرأة ضمنت ربع الحق وإن رجعنا ضمنتا نصف الحق"]]},{"id":"q109_4","label":"باب الرجوع عن الشهادة · الفقرة ٤","segs":[["matn","وإن شهد رجل وعشر نسوة ثم رجع ثمان منهن فلا ضمان عليهن وإن رجعت آخرى كان على النسوة ربع الحق فإن رجع الرجل والنساء فعلى الرجل سدس الحق وعلى النسوة خمسة أسداس الحق عند أبي حنيفة وقال أبو يوسف ومحمد: على الرجل النصف وعلى النسوة النصف"]]},{"id":"q109_5","label":"باب الرجوع عن الشهادة · الفقرة ٥","segs":[["matn","وإن شهد شاهدان على امرأة بالنكاح بمقدار مهر مثلها ثم رجعا فلا ضمان عليهما وكذلك إن شهدا على رجل بتزوج امرأة بمقدار مهر مثلها وإن شهدا بأكثر من مهر المثل ثم رجعا ضمنا الزيادة"]]},{"id":"q109_6","label":"باب الرجوع عن الشهادة · الفقرة ٦","segs":[["matn","وإن شهدا ببيع بمثل القيمة أو أكثر ثم رجعا لم يضمنا وإن كان بأقل من القيمة ضمنا النقصان"]]},{"id":"q109_7","label":"باب الرجوع عن الشهادة · الفقرة ٧","segs":[["matn","وإن شهدا على رجل أنه طلق امرأته قبل الدخول ثم رجعا ضمنا نصف"]]},{"id":"q109_8","label":"باب الرجوع عن الشهادة · الفقرة ٨","segs":[["matn","المهر فإن كان الدخول لم يضمنا وإن شهدا أنه أعتق عبده ثم رجعا ضمنا قيمته"]]},{"id":"q109_9","label":"باب الرجوع عن الشهادة · الفقرة ٩","segs":[["matn","وإن شهدا بقصاص ثم رجعا بعد القتل ضمنا الدية ولا يقتص منهما"]]},{"id":"q109_10","label":"باب الرجوع عن الشهادة · الفقرة ١٠","segs":[["matn","وإذا رجع شهود الفرع ضنوا وإن رجع شهود الأصل وقالوا: لم نشهد شهود الفرع على شهادتنا فلا ضمان عليهم وإن قالوا: أشهدناهم وغلطنا ضمنوا"]]},{"id":"q109_11","label":"باب الرجوع عن الشهادة · الفقرة ١١","segs":[["matn","وإن قال شهود الفرع: كذب شهود الأصل أو غلطوا في شهادتهم ثم يلتفت إلى ذلك"]]},{"id":"q109_12","label":"باب الرجوع عن الشهادة · الفقرة ١٢","segs":[["matn","وإذا شهدوا أربعة بالزنا وشاهدان بالإحصان فرجع شهود الإحصان لم يضمنوا وإذا رجع المزكون عن التزكية ضمنوا"]]},{"id":"q109_13","label":"باب الرجوع عن الشهادة · الفقرة ١٣","segs":[["matn","وإذا شهد شاهدان باليمين وشاهدان بوجود الشرط ثم رجعوا فالضمان على شهود اليمين خاصة"]]}]},{"id":"q110","title":"كتاب أدب القاضي","group":"كتاب أدب القاضي","units":[{"id":"q110_1","label":"كتاب أدب القاضي · الفقرة ١","segs":[["matn","لا تصح ولاية القاضي حتى يجتمع في المولى شرائط الشهادة"]]},{"id":"q110_2","label":"كتاب أدب القاضي · الفقرة ٢","segs":[["matn","ويكون من أهل الاجتهاد ولا بأس بالدخول في القضاء لمن يثق أنه يؤدي فرضه ويكره الدخول فيه لمن يخاف العجز عنه ولا يأمن على نفسه الحيف فيه ولا ينبغي أن يطلب الولاية ولا يسألها"]]},{"id":"q110_3","label":"كتاب أدب القاضي · الفقرة ٣","segs":[["matn","ومن قلد القضاء يسلم إليه ديوان القاضي الذي قبله وينظر في حال المحبوسين فمن اعترف بحق ألزمه إياه ومن أنك لم يقبل قول المعزول عليه إلا بينة وإن لم تقم بينة لم يعجل بتخليته حتى ينادي عليه ويستظهر في أمره"]]},{"id":"q110_4","label":"كتاب أدب القاضي · الفقرة ٤","segs":[["matn","وينظر في الودائع وارتفاع الوقوف فيعمل على ما تقوم به البينة أو يعترف به من هو في يده"]]},{"id":"q110_5","label":"كتاب أدب القاضي · الفقرة ٥","segs":[["matn","ولا يقبل قول المعزول إلا أن يعترف الذي هو في يده أن"]]},{"id":"q110_6","label":"كتاب أدب القاضي · الفقرة ٦","segs":[["matn","المعزول سلمها إليه فيقبل قوله فيها"]]},{"id":"q110_7","label":"كتاب أدب القاضي · الفقرة ٧","segs":[["matn","ويجلس للحكم جلوسا ظاهرا في المسجد"]]},{"id":"q110_8","label":"كتاب أدب القاضي · الفقرة ٨","segs":[["matn","ولا يقبل هدية إلا من ذي رحم محرم أو ممن جرت عادته قبل القضاء بمهاداته"]]},{"id":"q110_9","label":"كتاب أدب القاضي · الفقرة ٩","segs":[["matn","ولا يحضر دعوة إلا أن تكون عامة ويشهد الجنازة ويعود المريض"]]},{"id":"q110_10","label":"كتاب أدب القاضي · الفقرة ١٠","segs":[["matn","ولا يضيف أحد الخصمين دون خصمه وإذا حضرا سوى بينهما في المجلوس والإقبال: ولا يسار أحدهما ولا يشير إليه ولا يلقنه حجة"]]},{"id":"q110_11","label":"كتاب أدب القاضي · الفقرة ١١","segs":[["matn","فإذا ثبت الحق عند وطلب صاحب الحق حبس"]]},{"id":"q110_12","label":"كتاب أدب القاضي · الفقرة ١٢","segs":[["matn","غريمه لم يعجل بحبسه وأمره بدفع ما عليه فإن امتنع حبسه"]]},{"id":"q110_13","label":"كتاب أدب القاضي · الفقرة ١٣","segs":[["matn","في كل دين لزمه بدلا عن مال حصل في يده كثمن المبيع وبدل القرض أو التزمه بعقد كالمهر والكفالة"]]},{"id":"q110_14","label":"كتاب أدب القاضي · الفقرة ١٤","segs":[["matn","ولا يحبسه فيما سوى ذلك إذا قال: إني فقير إلا أن يثبت غريمه أن له مالا ويحبسه شهرين أو ثلاثة ثم يسأل عنه فإن لم يظهر له مال خلى سبيله"]]},{"id":"q110_15","label":"كتاب أدب القاضي · الفقرة ١٥","segs":[["matn","ولا يحول بينه وبين غرمائه"]]},{"id":"q110_16","label":"كتاب أدب القاضي · الفقرة ١٦","segs":[["matn","ويحبس الرجل في نفقة زوجته ولا يحبس والد في دين ولده إلا إذا امتنع من الإنفاق عليه"]]},{"id":"q110_17","label":"كتاب أدب القاضي · الفقرة ١٧","segs":[["matn","ويجوز قضاء المرأة في كل شيء إلا في الحدود والقصاص"]]},{"id":"q110_18","label":"كتاب أدب القاضي · الفقرة ١٨","segs":[["matn","ويقبل كتاب القاضي إلى القاضي في الحقوق إذا شهد به عنده فإن شهدوا على خصم حكم بالشهادة وكتب بحكمه وإن شهدوا بغير حضرة خصم لم يحكم وكتب بالشهادة ليحكم بها المكتوب إليه"]]},{"id":"q110_19","label":"كتاب أدب القاضي · الفقرة ١٩","segs":[["matn","ولا يقبل الكتاب إلا بشهادة رجلين أو رجل وامرأتين ويجب أن يقرأ الكتاب عليهم ليعوفوا ما فيه ثم يختمه بحضرتهم ويسلمه إليهم فإذا وصل إلى القاضي لم يقبله إلا بحضرة الخصم فإن شهدوا أنه كتاب فلان القاضي سلمه إلينا في مجلس حكمه وقرأه علينا وختمه فضه القاضي وقرأه على الخصم وألزمه ما فيه"]]},{"id":"q110_20","label":"كتاب أدب القاضي · الفقرة ٢٠","segs":[["matn","ولا يقبل كتاب القاضي إلى القاضي في الحدود والقصاص وليس للقاضي أن يستخلف على القضاء إلا أن يفوض ذلك إليه"]]},{"id":"q110_21","label":"كتاب أدب القاضي · الفقرة ٢١","segs":[["matn","وإذا رفع القاضي حكم حاكم أمضاه"]]},{"id":"q110_22","label":"كتاب أدب القاضي · الفقرة ٢٢","segs":[["matn","إلا أن يخالف الكتاب أو السنة أو الإجماع أو يكون قولا لا دليل عليه"]]},{"id":"q110_23","label":"كتاب أدب القاضي · الفقرة ٢٣","segs":[["matn","ولا يقضي القاضي على غائب إلا أن يحضر من يقوم مقامه"]]},{"id":"q110_24","label":"كتاب أدب القاضي · الفقرة ٢٤","segs":[["matn","وإذا حكم رجلان رجلا ليحكم بينهما ورضيا بحكمه جاز إذا كان"]]},{"id":"q110_25","label":"كتاب أدب القاضي · الفقرة ٢٥","segs":[["matn","بصفة الحاكم ولا يجوز تحكيم الكافر والعبد والذمي والمحدود في القذف والفاسق والصبي"]]},{"id":"q110_26","label":"كتاب أدب القاضي · الفقرة ٢٦","segs":[["matn","ولكل واحد من المحكمين أن يرجع ما لم يحكم عليهما فإذا حكم لزمهما وإذا رفع حكمه إلى القاضي فوافق مذهبه أمضاه وإن خالفه أبطله"]]},{"id":"q110_27","label":"كتاب أدب القاضي · الفقرة ٢٧","segs":[["matn","ولا يجوز التحكيم في الحدود والقصاص"]]},{"id":"q110_28","label":"كتاب أدب القاضي · الفقرة ٢٨","segs":[["matn","وإن حكما في دم خطإ فقضى الحاكم على العاقلة بالدية لم ينفذ حكمه"]]},{"id":"q110_29","label":"كتاب أدب القاضي · الفقرة ٢٩","segs":[["matn","ويجوز أن يسمع البينة ويقضي بالنكول"]]},{"id":"q110_30","label":"كتاب أدب القاضي · الفقرة ٣٠","segs":[["matn","وحكم الحاكم لأبويه وولده وزوجته باطل"]]}]},{"id":"q111","title":"كتاب القسمة","group":"كتاب القسمة","units":[{"id":"q111_1","label":"كتاب القسمة · الفقرة ١","segs":[["matn","ينبغي للإمام أن ينصب قاسما يرقه من بيت المال ليقسم بين الناس بغير أجرة"]]},{"id":"q111_2","label":"كتاب القسمة · الفقرة ٢","segs":[["matn","فإن لم يفعل نصب قاسما بالأجرة"]]},{"id":"q111_3","label":"كتاب القسمة · الفقرة ٣","segs":[["matn","ويجب أن يكون عدلا مأمونا عالما بالقسمة"]]},{"id":"q111_4","label":"كتاب القسمة · الفقرة ٤","segs":[["matn","ولا يجبر القاضي الناس على قاسم واحد ولا يترك القسام يشتركون"]]},{"id":"q111_5","label":"كتاب القسمة · الفقرة ٥","segs":[["matn","وأجر القسمة على عدد الرؤوس عند أبي حنيفة وقال أبو يوسف ومحمد: على قدر الأنصاء"]]},{"id":"q111_6","label":"كتاب القسمة · الفقرة ٦","segs":[["matn","وإذا حضر الشركاء وفي أيديهم دار أو ضيعة ادعوا أنهم رثوها عن فلان لم يقسمها عند أبي حنيفة"]]},{"id":"q111_7","label":"كتاب القسمة · الفقرة ٧","segs":[["matn","حتى يقيموا البيئة على موته وعدد ورثته"]]},{"id":"q111_8","label":"كتاب القسمة · الفقرة ٨","segs":[["matn","وقال أبو يوسف ومحمد: يقسمها باعترافهم ويذكر في كتاب القسمة أنه قسمها بقولهم وإذا كان المال المشترك ما سوى العقار وادعوا أنه ميراث قسمه في قولهم جميعا وإن ادعوا في العقار اشتروه قسمه بينهم وإن ادعوا الملك ولم يذكروا كيف انتقل قسمه بينهم"]]},{"id":"q111_9","label":"كتاب القسمة · الفقرة ٩","segs":[["matn","وإذا كان كل واحد من الشركاء ينتفع بنصيبه قسم بطلب أحدهم"]]},{"id":"q111_10","label":"كتاب القسمة · الفقرة ١٠","segs":[["matn","وإن كان أحدهم ينتفع والآخر يستضر لقلة نصيبه فإن طلب صاحب الكثير قسم وإن طلب صاحب القليل لم يقسم وإن كان كل واحد يستضر لم يقسمها إلا بتراضيها"]]},{"id":"q111_11","label":"كتاب القسمة · الفقرة ١١","segs":[["matn","ويقسم العروض إذا كانت من صنف واحد ولا يقسم الجنسان بعضهما في بعض"]]},{"id":"q111_12","label":"كتاب القسمة · الفقرة ١٢","segs":[["matn","وقال أبو حنيفة: لا يقسم الرقيق ولا الجوهر لتفاوته وقال أبو يوسف ومحمد: يقسم الرقيق"]]},{"id":"q111_13","label":"كتاب القسمة · الفقرة ١٣","segs":[["matn","ولا يقسم حمام ولا بئر ولا رحى إلا أن يتراضى الشركاء"]]},{"id":"q111_14","label":"كتاب القسمة · الفقرة ١٤","segs":[["matn","وإذا حضر وارثان وأقاما البينة على الوفاة وعدد الورثة والدار في أيديهم ومعهم وارث غائب قسمها القاضي بطلب الحاضرين وينصب للغائب وكيلا يقبض نصيبه"]]},{"id":"q111_15","label":"كتاب القسمة · الفقرة ١٥","segs":[["matn","وإن كانوا مشترين لم يقسم مع غيبة أحدهم"]]},{"id":"q111_16","label":"كتاب القسمة · الفقرة ١٦","segs":[["matn","وإن كان العقار في يد الوارث الغائب لم يقسم وإن حضر وارث واحد لم يقسم"]]},{"id":"q111_17","label":"كتاب القسمة · الفقرة ١٧","segs":[["matn","وإذا كانت دور مشتركة في مصر واحد قسمت كل دار على"]]},{"id":"q111_18","label":"كتاب القسمة · الفقرة ١٨","segs":[["matn","حدتها في قول أبي حنيفة رحمه الله"]]},{"id":"q111_19","label":"كتاب القسمة · الفقرة ١٩","segs":[["matn","وقالا: إن كان الأصلح لهم قسمة بعضها في بعض قسمها"]]},{"id":"q111_20","label":"كتاب القسمة · الفقرة ٢٠","segs":[["matn","وإن كانت دار وضيعة أو دار وحانوت قسم كل واحد على حدته"]]},{"id":"q111_21","label":"كتاب القسمة · الفقرة ٢١","segs":[["matn","وينبغي للقاسم: أن يصور ما يقسمه ويعدله ويذرعه ويقوم البناء ويفرز كل نصيب عن الباقي بطريقة وشربه حتى لا يكون لنصيب بعضهم بنصيب الآخر تعلق ثم يلقب نصيبا بالأول"]]},{"id":"q111_22","label":"كتاب القسمة · الفقرة ٢٢","segs":[["matn","والذي يليه بالثاني والثالث وعلى هذا ثم يخرج القرعة فمن خرج اسمه أولا فله السهم الأول ومن خرج ثانيا فله السهم الثاني"]]},{"id":"q111_23","label":"كتاب القسمة · الفقرة ٢٣","segs":[["matn","ولا يدخل في القسمة الدراهم والدنانير إلا بتراضيهم"]]},{"id":"q111_24","label":"كتاب القسمة · الفقرة ٢٤","segs":[["matn","وإن قسم بينهم ولأحدهم مسيل ي مل الآخر أو طريق لم يشترط في القسمة: فإن أمكن صرف الطريق والمسيل عنه فليس له أن يستطرق ويسيل في نصيب الآخر وإن لم يمكن فسخت القسمة"]]},{"id":"q111_25","label":"كتاب القسمة · الفقرة ٢٥","segs":[["matn","وإن كان سفل لا علو له وعلو لا سفل له وسفل له علو قوم كل واحد على حدته وقسم بالقيمة ولا معتبر بغير ذلك"]]},{"id":"q111_26","label":"كتاب القسمة · الفقرة ٢٦","segs":[["matn","وإذا اختلف المتقاسمون فشهد القاسمان قبلت شهادتهما"]]},{"id":"q111_27","label":"كتاب القسمة · الفقرة ٢٧","segs":[["matn","فإن ادعى أحدهما الغلط وزعم أن مما أصابه شيئا في يد صاحبه وقد أشهد على نفسه بالاستيفاء لم يصدق على ذلك إلا ببينة"]]},{"id":"q111_28","label":"كتاب القسمة · الفقرة ٢٨","segs":[["matn","وإن قال: استوفيت حقي ثم قال: أخذت بعضه فالقول قول خصمه مع يمينه"]]},{"id":"q111_29","label":"كتاب القسمة · الفقرة ٢٩","segs":[["matn","وإن قال: أصابني إلى موضع كذا فلم تسلمه إلىولم يشهد على نفسه بالاستيفاء وكذبه شريكه تحالفا وفسخت القسمة"]]},{"id":"q111_30","label":"كتاب القسمة · الفقرة ٣٠","segs":[["matn","وإن استحق بعض نصيب أحدهما بعينه لم تفسخ القسمة عند أبي حنيفة ورجع بحصة ذلك من نصب شريكه وقال أبو يوسف: تفسخ القسمة"]]}]},{"id":"q112","title":"كتاب الإكراه","group":"كتاب الإكراه","units":[{"id":"q112_1","label":"كتاب الإكراه · الفقرة ١","segs":[["matn","الإكراه يثبت حكمه إذا حصل ممن يقدر على إيقاع ما توعد به سلطانا كان أو لصا"]]},{"id":"q112_2","label":"كتاب الإكراه · الفقرة ٢","segs":[["matn","وإذا أكره الرجل على بيع ماله أو على شراء سلعة أو على أن يقر لرجل بألف أو يؤاجر داره - وأكره على ذلك بالقتل أو بالضرب الشديد أو بالحبس المديد - فباع أو اشترى فهو بالخيار: إن شاء أمضى البيع وإن شاء فسخه"]]},{"id":"q112_3","label":"كتاب الإكراه · الفقرة ٣","segs":[["matn","وإن كان قبض الثمن طوعا فقد أجاز البيع وإن كان قبضه مكرها فليس بإجازة وعليه رده إن كان قائما في يده وإن هلك المبيع في يد المشتري وهو غير مكره ضمن قيمته"]]},{"id":"q112_4","label":"كتاب الإكراه · الفقرة ٤","segs":[["matn","وللمكره أن يضمن المكره إن شاء"]]},{"id":"q112_5","label":"كتاب الإكراه · الفقرة ٥","segs":[["matn","ومن أكره على أن يأكل الميتة أو يشرب الخمر - وأكره على ذلك بحبس أو ضرب أو يد لم يحل له إلا أن يكره بما يخاف منه على نفسه أو على عضو من أعضائه فإذا خاف ذلك وسعه أن يقدم على ما أكره عليه ولا يسعه أن يصبر على ما توعد به فإن صبر حتى أوقعوا به ولم يأكل فهو آثم"]]},{"id":"q112_6","label":"كتاب الإكراه · الفقرة ٦","segs":[["matn","وإن أكره على الكفر بالله عز وجل أو سب النبي عليه الصلاة والسلام: بقيد أو حبس أو ضرب لم"]]},{"id":"q112_7","label":"كتاب الإكراه · الفقرة ٧","segs":[["matn","يكن ذلك إكراها حتى يكره بأمر يخاف منه على نفسه أو على عضو من أعضائه"]]},{"id":"q112_8","label":"كتاب الإكراه · الفقرة ٨","segs":[["matn","فإذا خاف ذلك وسعه أن يظهر ما أمروه به ويوري فإذا أظهر ذلك وقلبه مطمئن بالإيمان فلا إثم عليه وإن صبر حتى قتل ولم"]]},{"id":"q112_9","label":"كتاب الإكراه · الفقرة ٩","segs":[["matn","يظهر الكفر ذلك كان مأجورا"]]},{"id":"q112_10","label":"كتاب الإكراه · الفقرة ١٠","segs":[["matn","وإن أكره على إتلاف مال مسلم لأمر يخاف منه على نفسه أو على عضو من أعضائه وسعه أن يفعل ذلك ولصاحب المال أن يضمن المكره"]]},{"id":"q112_11","label":"كتاب الإكراه · الفقرة ١١","segs":[["matn","وإن أكره بقتل على قتل لم يسعه أن يقدم عليه ويصبر حتى يقتل فإن قتله كان آثما والقصاص على الذي أكرهه إن كان القتل عمدا"]]},{"id":"q112_12","label":"كتاب الإكراه · الفقرة ١٢","segs":[["matn","وإن أكرهه على طلاق امرأته أو أعتق عبده ففعل وقع ما أكره عليه ويرجع على الذي أكرهه بقيمة العبد وبنصف مهر المرأة إن كان الطلاق قبل الدخول"]]},{"id":"q112_13","label":"كتاب الإكراه · الفقرة ١٣","segs":[["matn","وإن أكرهه على الزنا وجب عليه الحد عند أبي حنيفة إلا أن يكرهه السلطان وقال أبو يوسف ومحمد: لا يلزمه الحد"]]},{"id":"q112_14","label":"كتاب الإكراه · الفقرة ١٤","segs":[["matn","وإذا أكره على الردة لم تبن امرأته منه"]]}]},{"id":"q113","title":"كتاب السير","group":"كتاب السير","units":[{"id":"q113_1","label":"كتاب السير · الفقرة ١","segs":[["matn","الجهاد فرض على الكفاية إذا قام به فريق من الناس سقط عن الباقين وإن لم يقم به أحد أثم جميع الناس بتركه"]]},{"id":"q113_2","label":"كتاب السير · الفقرة ٢","segs":[["matn","وقتال الكفار واجب وإن لم يبدؤونا ولا يجب الجهاد على صبي ولا عبد ولا امرأة ولا أعمى ولا مقعد ولا أقطع"]]},{"id":"q113_3","label":"كتاب السير · الفقرة ٣","segs":[["matn","وإن هجم العدو على بلد وجب على جميع المسلمين الدفع تخرج المرأة بغير إذن زوجها والعبد بغير إذن المولى"]]},{"id":"q113_4","label":"كتاب السير · الفقرة ٤","segs":[["matn","وإذا دخل المسلمون دار الحرب فحاصروا مدينة أو حصنا دعوهم إلى الإسلام فإن أجابوهم كفوا عن قتالهم وإن امتنعوا دعوهم إلى أداء الجزية فإن بذلوها فلهم ما للمسلمين وعليهم ما عليهم"]]},{"id":"q113_5","label":"كتاب السير · الفقرة ٥","segs":[["matn","ولا يجوز أن يقاتل من لم تبلغه دعوة الإسلام إلا بعد أن يدعوهم ويستحب أن يدعو من بلغته الدعوة ولا يجب ذلك وإن أبوا استعانوا بالله تعالى عليهم وحاربوهم ونصبوا عليهم المجانيق وحرقوهم وأرسلوا عليهم الماء وقطعوا أشجارهم وأفسدوا زروعهم ولا بأس برميهم وإن كان فيهم مسلم أسير أو تاجر وإن تترسوا بصبيان المسلمين أو بالأسارى لم يكفوا"]]},{"id":"q113_6","label":"كتاب السير · الفقرة ٦","segs":[["matn","عن رميهم ويقصدون بالرمي الكفار"]]},{"id":"q113_7","label":"كتاب السير · الفقرة ٧","segs":[["matn","ولا بأس بإخراج النساء والمصاحف مع المسلمين إذا كان عسكرا عظيما يؤمن عليه ويكره إخراج ذلك في سرية لا يؤمن عليها"]]},{"id":"q113_8","label":"كتاب السير · الفقرة ٨","segs":[["matn","ولا تقاتل المرأة إلا بإذن زوجها ولا العبد إلا بإذن سيده إلا أن يهجم العدو"]]},{"id":"q113_9","label":"كتاب السير · الفقرة ٩","segs":[["matn","وينبغي للمسلمين أن لا يغدروا ولا يغلوا ولا"]]},{"id":"q113_10","label":"كتاب السير · الفقرة ١٠","segs":[["matn","يمثلوا ولا يقتلوا امرأة أو شيخا فانيا ولا صبيا ولا أعمى ولا مقعدا إلا أن يكون هؤلاء ممن له رأي في الحرب أو تكون المرأة ملكة ولا يقتلوا مجنونا"]]},{"id":"q113_11","label":"كتاب السير · الفقرة ١١","segs":[["matn","وإذا رأى الأمام أن يصالح أهل الحرب أو فريقا منهم وكان في ذلك مصلحة للمسلمين فلا بأس به وإن صالحهم مدة ثم رأى أن نقض الصلح أنفع نبذ إليهم وقاتلهم"]]},{"id":"q113_12","label":"كتاب السير · الفقرة ١٢","segs":[["matn","وإن بدؤوا بخيانة قاتلهم ولم ينبذ إليهم إذا كان ذلك باتفاقهم"]]},{"id":"q113_13","label":"كتاب السير · الفقرة ١٣","segs":[["matn","وإذا خرج عبيدهم إلى عسكر المسلمين فهم أحرار"]]},{"id":"q113_14","label":"كتاب السير · الفقرة ١٤","segs":[["matn","ولا بأس بأن يعلق العسكر في دار الحرب ويأكلوا ما وجدوه من الطعام"]]},{"id":"q113_15","label":"كتاب السير · الفقرة ١٥","segs":[["matn","ويستعملون الحطب ويدهنون بالدهن ويقاتلون بما يجدونه من السلاح بغير قسمه ذلك ولا يجوز أن يبيعوا من ذلك شيئا لوا يتمولوه"]]},{"id":"q113_16","label":"كتاب السير · الفقرة ١٦","segs":[["matn","ومن أسلم منهم أحرز بإسلامه نفسه وأولاد الصغار وكل مال هو في يده أو وديعة في يد مسلم أو ذمي فإن ظهرنا على الدار فعقاره فيء وزوجته فيء وحملها فيء وأولاده فيء"]]},{"id":"q113_17","label":"كتاب السير · الفقرة ١٧","segs":[["matn","ولا ينبغي أن يباع السلاح من أهل الحرب ولا يجهز إليهم ولا يفدون بالأسارى عند أبي حنيفة وقال أبو يوسف ومحمد: يفادى بهم أسارى المسلمين ولا يجوز المن عليهم"]]},{"id":"q113_18","label":"كتاب السير · الفقرة ١٨","segs":[["matn","وإذا فتح الإمام بلدا عنوة فهو بالخيار: إن شاء قسمه بين الغانمين وإن شاء أقر أهله عليه ووضع عليهم الخراج وهو في الأسارى بالخيار: إن شاء قتلهم وإن شاء استرقهم وإن شاء تركهم أحرارا ذمة للمسلمين"]]},{"id":"q113_19","label":"كتاب السير · الفقرة ١٩","segs":[["matn","ولا يجوز أن يردهم إلى دار الحرب"]]},{"id":"q113_20","label":"كتاب السير · الفقرة ٢٠","segs":[["matn","وإذا أراد العود معهم مواش فلم يقدروا على نقلها إلى دار الإسلام ذبحوها وحرقوها ولا يعقرونها ولا يتركونها"]]},{"id":"q113_21","label":"كتاب السير · الفقرة ٢١","segs":[["matn","ولا يقسم غنيمة في دار الحرب حتى يخرجها إلى دار الإسلام والردء والمقاتل في العسكر سواء"]]},{"id":"q113_22","label":"كتاب السير · الفقرة ٢٢","segs":[["matn","وإذا لحقهم المدد في دار الحرب قبل أن يخرجوا الغنيمة إلى دار الإسلام شاركوهم فيها ولا حق لأهل سوق العسكر في الغنيمة إلا أن يقاتلوا"]]},{"id":"q113_23","label":"كتاب السير · الفقرة ٢٣","segs":[["matn","وإذا أمن رجل حر أو امرأة كافرا أو جماعة أو أهل حصن أو مدينة صح أمانهم ولم يجز لأحد من المسلمين قتلهم إلا أن يكون في ذلك مفسدة فينبذ إليهم الإمام"]]},{"id":"q113_24","label":"كتاب السير · الفقرة ٢٤","segs":[["matn","ولا يجوز أمان ذمي ولا أسير ولا تاجر يدخل عليهم"]]},{"id":"q113_25","label":"كتاب السير · الفقرة ٢٥","segs":[["matn","ولا يجوز أمان العبد عند أبي حنيفة إلا أن يأذن له مولاه في القتال وقال أبو يوسف ومحمد: يصح أمانة"]]},{"id":"q113_26","label":"كتاب السير · الفقرة ٢٦","segs":[["matn","وإذا غلب الترك على الروم فسبوهم وأخذوا أموالهم ملكوها فإن غلبنا على الترك حل لنا من ذلك وإذا غلبوا على أموالنا فأحرزوها بدارهم ملكوها فإن ظهر عليها المسلمون فوجدوها قبل القسمة فهي لهم بغير شيء وإن وجدوها بعد القسمة أخذوها"]]},{"id":"q113_27","label":"كتاب السير · الفقرة ٢٧","segs":[["matn","بالقيمة إ أحبوا وإن دخل دار الحرب تاجر فاشترى ذلك وأخرجه إلى دار الإسلام فمالكه بالخيار: إن شاء أخذه بالثمن الذي اشتراه به التاجر وإن شاء ترك"]]},{"id":"q113_28","label":"كتاب السير · الفقرة ٢٨","segs":[["matn","ولا يملك علينا أهل الحرب بالغلبة مدبرينا ومكاتبنا وأمهات أولادنا وأحرارنا ونملك عليهم جميع ذلك وإذا أبق عبد لمسلم فدخل إليهم فأخذوه لم يملكوه عند أبي حنيفة"]]},{"id":"q113_29","label":"كتاب السير · الفقرة ٢٩","segs":[["matn","وإن ند تعير إليهم فأخذوه ملكوه"]]},{"id":"q113_30","label":"كتاب السير · الفقرة ٣٠","segs":[["matn","وإذا لم يكن للإمام حمولة يحمل عليها"]]},{"id":"q113_31","label":"كتاب السير · الفقرة ٣١","segs":[["matn","الغنائم قسمها بين الغانمين قسمة إيداع ليحملوها إلى دار الإسلام ثم يرتجعها فيقسمها"]]},{"id":"q113_32","label":"كتاب السير · الفقرة ٣٢","segs":[["matn","ولا يجوز بيع الغنائم قبل القسمة"]]},{"id":"q113_33","label":"كتاب السير · الفقرة ٣٣","segs":[["matn","ومن مات من الغانمين في دار الحرب فلا حق له في الغنيمة ومن مات منهم بعد إخراجها إلى دار الإسلام فنصيبه لورثته"]]},{"id":"q113_34","label":"كتاب السير · الفقرة ٣٤","segs":[["matn","ولا بأس أن ينقل الإمام في حال القتال ويحرض بالنفل على القتال فيقول: من قتل قتيلا فله سلبه أو يقول لسرية: قد جعلت لكم الربع بعد الخمس"]]},{"id":"q113_35","label":"كتاب السير · الفقرة ٣٥","segs":[["matn","ولا ينقبل بعد إحراز الغنيمة إلا من الخمس وإذا لم يجعل السلب للقاتل فهو من جملة الغنيمة والقاتل وغيره فيه سواء"]]},{"id":"q113_36","label":"كتاب السير · الفقرة ٣٦","segs":[["matn","والسلب: ما على المقتول من ثيابه وسلاحه ومركبه"]]},{"id":"q113_37","label":"كتاب السير · الفقرة ٣٧","segs":[["matn","وإذا خرج المسلمون من دار الحرب لم يجز أن يعلفوا من الغنيمة ولا يأكلوا منها"]]},{"id":"q113_38","label":"كتاب السير · الفقرة ٣٨","segs":[["matn","ومن فضل معه علف أو طعام إلى الغنية"]]},{"id":"q113_39","label":"كتاب السير · الفقرة ٣٩","segs":[["matn","ويقسم الإمام الغنيمة: فيخرج خمسها ويقسم أربعة أخماسها بين الغانمين: للفارس سهما وللراجل سهم عند أبي حنيفة وقالا: للفارس ثلاثة أسهم ولا يسهم إلا لفرس واحد والبراذين والعتاق سواء ولا يسهم لراحلة ولا بغل"]]},{"id":"q113_40","label":"كتاب السير · الفقرة ٤٠","segs":[["matn","ومن دخل دار الحرب فارسا فنفق فرسه استحق سهم فارس ومن دخل راجلا فاشترى فرسا استحق سهم راجل"]]},{"id":"q113_41","label":"كتاب السير · الفقرة ٤١","segs":[["matn","ولا يسهم لمملوك ولا امرأة ولا ذمي ولا صبي ولكن يرضخ لهم على حسب ما يراه الإمام"]]},{"id":"q113_42","label":"كتاب السير · الفقرة ٤٢","segs":[["matn","وأما الخمس فيقسم على ثلاثة أسهم: سهم لليتامى وسهم للمساكين"]]},{"id":"q113_43","label":"كتاب السير · الفقرة ٤٣","segs":[["matn","وسهم لأبناء السبيل يدخل فقراء ذوي القربى فيهم ويقدمون ولا يدفع إلى أغنيائهم شيء"]]},{"id":"q113_44","label":"كتاب السير · الفقرة ٤٤","segs":[["matn","وما ذكر الله تعالى في الخمس فإنما هو لافتتاح الكلام تبركا باسمه وسهم النبي صلى الله عليه وسلم سقط بموته كما سقط الصفي وسهم ذوي القربى كانوا يستحقونه في زمن النبي صلى الله عليه وسلم بالنصرة وبعده بالفقر"]]},{"id":"q113_45","label":"كتاب السير · الفقرة ٤٥","segs":[["matn","وإذا دخل الواحد أو الاثنان إلى دار الحرب مغيرين بغير إذن الإمام فأخذوا شيئا لم يخمس"]]},{"id":"q113_46","label":"كتاب السير · الفقرة ٤٦","segs":[["matn","وإن دخل جماعة لها منعة وأخذوا شيئا خمس وإن لم يأذن لهم الإمام"]]},{"id":"q113_47","label":"كتاب السير · الفقرة ٤٧","segs":[["matn","وإذا دخل المسلم دار الحرب تاجرا فلا يحل له أن يتعرض لشيء من أموالهم ولا من دمائهم"]]},{"id":"q113_48","label":"كتاب السير · الفقرة ٤٨","segs":[["matn","وإن غدر بهم وأخذ شيئا وخرج به ملكه ملكا محظورا ويؤمر أن يتصدق به"]]},{"id":"q113_49","label":"كتاب السير · الفقرة ٤٩","segs":[["matn","وإذا دخل الحربي إلينا مستأمنا لم يمكن أن يقيم في دارنا سنة ويقول له الإمام: إن أقمت تمام السنة وضعت عليك الجزية فإن أقام أخذ منه الجزية وصار ذميا ولم يترك أن يرجع إلى دار الحرب وإن عاد إلى دار الحرب وترك وديعة عند مسلم أو ذمي أو دينا في ذمتهم فقد صار ذمه مباحا بالعود وما في دار الإسلام من ماله على خطر فإن أسر أو قتل سقطت ديونه وصارت الوديعة فيئا"]]},{"id":"q113_50","label":"كتاب السير · الفقرة ٥٠","segs":[["matn","وما أوجف عليه المسلمون من أموال أهل الحرب بغير قتال يصرف مصالح المسلمين كما يصرف الخراج"]]},{"id":"q113_51","label":"كتاب السير · الفقرة ٥١","segs":[["matn","وأرض العرب كلها أرض عسير وهي: ما بين العذيب إلى أقصى حجر"]]},{"id":"q113_52","label":"كتاب السير · الفقرة ٥٢","segs":[["matn","باليمن بمهرة إلى حد"]]},{"id":"q113_53","label":"كتاب السير · الفقرة ٥٣","segs":[["matn","الشام، والسواد كلها أرض خراج وهي: ما بين العذيب إلى عقبة حلوان ومن العلث إلى عبادان"]]},{"id":"q113_54","label":"كتاب السير · الفقرة ٥٤","segs":[["matn","وأرض السواد مملوكه لأهلها: يجوز بيعهم لها وتصرفهم فيها"]]},{"id":"q113_55","label":"كتاب السير · الفقرة ٥٥","segs":[["matn","وكل أرض أسلم أهلها عليها أو فتحت عنوة وقسمت بين الغانمين فهي أرض عشر"]]},{"id":"q113_56","label":"كتاب السير · الفقرة ٥٦","segs":[["matn","وكل أرض فتحت عنوة وأقر عليها فهي أرض خراج"]]},{"id":"q113_57","label":"كتاب السير · الفقرة ٥٧","segs":[["matn","إحياء الموات ومن أحيا أرضا مواتا فهي عند أبي يوسف معتبرة بحيزها: فإن كانت من حيز أرض الخارج فهي خراجية وإن كانت من حيز أرض العشر فهي عشرية والبصرة عنده عشرية بإجماع الصحابة رضي الله عنهم"]]},{"id":"q113_58","label":"كتاب السير · الفقرة ٥٨","segs":[["matn","وقال محمد: إن أحياها ببئر حفرها أو عين استخرجها أو ماء دجله أو الفرات أو الأنهار العظام التي لا يملكها أحد"]]},{"id":"q113_59","label":"كتاب السير · الفقرة ٥٩","segs":[["matn","فهي عشرية وإن أحياها بماء الأنهار التي احتفرها الأعاجم مثل نهر الملك ونهر يزدجرد فهي خراجية"]]},{"id":"q113_60","label":"كتاب السير · الفقرة ٦٠","segs":[["matn","والخراج الذي وضعه عمر رضي الله عنه على أهل السواد من كل جريب يبلغه الماء قفيز هاشمي وهو الصاع ودرهم ومن جريب الرطبة خمسة دارهم ومن جريب الكرم المتصل والنخل المتصل عشرة دارهم"]]},{"id":"q113_61","label":"كتاب السير · الفقرة ٦١","segs":[["matn","وما سوى ذلك من الأصناف يوضع عليها بحسب الطاقة فإن لم تطق ما وضع عليها نقصهم الإمام"]]},{"id":"q113_62","label":"كتاب السير · الفقرة ٦٢","segs":[["matn","وإن غلب الماء على أرض الخراج أو انقطع عنها أو اصطلم الزرع آفة فلا خراج عليهم وإن عطلها صاحبها فعليه الخراج"]]},{"id":"q113_63","label":"كتاب السير · الفقرة ٦٣","segs":[["matn","ومن أسلم من أهل الخراج أخذ منه الخراج على حاله"]]},{"id":"q113_64","label":"كتاب السير · الفقرة ٦٤","segs":[["matn","ويجوز أن يشتري المسلم أرض الخراج من الذمي ويؤخذ منه الخراج ولا عشر في الخارج من أرض الخراج"]]},{"id":"q113_65","label":"كتاب السير · الفقرة ٦٥","segs":[["matn","والجزية على ضربين: جزية توضع بالتراضي والصلح فتقدر بحسب ما يقع عليه الاتفاق وجزية يبتدئ الإمام وضعها إذا غلب الكفار وأقرهم على أملاكهم فيضع على الغني الظاهر الغني في كل سنة ثمانية وأربعين درهما يأخذ منه في كل شهر أربعة دراهم"]]},{"id":"q113_66","label":"كتاب السير · الفقرة ٦٦","segs":[["matn","وعلى المتوسط الحال أربعة وعشرين درهما في كل شهر درهمين وعلى الفقير المعتمل اثني عشر درهما في كل شهر درهما"]]},{"id":"q113_67","label":"كتاب السير · الفقرة ٦٧","segs":[["matn","وتوضع الجزية على أهل الكتاب والمجوس وعبدة الأوثان من العجم ولا توضع على عبدة الأوثان من العرب ولا على المرتدين"]]},{"id":"q113_68","label":"كتاب السير · الفقرة ٦٨","segs":[["matn","ولا جزية على امرأة ولا صبي ولا زمن ولا أعمى ولا فقير غير معتمل ولا الرهبان الذين لا"]]},{"id":"q113_69","label":"كتاب السير · الفقرة ٦٩","segs":[["matn","يخالطون الناس ومن أسلم وعليه جزية سقطت عنه وإن اجتمع حولان تداخلت الجزية"]]},{"id":"q113_70","label":"كتاب السير · الفقرة ٧٠","segs":[["matn","ولا يجوز إحداث بيعة ولا كنيسة في دار الإسلام وإذا انهدمت الكنائس البيع القديمة أعادوها"]]},{"id":"q113_71","label":"كتاب السير · الفقرة ٧١","segs":[["matn","ويؤخذ أهل الذمة بالتميز عن المسلمين في زيهم ومراكبهم وسروجهم وقلانسهم ولا يركبون الخيل ولا يحملون السلاح"]]},{"id":"q113_72","label":"كتاب السير · الفقرة ٧٢","segs":[["matn","ومن امتنع من أداء الجزية أو قتل مسلما أو سب النبي عليه الصلاة والسلام أو زنى بمسلمة لم ينقض عهده ولا ينتقض العهد إلا بأن يلحق بدار الحرب أو يغلبوا على موضع فيحاربونا"]]},{"id":"q113_73","label":"كتاب السير · الفقرة ٧٣","segs":[["matn","وإذا ارتد المسلم عن الإسلام عرض عليه السلام فإن كانت له شبهة كشفت له ويحبسن ثلاثة أيام فإن أسلم"]]},{"id":"q113_74","label":"كتاب السير · الفقرة ٧٤","segs":[["matn","وإلا قتل فإن قتله قاتل قبل عرض الإسلام عليه كره له ذلك ولا شيء على القاتل"]]},{"id":"q113_75","label":"كتاب السير · الفقرة ٧٥","segs":[["matn","فأما المرأة إذا ارتدت فلا تقتل ولكن تحبس حتى تسلم"]]},{"id":"q113_76","label":"كتاب السير · الفقرة ٧٦","segs":[["matn","ويزول ملك المرتد عن أمواله بردته زوالا مراعى فإن أسلم عادت على حالها وإن مات أو قتل على ردته انتقل ما كان اكتسبه في حال الإسلام إلى ورثته المسلمين"]]},{"id":"q113_77","label":"كتاب السير · الفقرة ٧٧","segs":[["matn","وكان ما اكتسبه في حال ردته فيئا"]]},{"id":"q113_78","label":"كتاب السير · الفقرة ٧٨","segs":[["matn","فإن لحق بدرا الحرب مرتدا وحكم الحاكم بلحاقه عتق مدبروه وأمهات أولاده وحلت الديون التي عليه ونقل ما اكتسبه في حال الإسلام إلى ورثته المسلمين وتقضى الديون التي لزمته في حال الإسلام مما اكتسبه في حال الإسلام وما لزمه من الديون في حال ردته مما اكتسبه في حال ردته"]]},{"id":"q113_79","label":"كتاب السير · الفقرة ٧٩","segs":[["matn","وما باعه أو اشتراه أو تصرف فيه من أمواله في حال ردته"]]},{"id":"q113_80","label":"كتاب السير · الفقرة ٨٠","segs":[["matn","موقوف: فإن أسلم صحت عقوده وإن مات أو قتل أو لحق بدار الحرب بطلت"]]},{"id":"q113_81","label":"كتاب السير · الفقرة ٨١","segs":[["matn","وإن عاد المرتد بعد الحكم بلحاقه إلى دار الإسلام مسلما فما وجده في يد ورثته من"]]},{"id":"q113_82","label":"كتاب السير · الفقرة ٨٢","segs":[["matn","ماله بعينه أخذه والمرتدة إذا انصرفت في مالها في حال ردتها جاز تصرفها"]]},{"id":"q113_83","label":"كتاب السير · الفقرة ٨٣","segs":[["matn","ونصارى بني تغلب يؤخذ من أموالهم ضعف ما يؤاخذ من المسلمين من الزكاة ويؤخذ من نسائهم ولا يؤخذ من صبيانهم"]]},{"id":"q113_84","label":"كتاب السير · الفقرة ٨٤","segs":[["matn","وما جباه الإمام من الخراج ومن أموال بني تغلب وما أهداه أهل الحرب إلى الإمام والجزية تصرف في مصالح المسلمين فتسد منها الثغور وتبنى القناطر والجسور ويعطى قضاة المسلمين وعلماؤهم منه ما يكفيهم ويدفع منه أرزاق المقاتلة وذراريهم"]]}]},{"id":"q114","title":"كتاب البغاة","group":"كتاب البغاة","units":[{"id":"q114_1","label":"كتاب البغاة · الفقرة ١","segs":[["matn","إذا تغلب قوم من المسلمين على بلد وخرجوا عن طاعة الإمام"]]},{"id":"q114_2","label":"كتاب البغاة · الفقرة ٢","segs":[["matn","دعاهم إلى العود إلى الجماعة وكشف عن شبهتهم ولا يبدؤهم بالقتال حتى يبدؤوا فإن بدؤوا قاتلهم حتى يفرق جمعهم فإن كانت لهم فئة أجهز على جريحهم واتبع موليهم وإن لم يكن لهم فئة لم يجهز على جريحهم ولم يتبع موليهم ولا تسبى لهم ذرية ولا يغنم لهم مال ولا بأس أن يقاتلوا بسلاحهم"]]},{"id":"q114_3","label":"كتاب البغاة · الفقرة ٣","segs":[["matn","إن احتاج المسلمون إليه ويحبس الإمام أموالهم ولا يردها عليهم ولا يقسمها حتى يتوبوا فيردها"]]},{"id":"q114_4","label":"كتاب البغاة · الفقرة ٤","segs":[["matn","وما جناه أهل البغي من البلاد التي غلبوا عليها من الخراج والعشر لم يأخذه الإمام ثانيا فإن كانوا صرفوه في حقه أجزأ من أخذ منه وإن لم يكونوا صرفوه في حقه أفتى أهله فيما بينهم وبين الله تعالى أن يعيدوا ذلك"]]}]},{"id":"q115","title":"كتاب الحظر والإباحة","group":"كتاب الحظر والإباحة","units":[{"id":"q115_1","label":"كتاب الحظر والإباحة · الفقرة ١","segs":[["matn","لا يحل للرجال لبس الحرير ويحل للنساء ولا بأس بتوسده"]]},{"id":"q115_2","label":"كتاب الحظر والإباحة · الفقرة ٢","segs":[["matn","عند أبي حنيفة وقال أبو يوسف ومحمد: يكره توسده"]]},{"id":"q115_3","label":"كتاب الحظر والإباحة · الفقرة ٣","segs":[["matn","ولا بأس بلبس الديباج في الحرب عندهما ويكره عند أبي حنيفة"]]},{"id":"q115_4","label":"كتاب الحظر والإباحة · الفقرة ٤","segs":[["matn","ولا بأس بلبس الملحم إذا كان سداه إبرسما ولحمته قطنا أو خزا"]]},{"id":"q115_5","label":"كتاب الحظر والإباحة · الفقرة ٥","segs":[["matn","ولا يجوز للرجال التحلي بالذهب والفضة إلا الخاتم والمنطقة وحلية السيف من الفضة"]]},{"id":"q115_6","label":"كتاب الحظر والإباحة · الفقرة ٦","segs":[["matn","ويجوز للنساء التحلي بالذهب والفضة ويكره أن يلبس الصبي الذهب والحرير"]]},{"id":"q115_7","label":"كتاب الحظر والإباحة · الفقرة ٧","segs":[["matn","ولا يجوز الأكل والشرب والادهان والتطيب في آنية الذهب والفضة للرجال والنساء"]]},{"id":"q115_8","label":"كتاب الحظر والإباحة · الفقرة ٨","segs":[["matn","ولا بأس باستعمال آنية الزجاج والبلور والعقيق"]]},{"id":"q115_9","label":"كتاب الحظر والإباحة · الفقرة ٩","segs":[["matn","ويجوز الشرب في الإناء المفضض عند أبي حنيفة والركوب على السرج المفضض والجلوس على السرير المفضض"]]},{"id":"q115_10","label":"كتاب الحظر والإباحة · الفقرة ١٠","segs":[["matn","ويكره التعشير في المصحف والنفط"]]},{"id":"q115_11","label":"كتاب الحظر والإباحة · الفقرة ١١","segs":[["matn","ولا بأس بتحلية المصحف ونقش المسجد وزخرفته بماء الذهب"]]},{"id":"q115_12","label":"كتاب الحظر والإباحة · الفقرة ١٢","segs":[["matn","ويكره استخدام الخصيان ولا بأس بخصاء البهائم وإنزاء الحمير على النخيل"]]},{"id":"q115_13","label":"كتاب الحظر والإباحة · الفقرة ١٣","segs":[["matn","ويجوز أن يقبل في الهدية والإذن قول الصبي والعبد ويقبل في المعاملات قول الفاسق"]]},{"id":"q115_14","label":"كتاب الحظر والإباحة · الفقرة ١٤","segs":[["matn","ولا يقبل في أخبار الديانات إلا قول العدل ولا يجوز أن ينظر الرجل من الأجنبية إلا إلى وجهها وكفيها وإن كان لا يأمن الشهوة لا ينظر إلى وجهها إلا لحاجة"]]},{"id":"q115_15","label":"كتاب الحظر والإباحة · الفقرة ١٥","segs":[["matn","ويجوز للقاضي إذا أرد أن يحكم عليها وللشاهد إذا أراد الشهادة عليها"]]},{"id":"q115_16","label":"كتاب الحظر والإباحة · الفقرة ١٦","segs":[["matn","النظر إلى وجهها وإن خاف أن يشتهي"]]},{"id":"q115_17","label":"كتاب الحظر والإباحة · الفقرة ١٧","segs":[["matn","ويجوز للطبيب أن ينظر إلى موضع المرض منها"]]},{"id":"q115_18","label":"كتاب الحظر والإباحة · الفقرة ١٨","segs":[["matn","وينظر الرجل من الرجل إلى جميع بدنه إلا ما بين سرته إلى ركبته"]]},{"id":"q115_19","label":"كتاب الحظر والإباحة · الفقرة ١٩","segs":[["matn","ويجوز للمرأة أن تنظر من الرجل إلى ما ينظر الرجل إليه منه وتنظر المرأة من المرأة إلى ما يجوز للرجل أن ينظر إليه من الرجل"]]},{"id":"q115_20","label":"كتاب الحظر والإباحة · الفقرة ٢٠","segs":[["matn","وينظر الرجل من أمته التي تحل له وزوجته إلى فرجها"]]},{"id":"q115_21","label":"كتاب الحظر والإباحة · الفقرة ٢١","segs":[["matn","وينظر الرجل من ذوات محارمه إلى الوجه والرأس والصدر والساقين والعضدين ولا ينظر إلى ظهرها وبطنها"]]},{"id":"q115_22","label":"كتاب الحظر والإباحة · الفقرة ٢٢","segs":[["matn","ولا بأس أن يمس ما جاز أن ينظر إليه منها"]]},{"id":"q115_23","label":"كتاب الحظر والإباحة · الفقرة ٢٣","segs":[["matn","وينظر الرجل من مملوكه غيره إلى ما يجوز أن ينظر إليه من ذوات محارمه"]]},{"id":"q115_24","label":"كتاب الحظر والإباحة · الفقرة ٢٤","segs":[["matn","ولا بأس بأن يمس ذلك إذا أراد الشراء وإن خاف أن يشتهي"]]},{"id":"q115_25","label":"كتاب الحظر والإباحة · الفقرة ٢٥","segs":[["matn","والخصي في النظر إلى الأجنبية كالفحل"]]},{"id":"q115_26","label":"كتاب الحظر والإباحة · الفقرة ٢٦","segs":[["matn","ولا يجوز للمملوك أن ينظر من سيدته إلا إلى ما يجوز للأجنبي أن ينظر إليه منها"]]},{"id":"q115_27","label":"كتاب الحظر والإباحة · الفقرة ٢٧","segs":[["matn","ويعزل عن أمته بغير إذنها ولا يعزل عن زوجته إلا بإذنها"]]},{"id":"q115_28","label":"كتاب الحظر والإباحة · الفقرة ٢٨","segs":[["matn","ويكره الاحتكار في أقوات الآدميين"]]},{"id":"q115_29","label":"كتاب الحظر والإباحة · الفقرة ٢٩","segs":[["matn","والبهائم إذا كان ذلك في بلد يضر الاحتكار بأهله ومن احتكر غلة ضيعته أو ما جلبه من بلد آخر فليس بمحتكر"]]},{"id":"q115_30","label":"كتاب الحظر والإباحة · الفقرة ٣٠","segs":[["matn","ولا ينبغي للسلطان أن يسعر على الناس"]]},{"id":"q115_31","label":"كتاب الحظر والإباحة · الفقرة ٣١","segs":[["matn","ويكره بيع السلاح في أيام الفتنة ولا بأس ببيع العصير ممن يعلم أنه يتخذه خمرا"]]}]},{"id":"q116","title":"كتاب الوصايا","group":"كتاب الوصايا","units":[{"id":"q116_1","label":"كتاب الوصايا · الفقرة ١","segs":[["matn","الوصية غير واجبة وهي مستحبة ولا تجوز الوصية لوارث"]]},{"id":"q116_2","label":"كتاب الوصايا · الفقرة ٢","segs":[["matn","إلا أن يجيزها الورثة ولا يجوز الوصية بما زاد على الثلث ولا للقاتل"]]},{"id":"q116_3","label":"كتاب الوصايا · الفقرة ٣","segs":[["matn","ويجوز أن يوصي المسلم للكافر والكافر للمسلم"]]},{"id":"q116_4","label":"كتاب الوصايا · الفقرة ٤","segs":[["matn","وقبول الوصية بعد الموت فإن قبلها الموصى له في حال الحياة أو ردها فذلك باطل"]]},{"id":"q116_5","label":"كتاب الوصايا · الفقرة ٥","segs":[["matn","ويستحب أن يوصي الإنسان بدون الثلث"]]},{"id":"q116_6","label":"كتاب الوصايا · الفقرة ٦","segs":[["matn","وإذا أوصى إلى رجل فقبل الوصي في وجه الموصي فردها في غير وجهه فليس برد وإن ردها في وجهه فهو رد"]]},{"id":"q116_7","label":"كتاب الوصايا · الفقرة ٧","segs":[["matn","والموصى به يملك بالقبول إلا في مسألة وهي: أن يموت الموصي ثم يموت الموصى له قبل القبول فيدخل الموصى به في ملك ورثته"]]},{"id":"q116_8","label":"كتاب الوصايا · الفقرة ٨","segs":[["matn","ومن أوصى إلى عبد أو كافر أو فاسق أخرجهم القاضي من الوصية ونثب غيرهم"]]},{"id":"q116_9","label":"كتاب الوصايا · الفقرة ٩","segs":[["matn","ومن أوصى إلى عبد نفسه وفي الورثة كبار لم تصح الوصية"]]},{"id":"q116_10","label":"كتاب الوصايا · الفقرة ١٠","segs":[["matn","ومن أوصى إلى من يعجز عن القيام بالوصية صم إليه القاضي غيره"]]},{"id":"q116_11","label":"كتاب الوصايا · الفقرة ١١","segs":[["matn","ومن أوصى إلى اثنين لم يجز لأحدهما أن يتصرف عند أبي حنيفة ومحمد دون صاحبه إلا من شراء كفن الميت وتجهيزه وطعام الصغار وكسوتهم ورد وديعة بعينها وقضاء دين وتنفيذ وصية بعينها وعتق عبد بتعينه والخصومة في حقوق الميت"]]},{"id":"q116_12","label":"كتاب الوصايا · الفقرة ١٢","segs":[["matn","ومن أوصى لرجل بثلث ماله ولآخر بثلث ماله فلم تجز الورثة فالثلث بينهما نصفان وإن أوصى لأحدهما بالثلث وللآخر بالسدس فالثلث بينهما أثلاثا وإن أوصى لأحدهما بجميع ماله وللآخر بثلث ماله فلم تجز الورثة فالثلث بينهما على أربعة أسهم عند أبي يوسف ومحمد وقال أبو حنيفة: الثلث بينهما نصفان ولا يضرب أبو حنيفة للموصى له بما زاد على الثلث إلا في المحاباة والسعاية والدراهم المرسلة"]]},{"id":"q116_13","label":"كتاب الوصايا · الفقرة ١٣","segs":[["matn","ومن أوصى وعليه دين يحيط بماله لم تجز الوصية إلا أن يبرئ الغرماء الدين"]]},{"id":"q116_14","label":"كتاب الوصايا · الفقرة ١٤","segs":[["matn","ومن أوصى بنصيب ابنه فالوصية باطلة وإن أوصى بمثل"]]},{"id":"q116_15","label":"كتاب الوصايا · الفقرة ١٥","segs":[["matn","نصيب ابنه جازت فإن كان له ابنان فللموصى له الثلث"]]},{"id":"q116_16","label":"كتاب الوصايا · الفقرة ١٦","segs":[["matn","ومن أعتق عبدا في مرضه أو باع وحابى أو وهب فذلك كله جائز يعتبر من الثلث ويضرب به مع أصحاب الوصايا"]]},{"id":"q116_17","label":"كتاب الوصايا · الفقرة ١٧","segs":[["matn","فإن حابى ثم أعتق بالمحاباة أولى عند أبي حنيفة وإن أعتق ثم حابى فهما سواء وقال أ [ويوسف ومحمد: العتق أولى في المسألتين"]]},{"id":"q116_18","label":"كتاب الوصايا · الفقرة ١٨","segs":[["matn","ومن أوصى بسهم من ماله فله أخس سهام الورثة إلا أن ينقص من السدس فيتم له السدس"]]},{"id":"q116_19","label":"كتاب الوصايا · الفقرة ١٩","segs":[["matn","وإن أوصى بجزء من ماله قيل للورثة: أعطوه ما شئتم"]]},{"id":"q116_20","label":"كتاب الوصايا · الفقرة ٢٠","segs":[["matn","ومن أوصى بوصايا من حقوق الله تعالى قدمت الفرائض منها قدمها الموصي أو آخرها"]]},{"id":"q116_21","label":"كتاب الوصايا · الفقرة ٢١","segs":[["matn","مثل الحج والزكاة والكفارات وما ليس بواجب قدم منه ما قدمه الموصي"]]},{"id":"q116_22","label":"كتاب الوصايا · الفقرة ٢٢","segs":[["matn","ومن أوصى بحجة الإسلام أحجوا عنه رجلا من بلده يحج عنه راكبا فإن لم تبلغ الوصية النفقة أحجوا عنه من حيث تبلغ"]]},{"id":"q116_23","label":"كتاب الوصايا · الفقرة ٢٣","segs":[["matn","ومن خرج من بلده حاجا فمات في الطريق وأوصى أن يحج عنه حج عنه من بلده عند أبي حنيفة"]]},{"id":"q116_24","label":"كتاب الوصايا · الفقرة ٢٤","segs":[["matn","ولا تصح وصية الصبي والمكاتب وإن ترك وفاء"]]},{"id":"q116_25","label":"كتاب الوصايا · الفقرة ٢٥","segs":[["matn","ويجوز للموصي الرجوع عن الوصية"]]},{"id":"q116_26","label":"كتاب الوصايا · الفقرة ٢٦","segs":[["matn","فإن صرح بالرجوع أو فعل ما يدل على الرجوع كان رجوعا ومن جحد الوصية لم يكن رجوعا"]]},{"id":"q116_27","label":"كتاب الوصايا · الفقرة ٢٧","segs":[["matn","ومن أوصى لجيرانه فهم الملاصقون عند أبي حنيفة"]]},{"id":"q116_28","label":"كتاب الوصايا · الفقرة ٢٨","segs":[["matn","ومن أوصى لأصهاره فالوصية لكل ذي رحم محرم من امرأته ومن أوصى لأختانه فالختن كل ذات رحم محرم منه"]]},{"id":"q116_29","label":"كتاب الوصايا · الفقرة ٢٩","segs":[["matn","ومن أوصى لأقربائه فالوصية للأقرب فالأقرب من كل ذي"]]},{"id":"q116_30","label":"كتاب الوصايا · الفقرة ٣٠","segs":[["matn","رحمه محرم منه ولا يدخل فيهم الوالدان والولد"]]},{"id":"q116_31","label":"كتاب الوصايا · الفقرة ٣١","segs":[["matn","ويكون للإثنين فصاعدا وإذا أوصى بذلك وله عمان وخالان فالوصية لعميه عند أبي حنيفة وإن كان له عم وخالان فللعم النصف وللخالين النصف وقال أبو يوسف ومحمد: الوصية لكل من ينسب إلى أقصى أب له في الإسلام"]]},{"id":"q116_32","label":"كتاب الوصايا · الفقرة ٣٢","segs":[["matn","ومن أوصى لرجل بثلث دراهمه أو ثلث غنمه فهلك ثلثا ذلك وبقي ثلثه وهو يخرج من ثلث ما بقي من ماله فله جميع ما بقي وإن أوصى بثلث ثيابه فهلك ثلثاها وبقي ثلثها وهو يخرج من ثلث ما بقي من ماله لم يستحق إلا ثلث ما بقي من الثياب"]]},{"id":"q116_33","label":"كتاب الوصايا · الفقرة ٣٣","segs":[["matn","ومن أوصى لرجل بألف درهم وله مال عين ودين فإن خرجت الألف من ثلث العين دفعت إلى الموصى له وإن لم تخرج دفع إليه ثلث العين وكلما خرج شيء من الدين أخذ ثلثه حتى يستوفي الألف"]]},{"id":"q116_34","label":"كتاب الوصايا · الفقرة ٣٤","segs":[["matn","وتجوز الوصية للحمل وبالحمل إذا وضع لأقل من ستة أشهر من يوم الوصية"]]},{"id":"q116_35","label":"كتاب الوصايا · الفقرة ٣٥","segs":[["matn","ومن أوصى لرجل بجارية إلا حملها صحت الوصية والاستثناء"]]},{"id":"q116_36","label":"كتاب الوصايا · الفقرة ٣٦","segs":[["matn","ومن أوصى لرجل بجارية فولدت بعد موت الموصي قبل أن يقبل الموصى له ولدا ثم قبل وهما يخرجان من الثلث فهما للموصى له وإن لم يخرجا من الثلث ضرب بالثلث وأخذ ما يخصه منهما جميعا في قول أبو يوسف ومحمد"]]},{"id":"q116_37","label":"كتاب الوصايا · الفقرة ٣٧","segs":[["matn","وقال أبو حنيفة: يأخذ ذلك من الأم فإن فضل شيء أخذه من الولد"]]},{"id":"q116_38","label":"كتاب الوصايا · الفقرة ٣٨","segs":[["matn","وتجوز الوصية بخدمة عبده وسكنى داره سنين معلومة وتجوز بذلك أبدا فإن خرجت رقبة العبد من الثلث سلم إليه للخدمة وإن كان لا مال له غيره خدم الورثة يومين والموصى له يوما فإن مات الموصى له عاد إلى الورثة وإن مات الموصى له في حياة الموصى بطلت الوصية"]]},{"id":"q116_39","label":"كتاب الوصايا · الفقرة ٣٩","segs":[["matn","وإذا أوصى لولد فلان فالوصية بينهم: الذكر والأنثى فيه سواء"]]},{"id":"q116_40","label":"كتاب الوصايا · الفقرة ٤٠","segs":[["matn","ومن أوصى لورثة فلان فالوصية بينهم: للذكر مثل حظ الأنثيين"]]},{"id":"q116_41","label":"كتاب الوصايا · الفقرة ٤١","segs":[["matn","ومن أوصى لزيد وعمرو بثلث ماله فإذا عمرو ميت فالثلث كله لزيد"]]},{"id":"q116_42","label":"كتاب الوصايا · الفقرة ٤٢","segs":[["matn","وإن قال: ثلث مالي بين زيد وعمرو وزيد ميت كان لعمرو نصف الثلث"]]},{"id":"q116_43","label":"كتاب الوصايا · الفقرة ٤٣","segs":[["matn","ومن أوصى بثلث ماله له ثم اكتسب مالا استحق الموصى له ثلث ما يملكه عند الموت والله أعلم"]]}]},{"id":"q117","title":"كتاب الفرائض","group":"كتاب الفرائض","units":[{"id":"q117_1","label":"كتاب الفرائض · الفقرة ١","segs":[["matn","المجمع على توريثهم من الذكور"]]},{"id":"q117_2","label":"كتاب الفرائض · الفقرة ٢","segs":[["matn","عشرة: الابن وابن الابن وإن سفل والأب والجد أب الأب وإن علا والأخ وابن الأخ والعم وابن العم والزوج ومولى النعمة"]]},{"id":"q117_3","label":"كتاب الفرائض · الفقرة ٣","segs":[["matn","ومن الإناث سبع: البنت وبنت الابن والأم والجدة والأخت والزوجة ومولاة النعمة"]]},{"id":"q117_4","label":"كتاب الفرائض · الفقرة ٤","segs":[["matn","ولا يرث أربعة: المملوك والقاتل من المقتول والمرتد وأهل الملتين والفروض المحدودة في كتاب الله تعالى ستة: النصف"]]},{"id":"q117_5","label":"كتاب الفرائض · الفقرة ٥","segs":[["matn","والربع والثمن والثلثان والثلث والسدس"]]},{"id":"q117_6","label":"كتاب الفرائض · الفقرة ٦","segs":[["matn","فالنصف من الأب والأم والأخت من الأب إذا لم تكن أخت لأب وأم والزوج إذا لم يكن للميت ولد ولد ولا ولد ابن"]]},{"id":"q117_7","label":"كتاب الفرائض · الفقرة ٧","segs":[["matn","والربع: فرض الزوج مع الولد أو ولد الابن والزوجات إذا لم يكن للميت ولد ولا ولد ابن"]]},{"id":"q117_8","label":"كتاب الفرائض · الفقرة ٨","segs":[["matn","والثمن: فرض الزوجات مع الولد وولد الابن"]]},{"id":"q117_9","label":"كتاب الفرائض · الفقرة ٩","segs":[["matn","والثلثان: لكل اثنين فصاعدا ممن فرضه النصف إلا الزوج"]]},{"id":"q117_10","label":"كتاب الفرائض · الفقرة ١٠","segs":[["matn","والثلث: للأم إذا لم يكن للميت ولد ولا ولد ابن ولا"]]},{"id":"q117_11","label":"كتاب الفرائض · الفقرة ١١","segs":[["matn","اثنان من الإخوة والأخوات فصاعدا ويفرض لها في مسألتين - وهما: زوج وأبوان وامرأة وأبوان - ثلث ما يبقى بعد فرض الزوج أو الزوجة وهو لكل اثنين فصاعدا من ولد الأم: ذكورهم وإناثهم فيه سواء"]]},{"id":"q117_12","label":"كتاب الفرائض · الفقرة ١٢","segs":[["matn","والسدس: فرض سبعة: لكل واحد من الأبوين مع الولد أو ولد الابن وللأم مع الإخوة والأخوات من أي جهة كانوا وللجدات وللجد مع الولد أو ولد الابن ولبنات الابن مع البنت وللأخوات لأب مع الأخت لأب وأم وللواحد من ولد الأم"]]},{"id":"q117_13","label":"كتاب الفرائض · الفقرة ١٣","segs":[["matn","وتسقط الجدات بالأم والجد والإخوة والأخوات بالأب"]]},{"id":"q117_14","label":"كتاب الفرائض · الفقرة ١٤","segs":[["matn","ويسقط ولد الأم بأربعة: بالولد وولد الابن والأب والجد"]]},{"id":"q117_15","label":"كتاب الفرائض · الفقرة ١٥","segs":[["matn","وإذا استكمل البنات الثلثين سقطت بنات الابن إلا أن يكون بإزائهن أو أسفل منهن ابن ابن فيعصبهن"]]},{"id":"q117_16","label":"كتاب الفرائض · الفقرة ١٦","segs":[["matn","وإذا استكمل الأخوات لأب وأم الثلثين سقطت الأخوات لأب إلا أن يكون معهن أخ لهن فيعصبهن"]]},{"id":"q117_17","label":"كتاب الفرائض · الفقرة ١٧","segs":[["matn","1 - باب أقرب العصبات"]]},{"id":"q117_18","label":"كتاب الفرائض · الفقرة ١٨","segs":[["matn","وأقرب العصبات البنون ثم بنوهم ثم الأب ثم الجد ثم بنو الأب وهم الإخوة"]]},{"id":"q117_19","label":"كتاب الفرائض · الفقرة ١٩","segs":[["matn","ثم بنو الجد وهم الأعمام ثم بنوا أب الجد"]]},{"id":"q117_20","label":"كتاب الفرائض · الفقرة ٢٠","segs":[["matn","وإذا استوى بنو أب في الدرجة فأولاهم من كان لأب وأم"]]},{"id":"q117_21","label":"كتاب الفرائض · الفقرة ٢١","segs":[["matn","والابن وابن الابن والإخوة يقاسمون أخواتهم للذكر مثل حظ الأنثيين ومن عداهم من العصبات ينفرد بالميراث ذكورهم دون إناثهم"]]},{"id":"q117_22","label":"كتاب الفرائض · الفقرة ٢٢","segs":[["matn","وإذا لم يكن عصبة من النسب فالعصبة هو المولى المعتق ثم أقرب عصبة المولى"]]},{"id":"q117_23","label":"كتاب الفرائض · الفقرة ٢٣","segs":[["matn","باب الحجب وتحجب الأم من الثلث إلى السدس بالولد أو بأخوين"]]},{"id":"q117_24","label":"كتاب الفرائض · الفقرة ٢٤","segs":[["matn","والفاضل عن فرض البنات لبني الابن وأخواتهم للذكر مثل حظ الأنثيين"]]},{"id":"q117_25","label":"كتاب الفرائض · الفقرة ٢٥","segs":[["matn","والفاضل عن فرض الأختين من الأب والأم للإخوة والأخوات من الأب للذكر مثل حظ الأنثيين"]]},{"id":"q117_26","label":"كتاب الفرائض · الفقرة ٢٦","segs":[["matn","وإذا ترك بنتا ابن وبني ابن فللبنت النصف والباقي لبني الابن وأخواتهم للذكر مثل حظ الأنثيين وكذلك الفاضل عن فرض الأخت من الأب والأم لبني الأب وبنات الأب للذكر مثل حظ الأنثيين"]]},{"id":"q117_27","label":"كتاب الفرائض · الفقرة ٢٧","segs":[["matn","ومن ترك ابني عم أحدهما أخ الأم فللأخ للأم السدس والباقي بنيهما"]]},{"id":"q117_28","label":"كتاب الفرائض · الفقرة ٢٨","segs":[["matn","والمشركة: أن تترك المرأة زوجا وأما - أو جدة - وأختين من أم وأخا لأب وأم فللزوج النصف وللأم السدس ولولد الأم الثلث ولا شيء للأخوة من الأب والأم"]]},{"id":"q117_29","label":"كتاب الفرائض · الفقرة ٢٩","segs":[["matn","باب الرد والفاضل عن فرض ذوي السهام إذا لم يكن عصبة مردود عليهم بمقدار سهامهم إلا على الزوجين"]]},{"id":"q117_30","label":"كتاب الفرائض · الفقرة ٣٠","segs":[["matn","ولا يرث القاتل من المقتول والكفر كله ملة واحدة يتوارث به أهله"]]},{"id":"q117_31","label":"كتاب الفرائض · الفقرة ٣١","segs":[["matn","ولا يرث المسلم من الكافر ولا الكافر من المسلم ومال المرتد لورثته من"]]},{"id":"q117_32","label":"كتاب الفرائض · الفقرة ٣٢","segs":[["matn","المسلمين وما اكتسبه في حال ردته فيء"]]},{"id":"q117_33","label":"كتاب الفرائض · الفقرة ٣٣","segs":[["matn","وإذا غرق جماعة أو سقط عليهم حائط فلم يعلم من مات منم أولا فمال كل واحد منهم للأحياء من ورثته"]]},{"id":"q117_34","label":"كتاب الفرائض · الفقرة ٣٤","segs":[["matn","وإذا اجتمع في المجوسي قرابتان لو تفرقت في شخصين ورث أحدهما مع الآخر ورث بهما ولا يرث المجوسي بالأنكحة الفاسدة التي يستحلونها في دينهم"]]},{"id":"q117_35","label":"كتاب الفرائض · الفقرة ٣٥","segs":[["matn","وعصبة ولد الزنا وولد الملاعنة مولى أمهما"]]},{"id":"q117_36","label":"كتاب الفرائض · الفقرة ٣٦","segs":[["matn","ومن مات وترك حملا وقف ماله حتى تضع امرأته حملها في قول أبي حنيفة"]]},{"id":"q117_37","label":"كتاب الفرائض · الفقرة ٣٧","segs":[["matn","والجد أولى بالميراث من الإخوة عند أبي حنيفة وقال أبو يوسف ومحمد: يقاسمهم إلا أن تنقصه المقاسمة من الثلث"]]},{"id":"q117_38","label":"كتاب الفرائض · الفقرة ٣٨","segs":[["matn","وإذا اجتمعت الجدات فالسدس لأقربهن"]]},{"id":"q117_39","label":"كتاب الفرائض · الفقرة ٣٩","segs":[["matn","ويحجب الجد أمه ولا ترث أم أبي الأم بسهم وكل جدة تحجب أمها"]]},{"id":"q117_40","label":"كتاب الفرائض · الفقرة ٤٠","segs":[["matn","باب ذوي الأرحام وإذا لم يكن للميت عصبة ولا ذو سهم ورثه ذوو أرحامه وهم عشرة: ولد البنت وولد الأخت"]]},{"id":"q117_41","label":"كتاب الفرائض · الفقرة ٤١","segs":[["matn","وابنة الأخ وابنة العم والخال والخالة وأب الأم والعم من الأم والعمة وولد الأخ من الأم ومن أدلى بهم"]]},{"id":"q117_42","label":"كتاب الفرائض · الفقرة ٤٢","segs":[["matn","وأولاهم ولد الميت ثم ولد الأبوين أو أحدهما وهم بنات الإخوة وولد الأخوات ثم ولد أبوي أبويه أو أحدهما وهم الأخوال والخالات والعمات"]]},{"id":"q117_43","label":"كتاب الفرائض · الفقرة ٤٣","segs":[["matn","وإذا استوى ولد أب في درجة فأولاهم من أدلى بوارث وأقربهم أولى من أبعدهم وأب الأم أولى من ولد الأخ والأخت"]]},{"id":"q117_44","label":"كتاب الفرائض · الفقرة ٤٤","segs":[["matn","والمعتق أحق بالفاضل من سهم ذوي سهام إذا لم تكن عصبة"]]},{"id":"q117_45","label":"كتاب الفرائض · الفقرة ٤٥","segs":[["matn","سواه ومولى الموالاة يرث"]]},{"id":"q117_46","label":"كتاب الفرائض · الفقرة ٤٦","segs":[["matn","وإذا ترك المعتق أبا مولاه وابن مولاه فماله للابن وقال أبو يوسف: للأب السدس والباقي للابن فإن ترك جد مولاه وأخ مولاه فالمال للجد في قول أبي حنيفة وقال أبو يوسف ومحمد: هو بينهما"]]},{"id":"q117_47","label":"كتاب الفرائض · الفقرة ٤٧","segs":[["matn","ولا يباع الولاء ولا يوهب"]]}]},{"id":"q118","title":"باب حساب الفرائض","group":"كتاب الفرائض","units":[{"id":"q118_1","label":"باب حساب الفرائض · الفقرة ١","segs":[["matn","إذا كان في المسألة نصف ونصف أو نصف وما بقي فأصلها من اثنين وإن كان ثلث وما بقي أو ثلثان وما بقي فأصلها من ثلاثة وإن كان ربع وما بقي فأصلها من ثمانية وإذا كان سدس وما بقي أو نصف وثلث أو سدس فأصلها من ستة وتعول إلى سبعة وثمانية وتسعة وعشرة"]]},{"id":"q118_2","label":"باب حساب الفرائض · الفقرة ٢","segs":[["matn","وإن كان مع الربع ثلث أو سدس فأصلها من اثني عشر وتعول إلى ثلاثة عشر وخمسة عشرة وسبعة عشر"]]},{"id":"q118_3","label":"باب حساب الفرائض · الفقرة ٣","segs":[["matn","وإذا كان مع الثمن ثلثان أو سدس فأصلها من أربعة وعشرين وتعول إلى سبعة وعشرين"]]},{"id":"q118_4","label":"باب حساب الفرائض · الفقرة ٤","segs":[["matn","فإذا انقسمت المسألة على الورثة فقد صحت وإن لم تنقسم سهام فريق عليهم فاضرب عددهم في أصل المسألة وعولها إن كانت عائلة فما خرج فمنه تصح المسألة كامرأة وأخوين: للمرأة الربع سهم وللأخوين ما بقي وهي ثلاثة أسهم لا تنقسم عليهما فاضرب اثنين في أصل المسألة فتكون ثمانية ومنها تصح"]]},{"id":"q118_5","label":"باب حساب الفرائض · الفقرة ٥","segs":[["matn","وإن وافق سهامهم عددهم فاضرب وفق عددهم في أصل المسألة كامرأة وستة"]]},{"id":"q118_6","label":"باب حساب الفرائض · الفقرة ٦","segs":[["matn","إخوة للمرأة الربع سهم وللإخوة ثلاثة فاضرب وفق عددهم في أصل المسألة يكون ثمانية ومنه تصح"]]},{"id":"q118_7","label":"باب حساب الفرائض · الفقرة ٧","segs":[["matn","وإن لم تنقسم سهام فريقين أو أكثر فاضرب أحد الفريقين ي الآخر ثم ما اجتمع في الفريق الثالث ثم ما اجتمع في أصل المسألة"]]},{"id":"q118_8","label":"باب حساب الفرائض · الفقرة ٨","segs":[["matn","فإن تساوت الأعداد أجزأ أحدهما عن الآخر كامرأتين وأخوين"]]},{"id":"q118_9","label":"باب حساب الفرائض · الفقرة ٩","segs":[["matn","فاضرب اثنين في أصل المسألة"]]},{"id":"q118_10","label":"باب حساب الفرائض · الفقرة ١٠","segs":[["matn","فإن كان أحد العددين جزءا من الآخر أغنى الأكثر عن الأقل كأربع نسوة وأخوين إذا ضربت الأربعة أجزأك عن"]]},{"id":"q118_11","label":"باب حساب الفرائض · الفقرة ١١","segs":[["matn","الآخر فإن وافق أحد العددين الآخر ضربت وفق أحدهما في جميع الآخر ثم ما اجتمع في أصل المسألة كأربع نسوة وأخت وستة أعمام فالستة توافق الأربعة بالنصف فاضرب نصف أحدهما في جميع الآخر ثم ما اجتمع في أصل المسألة تكون ثمانية وأربعين ومنها تصح"]]},{"id":"q118_12","label":"باب حساب الفرائض · الفقرة ١٢","segs":[["matn","فإذا صحت المسألة فاضرب سهام كل وارث في التركة ثم اقسم ما اجتمع على ما صحت منه الفريضة يخرج حق ذلك الوارث"]]},{"id":"q118_13","label":"باب حساب الفرائض · الفقرة ١٣","segs":[["matn","وإذا لم تقسم التركة حتى مات أحد الورثة فإن كان ما يصيبه من الميت الأول ينقسم على ورثته فقد صحت المسألتان مما صحت الأولى وإن لم ينقسم صححت فريضة الميت الثاني بالطريقة التي ذكرناها ثم ضربت إحدى المسألتين في الأخرى إن لم يكن بين سهام الميت الثاني وما صحت منه"]]},{"id":"q118_14","label":"باب حساب الفرائض · الفقرة ١٤","segs":[["matn","فريضة موافقة فإن كان بينهما موافقة فاضرب المسألة الثانية في الأولى فما اجتمع صحت منه المسألتان"]]},{"id":"q118_15","label":"باب حساب الفرائض · الفقرة ١٥","segs":[["matn","وكل من له شيء من المسألة الأولى مضروب في وفق المسألة الثانية ومن كان له شيء من المسألة الثانية مضروب في وفق تركة الميت الثاني وإذا صحت مسألة المناسخة وأردت معرفة ما يصيب كل واحد من حبات الدرهم"]]},{"id":"q118_16","label":"باب حساب الفرائض · الفقرة ١٦","segs":[["matn","قسمت ما صحت منه المسألة على ثمانية وأربعين فما خرج أخذت له من سهام كل وارث والله أعلم بالصواب."]]}]}]};
